         CREATE PROCEDURE [dbo].[UPD_VIREMENT]  
         	@ID_VIREMENT INT,  
         	@ID_UTILISATEUR INT,
         	@ID_ENVELOPPE_SOURCE INT,
         	@ID_ENVELOPPE_DESTINATION INT,
         	@COM_VIREMENT_ENVELOPPE VARCHAR(255),
         	@TIME_STAMP TIMESTAMP
         AS  

         UPDATE VIREMENT_ENVELOPPE SET
         	ID_ENVELOPPE_SOURCE = @ID_ENVELOPPE_SOURCE,
         	ID_ENVELOPPE_DESTINATION = @ID_ENVELOPPE_DESTINATION,
         	ID_UTILISATEUR = @ID_UTILISATEUR,
         	COM_VIREMENT_ENVELOPPE = @COM_VIREMENT_ENVELOPPE
         FROM VIREMENT_ENVELOPPE
         WHERE ID_VIREMENT_ENVELOPPE = @ID_VIREMENT AND
         	TIME_STAMP = @TIME_STAMP

         IF @@ROWCOUNT = 0   
         BEGIN  
            IF EXISTS(SELECT * FROM VIREMENT_ENVELOPPE WHERE ID_VIREMENT_ENVELOPPE  = @ID_VIREMENT)      
            BEGIN  

               RAISERROR('Problme de Concurrende d''accs', 16, 1) 
               RETURN -1 
            END 
            ELSE  
            BEGIN  

               RAISERROR(50002, 16, 1)  
            END      
         END 

GO

         CREATE PROCEDURE [dbo].[LEC_PRC_VIR_SELECTIONNEES_ANNULEES]
         AS
         BEGIN
         	DECLARE @PRC AS DECIMAL(18,2)

         	DECLARE @NUMERATEUR AS DECIMAL(18,2)
         	DECLARE @DENOMINATEUR AS DECIMAL(18,2)
         	SET @NUMERATEUR = 
         	(
         		SELECT 	COUNT(REGLEMENT.ID_REGLEMENT)
         		FROM	REGLEMENT
         		WHERE	REGLEMENT.BLN_EN_COURS = 1 AND
         				REGLEMENT.BLN_CRITERE = 1 AND
         				REGLEMENT.BLN_ACTIF = 0
         	)

         	SET @DENOMINATEUR = 
         	(
         		SELECT 	COUNT(REGLEMENT.ID_REGLEMENT)
         		FROM	REGLEMENT
         		WHERE	REGLEMENT.BLN_EN_COURS = 1 AND
         				REGLEMENT.BLN_CRITERE = 1
         	)

         		IF @DENOMINATEUR = 0
         			SET @PRC = 0

         		IF @DENOMINATEUR != 0 
         			SET @PRC = @NUMERATEUR/@DENOMINATEUR

         	SELECT 'Return Value' = COALESCE(ROUND(@PRC,2),0)
         END

GO
