          @DAT_CLOTURE     DATETIME,
          @BLN_ORIGINE_SFEIR    TINYINT,
          @ID_UTILISATEUR     INT,
          @ID_CLASSIFICATION    INT,
          @ID_AGENCE      INT,
          @ID_TIERS_DDTE     INT,
          @ID_FORMACODE     INT,
          @ID_PUBLIC_SPECIFIQUE   INT,
