          @ID_TUTEUR      INT,
          @ID_TYPE_CONTRAT    INT,
          @ID_SPECIALITE     INT,
          @ID_ETABLISSEMENT    INT,
          @ID_ETAT_CONTRAT_PRO   INT,
          @ID_MOTIF_CLOTURE_PRO   INT,
          @ID_TYPE_CONTRAT_PRO   INT,
          @DAT_BAE_INITIALE    DATETIME,
          @LIB_LIEU_FORMATION    VARCHAR(80),
          @ID_IDCC      INT,
          @ID_TYPE_CONTRAT_FAF   INT,
          @NUM_DERNIER_AVENANT   INT,
          @BLN_OK_PIECE     TINYINT,
