           MNT_SALAIRE_BRUT_MENSUEL, BLN_CONFORME_ACCORD,  BLN_PARTICIPATION_FINANCIERE,  BLN_EXONERATION_CHARGES,
           NUM_ENREGISTREMENT_DDTE, DAT_DEPOT_DDTE,    DAT_ENREGISTREMENT_DDTE,   DAT_CLOTURE, 
