         CREATE PROCEDURE [dbo].[UPD_VERSEMENT_EXTRANET]  
         	@ID_VERSEMENT INTEGER,
         	@ID_ADHERENT_EMETTEUR INTEGER,
         	@ID_TIERS_EMETTEUR INTEGER,
         	@ID_MODE_VERSEMENT INTEGER,  
         	@COD_VERSEMENT INTEGER, 
         	@DAT_CREATION datetime,
         	@LIB_BANQUE varchar(50),
         	@MNT_VERSEMENT decimal(18,2),
         	@BLN_PB_IMPUTATION TINYINT,
         	@BLN_ACTIF TINYINT,
         	@COM_VERSEMENT VARCHAR(255),
         	@ID_UTILISATEUR INTEGER,
         	@TIME_STAMP timestamp,
         	@ID_BORDEREAU INTEGER,
         	@NUM_CHEQUE varchar(10),
         	@DAT_ENCAISSEMENT datetime,
         	@DAT_IMPUTATION datetime,
         	@DAT_MODIF datetime,
         	@DAT_SAISIE datetime,
         	@DAT_MAJ_COMPTES datetime,
         	@DAT_COMPTA_COMPTES_ADH datetime,
         	@DAT_ANNUL_COMPTES_ADH datetime,
         	@DAT_PASSAGE_COMPTA datetime,
         	@INDICATEUR_INSTANCE INTEGER,
         	@ID_STATUT_VERSEMENT INTEGER,
         	@BLN_IMPAYE TINYINT,
         	@DAT_SAISIE_IMPAYE datetime,
         	@BLN_ENCAISSEMENT_DIFFERE TINYINT,
         	@BLN_DIFFERE_PRIS_EN_COMPTE TINYINT = null,
         	@DAT_VALID_VERSEMENT datetime = null,
         	@ID_BANQUE INTEGER,
         	@MODE_SAISIE_VERSEMENT varchar(15),
         	@REF_EXTRANET varchar(20),
         	@DAT_VALIDATION_EXTRANET datetime,
         	@DAT_ECHEANCE datetime,
         	@ID_MOTIF_REGLEMENT INTEGER,
         	@ID_ETABLISSEMENT_EMETTEUR int

         AS  

         select @LIB_BANQUE =LIBC_BANQUE  from BANQUE WHERE ID_BANQUE = @ID_BANQUE

         	IF( ISNULL(@BLN_ENCAISSEMENT_DIFFERE,0) = 0)
         	BEGIN
         	SET @DAT_ENCAISSEMENT = NULL
         	END

         	UPDATE VERSEMENT
         	SET  
         			ID_ADHERENT_EMETTEUR=@ID_ADHERENT_EMETTEUR ,
         			ID_TIERS_EMETTEUR=@ID_TIERS_EMETTEUR ,
         			ID_MODE_VERSEMENT=@ID_MODE_VERSEMENT ,  
         			COD_VERSEMENT=@COD_VERSEMENT , 
         			DAT_CREATION=@DAT_CREATION ,
         			LIB_BANQUE=@LIB_BANQUE ,
         			MNT_VERSEMENT=@MNT_VERSEMENT ,
         			BLN_PB_IMPUTATION=@BLN_PB_IMPUTATION ,
         			BLN_ACTIF=@BLN_ACTIF ,
         			COM_VERSEMENT=@COM_VERSEMENT ,
         			ID_UTILISATEUR=@ID_UTILISATEUR ,
         			ID_BORDEREAU = @ID_BORDEREAU ,
         			NUM_CHEQUE = @NUM_CHEQUE ,
         			DAT_ENCAISSEMENT=@DAT_ENCAISSEMENT ,
         			DAT_IMPUTATION=@DAT_IMPUTATION ,
         			DAT_MODIF = getdate(),
         			DAT_SAISIE=@DAT_SAISIE ,
         			DAT_MAJ_COMPTES=@DAT_MAJ_COMPTES ,
         			DAT_COMPTA_COMPTES_ADH=@DAT_COMPTA_COMPTES_ADH ,
         			DAT_ANNUL_COMPTES_ADH = @DAT_ANNUL_COMPTES_ADH ,
         			DAT_PASSAGE_COMPTA=@DAT_PASSAGE_COMPTA ,
         			INDICATEUR_INSTANCE= @INDICATEUR_INSTANCE ,
         			ID_STATUT_VERSEMENT = @ID_STATUT_VERSEMENT ,
         			BLN_IMPAYE=@BLN_IMPAYE ,
         			DAT_SAISIE_IMPAYE= @DAT_SAISIE_IMPAYE ,
         			BLN_ENCAISSEMENT_DIFFERE =@BLN_ENCAISSEMENT_DIFFERE,
         			BLN_DIFFERE_PRIS_EN_COMPTE		= @BLN_DIFFERE_PRIS_EN_COMPTE,
         			DAT_VALID_VERSEMENT = @DAT_VALID_VERSEMENT,
         			ID_BANQUE = @ID_BANQUE,
         			MODE_SAISIE_VERSEMENT = @MODE_SAISIE_VERSEMENT,
         			REF_EXTRANET = @REF_EXTRANET,
         			DAT_VALIDATION_EXTRANET = @DAT_VALIDATION_EXTRANET,
         			DAT_ECHEANCE = @DAT_ECHEANCE,
         			ID_MOTIF_REGLEMENT = @ID_MOTIF_REGLEMENT,
         			ID_ETABLISSEMENT_EMETTEUR = @ID_ETABLISSEMENT_EMETTEUR

         	FROM VERSEMENT
         	WHERE
         			ID_VERSEMENT  = @ID_VERSEMENT  
         		AND TIME_STAMP = @TIME_STAMP  

         	IF @@ROWCOUNT = 0   
         		BEGIN  
         		   IF EXISTS(SELECT * FROM VERSEMENT WHERE ID_VERSEMENT  = @ID_VERSEMENT)      
         		   BEGIN  

         		      RAISERROR(50001, 16, 1)  
         		   END  
         		   ELSE  
         		   BEGIN  

         		      RAISERROR(50002, 16, 1)  
         		   END  
         		END       

         select ID_POSTE_VERSEMENT
         into #tmp_poste_vers_to_update
         from POSTE_VERSEMENT
         	inner join TYPE_VERSEMENT ON POSTE_VERSEMENT.ID_TYPE_VERSEMENT = TYPE_VERSEMENT.ID_TYPE_VERSEMENT
         where 
         	POSTE_VERSEMENT.ID_VERSEMENT = @ID_VERSEMENT
         	AND POSTE_VERSEMENT.BLN_ACTIF <> @BLN_ACTIF
         	AND TYPE_VERSEMENT.BLN_VERSEMENT = 0 

         update POSTE_VERSEMENT
         set BLN_ACTIF = @BLN_ACTIF
         where POSTE_VERSEMENT.ID_POSTE_VERSEMENT in
         	(select ID_POSTE_VERSEMENT from #tmp_poste_vers_to_update)

GO

         CREATE PROCEDURE LEC_GRP_ORDRE_VIREMENT_REGULARISATION_NEGATIVES
         	@TYPE_ETAT		int,		
         	@DATE_DEBUT		datetime,
         	@DATE_FIN		datetime
         with recompile
         AS
         	BEGIN
         		CREATE TABLE #TEMP
         		(
         			ID_VIREMENT_INTERNE_COLLECTE INTEGER,
         			ID_VIREMENT_INTERNE_COLLECTE_IMPAYE INTEGER,
         			ID_ACTIVITE INTEGER,
         			DAT_EDIT_VIREMENT_INTERNE_COLLECTE Datetime,
         			DAT_COMPTA_VIREMENT_INTERNE_COLLECTE Datetime,
         			MNT_VIREMENT_INTERNE_COLLECTE decimal(18,2)
         		)

         		IF (@TYPE_ETAT = 1)
         			BEGIN

         				INSERT INTO #TEMP
         				SELECT DISTINCT
         					VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE,
         					POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE_IMPAYE,
         					VIREMENT_INTERNE_COLLECTE.ID_ACTIVITE,
         					VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.DAT_COMPTA_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE
         				FROM
         					VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_IMPUTATION	ON VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE = POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_VERSEMENT		ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT = POSTE_VERSEMENT.ID_POSTE_VERSEMENT
         					LEFT OUTER JOIN VERSEMENT			on POSTE_VERSEMENT.ID_VERSEMENT = VERSEMENT.ID_VERSEMENT

         					INNER JOIN TYPE_VERSEMENT			ON	POSTE_VERSEMENT.ID_TYPE_VERSEMENT = TYPE_VERSEMENT.ID_TYPE_VERSEMENT
         				WHERE       

         					TYPE_VERSEMENT.BLN_VERSEMENT_INITIAL = 0 

         					AND (VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE IS NULL)
         					AND (VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE <= 0 )

         				UPDATE VIREMENT_INTERNE_COLLECTE
         				SET VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE = getDate()
         				where VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE in (select ID_VIREMENT_INTERNE_COLLECTE from #TEMP)

         				UPDATE #TEMP
         				SET DAT_EDIT_VIREMENT_INTERNE_COLLECTE = getDate()

         				INSERT INTO #TEMP
         				SELECT DISTINCT
         					VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE,
         					POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE_IMPAYE,
         					VIREMENT_INTERNE_COLLECTE.ID_ACTIVITE,
         					VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.DAT_COMPTA_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE*(-1) as MNT_VIREMENT_INTERNE_COLLECTE
         				FROM
         					VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_IMPUTATION ON VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE = POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE_IMPAYE 
         					LEFT OUTER JOIN POSTE_VERSEMENT ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT = POSTE_VERSEMENT.ID_POSTE_VERSEMENT
         					LEFT OUTER JOIN VERSEMENT on POSTE_VERSEMENT.ID_VERSEMENT = VERSEMENT.ID_VERSEMENT
         				WHERE
         					VERSEMENT.ID_STATUT_VERSEMENT = 7
         					and POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE_IMPAYE IS not NULL
         					and VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE IS NULL
         					AND VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE < 0

         				UPDATE VIREMENT_INTERNE_COLLECTE
         				SET VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE = getDate()
         				where VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE in (select
         																					ID_VIREMENT_INTERNE_COLLECTE_IMPAYE
         																				from
         																					#TEMP
         																				WHERE
         																					ID_VIREMENT_INTERNE_COLLECTE_IMPAYE IS NOT NULL)
         			END
         		ELSE
         			BEGIN
         				INSERT INTO #TEMP
         				SELECT DISTINCT
         					VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE,
         					POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE_IMPAYE,
         					VIREMENT_INTERNE_COLLECTE.ID_ACTIVITE,
         					VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.DAT_COMPTA_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE
         				FROM
         					VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_IMPUTATION ON VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE = POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_VERSEMENT ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT = POSTE_VERSEMENT.ID_POSTE_VERSEMENT
         					LEFT OUTER JOIN VERSEMENT on POSTE_VERSEMENT.ID_VERSEMENT = VERSEMENT.ID_VERSEMENT

         					INNER JOIN TYPE_VERSEMENT			ON	POSTE_VERSEMENT.ID_TYPE_VERSEMENT = TYPE_VERSEMENT.ID_TYPE_VERSEMENT
         				WHERE      

         					TYPE_VERSEMENT.BLN_VERSEMENT_INITIAL = 0 

         					AND (@DATE_DEBUT IS NULL OR DATEDIFF(DAY,DAT_EDIT_VIREMENT_INTERNE_COLLECTE,@DATE_DEBUT) <= 0)
         					AND	(@DATE_FIN  IS NULL OR DATEDIFF(DAY,DAT_EDIT_VIREMENT_INTERNE_COLLECTE,@DATE_FIN ) >= 0)
         					AND VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE < 0

         				INSERT INTO #TEMP
         				SELECT DISTINCT
         					VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE,
         					POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE_IMPAYE,
         					VIREMENT_INTERNE_COLLECTE.ID_ACTIVITE,
         					VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.DAT_COMPTA_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE
         				FROM
         					VIREMENT_INTERNE_COLLECTE
         					LEFT OUTER JOIN POSTE_IMPUTATION ON VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE = POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE_IMPAYE
         					LEFT OUTER JOIN POSTE_VERSEMENT ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT = POSTE_VERSEMENT.ID_POSTE_VERSEMENT
         					LEFT OUTER JOIN VERSEMENT on POSTE_VERSEMENT.ID_VERSEMENT = VERSEMENT.ID_VERSEMENT
         				WHERE
         					VERSEMENT.ID_STATUT_VERSEMENT = 7
         					and POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE_IMPAYE IS not NULL
         					AND (@DATE_DEBUT IS NULL OR DATEDIFF(DAY,DAT_EDIT_VIREMENT_INTERNE_COLLECTE,@DATE_DEBUT) <= 0)
         					AND	(@DATE_FIN  IS NULL OR DATEDIFF(DAY,DAT_EDIT_VIREMENT_INTERNE_COLLECTE,@DATE_FIN ) >= 0)
         					AND VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE < 0
         			END

         			SELECT
         				#TEMP.ID_VIREMENT_INTERNE_COLLECTE,
         				CASE WHEN #TEMP.MNT_VIREMENT_INTERNE_COLLECTE < 0 
         					THEN #TEMP.MNT_VIREMENT_INTERNE_COLLECTE * (-1) 
         					ELSE #TEMP.MNT_VIREMENT_INTERNE_COLLECTE 
         				END AS MNT_VIREMENT_INTERNE_COLLECTE,
         				#TEMP.DAT_EDIT_VIREMENT_INTERNE_COLLECTE,
         				TRANSIT.NUM_IBAN_TRANSIT,
         				TRANSIT.LIB_COMPTE_BANQUE AS LIB_COMPTE_BANQUE_TRANSIT,
         				ACTIVITE.LIB_COMPTE_BANQUE AS LIB_COMPTE_BANQUE_ACTIVITE,
         				ACTIVITE.NUM_IBAN_ACTIVITE,
         				ACTIVITE.LIB_BANQUE,
         				PARAMETRES.NOM_PNM_SECRETAIRE_GENERAL,
         				PARAMETRES.NOM_PNM_DAF,
         				PARAMETRES.NOM_PNM_DIRECTEUR,
         				PARAMETRES.PIED_PAGE_C2P,			
         				(SELECT RTRIM(
         						CASE 
         							WHEN PATINDEX('%CEDEX%', LIB_VILLE) <> 0 THEN LEFT(LIB_VILLE, PATINDEX('%CEDEX%', LIB_VILLE)-1) 
         							ELSE LIB_VILLE 
         						END) 
         				FROM AGENCE 
         				WHERE COD_AGENCE = 'NE') AGENCE_LIB_VILLE,
         				PARAMETRES.BANQUE_VIREMENT		
         			FROM
         				#TEMP
         				INNER JOIN ACTIVITE ON  #TEMP.ID_ACTIVITE = ACTIVITE.ID_ACTIVITE
         				CROSS JOIN PARAMETRES
         				CROSS JOIN TRANSIT
         			WHERE
         				#TEMP.MNT_VIREMENT_INTERNE_COLLECTE <> 0
         			order by
         				ACTIVITE.ID_ACTIVITE,
         				#TEMP.ID_VIREMENT_INTERNE_COLLECTE
         	END
GO

         CREATE PROCEDURE [dbo].[UPD_ID_REGLEMENT_PRO_DANS_SESSION_PRO]
         	@ID_SESSION_PRO INT,
         	@ID_REGLEMENT_PRO INT
         AS
         BEGIN

         declare @ID_REGLEMENT_PRO_of int
         declare @ID_REGLEMENT_PRO_adh int
         declare @dat_valid_reglement_OF as datetime
         set @dat_valid_reglement_OF = null
         declare @dat_valid_reglement_ADH as datetime
         set @dat_valid_reglement_ADH = null

         select @ID_REGLEMENT_PRO_OF=id_reglement_pro_of, @ID_REGLEMENT_PRO_adh=id_reglement_pro_adh from session_pro 
         where (id_reglement_pro_of = @ID_REGLEMENT_PRO or id_reglement_pro_adh=@ID_REGLEMENT_PRO)
         and id_session_pro=@id_session_pro

         select @dat_valid_reglement_OF=dat_valid_reglement from reglement_pro where id_reglement_pro = @ID_REGLEMENT_PRO_OF
         select @dat_valid_reglement_ADH=dat_valid_reglement from reglement_pro where id_reglement_pro = @ID_REGLEMENT_PRO_ADH

         	IF @dat_valid_reglement_OF is null and @dat_valid_reglement_adh is null
         	BEGIN
         		if (@ID_REGLEMENT_PRO_adh is not null) 
         			UPDATE SESSION_PRO 
         			set ID_REGLEMENT_PRO_ADH=null  
         			where ID_SESSION_PRO=@ID_SESSION_PRO
         				and id_reglement_pro_adh= @ID_REGLEMENT_PRO_adh

         		if (@ID_REGLEMENT_PRO_of is not null) 
         			UPDATE SESSION_PRO 
         			set ID_REGLEMENT_PRO_OF=null
         			where ID_SESSION_PRO=@ID_SESSION_PRO
         			and id_reglement_pro_of= @ID_REGLEMENT_PRO_of
         	END

         END

GO

         CREATE PROCEDURE [dbo].[EDT_LETTRE_PEC_RELANCE_INSTRUCTION]
         	@ID_ETABLISSEMENT int,
         	@ID_ACTION_PEC int
         AS

         BEGIN

         		SELECT
         				ADHERENT.ID_ADRESSE_PRINCIPALE,
         				ADHERENT.ID_ETABLISSEMENT_PRINCIPAL,
         				ADHERENT.ID_ADHERENT,
         				ADHERENT.COD_ADHERENT,
         				ADHERENT.LIB_RAISON_SOCIALE,

         				AGENCE.ID_AGENCE,
         				AGENCE.LIBL_AGENCE,
         				AGENCE.LIB_NOM_CONSEILLER,
         				AGENCE.LIB_PNM_CONSEILLER,
         				AGENCE.LIB_ADR1,
         				AGENCE.LIB_VILLE,
         				AGENCE.COD_POSTAL,
         				AGENCE.NUM_TEL,
         				AGENCE.NUM_FAX,
         				AGENCE.EMAIL
         		INTO
         				#TMP_GENERAL
         		FROM
         				ADHERENT
         				INNER JOIN AGENCE ON AGENCE.ID_AGENCE = ADHERENT.ID_AGENCE
         				INNER JOIN ETABLISSEMENT ON ADHERENT.ID_ETABLISSEMENT_PRINCIPAL = ETABLISSEMENT.ID_ETABLISSEMENT AND 
         						  ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         		WHERE
         				ETABLISSEMENT.ID_ETABLISSEMENT = @ID_ETABLISSEMENT;

         		SELECT  ACTION_PEC.COD_ACTION_PEC,

         				MODULE_PEC.ID_MODULE_PEC,
         				MODULE_PEC.COD_MODULE_PEC, 
         				MODULE_PEC.LIBL_MODULE_PEC, 
         				MODULE_PEC.DAT_DEBUT, 
         				MODULE_PEC.DAT_FIN,

                         ORGANISME_FORMATION.LIB_RAISON_SOCIALE
         		INTO
         				#TMP_MODULE
         		FROM         
         				ORGANISME_FORMATION 
         				INNER JOIN ETABLISSEMENT_OF ON ORGANISME_FORMATION.ID_OF = ETABLISSEMENT_OF.ID_OF 
         				INNER JOIN MODULE_PEC ON ETABLISSEMENT_OF.ID_OF = MODULE_PEC.ID_ETABLISSEMENT_OF 
         				INNER JOIN ACTION_PEC ON MODULE_PEC.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC

         		WHERE	ACTION_PEC.ID_ACTION_PEC = @ID_ACTION_PEC;

         		SELECT  
         				ACTION_PEC.COD_ACTION_PEC

         		INTO
         				#TMP_ACTION_PEC
         		FROM      
         				ACTION_PEC 

         		WHERE	ACTION_PEC.ID_ACTION_PEC = @ID_ACTION_PEC;

         	WITH XMLNAMESPACES (
         		DEFAULT 'LETTRE_PEC_RELANCE_INSTRUCTION'
         	)

         	SELECT

         			(
         				SELECT
         					AGENCE.LIBL_AGENCE	as AGENCE_NOM,
         					AGENCE.LIB_ADR1		as AGENCE_ADRESSE,
         					AGENCE.COD_POSTAL	as AGENCE_CP,
         					AGENCE.LIB_VILLE	as AGENCE_VILLE,
         					AGENCE.NUM_FAX		as AGENCE_FAX,
         					AGENCE.EMAIL		as AGENCE_EMAIL
         				FROM
         					#TMP_GENERAL as AGENCE
         				FOR XML AUTO, ELEMENTS, TYPE
         			),

         			(
         				SELECT
         						LETTRE.LIB_RAISON_SOCIALE,
         						DESTINATAIRE.LIB_ADR,
         						DESTINATAIRE.LIB_CP_CEDEX,
         						DESTINATAIRE.LIB_VIL_CEDEX
         				FROM
         						ADRESSE as DESTINATAIRE
         				WHERE
         						LETTRE.ID_ADRESSE_PRINCIPALE = DESTINATAIRE.ID_ADRESSE
         				FOR XML AUTO, ELEMENTS, TYPE

         			),

         			(
         				SELECT
         						LETTRE.COD_ADHERENT as COD_ADHERENT,
         						LETTRE.LIB_VILLE as LIB_VILLE	
         				FROM
         						#TMP_GENERAL AS ENTETE
         				FOR XML AUTO, ELEMENTS, TYPE

         			),

         			(
         				SELECT
         					CORPS.COD_ACTION_PEC as COD_ACTION_PEC,

         					(
         						SELECT
         							MODULE.ID_MODULE_PEC, 
         							MODULE.COD_MODULE_PEC, 
         							MODULE.LIBL_MODULE_PEC,
         							CASE WHEN (DATEDIFF(DAY,MODULE.DAT_FIN,getDate())>= 0) THEN 'r‚alis‚ par' 
         																					ELSE '… r‚alis‚ par '
         							END as REALISATION,
         							MODULE.LIB_RAISON_SOCIALE,
         							MODULE.DAT_DEBUT, 
         							MODULE.DAT_FIN,

         							(
         								SELECT     PIECE.COD_PIECE_PEC as NOM_PIECE

         								FROM		 
         											PIECE_PEC AS PIECE INNER JOIN ARRIVEE_PIECE_PEC ON PIECE.ID_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_PIECE_PEC
         								WHERE		(PIECE.BLN_BLOQUANT_ENGAGEMENT = 1)
         										AND ((BLN_ADHERENT = 1) OR (BLN_MODULE = 1) OR (BLN_STAGIAIRE = 1))
         										AND (ARRIVEE_PIECE_PEC.BLN_ACTIF = 0 ) 
         										AND (ARRIVEE_PIECE_PEC.DAT_ARRIVEE_PIECE_PEC IS NULL)
         										AND (ARRIVEE_PIECE_PEC.ID_ADHERENT = LETTRE.ID_ADHERENT)
         										AND (ARRIVEE_PIECE_PEC.ID_MODULE_PEC = MODULE.ID_MODULE_PEC)
         								FOR XML AUTO, ELEMENTS, TYPE,ROOT('PIECES_MANQUANTES')
         							),
         							(
         								SELECT      PIECE_PEC.ID_PIECE_PEC as ID_PIECE_PEC,
         									        PIECE_PEC.COD_PIECE_PEC as COD_PIECE_PEC, 
         											MOTIF_NON_CONFORMITE.LIBL_MOTIF_NON_CONFORM_PIECE AS MOTIF
         								FROM		 
         											PIECE_PEC 
         											INNER JOIN ARRIVEE_PIECE_PEC ON PIECE_PEC.ID_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_PIECE_PEC
         											INNER JOIN NR210 ON NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC
         											INNER JOIN MOTIF_NON_CONFORM_PIECE AS MOTIF_NON_CONFORMITE ON NR210.ID_MOTIF_NON_CONFORM_PIECE = MOTIF_NON_CONFORMITE.ID_MOTIF_NON_CONFORM_PIECE

         								WHERE		(PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1)
         										AND ((BLN_ADHERENT = 1) OR (BLN_MODULE = 1) OR (BLN_STAGIAIRE = 1))
         										AND (ARRIVEE_PIECE_PEC.BLN_ACTIF = 1 ) 
         										AND (ARRIVEE_PIECE_PEC.DAT_ARRIVEE_PIECE_PEC IS NOT NULL)
         										AND (ARRIVEE_PIECE_PEC.ID_ADHERENT = LETTRE.ID_ADHERENT)
         										AND (ARRIVEE_PIECE_PEC.ID_MODULE_PEC = MODULE.ID_MODULE_PEC)
         								FOR XML AUTO, ELEMENTS, TYPE,ROOT('PIECES_NON_CONFORMES')
         							)
         						FROM
         								#TMP_MODULE AS MODULE
         						FOR XML AUTO, ELEMENTS, TYPE
         					)

         				FROM
         						#TMP_ACTION_PEC AS CORPS
         				FOR XML AUTO, ELEMENTS, TYPE

         			),

         			(
         				SELECT
         						SIGNATURE.LIB_PNM_CONSEILLER,
         						SIGNATURE.LIB_NOM_CONSEILLER
         				FROM
         						#TMP_GENERAL as SIGNATURE
         				FOR XML AUTO, ELEMENTS, TYPE
         			)

         	FROM	#TMP_GENERAL as LETTRE
         	FOR XML AUTO, ELEMENTS
         END

GO

         CREATE PROCEDURE LEC_GRP_ORDRE_VIREMENT_REGULARISATION_POSITIVES
         	@TYPE_ETAT		int,		
         	@DATE_DEBUT		datetime,
         	@DATE_FIN		datetime
         with recompile
         AS
         	BEGIN
         		CREATE TABLE #TEMP
         		(
         			ID_VIREMENT_INTERNE_COLLECTE INTEGER,
         			ID_ACTIVITE INTEGER,
         			DAT_EDIT_VIREMENT_INTERNE_COLLECTE Datetime,
         			DAT_COMPTA_VIREMENT_INTERNE_COLLECTE Datetime,
         			MNT_VIREMENT_INTERNE_COLLECTE decimal(18,2)
         		)

         		IF (@TYPE_ETAT = 1)
         			BEGIN
         				INSERT INTO #TEMP
         				SELECT DISTINCT
         					VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.ID_ACTIVITE,
         					VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.DAT_COMPTA_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE
         				FROM
         					VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_IMPUTATION ON VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE = POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_VERSEMENT ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT = POSTE_VERSEMENT.ID_POSTE_VERSEMENT
         					LEFT OUTER JOIN VERSEMENT on POSTE_VERSEMENT.ID_VERSEMENT = VERSEMENT.ID_VERSEMENT

         					INNER JOIN TYPE_VERSEMENT			ON	POSTE_VERSEMENT.ID_TYPE_VERSEMENT = TYPE_VERSEMENT.ID_TYPE_VERSEMENT
         				WHERE       

         					(TYPE_VERSEMENT.BLN_VERSEMENT_INITIAL = 0 OR VERSEMENT.ID_STATUT_VERSEMENT = 7) 

         					AND (VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE IS NULL)
         					AND (VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE >= 0)

         				UPDATE VIREMENT_INTERNE_COLLECTE
         				SET VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE = getDate()
         				where VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE in (select ID_VIREMENT_INTERNE_COLLECTE from #TEMP)

         				UPDATE #TEMP
         				SET DAT_EDIT_VIREMENT_INTERNE_COLLECTE = getDate()
         			END
         		ELSE
         			BEGIN
         				INSERT INTO #TEMP
         				SELECT DISTINCT
         					VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.ID_ACTIVITE,
         					VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.DAT_COMPTA_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE
         				FROM
         					VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_IMPUTATION ON VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE = POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_VERSEMENT ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT = POSTE_VERSEMENT.ID_POSTE_VERSEMENT
         					LEFT OUTER JOIN VERSEMENT on POSTE_VERSEMENT.ID_VERSEMENT = VERSEMENT.ID_VERSEMENT

         					INNER JOIN TYPE_VERSEMENT			ON	POSTE_VERSEMENT.ID_TYPE_VERSEMENT = TYPE_VERSEMENT.ID_TYPE_VERSEMENT
         				WHERE       

         					(TYPE_VERSEMENT.BLN_VERSEMENT_INITIAL = 0 OR VERSEMENT.ID_STATUT_VERSEMENT = 7) 

         					AND ((@DATE_DEBUT IS NULL OR DATEDIFF(DAY,DAT_EDIT_VIREMENT_INTERNE_COLLECTE,@DATE_DEBUT) <= 0)) 
         					AND	((@DATE_FIN  IS NULL OR DATEDIFF(DAY,DAT_EDIT_VIREMENT_INTERNE_COLLECTE,@DATE_FIN ) >= 0)) 
         					AND (VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE > 0 )		
         			END

         		SELECT
         			#TEMP.ID_VIREMENT_INTERNE_COLLECTE,
         			#TEMP.MNT_VIREMENT_INTERNE_COLLECTE,
         			#TEMP.DAT_EDIT_VIREMENT_INTERNE_COLLECTE,
         			TRANSIT.NUM_IBAN_TRANSIT,
         			TRANSIT.LIB_COMPTE_BANQUE AS LIB_COMPTE_BANQUE_TRANSIT,
         			ACTIVITE.LIB_COMPTE_BANQUE AS LIB_COMPTE_BANQUE_ACTIVITE,
         			ACTIVITE.NUM_IBAN_ACTIVITE,
         			ACTIVITE.LIB_BANQUE,
         			PARAMETRES.NOM_PNM_SECRETAIRE_GENERAL,
         			PARAMETRES.NOM_PNM_DAF,
         			PARAMETRES.NOM_PNM_DIRECTEUR,
         			PARAMETRES.PIED_PAGE_C2P,
         			(SELECT RTRIM(
         				CASE 
         					WHEN PATINDEX('%CEDEX%', LIB_VILLE) <> 0 THEN LEFT(LIB_VILLE, PATINDEX('%CEDEX%', LIB_VILLE)-1) 
         					ELSE LIB_VILLE 
         				END) 
         			FROM AGENCE 
         			WHERE COD_AGENCE = 'NE') AGENCE_LIB_VILLE,
         			PARAMETRES.BANQUE_VIREMENT		
         		FROM
         			#TEMP 
         			INNER JOIN ACTIVITE ON  #TEMP.ID_ACTIVITE = ACTIVITE.ID_ACTIVITE
         			CROSS JOIN PARAMETRES 
         			CROSS JOIN TRANSIT
         		WHERE
         			#TEMP.MNT_VIREMENT_INTERNE_COLLECTE > 0
         		order by
         			ACTIVITE.ID_ACTIVITE,
         			#TEMP.ID_VIREMENT_INTERNE_COLLECTE
         	END
GO

         CREATE PROCEDURE [dbo].[INS_MVT_BUDG_PERIODE] 
         	@ID_MODULE int,
         	@ID_DISPOSITIF int,
         	@ID_BRANCHE int,
         	@ID_ENVELOPPE int,
         	@ID_COMPTE int,
         	@ID_TYPE_FINANCEMENT int,		
         	@TYPE_ENREGISTREMENT varchar(3),
         	@MNT decimal(18,2),

         	@ID_SESSION int,
         	@DATE datetime = NULL  
         AS
         BEGIN
         	SET NOCOUNT ON;

         	DECLARE @dat_debut datetime
         	DECLARE @dat_fin datetime
         	DECLARE @jours_total int
         	DECLARE @id_periode int
         	DECLARE @jours_periode int

         	if @TYPE_ENREGISTREMENT in ('C', 'EN') 

         	begin
         		select  @dat_debut = CAST( floor(CAST(max(SESSION_PEC.DAT_FIN) AS FLOAT ))AS DATETIME), 
         				@dat_fin = CAST( floor(CAST(max(MODULE_PEC.dat_fin) AS FLOAT ))AS DATETIME),
         				@jours_total = datediff(d, @dat_debut, @dat_fin)
         		from MODULE_PEC
         			inner join SESSION_PEC on (SESSION_PEC.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC)

         			inner join POSTE_COUT_REGLE on (POSTE_COUT_REGLE.id_SESSION_PEC = SESSION_PEC.id_SESSION_PEC )
         		where MODULE_PEC.ID_MODULE_PEC = @ID_MODULE
         		and SESSION_PEC.BLN_ACTIF = 1

         	end	

         	if @DATE is null and @dat_debut is null 
         	begin
         		if @ID_SESSION is null 
         			select  @dat_debut = CAST( floor(CAST(dat_debut AS FLOAT ))AS DATETIME), 
         					@dat_fin = CAST( floor(CAST(dat_fin AS FLOAT ))AS DATETIME),
         					@jours_total = datediff(d, @dat_debut, @dat_fin)
         			from MODULE_PEC
         			where MODULE_PEC.ID_MODULE_PEC = @ID_MODULE
         		else 
         			select  @dat_debut = CAST( floor(CAST(max(SESSION_PEC.DAT_DEBUT) AS FLOAT ))AS DATETIME), 
         					@dat_fin = CAST( floor(CAST(max(SESSION_PEC.DAT_FIN) AS FLOAT ))AS DATETIME),
         					@jours_total = datediff(d, @dat_debut, @dat_fin)
         			from SESSION_PEC
         			where ID_SESSION_PEC = @ID_SESSION
         	end

         	IF (datepart(yy,@dat_debut) = datepart(yy,@dat_fin) 
         		OR @DATE is not null) 
         	BEGIN
         		IF @DATE is null
         			select @DATE = @dat_debut
         		select @id_periode = PERIODE.ID_PERIODE
         		from PERIODE
         		where ID_TYPE_PERIODE = 1 and
         		(@DATE >=DAT_DEB_PERIODE and @DATE <= DAT_FIN_PERIODE)

         		if @id_periode is not null
         			INSERT INTO MVT_BUDGETAIRE_PERIODE
         				   (DAT_CREATION,MNT_MVT_BUDG_PERIODE,ID_PERIODE,ID_DISPOSITIF,ID_BRANCHE, ID_MODULE_PEC, ID_ENVELOPPE, ID_COMPTE, ID_TYPE_FINANCEMENT, TYPE_ENREGISTREMENT)
         			VALUES
         			   (GetDate(), 
         				@MNT,
         				@id_periode,
         				@ID_DISPOSITIF,
         				@ID_BRANCHE,
         				@ID_MODULE,
         				@ID_ENVELOPPE, 
         				@ID_COMPTE, 
         				@ID_TYPE_FINANCEMENT,
         				@TYPE_ENREGISTREMENT	)

         	END
         	ELSE      
         	BEGIN
         		declare @mnt_calcule decimal (18,2)
         		declare @control_sum decimal (18,2)
         		set @control_sum = 0
         		DECLARE periode_cursor CURSOR FOR
         			select PERIODE.ID_PERIODE,
         			datediff(d,@dat_debut, DAT_FIN_PERIODE) as jours
         			from PERIODE
         			where ID_TYPE_PERIODE = 1 and
         			((@dat_debut >=DAT_DEB_PERIODE) and (@dat_debut <= DAT_FIN_PERIODE)) 
         			union
         			select PERIODE.ID_PERIODE,
         			datediff(d,DAT_DEB_PERIODE, @dat_fin)+1 as jours
         			from PERIODE
         			where ID_TYPE_PERIODE = 1 and
         			((@dat_fin>=DAT_DEB_PERIODE) and (@dat_fin <= DAT_FIN_PERIODE)) 
         			union
         			select PERIODE.ID_PERIODE,
         			datediff(d,DAT_DEB_PERIODE, DAT_FIN_PERIODE)+1 as jours 
         			from PERIODE
         			where ID_TYPE_PERIODE = 1 and
         			(DAT_DEB_PERIODE>@dat_debut and DAT_FIN_PERIODE <@dat_fin)

         		OPEN periode_cursor
         		FETCH NEXT FROM periode_cursor
         		INTO @id_periode, @jours_periode
         		WHILE @@FETCH_STATUS = 0
         		BEGIN
         			if @id_periode is not null
         			begin
         				set @mnt_calcule = round(@MNT*(cast(@jours_periode as decimal(18,2))/ cast(@jours_total as decimal(18,2))), 2)
         				set @control_sum = @control_sum + @mnt_calcule
         				INSERT INTO MVT_BUDGETAIRE_PERIODE
         				   (DAT_CREATION,MNT_MVT_BUDG_PERIODE,ID_PERIODE,ID_DISPOSITIF,ID_BRANCHE, ID_MODULE_PEC, ID_ENVELOPPE, ID_COMPTE, ID_TYPE_FINANCEMENT, TYPE_ENREGISTREMENT)
         				VALUES
         				   (GetDate(), 
         					round(@MNT*(cast(@jours_periode as decimal(18,2))/ cast(@jours_total as decimal(18,2))), 2),
         					@id_periode,
         					@ID_DISPOSITIF,
         					@ID_BRANCHE,
         					@ID_MODULE,
         					@ID_ENVELOPPE, 
         					@ID_COMPTE, 
         					@ID_TYPE_FINANCEMENT,
         					@TYPE_ENREGISTREMENT)
         			end
         			FETCH NEXT FROM periode_cursor
         			INTO @id_periode, @jours_periode
         		END
         		CLOSE periode_cursor
         		DEALLOCATE periode_cursor

         		select @control_sum = @MNT - @control_sum
         		if (@control_sum <> 0)
         		begin
         			UPDATE MVT_BUDGETAIRE_PERIODE
         			SET MNT_MVT_BUDG_PERIODE = MNT_MVT_BUDG_PERIODE + @control_sum
         			WHERE ID_MVT_BUDG_PERIODE = @@IDENTITY
         		end
         	END
         END

GO

         CREATE PROCEDURE DBO.BATCH_COMPENSATION_FPSPP_PLASTURGIE
         AS
         BEGIN

         	RETURN;

         	DECLARE
         		@ID_OPTION_PLASTA INT

         	SELECT
         		@ID_OPTION_PLASTA = ID_OPTION
         	FROM
         		OPTIONS
         	WHERE
         		COD_OPTION = 'PLASTA';

         	WITH LISTE_ETABS
         		AS (
         		SELECT
         			POSTE_VERSEMENT.ID_ETABLISSEMENT_BENEFICIAIRE AS ID_ETAB,
         			sum(POSTE_IMPUTATION.MNT_HT) AS ACOMPTESPLANDONTFPSPP,

         			SUM(isnull(POSTE_IMPUTATION.DONT_REGLE_FPSPP, 0))  AS DEJA_REGLE_FPSPP,

         			R20.ID_TYPE_ASSUJETISSEMENT,
         			max(VERSEMENT.ID_VERSEMENT) AS ID_VERSEMENT,

         			MAX(POSTE_IMPUTATION.ID_ACTIVITE ) AS ID_ACTIVITE,
         			POSTE_VERSEMENT.ID_PERIODE
         		FROM
         			VERSEMENT
         			INNER JOIN POSTE_VERSEMENT
         				ON POSTE_VERSEMENT.ID_VERSEMENT=VERSEMENT.ID_VERSEMENT
         			INNER JOIN TYPE_VERSEMENT
         				ON POSTE_VERSEMENT.ID_TYPE_VERSEMENT=TYPE_VERSEMENT.ID_TYPE_VERSEMENT
         			INNER JOIN POSTE_IMPUTATION
         				ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT=POSTE_VERSEMENT.ID_POSTE_VERSEMENT
         				AND POSTE_IMPUTATION.ID_ACTIVITE IN(4, 5) 
         			INNER JOIN R20
         				ON R20.ID_PERIODE=19
         				AND R20.ID_ADHERENT=VERSEMENT.ID_ADHERENT_EMETTEUR
         				AND POSTE_VERSEMENT.ID_PERIODE=R20.ID_PERIODE
         			INNER JOIN ETABLISSEMENT
         				ON POSTE_VERSEMENT.ID_ETABLISSEMENT_BENEFICIAIRE=ETABLISSEMENT.ID_ETABLISSEMENT
         				AND ETABLISSEMENT.BLN_ACTIF=1
         			INNER JOIN R20BIS
         				ON R20BIS.ID_GROUPE=ETABLISSEMENT.ID_GROUPE
         				AND R20BIS.ID_PERIODE=R20.ID_PERIODE
         				AND R20BIS.ID_OPTION=@ID_OPTION_PLASTA
         			LEFT JOIN BORDEREAU
         				ON VERSEMENT.ID_BORDEREAU=BORDEREAU.ID_BORDEREAU
         		WHERE
         			VERSEMENT.BLN_IMPAYE = 0 
         			AND
         			(
         				TYPE_VERSEMENT.BLN_VERSEMENT_INITIAL = 1
         				AND BORDEREAU.ID_LOT_REMISE_BANCAIRE IS NOT NULL 

         				OR 
         				(
         					TYPE_VERSEMENT.BLN_VERSEMENT_INITIAL = 0
         					AND
         					(
         						TYPE_VERSEMENT.BLN_VERSEMENT=1
         						OR VERSEMENT.DAT_VALID_VERSEMENT IS NOT NULL
         					)
         				)
         			)
         			AND TYPE_VERSEMENT.GRP_TYPE_VERSEMENT = 'V'	
         		GROUP BY
         			POSTE_VERSEMENT.ID_ETABLISSEMENT_BENEFICIAIRE,
         			R20.ID_TYPE_ASSUJETISSEMENT,
         			POSTE_VERSEMENT.ID_PERIODE
         		)

         		SELECT
         			ETABLISSEMENT.ID_ADHERENT,
         			LISTE_ETABS.ID_ETAB,
         			LISTE_ETABS.ACOMPTESPLANDONTFPSPP,
         			LISTE_ETABS.DEJA_REGLE_FPSPP ,
         			LISTE_ETABS.ID_ACTIVITE,
         			round(MASSE_SALARIALE_REELLE  *isnull(PARAMETRE_GLOBAL.TAU_GLO_APPEL, 0)/100 *isnull(PARAMETRE_APPEL.PRC_APPELE, 0) /100 *isnull(PARAMETRE_APPEL.
         PRC_FPSPP, 0) /100 , 2) AS DU_FPSPP
         		INTO
         			#TMP_ETAB
         		FROM
         			LISTE_ETABS
         			INNER JOIN ETABLISSEMENT ON ETABLISSEMENT.ID_ETABLISSEMENT=LISTE_ETABS.ID_ETAB
         			INNER JOIN ADHERENT ON ETABLISSEMENT.ID_ADHERENT=ADHERENT.ID_ADHERENT
         			INNER JOIN R21_BIS ON
         								  R21_BIS.ID_ETABLISSEMENT=ETABLISSEMENT.ID_ETABLISSEMENT
         							  AND R21_BIS.ID_PERIODE=LISTE_ETABS.ID_PERIODE
         			INNER JOIN BRANCHE ON ADHERENT.ID_BRANCHE=BRANCHE.ID_BRANCHE
         			INNER JOIN PARAMETRE_GLOBAL ON
         										   PARAMETRE_GLOBAL.ID_ACTIVITE=LISTE_ETABS.ID_ACTIVITE
         									   AND PARAMETRE_GLOBAL.ID_PERIODE=LISTE_ETABS.ID_PERIODE
         									   AND PARAMETRE_GLOBAL.ID_TYPE_ASSUJETISSEMENT=LISTE_ETABS.ID_TYPE_ASSUJETISSEMENT
         									   AND PARAMETRE_GLOBAL.ID_REGIME=BRANCHE.ID_REGIME
         									   AND PARAMETRE_GLOBAL.BLN_ACTIF=1
         			INNER JOIN PARAMETRE_APPEL ON
         										  PARAMETRE_APPEL.ID_PARAM_GLO=PARAMETRE_GLOBAL.ID_PARAM_GLO
         									  AND PARAMETRE_APPEL.ID_TYPE_VERSEMENT=4
         									  AND 
         										  PARAMETRE_APPEL.BLN_ACTIF=1
         		WHERE
         			  ACOMPTESPLANDONTFPSPP - DEJA_REGLE_FPSPP > 0.00001 
         		  AND isnull(MASSE_SALARIALE_REELLE, 0) > 0

         	DECLARE
         		@ID_ADH INT,
         		@ID_ETAB INT,
         		@ID_ACTIVITE INT,
         		@ACOMPTEDISPO DECIMAL(18, 2),
         		@RESTANT_DU_FPSPP DECIMAL(18, 2),
         		@REGUL_FPSSP DECIMAL(18, 2)

         	DECLARE CURS_ADH CURSOR
         		FOR
         			SELECT
         				ID_ADHERENT,
         				ID_ETAB,
         				ACOMPTESPLANDONTFPSPP - DEJA_REGLE_FPSPP,
         				DU_FPSPP - DEJA_REGLE_FPSPP,
         				ID_ACTIVITE
         			FROM #TMP_ETAB
         			WHERE 	
         			ABS(DU_FPSPP - DEJA_REGLE_FPSPP) > 0.00001  

         	OPEN CURS_ADH
         	FETCH NEXT FROM CURS_ADH
         	INTO @ID_ADH, @ID_ETAB, @ACOMPTEDISPO, @RESTANT_DU_FPSPP, @ID_ACTIVITE
         	WHILE @@FETCH_STATUS = 0
         		BEGIN

         			SET @REGUL_FPSSP = DBO.GETMIN (@ACOMPTEDISPO, @RESTANT_DU_FPSPP)
         			EXEC CREER_REGULARISATION_PV_PI
         			@ID_ADHERENT_EMETTEUR = @ID_ADH,
         			@ID_TIERS_EMETTEUR = NULL,
         			@ID_ETABLISSEMENT_EMETTEUR = @ID_ETAB ,
         			@MNT_VERSEMENT = @REGUL_FPSSP,
         			@ID_TYPE_VERSEMENT = 5,
         			@ID_PERIODE = 19,
         			@ID_ACTIVITE = @ID_ACTIVITE,
         			@DONT_FPSPP = @REGUL_FPSSP

         			SET @REGUL_FPSSP = -1 * @REGUL_FPSSP 
         			EXEC CREER_REGULARISATION_PV_PI
         			@ID_ADHERENT_EMETTEUR = @ID_ADH,
         			@ID_TIERS_EMETTEUR = NULL,
         			@ID_ETABLISSEMENT_EMETTEUR =  @ID_ETAB,
         			@MNT_VERSEMENT = @REGUL_FPSSP,
         			@ID_TYPE_VERSEMENT = 7,
         			@ID_PERIODE = 19,
         			@ID_ACTIVITE = @ID_ACTIVITE,
         			@DONT_FPSPP = 0
         			FETCH NEXT FROM CURS_ADH INTO @ID_ADH, @ID_ETAB, @ACOMPTEDISPO, @RESTANT_DU_FPSPP, @ID_ACTIVITE
         		END
         	CLOSE CURS_ADH
         	DEALLOCATE CURS_ADH
         END
GO

         CREATE PROCEDURE [dbo].[INS_MVT_BUDG_PERIODE_PRO] 
         	@ID_MODULE int,
         	@ID_DISPOSITIF int,
         	@ID_BRANCHE int,
         	@ID_ENVELOPPE int,
         	@ID_COMPTE int,
         	@ID_TYPE_FINANCEMENT int,		
         	@TYPE_ENREGISTREMENT varchar(3),
         	@MNT decimal(18,2),

         	@ID_SESSION int,
         	@DATE datetime = NULL  
         AS
         BEGIN
         	SET NOCOUNT ON;

         	DECLARE @dat_debut datetime
         	DECLARE @dat_fin datetime
         	DECLARE @jours_total int
         	DECLARE @id_periode int
         	DECLARE @jours_periode int

         	if @TYPE_ENREGISTREMENT in ('CP', 'ENP') 

         	begin
         		select  @dat_debut = CAST( floor(CAST(max(SESSION_PRO.DAT_FIN) AS FLOAT ))AS DATETIME), 
         				@dat_fin = CAST( floor(CAST(max(MODULE_PRO.dat_fin) AS FLOAT ))AS DATETIME),
         				@jours_total = datediff(d, @dat_debut, @dat_fin)
         		from MODULE_PRO
         			inner join SESSION_PRO on (SESSION_PRO.ID_MODULE_PRO = MODULE_PRO.ID_MODULE_PRO)
         		where MODULE_PRO.ID_MODULE_PRo = @ID_MODULE
         	end	

         	if @DATE is null and @dat_debut is null	
         	begin
         		if @ID_SESSION is null
         			select  @dat_debut = CAST( floor(CAST(dat_debut AS FLOAT ))AS DATETIME), 
         					@dat_fin = CAST( floor(CAST(dat_fin AS FLOAT ))AS DATETIME),
         					@jours_total = datediff(d, @dat_debut, @dat_fin)
         			from MODULE_PRO
         			where MODULE_PRO.ID_MODULE_PRO = @ID_MODULE
         		else
         			select  @dat_debut = CAST( floor(CAST(dat_debut AS FLOAT ))AS DATETIME), 
         					@dat_fin = CAST( floor(CAST(dat_fin AS FLOAT ))AS DATETIME),
         					@jours_total = datediff(d, @dat_debut, @dat_fin)
         			from SESSION_PRO
         			where ID_SESSION_PRO = @ID_SESSION
         	end

         if (@ID_ENVELOPPE is null and @ID_COMPTE is null)
         begin
         	declare @id_dispo_module int
         	declare @id_periode_module int
         	declare @ID_AGENCE int
         	select 
         		@id_dispo_module = case when ID_TYPE_FORMATION = 3 then 7 
         								else 5 end, 
         		@id_periode_module = MODULE_PRO.ID_PERIODE,
         		@ID_AGENCE = CONTRAT_PRO.ID_AGENCE
         	from MODULE_PRO 
         		inner join CONTRAT_PRO on (CONTRAT_PRO.ID_CONTRAT_PRO = MODULE_PRO.ID_CONTRAT_PRO)
         	where ID_MODULE_PRO = @ID_MODULE

         	select @ID_ENVELOPPE = id_enveloppe 
         	from enveloppe 
         	inner join type_enveloppe on (type_enveloppe.id_type_enveloppe = enveloppe.id_type_enveloppe)
         	where type_enveloppe.ID_BRANCHE = @ID_BRANCHE
         	and type_enveloppe.ID_DISPOSITIF = @id_dispo_module
         	and type_enveloppe.ID_AGENCE = @ID_AGENCE
         	and enveloppe.id_periode = @id_periode_module
         end

         	IF (datepart(yy,@dat_debut) = datepart(yy,@dat_fin) 
         		OR @DATE is not null) 
         	BEGIN
         		IF @DATE is null
         			select @DATE = @dat_debut
         		select @id_periode = PERIODE.ID_PERIODE
         		from PERIODE
         		where ID_TYPE_PERIODE = 1 and
         		(@DATE >=DAT_DEB_PERIODE and @DATE <= DAT_FIN_PERIODE)

         		if (@id_periode is not null and @MNT <> 0)
         			INSERT INTO MVT_BUDGETAIRE_PERIODE
         				   (DAT_CREATION,MNT_MVT_BUDG_PERIODE,ID_PERIODE,ID_DISPOSITIF,ID_BRANCHE, ID_MODULE_PRO, ID_ENVELOPPE, ID_COMPTE, ID_TYPE_FINANCEMENT, TYPE_ENREGISTREMENT)
         			VALUES
         			   (GetDate(), 
         				@MNT,
         				@id_periode,
         				@ID_DISPOSITIF,
         				@ID_BRANCHE,
         				@ID_MODULE,
         				@ID_ENVELOPPE, 
         				@ID_COMPTE, 
         				@ID_TYPE_FINANCEMENT,
         				@TYPE_ENREGISTREMENT	)

         	END
         	ELSE      
         	BEGIN
         		declare @mnt_calcule decimal (18,2)
         		declare @control_sum decimal (18,2)
         		set @control_sum = 0
         		DECLARE periode_cursor CURSOR FOR
         			select PERIODE.ID_PERIODE,
         			datediff(d,@dat_debut, DAT_FIN_PERIODE) as jours
         			from PERIODE
         			where ID_TYPE_PERIODE = 1 and
         			((@dat_debut >=DAT_DEB_PERIODE) and (@dat_debut <= DAT_FIN_PERIODE)) 
         			union
         			select PERIODE.ID_PERIODE,
         			datediff(d,DAT_DEB_PERIODE, @dat_fin)+1 as jours
         			from PERIODE
         			where ID_TYPE_PERIODE = 1 and
         			((@dat_fin>=DAT_DEB_PERIODE) and (@dat_fin <= DAT_FIN_PERIODE)) 
         			union
         			select PERIODE.ID_PERIODE,
         			datediff(d,DAT_DEB_PERIODE, DAT_FIN_PERIODE)+1 as jours 
         			from PERIODE
         			where ID_TYPE_PERIODE = 1 and
         			(DAT_DEB_PERIODE>@dat_debut and DAT_FIN_PERIODE <@dat_fin)

         		OPEN periode_cursor
         		FETCH NEXT FROM periode_cursor
         		INTO @id_periode, @jours_periode
         		WHILE @@FETCH_STATUS = 0
         		BEGIN
         			if @id_periode is not null
         			begin
         				set @mnt_calcule = round(@MNT*(cast(@jours_periode as float)/ cast(@jours_total as float)), 2)
         				set @control_sum = @control_sum + @mnt_calcule
         				if @mnt_calcule <> 0
         				begin
         					INSERT INTO MVT_BUDGETAIRE_PERIODE
         					   (DAT_CREATION,MNT_MVT_BUDG_PERIODE,ID_PERIODE,ID_DISPOSITIF,ID_BRANCHE, ID_MODULE_PRO, ID_ENVELOPPE, ID_COMPTE, ID_TYPE_FINANCEMENT, TYPE_ENREGISTREMENT)
         					VALUES
         					   (GetDate(), 
         						@mnt_calcule,
         						@id_periode,
         						@ID_DISPOSITIF,
         						@ID_BRANCHE,
         						@ID_MODULE,
         						@ID_ENVELOPPE, 
         						@ID_COMPTE, 
         						@ID_TYPE_FINANCEMENT,
         						@TYPE_ENREGISTREMENT)
         				end
         			end
         			FETCH NEXT FROM periode_cursor
         			INTO @id_periode, @jours_periode
         		END
         		CLOSE periode_cursor
         		DEALLOCATE periode_cursor

         		select @control_sum = @MNT - @control_sum
         		if (@control_sum <> 0)
         		begin
         			UPDATE MVT_BUDGETAIRE_PERIODE
         			SET MNT_MVT_BUDG_PERIODE = MNT_MVT_BUDG_PERIODE + @control_sum
         			WHERE ID_MVT_BUDG_PERIODE = @@IDENTITY
         		end
         	END
         END
GO

         CREATE PROCEDURE dbo.INS_POSTE_IMPUTATION
         	@ID_ACTIVITE							INT,
         	@ID_POSTE_VERSEMENT						INT,
         	@ID_VIREMENT_INTERNE_COLLECTE			INT,
         	@MNT_HT									DECIMAL(18, 2),
         	@MNT_TVA								DECIMAL(18, 2),
         	@MNT_TTC								DECIMAL(18, 2),
         	@DAT_MAJ_CPT_ADH						DATETIME,
         	@ID_VIREMENT_INTERNE_COLLECTE_IMPAYE	INT,
         	@DONT_REGLE_FPSPP						DECIMAL(18, 2)
         AS
         BEGIN
         	INSERT INTO POSTE_IMPUTATION
         	(
         		ID_ACTIVITE,
         		ID_POSTE_VERSEMENT,
         		ID_VIREMENT_INTERNE_COLLECTE,
         		MNT_HT,
         		MNT_TVA,
         		MNT_TTC,
         		DAT_MAJ_CPT_ADH,
         		ID_VIREMENT_INTERNE_COLLECTE_IMPAYE,
         		DONT_REGLE_FPSPP 
         	)
         	VALUES
         	(
         		@ID_ACTIVITE,
         		@ID_POSTE_VERSEMENT,
         		@ID_VIREMENT_INTERNE_COLLECTE,
         		@MNT_HT,
         		@MNT_TVA,
         		@MNT_TTC,
         		@DAT_MAJ_CPT_ADH,
         		@ID_VIREMENT_INTERNE_COLLECTE_IMPAYE,
         		@DONT_REGLE_FPSPP
         	)

         	DECLARE
         		@ID_POSTE_IMPUTATION AS INT

         	SET @ID_POSTE_IMPUTATION = scope_identity()

         	RETURN @ID_POSTE_IMPUTATION
         END
GO

         CREATE PROCEDURE LEC_GRP_REGLEMENT
         	@GENERATION_ONLY	TINYINT = NULL,
         	@MODE_CRITERE		SMALLINT = NULL,
         	@ID_UTILISATEUR		INT = NULL
         AS
         BEGIN

         	SELECT
         		ID_ETABLISSEMENT_OF,
         		COUNT(*) AS NB_POSTE_COUT_REGLE 
         	INTO
         		#TMP_PCR
         	FROM
         		POSTE_COUT_REGLE 
         		INNER JOIN MODULE_PEC ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC
         	WHERE
         		MODULE_PEC.ID_ETABLISSEMENT_OF IS NOT NULL
         		AND	MODULE_PEC.BLN_ACTIF = 1
         		AND POSTE_COUT_REGLE.BLN_ACTIF = 1
         		AND	@MODE_CRITERE IS NOT NULL
         	GROUP BY
         		ID_ETABLISSEMENT_OF

         	SELECT
         		ID_REGLEMENT, 
         		CASE
         			WHEN (COUNT(*) > 0)
         				THEN	1 
         			ELSE		0 
         		END AS IBAN_MODIFIE 
         	INTO
         		#TMP_PCR_VALID_6
         	FROM
         		POSTE_COUT_REGLE
         	WHERE
         		POSTE_COUT_REGLE.ID_ETAT_PEC = 8
         		AND	@MODE_CRITERE IS NOT NULL
         	GROUP BY
         		POSTE_COUT_REGLE.ID_REGLEMENT

         	DECLARE
         		@NB_REGL INT

         	SET
         		@NB_REGL =
         		(
         			SELECT
         				COUNT(R.ID_REGLEMENT) 
         			FROM
         				REGLEMENT R
         				INNER JOIN [TRANSACTION] T ON T.ID_TRANSACTION	= R.ID_TRANSACTION	
         			WHERE
         				(
         					(
         						@GENERATION_ONLY	= 1
         						AND	DAT_GENERATION_SEPA	IS NOT NULL
         					)	
         					OR 
         					(
         						@GENERATION_ONLY	= 0
         						AND	DAT_GENERATION_SEPA	IS NULL
         						AND R.BLN_ACTIF = 1
         						AND DAT_VALID_REGLEMENT	IS NOT NULL
         					)
         					OR 
         					(
         						@GENERATION_ONLY		IS NULL
         					)
         				) 
         				AND MNT_REGLE_TTC	<> 0
         				AND
         				(
         					@MODE_CRITERE IS NULL
         					OR 
         					(
         						@MODE_CRITERE IS NOT NULL
         						AND R.BLN_ACTIF = 1
         						AND R.BLN_EN_COURS = 1
         						AND R.DAT_VALID_REGLEMENT IS NULL
         						AND R.DAT_EDITION IS NULL
         					)
         				)
         		)

         		SELECT DISTINCT	
         			R.ID_REGLEMENT,
         			R.COD_REGLEMENT, 
         			R.NUM_CHEQUE,
         			R.NUM_VIREMENT, 
         			R.DAT_REGLEMENT,
         			R.DAT_EDITION, 
         			ISNULL(R.MNT_REGLE_TTC, 0)	AS MNT_REGLE_TTC,
         			ISNULL(R.MNT_REGLE_HT, 0)	AS MNT_REGLE_HT,
         			R.BLN_ACTIF,
         			R.COM_REGLEMENT, 
         			R.DAT_VALID_REGLEMENT,
         			R.DAT_COMPTA_REGLEMENT, 
         			R.DAT_MAJ_CPT_ADH,
         			R.TIME_STAMP, 
         			R.BLN_EN_COURS,
         			R.BLN_CRITERE, 
         			R.ID_TRANSACTION,
         			R.DAT_GENERATION_SEPA, 
         			R.ID_AGENCE,
         			AGENCE.LIBC_AGENCE,

         			T.NUM_IBAN					AS NUM_IBAN,
         			@NB_REGL					AS NB_REGL,
         			COALESCE(T.ID_ETABLISSEMENT_BENEF, 
         						T.ID_ETABLISSEMENT_OF_BENEF,
         						T.ID_TIERS_BENEF)	AS ID_BENEF,
         			CASE
         				WHEN (T.ID_ETABLISSEMENT_BENEF		IS NOT NULL)	THEN A2.LIB_RAISON_SOCIALE
         				WHEN (T.ID_ETABLISSEMENT_OF_BENEF	IS NOT NULL)	THEN O2.LIB_RAISON_SOCIALE
         				WHEN (T.ID_TIERS_BENEF				IS NOT NULL)	THEN TI.LIB_NOM
         				ELSE													 'ERREUR'
         			END							AS LIB_BENEF,
         			COALESCE(1 * T.ID_ETABLISSEMENT_BENEF/T.ID_ETABLISSEMENT_BENEF, 
         						2 * T.ID_ETABLISSEMENT_OF_BENEF/T.ID_ETABLISSEMENT_OF_BENEF,
         						3 * T.ID_TIERS_BENEF/T.ID_TIERS_BENEF)
         										AS ID_TYPE_BENEFICIAIRE,
         			CASE
         				WHEN (T.ID_ETABLISSEMENT_BENEF		IS NOT NULL)	THEN 'ADHERENT'
         				WHEN (T.ID_ETABLISSEMENT_OF_BENEF	IS NOT NULL)	THEN 'ETABLISSEMENT'
         				WHEN (T.ID_TIERS_BENEF				IS NOT NULL)	THEN 'TIERS'
         				ELSE													 'ERREUR'
         			END							AS LIB_TYPE_BENEFICIAIRE,
         			ISNULL(
         				(SELECT COUNT(*)
         				FROM POSTE_COUT_REGLE 
         				WHERE POSTE_COUT_REGLE.ID_REGLEMENT = R.ID_REGLEMENT)
         				, 0)
         										AS NOMBRE_DOSSIERS,
         			CASE
         				WHEN (T.ID_ETABLISSEMENT_DEST		IS NOT NULL)	THEN A2.ID_ADHERENT
         				WHEN (T.ID_ETABLISSEMENT_OF_DEST	IS NOT NULL)	THEN O2.ID_OF
         				ELSE													 NULL
         			END							AS ID_DEST,
         			COALESCE(1 * T.ID_ETABLISSEMENT_DEST / T.ID_ETABLISSEMENT_DEST, 
         						2 * T.ID_ETABLISSEMENT_OF_DEST / T.ID_ETABLISSEMENT_OF_DEST)
         						 				AS ID_TYPE_DEST,
         			CASE
         				WHEN (T.ID_ETABLISSEMENT_OF_DEST IS NOT NULL AND 
         						(O.DAT_CREATION > DATEADD(MM, -3, GETDATE()) OR NB_POSTE_COUT_REGLE < 10) ) THEN 1
         				ELSE 0
         			END							AS NOUVEAUX_OF,
         			ISNULL(P6.IBAN_MODIFIE, 0)	AS IBAN_MODIFIE
         		FROM        
         			REGLEMENT R
         			LEFT  JOIN AGENCE					ON AGENCE.ID_AGENCE					= R.ID_AGENCE					AND @MODE_CRITERE IS NOT NULL
         			INNER JOIN [TRANSACTION] T			ON T.ID_TRANSACTION					= R.ID_TRANSACTION
         			LEFT  JOIN ADHERENT A				ON A.ID_ETABLISSEMENT_PRINCIPAL		= T.ID_ETABLISSEMENT_BENEF		AND @MODE_CRITERE IS NOT NULL
         			LEFT  JOIN ORGANISME_FORMATION O	ON O.ID_ETABLISSEMENT_OF_PRINCIPAL	= T.ID_ETABLISSEMENT_OF_BENEF	AND @MODE_CRITERE IS NOT NULL
         			LEFT  JOIN TIERS TI					ON TI.ID_TIERS						= T.ID_TIERS_BENEF				AND @MODE_CRITERE IS NOT NULL
         			LEFT  JOIN ADHERENT A2				ON A2.ID_ETABLISSEMENT_PRINCIPAL	= T.ID_ETABLISSEMENT_DEST		AND @MODE_CRITERE IS NOT NULL
         			LEFT  JOIN ORGANISME_FORMATION O2	ON O2.ID_ETABLISSEMENT_OF_PRINCIPAL	= T.ID_ETABLISSEMENT_OF_DEST	AND @MODE_CRITERE IS NOT NULL
         			LEFT  JOIN #TMP_PCR	P				ON P.ID_ETABLISSEMENT_OF			= T.ID_ETABLISSEMENT_OF_DEST	AND @MODE_CRITERE IS NOT NULL
         			LEFT  JOIN #TMP_PCR_VALID_6 P6		ON P6.ID_REGLEMENT					= R.ID_REGLEMENT				AND @MODE_CRITERE IS NOT NULL
         		WHERE
         			(
         				(
         					@GENERATION_ONLY	= 1
         					AND	DAT_GENERATION_SEPA	IS NOT NULL
         				)	
         				OR 
         				(
         					@GENERATION_ONLY	= 0
         					AND	DAT_GENERATION_SEPA	IS NULL
         					AND R.BLN_ACTIF = 1
         					AND DAT_VALID_REGLEMENT	IS NOT NULL
         				)
         				OR 
         				(
         					@GENERATION_ONLY	IS NULL
         				)
         			)
         			AND MNT_REGLE_TTC	<> 0
         			AND
         			(
         				@MODE_CRITERE IS NULL
         				OR 
         				(
         					@MODE_CRITERE IS NOT NULL
         					AND R.BLN_ACTIF = 1
         					AND R.BLN_EN_COURS = 1
         					AND R.DAT_VALID_REGLEMENT IS NULL
         					AND R.DAT_EDITION IS NULL
         				)
         			)
         			AND
         			(
         				R.ID_UTILISATEUR = @ID_UTILISATEUR
         				OR @ID_UTILISATEUR IS NULL
         			)
         END
GO

         CREATE PROCEDURE [dbo].[GESTION_STAGIAIRE_PEC_CDC]
         @ID_STAGIAIRE int,
         @NUM_DOSSIER_CDC bigint,
         @DATE_ACCORD_TITULAIRE smalldatetime,
         @ID_UTILISATEUR_CREATEUR int,
         @ID_UTILISATEUR int

         AS  
         BEGIN

         DECLARE
           @COUNT INT

         		SELECT
         		  @COUNT = COUNT(*)
         		 FROM
         		  STAGIAIRE_PEC_CDC
         		 WHERE
         		  ID_STAGIAIRE_PEC = @ID_STAGIAIRE

         		IF (@COUNT > 0 )
         		BEGIN

         			UPDATE [STAGIAIRE_PEC_CDC]
         			SET 
         			NUM_DOSSIER_CDC = @NUM_DOSSIER_CDC ,
         			DATE_ACCORD_TITULAIRE = @DATE_ACCORD_TITULAIRE ,
         			ID_UTILISATEUR_CREATEUR = @ID_UTILISATEUR_CREATEUR,
         			ID_UTILISATEUR = @ID_UTILISATEUR,
         			DAT_MODIF = GETDATE()
         			WHERE ID_STAGIAIRE_PEC = @ID_STAGIAIRE

         		END
         		ELSE
         		BEGIN

         			INSERT INTO [STAGIAIRE_PEC_CDC]
         			(
         			NUM_DOSSIER_CDC,
         			ID_STAGIAIRE_PEC,
         			DATE_ACCORD_TITULAIRE  ,
         			ID_UTILISATEUR_CREATEUR ,
         			ID_UTILISATEUR ,
         			DAT_CREATION ,
         			DAT_MODIF 

         			)
         			VALUES
         			(
         				@NUM_DOSSIER_CDC,
         				@ID_STAGIAIRE,
         				@DATE_ACCORD_TITULAIRE,
         				@ID_UTILISATEUR_CREATEUR,
         				@ID_UTILISATEUR,
         				GETDATE(),
         				GETDATE()
         			)

         		END	
         END

GO

         CREATE PROCEDURE [dbo].[EDT_LETTRE_REJET_OF]
         		@ID_ETABLISSEMENT int,
         		@ID_BENEFICIAIRE int,
         		@TYPE_BENEFICIAIRE int,
         		@ID_ADRESSE int,
         		@ID_CONTACT int,
         		@ID_MODULE_PEC int
         AS

         BEGIN

         	SELECT DISTINCT ORGANISME_FORMATION.COD_OF,
         					ORGANISME_FORMATION.LIB_RAISON_SOCIALE,
         					AGENCE.ID_AGENCE,
         					AGENCE.COD_POSTAL,
         					AGENCE.LIB_VILLE,
         					AGENCE.LIB_NOM_CONSEILLER,
         					AGENCE.LIB_PNM_CONSEILLER,
         					MODULE_PEC.COD_MODULE_PEC
         	INTO			#TEMP_REFERENCE
         	FROM			ORGANISME_FORMATION 
         					INNER JOIN ETABLISSEMENT_OF ON ORGANISME_FORMATION.ID_OF = ETABLISSEMENT_OF.ID_OF 
         					INNER JOIN MODULE_PEC ON MODULE_PEC.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF
         					INNER JOIN ACTION_PEC ON MODULE_PEC.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC 
         					INNER JOIN AGENCE ON ACTION_PEC.ID_AGENCE = AGENCE.ID_AGENCE 
         	WHERE			MODULE_PEC.ID_MODULE_PEC = @ID_MODULE_PEC;

         	SELECT			MODULE_PEC.ID_MODULE_PEC,
         					MODULE_PEC.COD_MODULE_PEC, 
         					MODULE_PEC.LIBL_MODULE_PEC, 
         					MODULE_PEC.DAT_DEBUT,
         					MODULE_PEC.DAT_FIN,
         					MODULE_PEC.NUM_DUREE_HEURE,
         					ORGANISME_FORMATION.COD_OF,
         					ORGANISME_FORMATION.LIB_RAISON_SOCIALE
         	INTO			#TEMP_MODULE
         	FROM			MODULE_PEC
         					INNER JOIN ETABLISSEMENT_OF ON MODULE_PEC.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF
         					INNER JOIN ORGANISME_FORMATION ON ETABLISSEMENT_OF.ID_OF = ORGANISME_FORMATION.ID_OF 
         	WHERE			MODULE_PEC.ID_MODULE_PEC = @ID_MODULE_PEC;

         	SELECT     		ADHERENT.LIB_RAISON_SOCIALE
         	INTO			#TMP_ADHERENT
         	FROM         	ADHERENT 
         					INNER JOIN ETABLISSEMENT ON ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT 
         					INNER JOIN NR140 ON ETABLISSEMENT.ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT 
         					INNER JOIN ACTION_PEC ON NR140.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC 
         					INNER JOIN MODULE_PEC ON ACTION_PEC.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC
         	WHERE			MODULE_PEC.ID_MODULE_PEC = @ID_MODULE_PEC;

         	WITH XMLNAMESPACES (
         		DEFAULT 'LETTRE_REJET_OF'
         	)

         	SELECT
         		(			

         			SELECT	              	

         				dbo.GetXmlAgenceContact(ENTETE.ID_AGENCE) as EMETTEUR,

         				dbo.GetXmlBenefiaireContact(@ID_BENEFICIAIRE, @TYPE_BENEFICIAIRE, @ID_ADRESSE, @ID_CONTACT) as BENEFICIAIRE,

         				ENTETE.COD_OF,
         				ENTETE.LIB_VILLE,
         				dbo.GetFullDate(getDate()) as DATE,
         				ENTETE.COD_MODULE_PEC

         			FROM #TEMP_REFERENCE AS ENTETE     
         			FOR XML AUTO, ELEMENTS, TYPE
         		),

         		(

         			SELECT	CORPS.LIBL_MODULE_PEC,
         					CONVERT(varchar(10),CORPS.DAT_DEBUT, 103) AS DAT_DEBUT,
         					CONVERT(varchar(10),CORPS.DAT_FIN, 103) AS DAT_FIN,
         					(
         						SELECT CASE 
         							WHEN (SELECT COUNT(*) FROM #TMP_ADHERENT) > 1 THEN 'les entreprises' 
         							ELSE 'l''entreprise'
         							END

         					) AS COMPTEUR,

         					(
         						SELECT	ADHERENT.LIB_RAISON_SOCIALE AS NOM_ADHERENT
         						FROM	#TMP_ADHERENT as ADHERENT
         						FOR XML AUTO, ELEMENTS, TYPE, ROOT('ADHERENTS')

         					),
         					(
         						SELECT	MOTIF_NON_IMPUTABILITE.LIBL_MOTIF_NON_IMPUTABILITE AS LIBELLE
         						FROM	MOTIF_NON_IMPUTABILITE 
         								INNER JOIN  NR204 ON MOTIF_NON_IMPUTABILITE.ID_MOTIF_NON_IMPUTABILITE = NR204.ID_MOTIF_NON_IMPUTABILITE 
         								INNER JOIN  MODULE_PEC ON NR204.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         						WHERE	MODULE_PEC.ID_MODULE_PEC= @ID_MODULE_PEC
         						FOR XML AUTO, ELEMENTS, TYPE, ROOT('MOTIFS')
         					)
         			FROM	#TEMP_MODULE as CORPS
         			FOR XML AUTO, ELEMENTS, TYPE		
         		),

         		(
         			SELECT	SIGNATURE.LIB_PNM_CONSEILLER,
         					SIGNATURE.LIB_NOM_CONSEILLER
         			FROM
         					#TEMP_REFERENCE as SIGNATURE
         			FOR XML AUTO, ELEMENTS, TYPE
         		)

         FROM	#TEMP_MODULE as LETTRE
         	FOR XML AUTO, ELEMENTS
         END

GO

         CREATE PROCEDURE [dbo].[UPD_HISTO_RETOUR_CONTRAT]
         	@STATUT_HISTO				INT	= NULL,	
         	@COD_CONTRAT_PRO			VARCHAR(10),
         	@NUM_DEPOT_DDTE				VARCHAR(50) = NULL,
         	@NUM_ENREGISTREMENT			VARCHAR(20) = NULL,
         	@DAT_DEPOT_DDTE				DATETIME = NULL,
         	@DAT_ENREGISTREMENT_DDTE	DATETIME = NULL,
         	@CODE_TYPE					INT,
         	@EXONERATION_CHARGE			TINYINT = 0,
         	@MOTIF_CONTROL_CONFORMITE	TEXT = NULL,
         	@COMMENTAIRE_COMMANDITAIRE	TEXT = NULL,
         	@ID_UTILISATEUR				INT
         AS

         BEGIN

         	DECLARE @ID_HISTO_CONTRAT_DGEFP INT
         	DECLARE @ID_CONTRAT_PRO INT
         	DECLARE @ID_TYPE_EVENEMENT_ADMIN INT

         	SELECT  @ID_HISTO_CONTRAT_DGEFP = HISTO_CONTRAT_DGEFP.ID_HISTO_CONTRAT_DGEFP,
         			@ID_CONTRAT_PRO			= CONTRAT_PRO.ID_CONTRAT_PRO
         	FROM	CONTRAT_PRO 
         			INNER JOIN HISTO_CONTRAT_DGEFP ON CONTRAT_PRO.ID_CONTRAT_PRO = HISTO_CONTRAT_DGEFP.ID_CONTRAT_PRO
         	WHERE	CONTRAT_PRO.COD_CONTRAT_PRO = @COD_CONTRAT_PRO

         			AND HISTO_CONTRAT_DGEFP.ID_HISTO_CONTRAT_DGEFP = 
         					( 
         						SELECT	MAX(HCD.ID_HISTO_CONTRAT_DGEFP)
         						FROM	HISTO_CONTRAT_DGEFP HCD
         						WHERE	HCD.ID_CONTRAT_PRO = CONTRAT_PRO.ID_CONTRAT_PRO
         					  )

         	IF @DAT_DEPOT_DDTE IS NOT NULL
         		BEGIN
         			UPDATE	CONTRAT_PRO
         			SET		DAT_DEPOT_DDTE = @DAT_DEPOT_DDTE
         			WHERE	CONTRAT_PRO.ID_CONTRAT_PRO = @ID_CONTRAT_PRO
         		END 

         	IF @NUM_ENREGISTREMENT IS NOT NULL
         		BEGIN
         			UPDATE	CONTRAT_PRO
         			SET		NUM_ENREGISTREMENT_DDTE = @NUM_ENREGISTREMENT
         			WHERE	CONTRAT_PRO.ID_CONTRAT_PRO = @ID_CONTRAT_PRO
         		END 

         	IF @EXONERATION_CHARGE IS NOT NULL
         		BEGIN
         			UPDATE	CONTRAT_PRO
         			SET		BLN_EXONERATION_CHARGES = @EXONERATION_CHARGE
         			WHERE	CONTRAT_PRO.ID_CONTRAT_PRO = @ID_CONTRAT_PRO
         		END 

         	IF @CODE_TYPE = 18
         		BEGIN
         			IF @DAT_ENREGISTREMENT_DDTE IS NOT NULL
         				BEGIN
         					UPDATE	CONTRAT_PRO
         					SET		CONTRAT_PRO.DAT_ENREGISTREMENT_DDTE = @DAT_ENREGISTREMENT_DDTE
         					WHERE		CONTRAT_PRO.ID_CONTRAT_PRO = @ID_CONTRAT_PRO

         					UPDATE	HISTO_CONTRAT_DGEFP
         					SET		HISTO_CONTRAT_DGEFP.DAT_ENREGISTREMENT_DDTE = @DAT_ENREGISTREMENT_DDTE			
         					WHERE	HISTO_CONTRAT_DGEFP.ID_HISTO_CONTRAT_DGEFP = @ID_HISTO_CONTRAT_DGEFP

         					UPDATE	HISTO_CONTRAT_DGEFP
         					SET		HISTO_CONTRAT_DGEFP.STATUT_HISTO = 30
         					WHERE	HISTO_CONTRAT_DGEFP.ID_HISTO_CONTRAT_DGEFP = @ID_HISTO_CONTRAT_DGEFP

         				END
         		END

         	ELSE IF @CODE_TYPE = 19
         		BEGIN
         			IF @DAT_ENREGISTREMENT_DDTE IS NOT NULL
         				BEGIN
         					UPDATE	CONTRAT_PRO
         					SET		CONTRAT_PRO.DAT_ENREGISTREMENT_DDTE = @DAT_ENREGISTREMENT_DDTE
         					WHERE		CONTRAT_PRO.ID_CONTRAT_PRO = @ID_CONTRAT_PRO

         					UPDATE	HISTO_CONTRAT_DGEFP
         					SET		HISTO_CONTRAT_DGEFP.DAT_ENREGISTREMENT_DDTE = @DAT_ENREGISTREMENT_DDTE			
         					WHERE	HISTO_CONTRAT_DGEFP.ID_HISTO_CONTRAT_DGEFP = @ID_HISTO_CONTRAT_DGEFP
         				END

         			SET  @STATUT_HISTO = 100

         		END
         	ELSE IF @CODE_TYPE = 20
         		BEGIN
         			SET  @STATUT_HISTO = 50
         		END

         	IF	@STATUT_HISTO IS NOT NULL
         		BEGIN	
         			UPDATE	HISTO_CONTRAT_DGEFP
         			SET		HISTO_CONTRAT_DGEFP.STATUT_HISTO = @STATUT_HISTO			
         			WHERE	HISTO_CONTRAT_DGEFP.ID_HISTO_CONTRAT_DGEFP = @ID_HISTO_CONTRAT_DGEFP
         		END

         	IF (@CODE_TYPE = 4) AND (@STATUT_HISTO IS NULL)
         		BEGIN
         			UPDATE	HISTO_CONTRAT_DGEFP
         			SET		HISTO_CONTRAT_DGEFP.STATUT_HISTO = 30			
         			WHERE	HISTO_CONTRAT_DGEFP.ID_HISTO_CONTRAT_DGEFP = @ID_HISTO_CONTRAT_DGEFP
         		END

         	IF	@NUM_DEPOT_DDTE IS NOT NULL
         		BEGIN	
         			UPDATE	HISTO_CONTRAT_DGEFP
         			SET		HISTO_CONTRAT_DGEFP.NUM_DEPOT_DDTE = @NUM_DEPOT_DDTE
         			WHERE	HISTO_CONTRAT_DGEFP.ID_HISTO_CONTRAT_DGEFP = @ID_HISTO_CONTRAT_DGEFP
         		END

         	IF	@NUM_ENREGISTREMENT IS NOT NULL
         		BEGIN	
         			UPDATE	HISTO_CONTRAT_DGEFP
         			SET		HISTO_CONTRAT_DGEFP.NUM_ENREGISTREMENT_DDTE = @NUM_ENREGISTREMENT
         			WHERE	HISTO_CONTRAT_DGEFP.ID_HISTO_CONTRAT_DGEFP = @ID_HISTO_CONTRAT_DGEFP

         			UPDATE	CONTRAT_PRO
         			SET		NUM_ENREGISTREMENT_DDTE = @NUM_ENREGISTREMENT
         			WHERE	CONTRAT_PRO.ID_CONTRAT_PRO = @ID_CONTRAT_PRO

         		END

         	IF	@MOTIF_CONTROL_CONFORMITE IS NOT NULL
         		BEGIN	
         			UPDATE	HISTO_CONTRAT_DGEFP
         			SET		HISTO_CONTRAT_DGEFP.MOTIF_CONTROL_CONFORMITE = @MOTIF_CONTROL_CONFORMITE
         			WHERE	HISTO_CONTRAT_DGEFP.ID_HISTO_CONTRAT_DGEFP = @ID_HISTO_CONTRAT_DGEFP
         		END

         	IF	@COMMENTAIRE_COMMANDITAIRE IS NOT NULL
         		BEGIN	
         			UPDATE	HISTO_CONTRAT_DGEFP
         			SET		HISTO_CONTRAT_DGEFP.COMMENTAIRE_COMMANDITAIRE = @COMMENTAIRE_COMMANDITAIRE
         			WHERE	HISTO_CONTRAT_DGEFP.ID_HISTO_CONTRAT_DGEFP = @ID_HISTO_CONTRAT_DGEFP
         		END

         	IF	@MOTIF_CONTROL_CONFORMITE IS NOT NULL
         		BEGIN	
         			UPDATE	HISTO_CONTRAT_DGEFP
         			SET		HISTO_CONTRAT_DGEFP.MOTIF_CONTROL_CONFORMITE = @MOTIF_CONTROL_CONFORMITE
         			WHERE	HISTO_CONTRAT_DGEFP.ID_HISTO_CONTRAT_DGEFP = @ID_HISTO_CONTRAT_DGEFP
         		END

         	IF	@EXONERATION_CHARGE  = 1
         		BEGIN	
         			UPDATE	HISTO_CONTRAT_DGEFP
         			SET		HISTO_CONTRAT_DGEFP.BLN_EXONERATION_CHARGES = @EXONERATION_CHARGE
         			WHERE	HISTO_CONTRAT_DGEFP.ID_HISTO_CONTRAT_DGEFP = @ID_HISTO_CONTRAT_DGEFP
         		END

         	IF	@DAT_DEPOT_DDTE IS NOT NULL
         		BEGIN	
         			UPDATE	HISTO_CONTRAT_DGEFP
         			SET		HISTO_CONTRAT_DGEFP.DAT_DEPOT_DDTE = @DAT_DEPOT_DDTE
         			WHERE	HISTO_CONTRAT_DGEFP.ID_HISTO_CONTRAT_DGEFP = @ID_HISTO_CONTRAT_DGEFP

         			UPDATE	CONTRAT_PRO
         			SET		CONTRAT_PRO.DAT_DEPOT_DDTE = @DAT_DEPOT_DDTE
         			WHERE	CONTRAT_PRO.ID_CONTRAT_PRO = @ID_CONTRAT_PRO

         		END

         	IF	@CODE_TYPE = 4 and @DAT_DEPOT_DDTE IS NULL
         		BEGIN	
         			UPDATE	HISTO_CONTRAT_DGEFP
         			SET		HISTO_CONTRAT_DGEFP.DAT_DEPOT_DDTE = @DAT_ENREGISTREMENT_DDTE
         			WHERE	HISTO_CONTRAT_DGEFP.ID_HISTO_CONTRAT_DGEFP = @ID_HISTO_CONTRAT_DGEFP

         			UPDATE	CONTRAT_PRO
         			SET		CONTRAT_PRO.DAT_DEPOT_DDTE = @DAT_ENREGISTREMENT_DDTE
         			WHERE	CONTRAT_PRO.ID_CONTRAT_PRO = @ID_CONTRAT_PRO

         		END

         	IF	@EXONERATION_CHARGE  = 0
         		BEGIN	

         			SELECT  @ID_TYPE_EVENEMENT_ADMIN = ID_TYPE_EVENEMENT_ADMIN
         			FROM	TYPE_EVENEMENT_ADMIN
         			WHERE	COD_TYPE_EVENEMENT_ADMIN = 'REFUDDTE'

         			IF @MOTIF_CONTROL_CONFORMITE IS NULL BEGIN SET @MOTIF_CONTROL_CONFORMITE = '' END

         			EXEC INS_EVENEMENT_ADMIN @MOTIF_CONTROL_CONFORMITE,@ID_UTILISATEUR,@ID_TYPE_EVENEMENT_ADMIN,@ID_CONTRAT_PRO,1,@DAT_ENREGISTREMENT_DDTE
         	END

         END

GO

         CREATE PROCEDURE [dbo].[LEC_GRP_VIREMENT_INTERNE_COLLECTE_REGULARISATION]

         @DATE_DEBUT datetime,
         @DATE_FIN datetime,
         @TYPE_ETAT INTEGER

         AS  

         IF (@TYPE_ETAT = 1)
         	BEGIN

         		SELECT      DISTINCT VIREMENT_INTERNE_COLLECTE.*

         		FROM         VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_IMPUTATION ON VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE = POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_VERSEMENT ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT = POSTE_VERSEMENT.ID_POSTE_VERSEMENT

         					INNER JOIN TYPE_VERSEMENT			ON	POSTE_VERSEMENT.ID_TYPE_VERSEMENT = TYPE_VERSEMENT.ID_TYPE_VERSEMENT

         		WHERE       

         				(TYPE_VERSEMENT.BLN_VERSEMENT = 1 and BLN_VERSEMENT_INITIAL = 0) 

         					AND (VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE IS NULL)
         	END

         ELSE

         	BEGIN

         		SELECT      DISTINCT VIREMENT_INTERNE_COLLECTE.*

         		FROM         VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_IMPUTATION ON VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE = POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_VERSEMENT ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT = POSTE_VERSEMENT.ID_POSTE_VERSEMENT

         					INNER JOIN TYPE_VERSEMENT			ON	POSTE_VERSEMENT.ID_TYPE_VERSEMENT = TYPE_VERSEMENT.ID_TYPE_VERSEMENT

         		WHERE       

         				(TYPE_VERSEMENT.BLN_VERSEMENT = 1 and BLN_VERSEMENT_INITIAL = 0) 

         					AND (RTRIM(@DATE_DEBUT) IS NULL OR (DAT_EDIT_VIREMENT_INTERNE_COLLECTE >= @DATE_DEBUT))
         					AND (RTRIM(@DATE_FIN) IS NULL OR ( DAT_EDIT_VIREMENT_INTERNE_COLLECTE <= @DATE_FIN))
         	END

GO

         CREATE PROCEDURE [dbo].[INS_MOTIF_REFUS_CONTRAT]
         	@ID_CONTRAT_PRO		as int,
         	@ID_MOTIF_REFUS_PRO as int
         AS  
         	IF NOT EXISTS ( SELECT 1 FROM MOTIF_REFUS_CONTRAT WHERE	ID_CONTRAT_PRO		= @ID_CONTRAT_PRO		AND 
         															ID_MOTIF_REFUS_PRO	= @ID_MOTIF_REFUS_PRO)
         	BEGIN	
         		INSERT INTO MOTIF_REFUS_CONTRAT (ID_CONTRAT_PRO, ID_MOTIF_REFUS_PRO) VALUES (@ID_CONTRAT_PRO, @ID_MOTIF_REFUS_PRO)
         	END
GO

         CREATE PROCEDURE [dbo].[LEC_GRP_VIREMENT_INTERNE_COLLECTE_VERSEMENT]

         @DATE_DEBUT datetime,
         @DATE_FIN datetime,
         @TYPE_ETAT INTEGER

         AS  

         IF (@TYPE_ETAT = 1)
         	BEGIN

         		SELECT      DISTINCT VIREMENT_INTERNE_COLLECTE.*

         		FROM         VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_IMPUTATION ON VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE = POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_VERSEMENT ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT = POSTE_VERSEMENT.ID_POSTE_VERSEMENT

         		WHERE       (POSTE_VERSEMENT.ID_TYPE_VERSEMENT = 1 OR
         					POSTE_VERSEMENT.ID_TYPE_VERSEMENT = 2 OR
         					POSTE_VERSEMENT.ID_TYPE_VERSEMENT = 3 OR
         					POSTE_VERSEMENT.ID_TYPE_VERSEMENT = 4)
         					AND (VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE IS NULL)
         	END

         ELSE

         	BEGIN

         		SELECT      DISTINCT VIREMENT_INTERNE_COLLECTE.*

         		FROM         VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_IMPUTATION ON VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE = POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_VERSEMENT ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT = POSTE_VERSEMENT.ID_POSTE_VERSEMENT

         		WHERE       (POSTE_VERSEMENT.ID_TYPE_VERSEMENT = 1 OR
         					POSTE_VERSEMENT.ID_TYPE_VERSEMENT = 2 OR
         					POSTE_VERSEMENT.ID_TYPE_VERSEMENT = 3 OR
         					POSTE_VERSEMENT.ID_TYPE_VERSEMENT = 4)
         					AND (RTRIM(@DATE_DEBUT) IS NULL OR (DAT_EDIT_VIREMENT_INTERNE_COLLECTE >= @DATE_DEBUT))
         					AND (RTRIM(@DATE_FIN) IS NULL OR ( DAT_EDIT_VIREMENT_INTERNE_COLLECTE <= @DATE_FIN))
         	END

GO

         CREATE PROCEDURE dbo.INS_FONCTION
         	@COD_FONCTION VARCHAR(8),  
         	@LIBC_FONCTION VARCHAR(20),  
         	@LIBL_FONCTION VARCHAR(120),  
         	@BLN_PRIO TINYINT,  
         	@BLN_ACTIF TINYINT,  
         	@NUM_ORDRE INTEGER,
         	@ID_UTILISATEUR INTEGER,
         	@COM_FONCTION VARCHAR(255)  
         AS  
         BEGIN
         	DECLARE
         		@CPT INTEGER,
         		@COD_TABLE CHAR(25)

         	INSERT INTO FONCTION
         	(
         		COD_FONCTION,  
         		LIBC_FONCTION,  
         		LIBL_FONCTION,  
         		BLN_PRIO,  
         		BLN_ACTIF,  
         		DAT_MODIF,  
         		NUM_ORDRE,
         		ID_UTILISATEUR ,
         		COM_FONCTION
         	)
         	VALUES  
         	(
         		@COD_FONCTION,  
         		@LIBC_FONCTION,  
         		@LIBL_FONCTION,  
         		@BLN_PRIO,  
         		@BLN_ACTIF,  
         		GETDATE(),  
         		@NUM_ORDRE,
         		@ID_UTILISATEUR ,
         		@COM_FONCTION
         	)

         	SELECT @@IDENTITY AS ID
         END
GO

         CREATE PROCEDURE UPD_INS_EFFECTIF_MOYEN_SYNCHRO 
         	@ID_ADHERENT int, 
         	@ANNEE int,
         	@NUM_EFFECTIF_MOYEN decimal (12,2)
         AS
         BEGIN
         	DECLARE @id_periode int
         	SELECT @id_periode = id_periode from PERIODE where COD_PERIODE = @ANNEE and ID_TYPE_PERIODE = 1
         	if exists( SELECT 1 from R21 where ID_ADHERENT = @ID_ADHERENT and ID_PERIODE = @id_periode)
         		UPDATE R21 set NUM_EFFECTIF_MOYEN = @NUM_EFFECTIF_MOYEN
         		where ID_ADHERENT = @ID_ADHERENT and ID_PERIODE = @id_periode
         	ELSE
         		insert into R21 (ID_ADHERENT, ID_PERIODE,NUM_EFFECTIF_MOYEN)
         		values (@ID_ADHERENT, @id_periode, @NUM_EFFECTIF_MOYEN)

         END
GO

         CREATE PROCEDURE [dbo].[LEC_GRP_SUISI_ENVELOPPE]
         	@ID_PERIODE 	int,
         	@ID_ENVELOPPE	int,
         	@LIST_ID_TYPE_ENVELOPPES	varchar(1000)

         AS
         BEGIN

         	CREATE TABLE #TEMPLIST
         	(
         		ORDER_ID int
         	)

         	DECLARE @ORDERID varchar(10), @POS int

         	SET @LIST_ID_TYPE_ENVELOPPES = LTRIM(RTRIM(@LIST_ID_TYPE_ENVELOPPES))+ ','
         	SET @POS = CHARINDEX(',', @LIST_ID_TYPE_ENVELOPPES, 1)

         	IF REPLACE(@LIST_ID_TYPE_ENVELOPPES, ',', '') <> ''
         	BEGIN
         		WHILE @POS > 0
         		BEGIN
         			SET @ORDERID = LTRIM(RTRIM(LEFT(@LIST_ID_TYPE_ENVELOPPES, @POS - 1)))
         			IF @ORDERID <> ''
         			BEGIN
         				INSERT INTO #TEMPLIST (ORDER_ID) VALUES (CAST(@ORDERID AS int)) 
         			END
         			SET @LIST_ID_TYPE_ENVELOPPES = RIGHT(@LIST_ID_TYPE_ENVELOPPES, LEN(@LIST_ID_TYPE_ENVELOPPES) - @POS)
         			SET @POS = CHARINDEX(',', @LIST_ID_TYPE_ENVELOPPES, 1)

         		END
         	END	

         	DECLARE @TOTAL_PREVISIONEL AS decimal(18,2)
         	DECLARE @TOTAL_ENGAGE AS decimal(18,2)
         	DECLARE @TOTAL_REEL AS decimal(18,2)

         	SET @TOTAL_PREVISIONEL = 0
         	SET @TOTAL_ENGAGE = 0
         	SET @TOTAL_REEL = 0

         	CREATE TABLE #TEMPLIST2
         	(
         		SENS VARCHAR(1),
         		MNT_PREVISIONEL decimal(18,2),
         		MNT_ENGAGE decimal(18,2),
         		MNT_REEL decimal(18,2)
         	)

         	INSERT INTO #TEMPLIST2
         	SELECT
         		PARAMETRAGE_BUDGETAIRE.SENS,
         		CASE WHEN MVT_BUDGETAIRE.P_E_R = 'P' THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE ELSE 0 END,
         		CASE WHEN MVT_BUDGETAIRE.P_E_R = 'E' THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE ELSE 0 END,
         		CASE WHEN MVT_BUDGETAIRE.P_E_R = 'R' THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE ELSE 0 END
         	FROM  

         		ENVELOPPE 
         		INNER JOIN TYPE_ENVELOPPE ON TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE = ENVELOPPE.ID_TYPE_ENVELOPPE 
         		INNER JOIN PERIODE ON PERIODE.ID_PERIODE = ENVELOPPE.ID_PERIODE 
         		INNER JOIN PARAMETRAGE_BUDGETAIRE ON PARAMETRAGE_BUDGETAIRE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE 
         			AND PARAMETRAGE_BUDGETAIRE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE
         		INNER JOIN MVT_BUDGETAIRE ON MVT_BUDGETAIRE.ID_TYPE_MOUVEMENT = PARAMETRAGE_BUDGETAIRE.ID_TYPE_MOUVEMENT
         			AND MVT_BUDGETAIRE.ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE

         	WHERE
         			((RTRIM(@ID_PERIODE) IS NULL) OR ( PERIODE.ID_PERIODE = @ID_PERIODE))  
         		AND  ((RTRIM(@ID_ENVELOPPE) IS NULL) OR (ENVELOPPE.ID_ENVELOPPE  = @ID_ENVELOPPE))  			
         		AND  ((RTRIM(@LIST_ID_TYPE_ENVELOPPES) IS NULL) OR (TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE  IN (SELECT ORDER_ID FROM #TEMPLIST)))

         	DECLARE @CURRENT_PREVISIONEL AS decimal(18,2)
         	DECLARE @CURRENT_ENGAGE AS decimal(18,2)
         	DECLARE @CURRENT_REEL AS decimal(18,2)
         	DECLARE @CURRENT_SENS AS VARCHAR

         	DECLARE CURSOR_MONTANT CURSOR FOR
         		SELECT 
         			SENS,
         			MNT_PREVISIONEL,
         			MNT_ENGAGE,
         			MNT_REEL
         		FROM 
         			#TEMPLIST2
         	OPEN CURSOR_MONTANT

         	FETCH NEXT FROM CURSOR_MONTANT 
         	INTO @CURRENT_SENS, @CURRENT_PREVISIONEL, @CURRENT_ENGAGE, @CURRENT_REEL

         	WHILE @@FETCH_STATUS = 0
         	BEGIN

         		IF @CURRENT_SENS = 'D'
         			BEGIN
         				SET @TOTAL_PREVISIONEL = @TOTAL_PREVISIONEL - @CURRENT_PREVISIONEL
         				SET @TOTAL_ENGAGE = @TOTAL_ENGAGE - @CURRENT_ENGAGE
         				SET @TOTAL_REEL = @TOTAL_REEL - @CURRENT_REEL
         			END
         		ELSE
         			BEGIN
         				SET @TOTAL_PREVISIONEL = @TOTAL_PREVISIONEL + @CURRENT_PREVISIONEL
         				SET @TOTAL_ENGAGE = @TOTAL_ENGAGE + @CURRENT_ENGAGE
         				SET @TOTAL_REEL = @TOTAL_REEL + @CURRENT_REEL
         			END

         	FETCH NEXT FROM CURSOR_MONTANT 
         	INTO @CURRENT_SENS, @CURRENT_PREVISIONEL, @CURRENT_ENGAGE, @CURRENT_REEL

         	END
         	CLOSE CURSOR_MONTANT
         	DEALLOCATE CURSOR_MONTANT

         	SELECT

         		TYPE_ENVELOPPE.LIBL_TYPE_ENVELOPPE, 
         		ENVELOPPE.LIBL_ENVELOPPE, 
         		PERIODE.NUM_ANNEE, 
         		'' AS MOUVEMENT, 
         		ENVELOPPE.BLN_ACTIF, 
         		MVT_BUDGETAIRE.DAT_MVT_BUDGETAIRE,
         		MVT_BUDGETAIRE.LIBL_MVT_BUDGETAIRE,
         		PARAMETRAGE_BUDGETAIRE.SENS, 
         		CASE WHEN MVT_BUDGETAIRE.P_E_R = 'P' THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE ELSE 0 END AS MNT_PREVISIONNEL, 
         		CASE WHEN MVT_BUDGETAIRE.P_E_R = 'E' THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE ELSE 0 END AS MNT_ENGAGE, 
         		CASE WHEN MVT_BUDGETAIRE.P_E_R = 'R' THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE ELSE 0 END AS MNT_REEL,
         		CAST(@TOTAL_PREVISIONEL AS DECIMAL(10,2)) AS TOTAL_PREVISIONEL,
         		CAST(@TOTAL_ENGAGE AS DECIMAL(10,2)) AS TOTAL_ENGAGE,
         		CAST(@TOTAL_REEL AS DECIMAL(10,2)) AS TOTAL_REEL

         	FROM  

         		ENVELOPPE 
         		INNER JOIN TYPE_ENVELOPPE ON TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE = ENVELOPPE.ID_TYPE_ENVELOPPE 
         		INNER JOIN PERIODE ON PERIODE.ID_PERIODE = ENVELOPPE.ID_PERIODE 
         		INNER JOIN PARAMETRAGE_BUDGETAIRE ON PARAMETRAGE_BUDGETAIRE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE 
         			AND PARAMETRAGE_BUDGETAIRE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE
         		INNER JOIN MVT_BUDGETAIRE ON MVT_BUDGETAIRE.ID_TYPE_MOUVEMENT = PARAMETRAGE_BUDGETAIRE.ID_TYPE_MOUVEMENT
         			AND MVT_BUDGETAIRE.ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE

         	WHERE
         			((RTRIM(@ID_PERIODE) IS NULL) OR ( PERIODE.ID_PERIODE = @ID_PERIODE))  
         		AND  ((RTRIM(@ID_ENVELOPPE) IS NULL) OR (ENVELOPPE.ID_ENVELOPPE  = @ID_ENVELOPPE))  			
         		AND  ((RTRIM(@LIST_ID_TYPE_ENVELOPPES) IS NULL) OR (TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE  IN (SELECT ORDER_ID FROM #TEMPLIST)))

         END
GO

         CREATE PROCEDURE LEC_GRP_REGLEMENT_PRO
         	@GENERATION_ONLY	TINYINT = NULL,
         	@MODE_CRITERE		SMALLINT = NULL
         AS
         BEGIN

         	SELECT
         		ID_ETABLISSEMENT_OF,
         		count(*) AS NB_SESSION_PRO
         	INTO
         		#TMP_SESSION_PRO
         	FROM
         		SESSION_PRO
         		INNER JOIN MODULE_PRO ON MODULE_PRO.ID_MODULE_PRO=SESSION_PRO.ID_MODULE_PRO
         	WHERE
         		MODULE_PRO.ID_ETABLISSEMENT_OF IS NOT NULL
         		AND MODULE_PRO.BLN_ACTIF = 1
         		AND SESSION_PRO.BLN_ACTIF = 1
         		AND @MODE_CRITERE IS NOT NULL
         	GROUP BY
         		ID_ETABLISSEMENT_OF

         	SELECT
         		SESSION_PRO.ID_REGLEMENT_PRO_ADH AS ID_REGLEMENT_PRO,
         		CASE
         			WHEN count(*) > 0 THEN 1
         			ELSE 0
         		END AS IBAN_MODIFIE
         	INTO
         		#TMP_SESSION_PRO_VALID_6
         	FROM
         		SESSION_PRO
         		INNER JOIN ETAT_PRO ON SESSION_PRO.ID_ETAT_PRO=ETAT_PRO.ID_ETAT_PRO
         	WHERE
         		SESSION_PRO.ID_ETAT_PRO = 8
         		AND @MODE_CRITERE IS NOT NULL
         		AND ETAT_PRO.COD_ETAT_PRO = 'CHGIBAN'
         	GROUP BY
         		SESSION_PRO.ID_REGLEMENT_PRO_ADH

         	UNION ALL

         	SELECT
         		SESSION_PRO.ID_REGLEMENT_PRO_OF  AS ID_REGLEMENT_PRO,
         		CASE
         			WHEN	count(*) > 0 THEN 1
         			ELSE 0
         		END AS IBAN_MODIFIE
         	FROM
         		SESSION_PRO
         		INNER JOIN ETAT_PRO ON SESSION_PRO.ID_ETAT_PRO=ETAT_PRO.ID_ETAT_PRO
         	WHERE
         		SESSION_PRO.ID_ETAT_PRO = 8
         		AND @MODE_CRITERE IS NOT NULL
         		AND ETAT_PRO.COD_ETAT_PRO = 'CHGIBAN'
         	GROUP BY
         		SESSION_PRO.ID_REGLEMENT_PRO_OF

         	DECLARE
         		@NB_REGL INT
         	SET @NB_REGL =
         		(
         		SELECT
         			count(RP.ID_REGLEMENT_PRO)
         		FROM
         			REGLEMENT_PRO RP
         			INNER JOIN [TRANSACTION] T ON T.ID_TRANSACTION	= RP.ID_TRANSACTION
         		WHERE
         			(
         				@GENERATION_ONLY = 1
         				AND DAT_GENERATION_SEPA IS NOT NULL
         				OR
         				(
         					@GENERATION_ONLY = 0
         					AND DAT_GENERATION_SEPA IS NULL
         					AND RP.BLN_ACTIF = 1
         					AND DAT_VALID_REGLEMENT IS NOT NULL
         				)
         				OR
         				(
         					@GENERATION_ONLY IS NULL
         				)
         			)
         			AND MNT_REGLE_TTC <> 0
         			AND
         			(
         				@MODE_CRITERE IS  NULL
         				OR
         				(
         					@MODE_CRITERE IS NOT NULL
         					AND RP.BLN_ACTIF		= 1
         					AND RP.BLN_EN_COURS	= 1
         					AND RP.DAT_VALID_REGLEMENT IS NULL
         					AND RP.DAT_EDITION IS NULL
         				)
         			)
         		)

         	SELECT
         		RP.*,

         		T.NUM_IBAN	AS	NUM_IBAN,
         		@NB_REGL	AS	NB_REGL,
         		AGENCE.LIBC_AGENCE,
         		AGENCE.LIBL_AGENCE,
         		coalesce(T.ID_ETABLISSEMENT_BENEF, T.ID_ETABLISSEMENT_OF_BENEF, T.ID_TIERS_BENEF) AS ID_BENEF,
         		CASE
         			WHEN	T.ID_ETABLISSEMENT_BENEF		IS NOT NULL	THEN A.LIB_RAISON_SOCIALE
         			WHEN	T.ID_ETABLISSEMENT_OF_BENEF		IS NOT NULL	THEN O.LIB_RAISON_SOCIALE
         			WHEN	T.ID_TIERS_BENEF				IS NOT NULL	THEN TI.LIB_NOM
         			ELSE												'erreur'
         		END	AS                                                                               LIB_BENEF,
         		CASE
         			WHEN	T.ID_ETABLISSEMENT_BENEF		IS NOT NULL	THEN 'Adherent'
         			WHEN	T.ID_ETABLISSEMENT_OF_BENEF		IS NOT NULL	THEN 'Etablissement'
         			WHEN	T.ID_TIERS_BENEF				IS NOT NULL	THEN 'Tiers'
         			ELSE																	 'erreur'
         		END AS	LIB_TYPE_BENEFICIAIRE,
         		isnull((
         				SELECT
         					count(*)
         				FROM
         					SESSION_PRO
         				WHERE
         					 SESSION_PRO.ID_REGLEMENT_PRO_ADH = RP.ID_REGLEMENT_PRO
         					 OR SESSION_PRO.ID_REGLEMENT_PRO_OF = RP.ID_REGLEMENT_PRO
         				),0) AS	NOMBRE_DOSSIERS,
         		CASE
         			WHEN	T.ID_ETABLISSEMENT_DEST		IS NOT NULL	THEN A2.ID_ADHERENT
         			WHEN	T.ID_ETABLISSEMENT_OF_DEST	IS NOT NULL	THEN O2.ID_OF
         			ELSE	NULL
         		END	AS	ID_DEST,
         		coalesce(1*T.ID_ETABLISSEMENT_DEST/T.ID_ETABLISSEMENT_DEST,2*T.ID_ETABLISSEMENT_OF_DEST/T.ID_ETABLISSEMENT_OF_DEST)	AS	ID_TYPE_DEST,
         		CASE
         			WHEN	T.ID_ETABLISSEMENT_OF_DEST IS NOT NULL AND (O.DAT_CREATION > dateadd(MM, -3, getdate()) OR NB_SESSION_PRO < 10) THEN 1
         			ELSE 0
         		END	AS	NOUVEAUX_OF,
         		isnull(P6.IBAN_MODIFIE, 0)	AS	IBAN_MODIFIE
         	FROM
         		REGLEMENT_PRO	RP
         		LEFT JOIN AGENCE						ON	AGENCE.ID_AGENCE=RP.ID_AGENCE
         													AND @MODE_CRITERE IS NOT NULL
         		INNER JOIN [TRANSACTION] T				ON	T.ID_TRANSACTION=RP.ID_TRANSACTION
         		INNER JOIN SOUS_TYPE_TRANSACTION		ON	T.ID_SOUS_TYPE_TRANSACTION=SOUS_TYPE_TRANSACTION.ID_SOUS_TYPE_TRANSACTION
         													AND SOUS_TYPE_TRANSACTION.COD_SOUS_TYPE_TRANSACTION='REGLEMT'
         		LEFT JOIN ADHERENT A					ON	A.ID_ETABLISSEMENT_PRINCIPAL=T.ID_ETABLISSEMENT_BENEF
         													AND @MODE_CRITERE IS NOT NULL
         		LEFT JOIN ORGANISME_FORMATION O			ON	O.ID_ETABLISSEMENT_OF_PRINCIPAL=T.ID_ETABLISSEMENT_OF_BENEF
         													AND @MODE_CRITERE IS NOT NULL
         		LEFT JOIN TIERS TI						ON	TI.ID_TIERS=T.ID_TIERS_BENEF
         													AND @MODE_CRITERE IS NOT NULL
         		LEFT JOIN ADHERENT A2					ON	A2.ID_ETABLISSEMENT_PRINCIPAL=T.ID_ETABLISSEMENT_DEST
         													AND @MODE_CRITERE IS NOT NULL
         		LEFT JOIN ORGANISME_FORMATION O2		ON	O2.ID_ETABLISSEMENT_OF_PRINCIPAL=T.ID_ETABLISSEMENT_OF_DEST
         													AND @MODE_CRITERE IS NOT NULL
         		LEFT JOIN #TMP_SESSION_PRO P			ON	P.ID_ETABLISSEMENT_OF=T.ID_ETABLISSEMENT_OF_DEST
         													AND @MODE_CRITERE IS NOT NULL
         		LEFT JOIN #TMP_SESSION_PRO_VALID_6 P6	ON	P6.ID_REGLEMENT_PRO=RP.ID_REGLEMENT_PRO
         													AND @MODE_CRITERE IS NOT NULL
         	WHERE
         	(
         		@GENERATION_ONLY		= 1
         		AND DAT_GENERATION_SEPA					IS NOT NULL
         		OR
         		(
         			@GENERATION_ONLY	= 0
         			AND DAT_GENERATION_SEPA					IS NULL
         			AND RP.BLN_ACTIF = 1
         			AND DAT_VALID_REGLEMENT						IS NOT NULL
         		)
         		OR
         		(
         			@GENERATION_ONLY IS NULL
         		)
         	)
         	AND MNT_REGLE_TTC	<> 0
         	AND
         	(
         		@MODE_CRITERE IS  NULL
         		OR
         		(
         			@MODE_CRITERE IS NOT NULL
         			AND RP.BLN_ACTIF = 1
         			AND RP.BLN_EN_COURS	= 1
         			AND RP.DAT_VALID_REGLEMENT IS NULL
         			AND RP.DAT_EDITION IS NULL
         		)
         	)
         END
GO

         CREATE PROCEDURE [dbo].[LEC_GRP_ETAB_DOSSIES_FACTURABLES] 

         	@ID_CHARGERELATION INT,
         	@ID_ANTENNE INT,
         	@ID_ADHERENT INT,
         	@ID_ETABLISSEMENT INT,
         	@BLN_REPRISE_ADHOC tinyint
         AS
         BEGIN

         	create table  #tmp_etab (id_etablissement int)

         	DECLARE @NUM_ANNEE_EN_COURS int
         	SELECT @NUM_ANNEE_EN_COURS  = NUM_ANNEE
         	FROM PERIODE
         	WHERE ID_TYPE_PERIODE = 1
         	AND BLN_EN_COURS = 1

         	IF (@ID_ETABLISSEMENT is not null)

         	BEGIN
         		insert into #tmp_etab (id_etablissement) values (@ID_ETABLISSEMENT)
         	END
         	ELSE
         	IF @ID_ADHERENT is not null

         	BEGIN
         		insert into #tmp_etab (id_etablissement)
         		SELECT ID_ETABLISSEMENT 
         		FROM ETABLISSEMENT
         		where ID_ADHERENT = @ID_ADHERENT
         		and BLN_ACTIF = 1
         	END 
         	ELSE 
         	IF @ID_CHARGERELATION is not null
         	BEGIN

         		insert into #tmp_etab (id_etablissement)
         		select ID_ETABLISSEMENT
         		from ETABLISSEMENT
         		where ETABLISSEMENT.ID_CHARGEE_RELATION = @ID_CHARGERELATION
         	END
         	ELSE 
         	IF @ID_ANTENNE is not null
         	BEGIN
         		insert into #tmp_etab (id_etablissement)
         		select ID_ETABLISSEMENT
         		from ETABLISSEMENT
         		inner join UTILISATEUR on (UTILISATEUR.ID_UTILISATEUR = ETABLISSEMENT.ID_CHARGEE_RELATION)
         		where UTILISATEUR.id_agence = @ID_ANTENNE
         	END

         	SELECT  
         		MODULE_PEC.ID_MODULE_PEC,
         		STAGIAIRE_PEC.ID_ETABLISSEMENT,
         		STAGIAIRE_PEC.ID_INDIVIDU,
         		MNT_PLAN_FINANCEMENT_US AS MNT_ENGAGE,
         		MODULE_PEC.DAT_FIN,
         		POSTE_COUT_ENGAGE.ID_SOUS_TYPE_COUT,
         		MODULE_PEC.BLN_DELEGATION_PAIEMENT
         	into #TEMPLISTENGAGE_1ereEtape	
         		FROM MODULE_PEC
         		INNER JOIN ACTION_PEC			ON (ACTION_PEC.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC)and
         										ACTION_PEC.BLN_ACTIF = 1 and
         										ACTION_PEC.DAT_CLOTURE IS NULL
         		INNER JOIN STAGIAIRE_PEC		ON (STAGIAIRE_PEC.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC)

         										AND STAGIAIRE_PEC.ID_SESSION_PEC IS NULL 
         		INNER JOIN #tmp_etab			ON STAGIAIRE_PEC.ID_ETABLISSEMENT = #tmp_etab.id_etablissement
         		inner join UNITE_STAGIAIRE		on (UNITE_STAGIAIRE.ID_STAGIAIRE_PEC = STAGIAIRE_PEC.ID_STAGIAIRE_PEC)
         		INNER JOIN POSTE_COUT_ENGAGE	ON (MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_ENGAGE.ID_MODULE_PEC)
         										AND POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT	is NULL	
         										AND POSTE_COUT_ENGAGE.ID_ENGAGEMENT IS NOT NULL 
         										AND POSTE_COUT_ENGAGE.ID_ENGAGEMENT > 0 
         		INNER JOIN 	PLAN_FINANCEMENT_US	ON(PLAN_FINANCEMENT_US.ID_POSTE_COUT_ENGAGE	 = POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE					
         										and PLAN_FINANCEMENT_US.ID_UNITE_STAGIAIRE = UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE
         										and PLAN_FINANCEMENT_US.BLN_ACTIF = 1)
         		INNER JOIN ENGAGEMENT			ON ENGAGEMENT.ID_ENGAGEMENT = POSTE_COUT_ENGAGE.ID_ENGAGEMENT 	AND 
         										ID_TYPE_ENGAGEMENT	is not null AND 
         										ENGAGEMENT.ID_TYPE_ENGAGEMENT	<> 2 and
         										ENGAGEMENT.DAT_BAE is not null

         		INNER JOIN PERIODE				ON	PERIODE.ID_PERIODE = MODULE_PEC.ID_PERIODE
         										AND	PERIODE.NUM_ANNEE >= @NUM_ANNEE_EN_COURS - 2

         	where
         		MODULE_PEC.BLN_ACTIF = 1  AND 
         		MODULE_PEC.BLN_IMPUTABLE = 1  and
         		(@BLN_REPRISE_ADHOC = 1 OR isnull(ACTION_PEC.BLN_REPRISE_ADHOC,0) = 0)

         	select 	ID_MODULE_PEC,
         			ISNULL(sum(MNT_ENGAGE),0) as MNT_ENGAGE,
         		ID_SOUS_TYPE_COUT
         	into 	#TEMPLISTENGAGE
         	from 	#TEMPLISTENGAGE_1ereEtape
         	group by id_module_pec, id_sous_type_cout

         	select distinct ID_MODULE_PEC,
         		ID_ETABLISSEMENT,
         		ID_INDIVIDU,
         		DAT_FIN, id_sous_type_cout,
         		BLN_DELEGATION_PAIEMENT
         	into #tmp_modules
         	from #TEMPLISTENGAGE_1ereEtape

         	Select 
         		#tmp_modules.ID_MODULE_PEC AS ID_MODULE_PEC, 
         		PFUS.MNT_PLAN_FINANCEMENT_US as MNT_REGLE, 
         		#tmp_modules.id_sous_type_cout
         	INTO #TEMPLISTREEL__1ereEtape
         	FROM #tmp_modules 
         		Inner join SESSION_PEC 
         			on SESSION_PEC.ID_MODULE_PEC=#tmp_modules.ID_MODULE_PEC 
         			AND SESSION_PEC.BLN_ACTIF=1 
         		INNER JOIN STAGIAIRE_PEC 
         			ON STAGIAIRE_PEC.ID_SESSION_PEC=SESSION_PEC.ID_SESSION_PEC 
         			AND STAGIAIRE_PEC.ID_ETABLISSEMENT = #tmp_modules.ID_ETABLISSEMENT 
         			AND STAGIAIRE_PEC.ID_INDIVIDU = #tmp_modules.ID_INDIVIDU 
         		INNER JOIN UNITE_STAGIAIRE 
         			ON UNITE_STAGIAIRE.ID_STAGIAIRE_PEC = STAGIAIRE_PEC.ID_STAGIAIRE_PEC 

         		INNER JOIN POSTE_COUT_REGLE 
         			ON POSTE_COUT_REGLE.ID_SESSION_PEC = SESSION_PEC.ID_SESSION_PEC 

         			AND POSTE_COUT_REGLE.BLN_ACTIF=1 
         			AND POSTE_COUT_REGLE.ID_SOUS_TYPE_COUT=#tmp_modules.id_sous_type_cout
         		INNER JOIN PLAN_FINANCEMENT_US as PFUS 
         			ON PFUS.ID_UNITE_STAGIAIRE = UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE 
         			AND PFUS.ID_POSTE_COUT_REGLE = POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE 
         			AND PFUS.BLN_ACTIF=1 

         	select
         		ID_MODULE_PEC,
         		isnull(sum(MNT_REGLE),0) as MNT_REEL,
         		 id_sous_type_cout
         	into #TEMPLISTREEL
         	from #TEMPLISTREEL__1ereEtape
         	GROUP BY 
         		#TEMPLISTREEL__1ereEtape.ID_MODULE_PEC, id_sous_type_cout

         	DECLARE @ID_DOCUMENT int	
         	SELECT @ID_DOCUMENT = ID_DOCUMENT
         	FROM [DOCUMENT]
         	WHERE COD_DOCUMENT = 'LET_PEC_DOSFACT'

         	declare @PARAM_DUREE_C int            
         	declare @PARAM_MNT_D decimal(18,2)    
         	declare @PARAM_MNT_MIN decimal (18,2) 
         	declare @CHAINE as varchar(50)
         	declare @SEP as varchar (2)
         	set @SEP = ','

         	select 
         			@PARAM_DUREE_C	= DUREE_C,
         			@PARAM_MNT_D	= MONTANT_D,
         			@PARAM_MNT_MIN	= MNT_MIN,
         			@CHAINE			= STC_EXCLUS 
         	from dbo.PARAM_EDITION_PEC
         	where ID_DOCUMENT = @ID_DOCUMENT

         	SELECT cast(data as integer) as data into #LIST_STC_A_EXCLURE from F_SPLIT( @CHAINE, @SEP)

         	SELECT      
         		#tmp_mods_sans_individus.ID_ETABLISSEMENT
         	into #FINAL
         	from (select distinct ID_MODULE_PEC, ID_ETABLISSEMENT, DAT_FIN, id_sous_type_cout, BLN_DELEGATION_PAIEMENT 
         						from #tmp_modules) #tmp_mods_sans_individus 
         		LEFT JOIN #TEMPLISTENGAGE	ON (#TEMPLISTENGAGE.ID_MODULE_PEC		= #tmp_mods_sans_individus.ID_MODULE_PEC AND
         	 									#TEMPLISTENGAGE.ID_SOUS_TYPE_COUT	= #tmp_mods_sans_individus.id_sous_type_cout)
         		LEFT JOIN #TEMPLISTREEL		ON (#TEMPLISTREEL.ID_MODULE_PEC			= #tmp_mods_sans_individus.ID_MODULE_PEC AND
         										#TEMPLISTREEL.ID_SOUS_TYPE_COUT		= #tmp_mods_sans_individus.id_sous_type_cout)

         		where 
         		(#tmp_mods_sans_individus.BLN_DELEGATION_PAIEMENT=0  
         		or #tmp_mods_sans_individus.ID_SOUS_TYPE_COUT not in (select * from #LIST_STC_A_EXCLURE)
         		)
         		and
         		(ISNULL(#TEMPLISTENGAGE.MNT_ENGAGE,0) - ISNULL(#TEMPLISTREEL.MNT_REEL,0) > @PARAM_MNT_MIN)
         		AND 
         		(#tmp_mods_sans_individus.DAT_FIN < getdate() + @PARAM_DUREE_C 
         		OR	
         		  ( ISNULL(#TEMPLISTENGAGE.MNT_ENGAGE,0) - ISNULL(#TEMPLISTREEL.MNT_REEL,0) > @PARAM_MNT_D)		)

         		select distinct ETABLISSEMENT.ID_ETABLISSEMENT,
         		ETABLISSEMENT.ID_BRANCHE, 
         		ETABLISSEMENT.ID_ADHERENT,
         		ETABLISSEMENT.ID_AGENCE,
         		ETABLISSEMENT.ID_CHARGEE_RELATION,
         		ETABLISSEMENT.ID_ADRESSE_PRINCIPALE,
         		NR31.ID_CONTACT,
         		COD_ADHERENT,
         		ETABLISSEMENT.ID_ETABLISSEMENT as ID_BENEFICIAIRE
         		from ETABLISSEMENT
         		inner join #FINAL on (#FINAL.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT)
         		inner join adherent on (ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT)
         		left join dbo.NR31 on (ETABLISSEMENT.ID_ETABLISSEMENT = NR31.ID_ETABLISSEMENT
         								and NR31.BLN_ACTIF = 1 and NR31.BLN_PRINCIPAL = 1)
         		order by ETABLISSEMENT.ID_BRANCHE 

         END

GO

         CREATE PROCEDURE [dbo].[INS_MOTIF_REJET_CONTRAT]
         	@ID_CONTRAT_PRO		as int,
         	@ID_MOTIF_REJET_PRO as int
         AS  
         	IF NOT EXISTS ( SELECT 1 FROM MOTIF_REJET_CONTRAT WHERE	ID_CONTRAT_PRO		= @ID_CONTRAT_PRO		AND 
         															ID_MOTIF_REJET_PRO	= @ID_MOTIF_REJET_PRO)
         	BEGIN	
         		INSERT INTO MOTIF_REJET_CONTRAT (ID_CONTRAT_PRO, ID_MOTIF_REJET_PRO) VALUES (@ID_CONTRAT_PRO, @ID_MOTIF_REJET_PRO)
         	END

GO

         CREATE PROCEDURE [dbo].[EDT_LETTRE_CONTRAT_PRO_REMB_SAL_ADH]
         @ID_ETABLISSEMENT	INT,
         	@ID_BENEFICIAIRE	INT,
         	@TYPE_BENEFICIAIRE	INT,
         	@ID_ADRESSE			INT,
         	@ID_CONTACT			INT,
         	@_ID_MODULE_PRO INT,
         	@_COD_CONTRAT_PRO	VARCHAR(10)

         AS
         BEGIN

         	DECLARE @RELANCE INT
         	SET @RELANCE = 0

         	SELECT	ADHERENT.ID_ADHERENT,
         			ADHERENT.ID_TYPE_TVA,
         			ADHERENT.COD_ADHERENT,
         			AGENCE.ID_AGENCE,
         			AGENCE.COD_POSTAL,
         			AGENCE.LIB_VILLE,
         			AGENCE.LIB_NOM_CONSEILLER,
         			AGENCE.LIB_PNM_CONSEILLER,
         			ADHERENT.LIB_RAISON_SOCIALE
         	INTO	#TEMP_REGLEMENT_REFERENCE
         	FROM	ADHERENT
         			INNER JOIN AGENCE			ON AGENCE.ID_AGENCE = ADHERENT.ID_AGENCE
         			INNER JOIN ETABLISSEMENT	ON ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         	WHERE	(ETABLISSEMENT.ID_ETABLISSEMENT = @ID_ETABLISSEMENT);

         	SELECT	CONTRAT_PRO.ID_CONTRAT_PRO,
         			CONTRAT_PRO.COD_CONTRAT_PRO,
         			CONVERT(VARCHAR(8),CONTRAT_PRO.DAT_DEB_CONTRAT, 3) AS DAT_DEBUT,
         			CONVERT(VARCHAR(8),CONTRAT_PRO.DAT_FIN_CONTRAT, 3) AS DAT_FIN,
         			INDIVIDU.NOM_INDIVIDU, 
         			INDIVIDU.PRENOM_INDIVIDU,
         			Case when INDIVIDU.BLN_MASCULIN=1 then 'Monsieur' else 'Madame' end as Title ,
         			CONTRAT_PRO.LIB_LIEU_FORMATION
         	INTO	#TMP_CONTRAT_PRO
         	FROM	CONTRAT_PRO
         			INNER JOIN SALARIE_PRO ON CONTRAT_PRO.ID_SALARIE_PRO = SALARIE_PRO.ID_SALARIE_PRO 
         			INNER JOIN INDIVIDU ON SALARIE_PRO.ID_INDIVIDU = INDIVIDU.ID_INDIVIDU
         	WHERE   CONTRAT_PRO.COD_CONTRAT_PRO = @_COD_CONTRAT_PRO;

         		SELECT ORGANISME_FORMATION.LIB_RAISON_SOCIALE, ROUND(MODULE_PRO.TAUX_HORAIRE_MODULE,2) as TAUX_HORAIRE_MODULE , TYPE_FORMATION.LIBL_TYPE_FORMATION
         		INTO #TEMP_MODULE_ORGANISME_OF FROM ORGANISME_FORMATION
         		INNER JOIN ETABLISSEMENT_OF  ON ETABLISSEMENT_OF.ID_OF=ORGANISME_FORMATION.ID_OF
         		INNER join MODULE_PRO on MODULE_PRO.ID_ETABLISSEMENT_OF=ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF
         		INNER join TYPE_FORMATION on MODULE_PRO.ID_TYPE_FORMATION=TYPE_FORMATION.ID_TYPE_FORMATION
         		where MODULE_PRO.ID_MODULE_PRO=@_ID_MODULE_PRO;

         SELECT TAU_TVA
         INTO #TVA from R26
         inner join #TEMP_REGLEMENT_REFERENCE on #TEMP_REGLEMENT_REFERENCE.ID_TYPE_TVA = R26.ID_TYPE_TVA
         inner join PERIODE on PERIODE.ID_PERIODE=R26.ID_PERIODE and PERIODE.ID_TYPE_PERIODE=2 and (DATEDIFF(DAY,PERIODE.DAT_DEB_PERIODE,GETDATE()) >0)
         order by PERIODE.DAT_DEB_PERIODE desc

         	IF( (SELECT COUNT(*) FROM ECHEANCE_MODULE_PRO WHERE ECHEANCE_MODULE_PRO.ID_MODULE_PRO=@_ID_MODULE_PRO AND (DATEDIFF(DAY,ECHEANCE_MODULE_PRO.DAT_ENVOI_RELANCE1_PREV,GETDATE()) >0) AND (ECHEANCE_MODULE_PRO.DAT_ENVOI_RELANCE1_EFF IS NULL)) >0)
         			BEGIN
         				SET @RELANCE = 1
         			END
         		ELSE
         			IF ((SELECT COUNT(*) FROM ECHEANCE_MODULE_PRO WHERE ECHEANCE_MODULE_PRO.ID_MODULE_PRO=@_ID_MODULE_PRO AND (DATEDIFF(DAY,ECHEANCE_MODULE_PRO.DAT_ENVOI_RELANCE2_PREV,GETDATE()) >0) AND (ECHEANCE_MODULE_PRO.DAT_ENVOI_RELANCE2_EFF IS NULL)) >0)
         					BEGIN
         						SET @RELANCE = 2
         					END

         		ELSE
         			BEGIN
         				IF ((SELECT COUNT(*) FROM ECHEANCE_MODULE_PRO WHERE ECHEANCE_MODULE_PRO.ID_MODULE_PRO=@_ID_MODULE_PRO AND (DATEDIFF(DAY,ECHEANCE_MODULE_PRO.DAT_ENVOI_RELANCE3_PREV,GETDATE()) >0) AND (ECHEANCE_MODULE_PRO.DAT_ENVOI_RELANCE3_EFF IS NULL)) >0)
         					BEGIN
         						SET @RELANCE = 3
         					END
         			END;

         	WITH XMLNAMESPACES (
         		DEFAULT 'EDT_LETTRE_PRO_REMBOURSEMENT_SALAIRES_ADH'
         	)

         	SELECT

         			CASE WHEN (@RELANCE > 0) THEN 
         			(

         			SELECT
         				(
         					SELECT CASE WHEN @RELANCE=0 THEN null ELSE @RELANCE END
         					FOR XML RAW('NUM_RELANCE'), ELEMENTS, TYPE
         				),
         				( 
         					SELECT  CASE WHEN @RELANCE=0 THEN ''  WHEN @RELANCE=1 THEN 'Šre' ELSE 'Šme' END
         					FOR XML RAW('niŠme'), ELEMENTS, TYPE
         				),
         				( 
         					SELECT  CASE WHEN  @RELANCE=0 THEN '' ELSE ' RELANCE' END
         					FOR XML RAW('RELANCE'), ELEMENTS, TYPE
         				)
         				FOR XML RAW('TOP') ,ELEMENTS,TYPE

         			)end,

         			(

         				SELECT	              	

         					dbo.GetXmlAgenceContact(ENTETE.ID_AGENCE) as EMETTEUR,

         					dbo.GetXmlBenefiaireContact(@ID_BENEFICIAIRE, @TYPE_BENEFICIAIRE, @ID_ADRESSE, @ID_CONTACT) as BENEFICIAIRE,

         					(
         						SELECT	REFERENCE.LIB_VILLE,
         								dbo.GetFullDate(getDate()) as DATE

         						FROM #TEMP_REGLEMENT_REFERENCE AS REFERENCE     
         						FOR XML AUTO, ELEMENTS, TYPE
         					)
         				FROM #TEMP_REGLEMENT_REFERENCE AS ENTETE     
         				FOR XML AUTO, ELEMENTS, TYPE
         			),
         			(

         				SELECT	
         						DEMANDE.COD_ADHERENT,
         						DEMANDE.LIB_RAISON_SOCIALE AS LIB_RAISON_SOCIALE_ADHERENT,
         						(
         							SELECT 
         									CORPS.ID_CONTRAT_PRO,
         									CORPS.DAT_DEBUT,
         									CORPS.DAT_FIN,
         									CORPS.Title,
         									CORPS.PRENOM_INDIVIDU,
         									CORPS.NOM_INDIVIDU
         							FROM #TMP_CONTRAT_PRO  AS CORPS 
         							FOR XML PATH(''), ELEMENTS, TYPE
         						),	
         						(

         						SELECT	
         								ORGANISME.LIB_RAISON_SOCIALE,
         								ORGANISME.LIBL_TYPE_FORMATION
         						FROM #TEMP_MODULE_ORGANISME_OF as ORGANISME
         						FOR XML PATH(''), ELEMENTS, TYPE
         						)
         				FROM  #TEMP_REGLEMENT_REFERENCE AS DEMANDE
         				FOR XML AUTO, ELEMENTS, TYPE
         			),

         			(
         			select

         			(
         				SELECT	top 1
         						dbo.GetContactSalutation(@ID_CONTACT, 1)
         				FROM CIVILITE
         				FOR XML PATH('POLITESSE_HAUT'), TYPE
         			),
         						CAST(CORPS.TAUX_HORAIRE_MODULE AS decimal(10,2)) as TAUX_HORAIRE_MODULE,
         			(
         				SELECT 	top 1 CAST((TAU_TVA * 100) AS decimal(10,2)) as TAU_TVA from #TVA
         					FOR XML PATH(''), ELEMENTS, TYPE
         			),

         			(
         				SELECT	top 1
         						dbo.GetContactSalutation(@ID_CONTACT, 0)
         				FROM CIVILITE
         				FOR XML PATH('POLITESSE_BAS'), TYPE
         			)
         				FROM #TEMP_MODULE_ORGANISME_OF as CORPS
         				FOR XML AUTO, ELEMENTS, TYPE
         			),

         			(

         				SELECT	SIGNATURE.LIB_PNM_CONSEILLER,
         						SIGNATURE.LIB_NOM_CONSEILLER
         				FROM
         						#TEMP_REGLEMENT_REFERENCE as SIGNATURE
         				FOR XML AUTO, ELEMENTS, TYPE
         			)

         	FROM	#TEMP_REGLEMENT_REFERENCE as LETTRE
         	FOR XML AUTO, ELEMENTS

         END
GO
 CREATE PROCEDURE [dbo].[INS_NR34]
         (
         		@ID_CONTACT INT, 
         		@ID_FONCTION INT,  
         		@NUM_TEL VARCHAR(10), 
         		@NUM_PORT VARCHAR(10), 
         		@NUM_FAX VARCHAR(10), 
         		@BLN_PRINCIPAL TINYINT, 
         		@BLN_ACTIF TINYINT, 
         		@EMAIL_PRO VARCHAR(100), 
         		@ID_ADRESSE INT, 
         		@ID_ETABLISSEMENT_OF INT, 
         		@LIB_TITRE VARCHAR(100), 
         		@EMAIL_PERS VARCHAR(100)
         )
         AS
         BEGIN
         	INSERT INTO [dbo].[NR34] 
         	(
         		[ID_CONTACT], 
         		[ID_FONCTION], 
         		[NUM_TEL], 
         		[NUM_PORT], 
         		[NUM_FAX], 
         		[BLN_PRINCIPAL], 
         		[BLN_ACTIF], 
         		[EMAIL_PRO], 
         		[ID_ADRESSE], 
         		[ID_ETABLISSEMENT_OF], 
         		[LIB_TITRE], 
         		[EMAIL_PERS]
         	) 
         	VALUES 
         	(
         		@ID_CONTACT, 
         		@ID_FONCTION, 
         		@NUM_TEL, 
         		@NUM_PORT, 
         		@NUM_FAX, 
         		@BLN_PRINCIPAL, 
         		@BLN_ACTIF, 
         		@EMAIL_PRO, 
         		@ID_ADRESSE, 
         		@ID_ETABLISSEMENT_OF, 
         		@LIB_TITRE, 
         		@EMAIL_PERS
         	)

         	IF (EXISTS (
         				select [TRANSACTION].ID_ADRESSE, [TRANSACTION].ID_CONTACT, [TRANSACTION].ID_ADRESSE
         				from [TRANSACTION]
         				where 
         					[TRANSACTION].ID_ETABLISSEMENT_OF_DEST	=  @ID_ETABLISSEMENT_OF	AND
         					[TRANSACTION].ID_CONTACT				=  @ID_CONTACT			AND
         					[TRANSACTION].ID_ADRESSE				<> @ID_ADRESSE
         				) )
         	BEGIN
         		UPDATE [TRANSACTION] set [TRANSACTION].ID_ADRESSE = @ID_ADRESSE
         		where 
         			[TRANSACTION].ID_ETABLISSEMENT_OF_DEST	=  @ID_ETABLISSEMENT_OF	AND
         			[TRANSACTION].ID_CONTACT				=  @ID_CONTACT
         		print 'transaction ok'
         	END
         END
GO
GO

         CREATE PROCEDURE EDT_ORDRES_VIREMENT
         	@ID_ETABLISSEMENT		int,
         	@ID_BENEFICIAIRE		int,
         	@TYPE_BENEFICIAIRE		int,
         	@ID_ADRESSE				int,
         	@ID_CONTACT				int,
         	@TYPE_DESTINATAIRE		int,
         	@ID_TRANSACTION			int,
         	@ID_REGLEMENT			int
         AS
         	BEGIN
         		DECLARE
         			@MODE_EDITION tinyint,
         			@COD_ADHERENT_OF AS VARCHAR(8),
         			@ID_OF AS INT,
         			@ID_ADHERENT AS INT,
         			@LIB_RAISON_SOCIALE_ADHERENT AS VARCHAR(50),
         			@LIB_RAISON_SOCIALE_OF AS VARCHAR(64),
         			@ID_UTIL AS INT,
         			@LIB_VILLE AS VARCHAR(50),
         			@ID_ETAB_OF AS INT,
         			@ID_ETAB AS INT,
         			@TOT AS MONEY,

         			@num_iban varchar(34),
         			@bic varchar(11)

         		select
         			@num_iban = num_iban,
         			@bic = BIC  
         		from
         			[transaction]
         		where
         			id_transaction = @ID_TRANSACTION

         		SET @MODE_EDITION = 1
         		SET @ID_ETAB = NULL
         		SET @ID_ETAB_OF = NULL

         		IF (@TYPE_DESTINATAIRE = 1)
         		BEGIN
         			select
         				@ID_ADHERENT					= adherent.id_adherent,
         				@COD_ADHERENT_OF				= adherent.cod_adherent,
         				@LIB_RAISON_SOCIALE_ADHERENT	= adherent.lib_raison_sociale
         			from
         				etablissement
         			join
         				adherent
         			on	etablissement.id_adherent = adherent.id_adherent
         			where
         				etablissement.id_etablissement = @ID_ETABLISSEMENT
         		END

         		IF (@TYPE_DESTINATAIRE = 2)
         			BEGIN
         				select
         					@ID_OF							= organisme_formation.id_of,
         					@COD_ADHERENT_OF				= organisme_formation.cod_of,
         					@LIB_RAISON_SOCIALE_OF			= organisme_formation.lib_raison_sociale
         				from
         					etablissement_of
         					join organisme_formation on	etablissement_of.id_of = organisme_formation.id_of
         				where
         					etablissement_of.id_etablissement_of = @ID_ETABLISSEMENT
         			END

         		SELECT DISTINCT
         			MODULE_PEC.LIBL_MODULE_PEC,
         			MODULE_PEC.ID_MODULE_PEC
         		INTO
         			[#ORGANISME_FORMATION]
         		FROM
         			POSTE_COUT_REGLE
         			JOIN REGLEMENT	ON	POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT
         			JOIN MODULE_PEC	ON	POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         		WHERE
         			REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         			AND REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         			AND POSTE_COUT_REGLE.BLN_ACTIF = 1;

         		SELECT
         			SUM(PLAN_FINANCEMENT_US.MNT_PLAN_FINANCEMENT_US)		AS MNT_REGLE_HT,
         			SUM(PLAN_FINANCEMENT_US.MNT_PLAN_FINANCEMENT_US_TVA)	AS MNT_REGLE_TVA,

         			PLAN_FINANCEMENT_US.ID_POSTE_COUT_REGLE, 
         			STAGIAIRE_PEC.ID_ETABLISSEMENT 
         		INTO
         			[#PLAN_FINANCEMENT_US_OF]
         		FROM
         			PLAN_FINANCEMENT_US
         			JOIN UNITE_STAGIAIRE	ON	PLAN_FINANCEMENT_US.ID_UNITE_STAGIAIRE = UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE
         			JOIN STAGIAIRE_PEC		ON	UNITE_STAGIAIRE.ID_STAGIAIRE_PEC = STAGIAIRE_PEC.ID_STAGIAIRE_PEC
         			JOIN POSTE_COUT_REGLE	ON	PLAN_FINANCEMENT_US.ID_POSTE_COUT_REGLE = POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE
         			JOIN REGLEMENT			ON	REGLEMENT.ID_REGLEMENT = POSTE_COUT_REGLE.ID_REGLEMENT
         		WHERE
         			REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         			AND REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         			AND POSTE_COUT_REGLE.BLN_ACTIF = 1
         		GROUP BY
         			PLAN_FINANCEMENT_US.ID_POSTE_COUT_REGLE,
         			STAGIAIRE_PEC.ID_ETABLISSEMENT

         		SELECT DISTINCT 
         			MODULE_PEC.ID_MODULE_PEC,
         			MODULE_PEC.COD_MODULE_PEC,	
         			MODULE_PEC.LIBL_MODULE_PEC,
         			ADHERENT.ID_ADHERENT,
         			ADHERENT.COD_ADHERENT,
         			ADHERENT.LIB_RAISON_SOCIALE
         		INTO
         			#MODULE_PEC
         		FROM 
         			REGLEMENT
         			JOIN POSTE_COUT_REGLE ON	POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT	
         			JOIN MODULE_PEC ON	POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         			JOIN NR140 ON	MODULE_PEC.ID_ACTION_PEC = NR140.ID_ACTION_PEC
         			JOIN ETABLISSEMENT ON	ETABLISSEMENT.ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT
         			JOIN ADHERENT ON	ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         		WHERE
         			REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         			AND REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         			AND POSTE_COUT_REGLE.BLN_ACTIF = 1

         		CREATE TABLE #TMP_GENERAL
         		(
         			LIB_NOM_CONSEILLER varchar(35), 
         			LIB_PNM_CONSEILLER varchar(35), 
         			ID_UTILISATEUR int, 
         			LIB_PRENOM_CHARGE_RELATION varchar(35), 
         			LIB_NOM_CHARGE_RELATION varchar(35), 
         			LIB_VILLE varchar(50), 
         			EMAIL_CHARGE_RELATION varchar(100), 
         			NUM_VIREMENT int
         		)

         		IF (@TYPE_DESTINATAIRE = 1)
         			INSERT INTO #TMP_GENERAL
         			SELECT	DISTINCT
         				CM.LIB_NOM			as LIB_NOM_CONSEILLER,
         				CM.LIB_PNM			as LIB_PNM_CONSEILLER,
         				CR.ID_UTILISATEUR,
         				CR.LIB_PNM			as LIB_PRENOM_CHARGE_RELATION,
         				CR.LIB_NOM			as LIB_NOM_CHARGE_RELATION,
         				CR.LIB_VILLE,
         				CR.EMAIL			as EMAIL_CHARGE_RELATION,
         				REGLEMENT.NUM_VIREMENT
         			FROM 
         				REGLEMENT
         				JOIN POSTE_COUT_REGLE	ON	POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT	
         				JOIN MODULE_PEC			ON	POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         				JOIN NR140				ON	MODULE_PEC.ID_ACTION_PEC = NR140.ID_ACTION_PEC
         				JOIN ETABLISSEMENT		ON	ETABLISSEMENT.ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT AND	ETABLISSEMENT.ID_ETABLISSEMENT = POSTE_COUT_REGLE.ID_ETABLISSEMENT 
         				JOIN ADHERENT			ON	ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         				JOIN ACTION_PEC			ON	ACTION_PEC.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC
         				LEFT JOIN utilisateur CR ON	ETABLISSEMENT.id_chargee_relation = CR.id_utilisateur	
         				LEFT JOIN utilisateur CM ON	ETABLISSEMENT.id_chargee_mission = CM.id_utilisateur	
         			WHERE
         				REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         				AND REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         				AND POSTE_COUT_REGLE.BLN_ACTIF = 1

         		IF (@TYPE_DESTINATAIRE = 2)
         			INSERT INTO #TMP_GENERAL
         			SELECT	TOP 1
         				CM.LIB_NOM			as LIB_NOM_CONSEILLER,
         				CM.LIB_PNM			as LIB_PNM_CONSEILLER,
         				CR.ID_UTILISATEUR,
         				CR.LIB_PNM			as LIB_PRENOM_CHARGE_RELATION,
         				CR.LIB_NOM			as LIB_NOM_CHARGE_RELATION,
         				CR.LIB_VILLE,
         				CR.EMAIL			as EMAIL_CHARGE_RELATION,
         				REGLEMENT.NUM_VIREMENT
         			FROM 
         				REGLEMENT
         				JOIN POSTE_COUT_REGLE ON	POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT	
         				JOIN MODULE_PEC ON	POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         				JOIN NR140 ON	MODULE_PEC.ID_ACTION_PEC = NR140.ID_ACTION_PEC
         				JOIN ETABLISSEMENT ON	ETABLISSEMENT.ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT
         				JOIN ADHERENT ON	ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         				JOIN ACTION_PEC ON	ACTION_PEC.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC
         				LEFT JOIN utilisateur CR 
         			ON	ETABLISSEMENT.id_chargee_relation = CR.id_utilisateur	
         			LEFT JOIN
         				utilisateur CM 
         			ON	ETABLISSEMENT.id_chargee_mission = CM.id_utilisateur	
         			WHERE
         				REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         			AND REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         			AND POSTE_COUT_REGLE.BLN_ACTIF = 1

         		CREATE TABLE #POSTE_COUT_REGLE_ADH_OF
         		(
         			ID_POSTE_COUT_REGLE int,
         			LIB_RAISON_SOCIALE varchar(100), 
         			DAT_DEBUT datetime,
         			MNT_REGLE_HT decimal(18,2),
         			LIBC_TYPE_FACTURE varchar(50),
         			NUM_FACTURE varchar(50), 
         			DAT_FIN datetime,
         			MNT_REGLE_TVA decimal(18,2),
         			COD_SESSION_PEC varchar(17),
         			ID_MODULE_PEC int, 
         			ID_OF int, 
         			MNT_REGLE_TTC decimal(18,2),
         			MNT_POSTE_COUT_REGLE_TTC decimal(18,2)
         		)

         		IF (@TYPE_DESTINATAIRE = 2) 
         		BEGIN

         			insert into #POSTE_COUT_REGLE_ADH_OF (ID_POSTE_COUT_REGLE, LIB_RAISON_SOCIALE, DAT_DEBUT, MNT_REGLE_HT, LIBC_TYPE_FACTURE, NUM_FACTURE,  DAT_FIN, MNT_REGLE_TVA, COD_SESSION_PEC, ID_MODULE_PEC, ID_OF,  MNT_REGLE_TTC, MNT_POSTE_COUT_REGLE_TTC) 	(
         				SELECT DISTINCT
         					POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE,
         					ADHERENT.LIB_RAISON_SOCIALE as LIB_RAISON_SOCIALE, 
         					SESSION_PEC.DAT_DEBUT as DAT_DEBUT,
         					#PLAN_FINANCEMENT_US_OF.MNT_REGLE_HT AS MNT_REGLE_HT,
         					TYPE_FACTURE.LIBC_TYPE_FACTURE,
         					POSTE_COUT_REGLE.NUM_FACTURE, 
         					SESSION_PEC.DAT_FIN as DAT_FIN,
         					#PLAN_FINANCEMENT_US_OF.MNT_REGLE_TVA AS MNT_REGLE_TVA,
         					SESSION_PEC.COD_SESSION_PEC,
         					MODULE_PEC.ID_MODULE_PEC,
         					STAGIAIRE_PEC.ID_ETABLISSEMENT AS ID_OF, 
         					#PLAN_FINANCEMENT_US_OF.MNT_REGLE_HT + #PLAN_FINANCEMENT_US_OF.MNT_REGLE_TVA   AS MNT_REGLE_TTC,

         					#PLAN_FINANCEMENT_US_OF.MNT_REGLE_HT + #PLAN_FINANCEMENT_US_OF.MNT_REGLE_TVA AS MNT_POSTE_COUT_REGLE_TTC
         				FROM
         					REGLEMENT 
         						INNER JOIN POSTE_COUT_REGLE			ON REGLEMENT.ID_REGLEMENT = POSTE_COUT_REGLE.ID_REGLEMENT
         						INNER JOIN SESSION_PEC				ON POSTE_COUT_REGLE.ID_SESSION_PEC = SESSION_PEC.ID_SESSION_PEC
         						INNER JOIN MODULE_PEC				ON SESSION_PEC.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         						INNER JOIN STAGIAIRE_PEC			ON SESSION_PEC.ID_SESSION_PEC = STAGIAIRE_PEC.ID_SESSION_PEC
         						INNER JOIN ETABLISSEMENT			ON STAGIAIRE_PEC.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT 
         						INNER JOIN ADHERENT					ON ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT
         						INNER JOIN #PLAN_FINANCEMENT_US_OF	ON #PLAN_FINANCEMENT_US_OF.ID_POSTE_COUT_REGLE=POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE AND #PLAN_FINANCEMENT_US_OF.ID_ETABLISSEMENT=ETABLISSEMENT.ID_ETABLISSEMENT
         						INNER JOIN TYPE_FACTURE				ON POSTE_COUT_REGLE.ID_TYPE_FACTURE = TYPE_FACTURE.ID_TYPE_FACTURE
         			   WHERE
         					REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         					AND REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         					AND POSTE_COUT_REGLE.BLN_ACTIF = 1
         			)
         		END

         		IF (@TYPE_DESTINATAIRE = 1) 
         		BEGIN

         			insert into #POSTE_COUT_REGLE_ADH_OF (ID_POSTE_COUT_REGLE, LIB_RAISON_SOCIALE, DAT_DEBUT, MNT_REGLE_HT, LIBC_TYPE_FACTURE, NUM_FACTURE,  DAT_FIN, MNT_REGLE_TVA, COD_SESSION_PEC, ID_MODULE_PEC, ID_OF,  MNT_REGLE_TTC, MNT_POSTE_COUT_REGLE_TTC) 	(
         				SELECT DISTINCT
         					POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE,
         					convert(varchar,ORGANISME_FORMATION.COD_OF) + ' ' + ORGANISME_FORMATION.LIB_RAISON_SOCIALE as LIB_RAISON_SOCIALE,
         					SESSION_PEC.DAT_DEBUT as DAT_DEBUT,
         					POSTE_COUT_REGLE.MNT_REGLE_HT AS MNT_REGLE_HT,
         					TYPE_FACTURE.LIBC_TYPE_FACTURE,
         					POSTE_COUT_REGLE.NUM_FACTURE, 
         					SESSION_PEC.DAT_FIN as DAT_FIN,
         					POSTE_COUT_REGLE.MNT_REGLE_TVA AS MNT_REGLE_TVA,
         					SESSION_PEC.COD_SESSION_PEC,
         					MODULE_PEC.ID_MODULE_PEC,
         					null,
         					POSTE_COUT_REGLE.MNT_REGLE_TTC	AS MNT_REGLE_TTC,
         					POSTE_COUT_REGLE.MNT_REGLE_TTC AS MNT_POSTE_COUT_REGLE_TTC
         				FROM 
         					POSTE_COUT_REGLE
         						INNER JOIN REGLEMENT				ON POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT
         						INNER JOIN MODULE_PEC				ON POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         						INNER JOIN SESSION_PEC				ON SESSION_PEC.ID_SESSION_PEC = POSTE_COUT_REGLE.ID_SESSION_PEC
         						INNER JOIN NR140 ON MODULE_PEC.ID_ACTION_PEC = NR140.ID_ACTION_PEC
         						INNER JOIN ETABLISSEMENT ON ETABLISSEMENT.ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT
         						INNER JOIN ADHERENT ON ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         						LEFT OUTER JOIN ETABLISSEMENT_OF	ON ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF = MODULE_PEC.ID_ETABLISSEMENT_OF
         						LEFT OUTER JOIN ORGANISME_FORMATION	ON ORGANISME_FORMATION.ID_OF = ETABLISSEMENT_OF.ID_OF
         						INNER JOIN TYPE_FACTURE				ON TYPE_FACTURE.ID_TYPE_FACTURE = POSTE_COUT_REGLE.ID_TYPE_FACTURE
         				WHERE
         					REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         					AND REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         					AND POSTE_COUT_REGLE.BLN_ACTIF = 1
         			)
         		END

         		SELECT @TOT=SUM(round(MNT_REGLE_TVA, 2) + MNT_REGLE_HT) FROM  #POSTE_COUT_REGLE_ADH_OF;

         		WITH XMLNAMESPACES (
         			DEFAULT 'ORDRE_VIREMENT'
         		)
         		SELECT

         				dbo.GetXmlBenefiaireContact(@ID_BENEFICIAIRE, @TYPE_BENEFICIAIRE, @ID_ADRESSE, @ID_CONTACT) AS BENEFICIAIRE,

         				(
         					SELECT
         						CASE
         							WHEN (@TYPE_DESTINATAIRE = 2) THEN 'VOTRE CODE ORGANISME : '
         							WHEN (@TYPE_DESTINATAIRE = 1) THEN 'VOTRE CODE ADHRENT : '
         						END	AS VOTRE_CODE,
         						CAST(@COD_ADHERENT_OF AS VARCHAR) AS COD_ADHERENT_OF,
         						LIB_PRENOM_CHARGE_RELATION,
         						LIB_NOM_CHARGE_RELATION,
         						EMAIL_CHARGE_RELATION AS EMAIL,

         						dbo.GetXmlAdrUtilAvecTel(ID_UTILISATEUR, 
         												(
         													CASE
         														WHEN (@TYPE_DESTINATAIRE = 1) THEN 
         															(SELECT TOP 1 BLN_TSA FROM ETABLISSEMENT WHERE ID_ETABLISSEMENT = @ID_BENEFICIAIRE)
         														ELSE
         															(SELECT MAX(CAST(dbo.DossierEstTSA(COD_MODULE_PEC, 1) AS INT)) FROM #MODULE_PEC)
         													END
         												), 
         												(
         													CASE
         														WHEN (@TYPE_DESTINATAIRE = 1) THEN 1
         														ELSE 0
         													END
         												)) AS EMETTEUR,

         						cast(NUM_VIREMENT as varchar) as NUM_VIREMENT,
         						rtrim(case when patindex('%CEDEX%', LIB_VILLE) <> 0 then left(LIB_VILLE, patindex('%CEDEX%', LIB_VILLE)-1) else LIB_VILLE end) as LIB_VILLE, 
         						dbo.GetFullDate(getdate()) as DATE,
         						dbo.GetContactSalutation(@ID_CONTACT, 1) as POLITESSE_HAUT
         					FROM
         						#TMP_GENERAL
         					FOR XML RAW('REFERENCE_LETTRE'), ELEMENTS, TYPE
         				),

         				(
         					SELECT
         						MIN(dbo.GetFullDate(DAT_REGLEMENT)) AS DAT_REGLEMENT,
         						dbo.GetFrenchCurrencyFormat(CAST(SUM(POSTE_COUT_REGLE.MNT_REGLE_TTC) AS MONEY)) AS MNT_REGLE_TTC,
         						@num_iban AS IBAN,
         						@bic AS BIC,
         						dbo.GetFrenchCurrencyFormat(CAST(SUM(POSTE_COUT_REGLE.MNT_REGLE_HT) AS MONEY)) AS MNT_REGLE_HT,
         						dbo.GetFrenchCurrencyFormat(CAST(SUM(POSTE_COUT_REGLE.MNT_REGLE_TTC) - SUM(POSTE_COUT_REGLE.MNT_REGLE_HT) AS MONEY)) AS MNT_REGLE_TVA,
         						CASE 
         							WHEN (@TYPE_DESTINATAIRE = 2) THEN 'correspondant … (aux) l''action(s) de formation que vous avez r‚alis‚e(s).'			
         							WHEN (@TYPE_DESTINATAIRE = 1) THEN 'correspondant aux frais de salaires, annexes et divers li‚s aux actions de formation d‚crites ci-dessous.'			
         						END AS CORPS_TEXTE_VARIABLE

         					FROM REGLEMENT
         					JOIN POSTE_COUT_REGLE 
         					ON	 POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT
         					WHERE
         						REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         						AND REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         						AND REGLEMENT.BLN_ACTIF = 1
         						AND REGLEMENT.BLN_EN_COURS	= 1
         						AND POSTE_COUT_REGLE.BLN_ACTIF = 1
         					FOR XML RAW('TITRE'), ELEMENTS, TYPE
         				),

         				'Intitul‚ du module' AS LIB_TITRE_TABLEAU,

         				CASE
         					WHEN (@TYPE_DESTINATAIRE = 2) THEN 'Adh‚rent'
         					WHEN (@TYPE_DESTINATAIRE = 1) THEN 'Organisme Formation'
         				END	AS LIB_TITRE_TABLEAU_LIGNE_2,

         				CASE 
         				WHEN (@TYPE_DESTINATAIRE = 2) THEN
         				(
         					SELECT
         						LIBL_MODULE_PEC,
         						(
         							SELECT
         								coalesce(LIB_RAISON_SOCIALE,' ') as LIB_RAISON_SOCIALE,  
         								dbo.GetShorterDate(DAT_DEBUT) as DAT_DEBUT,
         								dbo.GetShorterDate(DAT_FIN) as DAT_FIN,
         								dbo.GetFrenchCurrencyFormat(CAST(MNT_REGLE_HT AS MONEY)) AS MNT_REGLE_HT,
         								dbo.GetFrenchCurrencyFormat(CAST(MNT_REGLE_TVA AS MONEY)) AS MNT_REGLE_TVA,
         								dbo.GetFrenchCurrencyFormat(CAST(MNT_POSTE_COUT_REGLE_TTC AS MONEY)) AS MNT_REGLE_TTC,
         								LIBC_TYPE_FACTURE,
         								NUM_FACTURE,
         								COD_SESSION_PEC
         							FROM #POSTE_COUT_REGLE_ADH_OF
         							WHERE	RUPTURE_OF.ID_MODULE_PEC = #POSTE_COUT_REGLE_ADH_OF.ID_MODULE_PEC
         							AND		MNT_POSTE_COUT_REGLE_TTC <> 0
         							FOR XML RAW ('TABLEAU_DETAIL'), ELEMENTS, TYPE
         						)
         					FROM 
         						#ORGANISME_FORMATION RUPTURE_OF
         					FOR XML RAW ('TABLEAU_RUPTURE'), ELEMENTS, TYPE
         				)

         				WHEN (@TYPE_DESTINATAIRE = 1) THEN 
         				(
         					SELECT
         						convert(varchar,COD_MODULE_PEC) + ' ' + LIBL_MODULE_PEC as LIBL_MODULE_PEC,
         						(
         							SELECT
         								coalesce(LIB_RAISON_SOCIALE,' ') as LIB_RAISON_SOCIALE,  
         								dbo.GetShorterDate(DAT_DEBUT) as DAT_DEBUT,
         								dbo.GetShorterDate(DAT_FIN) as DAT_FIN,
         								dbo.GetFrenchCurrencyFormat(CAST(MNT_REGLE_HT AS MONEY)) AS MNT_REGLE_HT,
         								dbo.GetFrenchCurrencyFormat(CAST(MNT_REGLE_TVA AS MONEY)) AS MNT_REGLE_TVA,
         								dbo.GetFrenchCurrencyFormat(CAST(MNT_POSTE_COUT_REGLE_TTC AS MONEY)) AS MNT_REGLE_TTC,
         								LIBC_TYPE_FACTURE,
         								NUM_FACTURE,
         								COD_SESSION_PEC
         							FROM #POSTE_COUT_REGLE_ADH_OF
         							WHERE	  RUPTURE_MOD.ID_MODULE_PEC = #POSTE_COUT_REGLE_ADH_OF.ID_MODULE_PEC
         								  AND MNT_POSTE_COUT_REGLE_TTC <> 0
         							FOR XML RAW ('TABLEAU_DETAIL'), ELEMENTS, TYPE
         						)
         					FROM
         						#MODULE_PEC RUPTURE_MOD
         					WHERE
         						RUPTURE_MOD.ID_ADHERENT = @ID_ADHERENT
         					FOR XML RAW ('TABLEAU_RUPTURE'), ELEMENTS, TYPE
         				)
         				END,

         				(
         				SELECT dbo.GetFrenchCurrencyFormat(CAST(@TOT AS MONEY)) AS MONTANT_TOTAL 
         				FOR XML RAW ('TABLEAU_TOTAL'), ELEMENTS, TYPE
         				),

         				(
         				SELECT dbo.GetContactSalutation(@ID_CONTACT, 1) as POLITESSE_BAS
         				FOR XML RAW ('POLITESSE_BAS'), ELEMENTS, TYPE
         				)

         		FOR XML RAW('REGLEMENT'), ELEMENTS

         	END
GO

         CREATE PROCEDURE [dbo].[LEC_GRP_SESSION_PRO_HORS_REGLEMENT]
         AS
         BEGIN

         	DECLARE @NB_SESSION_PRO	AS INT

         	SET @NB_SESSION_PRO =
         	(
         		SELECT
         				COUNT(ID_SESSION_PRO)
         		FROM
         				SESSION_PRO
         				INNER JOIN SESSION_BAP_PRO ON (
         							(SESSION_PRO.ID_SESSION_BAP_PRO_OF = SESSION_BAP_PRO.ID_SESSION_BAP_PRO AND SESSION_PRO.DAT_BAP_OF IS NOT NULL) 
         							OR (SESSION_PRO.ID_SESSION_BAP_PRO_ADH = SESSION_BAP_PRO.ID_SESSION_BAP_PRO AND SESSION_PRO.DAT_BAP_ADH IS NOT NULL))
         		WHERE	
         					SESSION_PRO.BLN_ACTIF = 1
         				AND	SESSION_PRO.ID_REGLEMENT_PRO_ADH IS NULL
         				AND	SESSION_PRO.ID_REGLEMENT_PRO_OF  IS NULL
         				AND	SESSION_BAP_PRO.DAT_PAIEMENT IS NULL 
         				AND SESSION_BAP_PRO.DAT_RECEPTION IS NOT NULL
         	)

         	SELECT 'Return Value' = COALESCE(@NB_SESSION_PRO,0)
         END

GO

         CREATE PROCEDURE [dbo].[INS_HISTO_OF]

         	@ID_OF int,

         	@ID_OF_REPRENEUR int,

         	@ID_TIERS_MANDATAIRE int,

         	@TYPE_DONNEE varchar(50),

         	@DAT_DEBUT datetime,

         	@DAT_FIN datetime,

         	@VAL_ID_DONNEE int

         AS

         	DECLARE @VAL_LIB_DONNEE AS VARCHAR(50)

         	IF( @TYPE_DONNEE = 'ID_SITUATION_ECONOMIQUE')

         	BEGIN

         	SET @VAL_LIB_DONNEE = (SELECT TOP 1 LIBL_SITUATION_ECONOMIQUE FROM SITUATION_ECONOMIQUE WHERE ID_SITUATION_ECONOMIQUE = @VAL_ID_DONNEE)

         	END

         	insert into HISTO_OF

         		(

         			ID_OF,

         			ID_OF_REPRENEUR,

         			ID_TIERS_MANDATAIRE,

         			DAT_DEBUT,

         			DAT_FIN,

         			TYPE_DONNEE,

         			VAL_LIB_DONNEE,

         			VAL_ID_DONNEE

         		)

         	values

         		(

         			@ID_OF,

         			@ID_OF_REPRENEUR,

         			@ID_TIERS_MANDATAIRE,

         			@DAT_DEBUT,

         			@DAT_FIN,

         			@TYPE_DONNEE,

         			@VAL_LIB_DONNEE,

         			@VAL_ID_DONNEE

         		)

         	RETURN SCOPE_IDENTITY()

GO

         CREATE PROCEDURE EDT_ORDRES_VIREMENT_COPIE
         	@ID_ETABLISSEMENT		INT,
         	@ID_BENEFICIAIRE		INT,
         	@TYPE_BENEFICIAIRE		INT,
         	@ID_ADRESSE				INT,
         	@ID_CONTACT				INT,
         	@TYPE_DESTINATAIRE		INT,
         	@ID_TRANSACTION			INT,
         	@ID_REGLEMENT			INT
         AS
         	BEGIN
         		DECLARE
         			@MODE_EDITION TINYINT,
         			@COD_ADHERENT_OF AS VARCHAR(8),
         			@ID_OF AS INT,
         			@ID_ADHERENT AS INT,
         			@LIB_RAISON_SOCIALE_ADHERENT AS VARCHAR(50),
         			@LIB_RAISON_SOCIALE_OF AS VARCHAR(64),
         			@ID_UTIL AS INT,
         			@LIB_VILLE AS VARCHAR(50),
         			@ID_ETAB_OF AS INT,
         			@ID_ETAB AS INT,
         			@TOT AS MONEY,

         			@NUM_IBAN VARCHAR(34),
         			@BIC VARCHAR(11)

         		SELECT
         			@NUM_IBAN = NUM_IBAN,
         			@BIC = BIC
         		FROM
         			[TRANSACTION]
         		WHERE
         			ID_TRANSACTION = @ID_TRANSACTION

         		SET @MODE_EDITION = 1

         		SET @ID_ETAB = NULL
         		SET @ID_ETAB_OF = NULL

         		IF (@TYPE_DESTINATAIRE = 1)
         		BEGIN
         			SELECT
         				@ID_ADHERENT					= ADHERENT.ID_ADHERENT,
         				@COD_ADHERENT_OF				= ADHERENT.COD_ADHERENT,
         				@LIB_RAISON_SOCIALE_ADHERENT	= ADHERENT.LIB_RAISON_SOCIALE
         			FROM
         				ETABLISSEMENT
         			JOIN
         				ADHERENT
         			ON	ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT
         			WHERE
         				ETABLISSEMENT.ID_ETABLISSEMENT = @ID_ETABLISSEMENT
         		END

         		IF (@TYPE_DESTINATAIRE = 2)
         		BEGIN
         			SELECT
         				@ID_OF							= ORGANISME_FORMATION.ID_OF,
         				@COD_ADHERENT_OF				= ORGANISME_FORMATION.COD_OF,
         				@LIB_RAISON_SOCIALE_OF			= ORGANISME_FORMATION.LIB_RAISON_SOCIALE
         			FROM
         				ETABLISSEMENT_OF
         			JOIN 
         				ORGANISME_FORMATION	
         			ON	ETABLISSEMENT_OF.ID_OF = ORGANISME_FORMATION.ID_OF
         			WHERE
         				ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF = @ID_ETABLISSEMENT

         		END

         		SELECT DISTINCT
         			MODULE_PEC.LIBL_MODULE_PEC,
         			MODULE_PEC.ID_MODULE_PEC
         		INTO
         			[#ORGANISME_FORMATION]
         		FROM
         			POSTE_COUT_REGLE
         		JOIN 
         			REGLEMENT
         		ON	POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT
         		JOIN 
         			MODULE_PEC
         		ON	POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         		WHERE
         			REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         		AND REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         		AND POSTE_COUT_REGLE.BLN_ACTIF = 1;

         		SELECT
         			SUM(PLAN_FINANCEMENT_US.MNT_PLAN_FINANCEMENT_US)		AS MNT_REGLE_HT,
         			SUM(PLAN_FINANCEMENT_US.MNT_PLAN_FINANCEMENT_US_TVA)	AS MNT_REGLE_TVA,

         			PLAN_FINANCEMENT_US.ID_POSTE_COUT_REGLE, 
         			STAGIAIRE_PEC.ID_ETABLISSEMENT 
         		INTO
         			[#PLAN_FINANCEMENT_US_OF]
         		FROM
         			PLAN_FINANCEMENT_US
         		JOIN 
         			UNITE_STAGIAIRE	
         		ON	PLAN_FINANCEMENT_US.ID_UNITE_STAGIAIRE = UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE
         		JOIN 
         			STAGIAIRE_PEC
         		ON	UNITE_STAGIAIRE.ID_STAGIAIRE_PEC = STAGIAIRE_PEC.ID_STAGIAIRE_PEC
         		JOIN 
         			POSTE_COUT_REGLE
         		ON	PLAN_FINANCEMENT_US.ID_POSTE_COUT_REGLE = POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE
         		JOIN 
         			REGLEMENT
         		ON	REGLEMENT.ID_REGLEMENT = POSTE_COUT_REGLE.ID_REGLEMENT
         		WHERE
         			REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         		AND REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         		AND POSTE_COUT_REGLE.BLN_ACTIF = 1
         		GROUP BY
         			PLAN_FINANCEMENT_US.ID_POSTE_COUT_REGLE,
         			STAGIAIRE_PEC.ID_ETABLISSEMENT

         		SELECT DISTINCT 
         			MODULE_PEC.ID_MODULE_PEC,
         			MODULE_PEC.COD_MODULE_PEC,	
         			MODULE_PEC.LIBL_MODULE_PEC,
         			ADHERENT.ID_ADHERENT,
         			ADHERENT.COD_ADHERENT,
         			ADHERENT.LIB_RAISON_SOCIALE
         		INTO
         			#MODULE_PEC
         		FROM 
         			REGLEMENT
         		JOIN 
         			POSTE_COUT_REGLE 
         		ON	POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT	
         		JOIN 
         			MODULE_PEC 
         		ON	POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         		JOIN 
         			NR140 
         		ON	MODULE_PEC.ID_ACTION_PEC = NR140.ID_ACTION_PEC
         		JOIN 
         			ETABLISSEMENT 
         		ON	ETABLISSEMENT.ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT
         		JOIN 
         			ADHERENT 
         		ON	ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         		WHERE
         			REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         		AND REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         		AND POSTE_COUT_REGLE.BLN_ACTIF = 1

         		CREATE TABLE #TMP_GENERAL
         		(
         			LIB_NOM_CONSEILLER VARCHAR(35), 
         			LIB_PNM_CONSEILLER VARCHAR(35), 
         			ID_UTILISATEUR INT, 
         			LIB_PRENOM_CHARGE_RELATION VARCHAR(35), 
         			LIB_NOM_CHARGE_RELATION VARCHAR(35), 
         			LIB_VILLE VARCHAR(50), 
         			EMAIL_CHARGE_RELATION VARCHAR(100), 
         			NUM_VIREMENT INT
         		)

         		IF (@TYPE_DESTINATAIRE = 1)
         			INSERT INTO #TMP_GENERAL
         			SELECT	DISTINCT
         					CM.LIB_NOM			as LIB_NOM_CONSEILLER,
         					CM.LIB_PNM			as LIB_PNM_CONSEILLER,
         					CR.ID_UTILISATEUR,
         					CR.LIB_PNM			as LIB_PRENOM_CHARGE_RELATION,
         					CR.LIB_NOM			as LIB_NOM_CHARGE_RELATION,
         					CR.LIB_VILLE,
         					CR.EMAIL			as EMAIL_CHARGE_RELATION,
         					REGLEMENT.NUM_VIREMENT
         			FROM 
         				REGLEMENT
         			JOIN 
         				POSTE_COUT_REGLE 
         			ON	POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT	
         			JOIN 
         				MODULE_PEC 
         			ON	POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         			JOIN 
         				NR140 
         			ON	MODULE_PEC.ID_ACTION_PEC = NR140.ID_ACTION_PEC
         			JOIN 
         				ETABLISSEMENT 
         			ON	ETABLISSEMENT.ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT
         			AND	ETABLISSEMENT.ID_ETABLISSEMENT = POSTE_COUT_REGLE.ID_ETABLISSEMENT 
         			JOIN 
         				ADHERENT 
         			ON	ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         			JOIN
         				ACTION_PEC
         			ON	ACTION_PEC.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC
         			LEFT JOIN
         				UTILISATEUR CR 
         			ON	ETABLISSEMENT.ID_CHARGEE_RELATION = CR.ID_UTILISATEUR	
         			LEFT JOIN
         				UTILISATEUR CM 
         			ON	ETABLISSEMENT.ID_CHARGEE_MISSION = CM.ID_UTILISATEUR	
         			WHERE
         				REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         			AND REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         			AND POSTE_COUT_REGLE.BLN_ACTIF = 1

         		IF (@TYPE_DESTINATAIRE = 2)
         			INSERT INTO #TMP_GENERAL
         			SELECT	TOP 1
         					CM.LIB_NOM			AS LIB_NOM_CONSEILLER,
         					CM.LIB_PNM			AS LIB_PNM_CONSEILLER,
         					CR.ID_UTILISATEUR,
         					CR.LIB_PNM			AS LIB_PRENOM_CHARGE_RELATION,
         					CR.LIB_NOM			AS LIB_NOM_CHARGE_RELATION,
         					CR.LIB_VILLE,
         					CR.EMAIL			AS EMAIL_CHARGE_RELATION,
         					REGLEMENT.NUM_VIREMENT
         			FROM 
         				REGLEMENT
         			JOIN 
         				POSTE_COUT_REGLE 
         			ON	POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT	
         			JOIN 
         				MODULE_PEC 
         			ON	POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         			JOIN 
         				NR140 
         			ON	MODULE_PEC.ID_ACTION_PEC = NR140.ID_ACTION_PEC
         			JOIN 
         				ETABLISSEMENT 
         			ON	ETABLISSEMENT.ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT
         			JOIN 
         				ADHERENT 
         			ON	ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         			JOIN
         				ACTION_PEC
         			ON	ACTION_PEC.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC
         			LEFT JOIN
         				UTILISATEUR CR 
         			ON	ETABLISSEMENT.ID_CHARGEE_RELATION = CR.ID_UTILISATEUR	
         			LEFT JOIN
         				UTILISATEUR CM 
         			ON	ETABLISSEMENT.ID_CHARGEE_MISSION = CM.ID_UTILISATEUR	
         			WHERE
         				REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         			AND REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         			AND POSTE_COUT_REGLE.BLN_ACTIF = 1

         		CREATE TABLE #POSTE_COUT_REGLE_ADH_OF
         		(
         			ID_POSTE_COUT_REGLE INT,
         			LIB_RAISON_SOCIALE VARCHAR(100), 
         			DAT_DEBUT DATETIME,
         			MNT_REGLE_HT DECIMAL(18,2),
         			LIBC_TYPE_FACTURE VARCHAR(50),
         			NUM_FACTURE VARCHAR(50), 
         			DAT_FIN DATETIME,
         			MNT_REGLE_TVA DECIMAL(18,2),
         			COD_SESSION_PEC VARCHAR(17),
         			ID_MODULE_PEC INT, 
         			ID_OF INT, 
         			MNT_REGLE_TTC DECIMAL(18,2),
         			MNT_POSTE_COUT_REGLE_TTC DECIMAL(18,2)
         		)

         		IF (@TYPE_DESTINATAIRE = 2) 
         		BEGIN

         			INSERT INTO #POSTE_COUT_REGLE_ADH_OF (ID_POSTE_COUT_REGLE, LIB_RAISON_SOCIALE, DAT_DEBUT, MNT_REGLE_HT, LIBC_TYPE_FACTURE, NUM_FACTURE,  DAT_FIN, MNT_REGLE_TVA, COD_SESSION_PEC, ID_MODULE_PEC, ID_OF,  MNT_REGLE_TTC, MNT_POSTE_COUT_REGLE_TTC) 	(
         				SELECT DISTINCT
         					POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE,
         					ADHERENT.LIB_RAISON_SOCIALE AS LIB_RAISON_SOCIALE, 
         					SESSION_PEC.DAT_DEBUT AS DAT_DEBUT,
         					#PLAN_FINANCEMENT_US_OF.MNT_REGLE_HT AS MNT_REGLE_HT,
         					TYPE_FACTURE.LIBC_TYPE_FACTURE,
         					POSTE_COUT_REGLE.NUM_FACTURE, 
         					SESSION_PEC.DAT_FIN AS DAT_FIN,
         					#PLAN_FINANCEMENT_US_OF.MNT_REGLE_TVA AS MNT_REGLE_TVA,
         					SESSION_PEC.COD_SESSION_PEC,
         					MODULE_PEC.ID_MODULE_PEC,
         					STAGIAIRE_PEC.ID_ETABLISSEMENT AS ID_OF, 
         					#PLAN_FINANCEMENT_US_OF.MNT_REGLE_HT + #PLAN_FINANCEMENT_US_OF.MNT_REGLE_TVA   AS MNT_REGLE_TTC,

         					#PLAN_FINANCEMENT_US_OF.MNT_REGLE_HT + #PLAN_FINANCEMENT_US_OF.MNT_REGLE_TVA AS MNT_POSTE_COUT_REGLE_TTC
         				FROM
         					REGLEMENT 
         						INNER JOIN POSTE_COUT_REGLE			ON REGLEMENT.ID_REGLEMENT = POSTE_COUT_REGLE.ID_REGLEMENT
         						INNER JOIN SESSION_PEC				ON POSTE_COUT_REGLE.ID_SESSION_PEC = SESSION_PEC.ID_SESSION_PEC
         						INNER JOIN MODULE_PEC				ON SESSION_PEC.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         						INNER JOIN STAGIAIRE_PEC			ON SESSION_PEC.ID_SESSION_PEC = STAGIAIRE_PEC.ID_SESSION_PEC
         						INNER JOIN ETABLISSEMENT			ON STAGIAIRE_PEC.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT 
         						INNER JOIN ADHERENT					ON ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT
         						INNER JOIN #PLAN_FINANCEMENT_US_OF	ON #PLAN_FINANCEMENT_US_OF.ID_POSTE_COUT_REGLE=POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE AND #PLAN_FINANCEMENT_US_OF.ID_ETABLISSEMENT=ETABLISSEMENT.ID_ETABLISSEMENT
         						INNER JOIN TYPE_FACTURE				ON POSTE_COUT_REGLE.ID_TYPE_FACTURE = TYPE_FACTURE.ID_TYPE_FACTURE
         			   WHERE
         					REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         					AND REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         					AND POSTE_COUT_REGLE.BLN_ACTIF = 1
         			)
         		END

         		IF (@TYPE_DESTINATAIRE = 1) 
         		BEGIN

         			INSERT INTO #POSTE_COUT_REGLE_ADH_OF (ID_POSTE_COUT_REGLE, LIB_RAISON_SOCIALE, DAT_DEBUT, MNT_REGLE_HT, LIBC_TYPE_FACTURE, NUM_FACTURE,  DAT_FIN, MNT_REGLE_TVA, COD_SESSION_PEC, ID_MODULE_PEC, ID_OF,  MNT_REGLE_TTC, MNT_POSTE_COUT_REGLE_TTC) 	(
         				SELECT DISTINCT
         					POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE,
         					CONVERT(VARCHAR,ORGANISME_FORMATION.COD_OF) + ' ' + ORGANISME_FORMATION.LIB_RAISON_SOCIALE AS LIB_RAISON_SOCIALE,
         					SESSION_PEC.DAT_DEBUT AS DAT_DEBUT,
         					POSTE_COUT_REGLE.MNT_REGLE_HT AS MNT_REGLE_HT,
         					TYPE_FACTURE.LIBC_TYPE_FACTURE,
         					POSTE_COUT_REGLE.NUM_FACTURE, 
         					SESSION_PEC.DAT_FIN AS DAT_FIN,
         					POSTE_COUT_REGLE.MNT_REGLE_TVA AS MNT_REGLE_TVA,
         					SESSION_PEC.COD_SESSION_PEC,
         					MODULE_PEC.ID_MODULE_PEC,
         					NULL,
         					POSTE_COUT_REGLE.MNT_REGLE_TTC	AS MNT_REGLE_TTC,
         					POSTE_COUT_REGLE.MNT_REGLE_TTC AS MNT_POSTE_COUT_REGLE_TTC
         				FROM 
         					POSTE_COUT_REGLE
         						INNER JOIN REGLEMENT				ON POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT
         						INNER JOIN MODULE_PEC				ON POSTE_COUT_REGLE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         						INNER JOIN SESSION_PEC				ON SESSION_PEC.ID_SESSION_PEC = POSTE_COUT_REGLE.ID_SESSION_PEC
         						INNER JOIN NR140					ON MODULE_PEC.ID_ACTION_PEC = NR140.ID_ACTION_PEC
         						INNER JOIN ETABLISSEMENT			ON ETABLISSEMENT.ID_ETABLISSEMENT = NR140.ID_ETABLISSEMENT
         						INNER JOIN ADHERENT					ON ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         						LEFT OUTER JOIN ETABLISSEMENT_OF	ON ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF = MODULE_PEC.ID_ETABLISSEMENT_OF
         						LEFT OUTER JOIN ORGANISME_FORMATION	ON ORGANISME_FORMATION.ID_OF = ETABLISSEMENT_OF.ID_OF
         						INNER JOIN TYPE_FACTURE				ON TYPE_FACTURE.ID_TYPE_FACTURE = POSTE_COUT_REGLE.ID_TYPE_FACTURE
         				WHERE
         					REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         					AND REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         					AND POSTE_COUT_REGLE.BLN_ACTIF = 1
         			)
         		END

         		SELECT @TOT = SUM(ROUND(MNT_REGLE_TVA, 2) + MNT_REGLE_HT) FROM  #POSTE_COUT_REGLE_ADH_OF;

         		WITH XMLNAMESPACES (
         			DEFAULT 'ORDRE_VIREMENT_COPIE'
         		)
         		SELECT

         				dbo.GetXmlBenefiaireContact(@ID_BENEFICIAIRE, @TYPE_BENEFICIAIRE, @ID_ADRESSE, @ID_CONTACT) AS BENEFICIAIRE,
         				(
         					SELECT
         						CASE
         							WHEN (@TYPE_DESTINATAIRE = 2) THEN 'VOTRE CODE ORGANISME : '
         							WHEN (@TYPE_DESTINATAIRE = 1) THEN 'VOTRE CODE ADHRENT : '
         						END	AS VOTRE_CODE,
         						CAST(@COD_ADHERENT_OF AS VARCHAR) AS COD_ADHERENT_OF,
         						LIB_PRENOM_CHARGE_RELATION,
         						LIB_NOM_CHARGE_RELATION,
         						EMAIL_CHARGE_RELATION AS EMAIL,

         						dbo.GetXmlAdrUtilAvecTel(ID_UTILISATEUR, 
         												(
         													CASE
         														WHEN (@TYPE_DESTINATAIRE = 1) THEN 
         															(SELECT TOP 1 BLN_TSA FROM ETABLISSEMENT WHERE ID_ETABLISSEMENT = @ID_BENEFICIAIRE)
         														ELSE
         															(SELECT MAX(CAST(dbo.DossierEstTSA(COD_MODULE_PEC, 1) AS INT)) FROM #MODULE_PEC)
         													END
         												), 
         												(
         													CASE
         														WHEN (@TYPE_DESTINATAIRE = 1) THEN 1
         														ELSE 0
         													END
         												)) AS EMETTEUR,

         						CAST(NUM_VIREMENT AS VARCHAR) AS NUM_VIREMENT,
         						RTRIM(CASE WHEN PATINDEX('%CEDEX%', LIB_VILLE) <> 0 THEN LEFT(LIB_VILLE, PATINDEX('%CEDEX%', LIB_VILLE)-1) ELSE LIB_VILLE END) AS LIB_VILLE, 
         						dbo.GetFullDate(GETDATE()) AS DATE,
         						dbo.GetContactSalutation(@ID_CONTACT, 1) AS POLITESSE_HAUT
         					FROM
         						#TMP_GENERAL
         					FOR XML RAW('REFERENCE_LETTRE'), ELEMENTS, TYPE
         				),

         				(
         					SELECT
         						MIN(dbo.GetFullDate(DAT_REGLEMENT)) AS DAT_REGLEMENT,
         						dbo.GetFrenchCurrencyFormat(CAST(SUM(POSTE_COUT_REGLE.MNT_REGLE_TTC) AS MONEY)) AS MNT_REGLE_TTC,
         						@num_iban AS IBAN,
         						@BIC AS BIC,
         						dbo.GetFrenchCurrencyFormat(CAST(SUM(POSTE_COUT_REGLE.MNT_REGLE_HT) AS MONEY)) AS MNT_REGLE_HT,
         						dbo.GetFrenchCurrencyFormat(CAST(SUM(POSTE_COUT_REGLE.MNT_REGLE_TTC) - SUM(POSTE_COUT_REGLE.MNT_REGLE_HT) AS MONEY)) AS MNT_REGLE_TVA,
         						CASE 
         							WHEN (@TYPE_DESTINATAIRE = 2) THEN 'correspondant … (aux) l''action(s) de formation que vous avez r‚alis‚e(s).'			
         							WHEN (@TYPE_DESTINATAIRE = 1) THEN 'correspondant aux frais de salaires, annexes et divers li‚s aux actions de formation d‚crites ci-dessous.'			
         						END AS CORPS_TEXTE_VARIABLE

         					FROM REGLEMENT
         					JOIN POSTE_COUT_REGLE 
         					ON	 POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT
         					WHERE
         						REGLEMENT.ID_TRANSACTION = @ID_TRANSACTION
         						AND REGLEMENT.ID_REGLEMENT = @ID_REGLEMENT
         						AND REGLEMENT.BLN_ACTIF = 1
         						AND REGLEMENT.BLN_EN_COURS	= 1
         						AND POSTE_COUT_REGLE.BLN_ACTIF = 1
         					FOR XML RAW('TITRE'), ELEMENTS, TYPE
         				),

         				'Intitul‚ du module' AS LIB_TITRE_TABLEAU,

         				CASE
         					WHEN (@TYPE_DESTINATAIRE = 2) THEN 'Adh‚rent'
         					WHEN (@TYPE_DESTINATAIRE = 1) THEN 'Organisme Formation'
         				END	AS LIB_TITRE_TABLEAU_LIGNE_2,

         				CASE 
         				WHEN (@TYPE_DESTINATAIRE = 2) THEN
         				(
         					SELECT
         						LIBL_MODULE_PEC,
         						(
         							SELECT
         								COALESCE(LIB_RAISON_SOCIALE,' ') AS LIB_RAISON_SOCIALE,  
         								dbo.GetShorterDate(DAT_DEBUT) AS DAT_DEBUT,
         								dbo.GetShorterDate(DAT_FIN) AS DAT_FIN,
         								dbo.GetFrenchCurrencyFormat(CAST(MNT_REGLE_HT AS MONEY)) AS MNT_REGLE_HT,
         								dbo.GetFrenchCurrencyFormat(CAST(MNT_REGLE_TVA AS MONEY)) AS MNT_REGLE_TVA,
         								dbo.GetFrenchCurrencyFormat(CAST(MNT_POSTE_COUT_REGLE_TTC AS MONEY)) AS MNT_REGLE_TTC,
         								LIBC_TYPE_FACTURE,
         								NUM_FACTURE,
         								COD_SESSION_PEC
         							FROM #POSTE_COUT_REGLE_ADH_OF
         							WHERE	  RUPTURE_OF.ID_MODULE_PEC = #POSTE_COUT_REGLE_ADH_OF.ID_MODULE_PEC
         								  AND MNT_POSTE_COUT_REGLE_TTC <> 0
         							FOR XML RAW ('TABLEAU_DETAIL'), ELEMENTS, TYPE
         						)
         					FROM 
         						#ORGANISME_FORMATION RUPTURE_OF
         					FOR XML RAW ('TABLEAU_RUPTURE'), ELEMENTS, TYPE
         				)

         				WHEN (@TYPE_DESTINATAIRE = 1) THEN 
         				(
         					SELECT
         						CONVERT(VARCHAR,COD_MODULE_PEC) + ' ' + LIBL_MODULE_PEC AS LIBL_MODULE_PEC,
         						(
         							SELECT
         								COALESCE(LIB_RAISON_SOCIALE,' ') AS LIB_RAISON_SOCIALE,  
         								dbo.GetShorterDate(DAT_DEBUT) AS DAT_DEBUT,
         								dbo.GetShorterDate(DAT_FIN) AS DAT_FIN,
         								dbo.GetFrenchCurrencyFormat(CAST(MNT_REGLE_HT AS MONEY)) AS MNT_REGLE_HT,
         								dbo.GetFrenchCurrencyFormat(CAST(MNT_REGLE_TVA AS MONEY)) AS MNT_REGLE_TVA,
         								dbo.GetFrenchCurrencyFormat(CAST(MNT_POSTE_COUT_REGLE_TTC AS MONEY)) AS MNT_REGLE_TTC,
         								LIBC_TYPE_FACTURE,
         								NUM_FACTURE,
         								COD_SESSION_PEC
         							FROM #POSTE_COUT_REGLE_ADH_OF
         							WHERE	  RUPTURE_MOD.ID_MODULE_PEC = #POSTE_COUT_REGLE_ADH_OF.ID_MODULE_PEC
         								  AND MNT_POSTE_COUT_REGLE_TTC <> 0
         							FOR XML RAW ('TABLEAU_DETAIL'), ELEMENTS, TYPE
         						)
         					FROM
         						#MODULE_PEC RUPTURE_MOD
         					WHERE
         						RUPTURE_MOD.ID_ADHERENT = @ID_ADHERENT
         					FOR XML RAW ('TABLEAU_RUPTURE'), ELEMENTS, TYPE
         				)
         				END,

         				(
         				SELECT dbo.GetFrenchCurrencyFormat(CAST(@TOT AS MONEY)) AS MONTANT_TOTAL 
         				FOR XML RAW ('TABLEAU_TOTAL'), ELEMENTS, TYPE
         				),

         				(
         				SELECT dbo.GetContactSalutation(@ID_CONTACT, 1) as POLITESSE_BAS
         				FOR XML RAW ('POLITESSE_BAS'), ELEMENTS, TYPE
         				)

         		FOR XML RAW('REGLEMENT'), ELEMENTS

         	END
GO

         CREATE PROCEDURE [dbo].[INS_NR410] 
         	@ID_ARRIVEE_PIECE_PRO			INT,
         	@ID_MOTIF_NON_CONFORM_PIECE_PRO	INT
         AS  

         	IF NOT EXISTS ( SELECT 1 
         					FROM NR410 
         					WHERE	 NR410.ID_ARRIVEE_PIECE_PRO = @ID_ARRIVEE_PIECE_PRO  
         						 AND NR410.ID_MOTIF_NON_CONFORM_PIECE_PRO = @ID_MOTIF_NON_CONFORM_PIECE_PRO  
         				)
         	BEGIN
         		INSERT INTO NR410
         		  (
         			ID_ARRIVEE_PIECE_PRO,
         			ID_MOTIF_NON_CONFORM_PIECE_PRO
         		  )
         		VALUES
         		(
         		   @ID_ARRIVEE_PIECE_PRO,
         		   @ID_MOTIF_NON_CONFORM_PIECE_PRO
         		)
         	END
GO

         CREATE PROCEDURE [dbo].[DARES_HISTO_DGEFP]
         	@ID_CONTRAT_PRO			AS INT
         AS
         BEGIN

         	DECLARE @NB_UNITE_FORMATION_TOT AS decimal(18,2)
         	DECLARE @NB_UNITE_TOTAL_TOT AS decimal(18,2)
         	DECLARE @NB_ORGANISMES_INTERVENANTS AS INT
         	DECLARE @NUM_SIRET_ORGANISME_PRINCIPAL AS VARCHAR(14)
         	DECLARE @BLN_EXTERNE tinyint

         	SELECT	@NB_UNITE_FORMATION_TOT = COALESCE(SUM(MODULE_PRO.NB_UNITE_FORMATION),0), 
         			@NB_UNITE_TOTAL_TOT = COALESCE(SUM(MODULE_PRO.NB_UNITE_TOTALE),0) 
         	FROM	CONTRAT_PRO 
         			INNER JOIN MODULE_PRO ON CONTRAT_PRO.ID_CONTRAT_PRO = MODULE_PRO.ID_CONTRAT_PRO
         			INNER JOIN TYPE_FORMATION ON MODULE_PRO.ID_TYPE_FORMATION = TYPE_FORMATION.ID_TYPE_FORMATION
         	WHERE		CONTRAT_PRO.ID_CONTRAT_PRO = @ID_CONTRAT_PRO 
         			AND	MODULE_PRO.BLN_ACTIF = 1			
         			AND TYPE_FORMATION.COD_TYPE_FORMATION != 'FTUT'

         	SELECT   @NB_ORGANISMES_INTERVENANTS = COUNT(DISTINCT ETABLISSEMENT_OF.ID_OF)
         	FROM	 MODULE_PRO 
         			 INNER JOIN ETABLISSEMENT_OF ON MODULE_PRO.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF
         	WHERE		MODULE_PRO.ID_CONTRAT_PRO = @ID_CONTRAT_PRO
         			AND MODULE_PRO.BLN_ACTIF = 1

         	SET		@NUM_SIRET_ORGANISME_PRINCIPAL = NULL
         	SET		@BLN_EXTERNE = 1
         	SELECT  @NUM_SIRET_ORGANISME_PRINCIPAL = ETABLISSEMENT_OF.NUM_SIRET,
         			@BLN_EXTERNE					= MODULE_PRO .BLN_EXTERNE 
         	FROM    MODULE_PRO 
         			LEFT JOIN ETABLISSEMENT_OF ON MODULE_PRO.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF
         	WHERE	MODULE_PRO.ID_CONTRAT_PRO = @ID_CONTRAT_PRO
         			AND MODULE_PRO.BLN_PRINCIPAL = 1

         	IF @NUM_SIRET_ORGANISME_PRINCIPAL IS NULL AND @BLN_EXTERNE = 0
         	BEGIN
         		SELECT	@NUM_SIRET_ORGANISME_PRINCIPAL = ETABLISSEMENT.NUM_SIRET
         		FROM	CONTRAT_PRO
         				INNER JOIN ETABLISSEMENT ON CONTRAT_PRO.ID_ETABLISSEMENT = ETABLISSEMENT .ID_ETABLISSEMENT 
         		WHERE	CONTRAT_PRO.ID_CONTRAT_PRO = @ID_CONTRAT_PRO
         	END

         	SELECT  TOP 1 CONTRAT_PRO.*,
         			@NB_UNITE_FORMATION_TOT			AS NB_UNITE_FORMATION,
         			@NB_UNITE_TOTAL_TOT				AS NB_UNITE_TOTALE,
         			CLASSIFICATION.COD_CLASSIFICATION, 
         			TYPE_CONTRAT_PRO.COD_TYPE_CONTRAT_PRO,
         			ADHERENT.LIB_RAISON_SOCIALE					AS LIB_RAISON_SOCIALE_ADH,
         			ETABLISSEMENT.NUM_SIRET						AS NUM_SIRET_ADH,
         			ADRESSE.LIB_ADR								AS LIB_ADR1_ADH,
         			ADRESSE.LIB_COMP_VOIE						AS LIB_ADR2_ADH,
         			ADRESSE.LIB_CP_CEDEX						AS LIB_CP_CEDEX_ADH,
         			ADRESSE.LIB_VIL_CEDEX						AS LIB_VIL_CEDEX_ADH,
         			ETABLISSEMENT_OF.NUM_SIRET					AS NUM_SIRET_OF,
         			TUTEUR.NOM_INDIVIDU							AS NOM_INDIVIDU_TUTEUR,
         			TUTEUR.PRENOM_INDIVIDU						AS PRENOM_INDIVIDU_TUTEUR,
         			TUTEUR.BLN_MASCULIN							AS BLN_MASCULIN_TUTEUR,
         			SALARIE_PRO.COD_IDE,
         			SALARIE_PRO.ID_TRANCHE_AGE, 
         			SALARIE_PRO.ID_NATIONALITE, 
         			SALARIE_PRO.BLN_TRAVAILLEUR_HANDICAPE,
         			SALARIE_PRO.LIB_DERNIERE_CERTIF_PROF,
         			SALARIE_PRO.LIB_DERNIER_EMPLOI_OCCUPE,
         			SALARIE_PRO.NUM_DUREE_SITUATION,

         			ADRESSE_SALARIE_PRO.NUM_TEL								AS NUM_TEL_SALARIE_PRO,
         			ADRESSE_SALARIE_PRO.NUM_FAX								AS NUM_FAX_SALARIE_PRO,
         			SALARIE_PRO.NUM_MOBILE									AS NUM_MOBILE_SALARIE_PRO,
         			ADRESSE_SALARIE_PRO.NUM_VOIE							AS NUM_VOIE_SALARIE_PRO,
         			COMP_NUM_ADR_SALARIE_PRO.COD_DDTEFP						AS COD_DDTEFP_COMP_NUM_VOIE_SALARIE_PRO,
         			TYPE_VOIE_SALARIE_PRO.COD_DDTEFP						AS COD_DDTEFP_TYPE_VOIE_SALARIE_PRO,
         			CASE WHEN (SELECT COD_MENTION_PARTICULIERE FROM MENTION_PARTICULIERE WHERE	ADRESSE_SALARIE_PRO.ID_MENTION_PARTICULIERE = MENTION_PARTICULIERE.ID_MENTION_PARTICULIERE) = 'BP'
         				  THEN
         					  ADRESSE_SALARIE_PRO.LIB_MENTION_PARTICULIERE
         				  ELSE
         					  NULL
         				  END
         																	AS LIB_MENTION_PARTICULIERE_SALARIE_PRO,
         			HEXAPOSTE_SALARIE_PRO.COD_INSEE_COMMUNE					AS COD_INSEE_COMMUNE_SALARIE_PRO,
         			PAYS_SALARIE_PRO.COD_DDTEFP								AS COD_PAYS_SALARIE_PRO,
         			ADRESSE_SALARIE_PRO.LIB_COMP_VOIE						AS LIB_COMP_VOIE_SALARIE_PRO,
         			ADRESSE_SALARIE_PRO.LIB_ADR								AS LIB_ADR1_SALARIE_PRO,
         			ADRESSE_SALARIE_PRO.LIB_COMP_VOIE						AS LIB_ADR2_SALARIE_PRO,
         			ADRESSE_SALARIE_PRO.LIB_CP_CEDEX						AS LIB_CP_CEDEX_SALARIE_PRO,
         			ADRESSE_SALARIE_PRO.LIB_VIL_CEDEX						AS LIB_VIL_CEDEX_SALARIE_PRO,

         			INDIVIDU.BLN_MASCULIN,
         			INDIVIDU.NOM_INDIVIDU,
         			INDIVIDU.PRENOM_INDIVIDU,
         			INDIVIDU.NOM_JEUNE_FILLE,
         			INDIVIDU.DAT_NAISSANCE,
         			NATIONALITE.COD_DDTEFP						AS COD_DDTEFP_NATIONALITE,
         			ADRESSE.NUM_TEL,
         			ADRESSE.NUM_FAX,
         			SALARIE_PRO.NUM_MOBILE,
         			ADRESSE.NUM_VOIE,
         			COMP_NUM_ADR.COD_DDTEFP						AS COD_DDTEFP_COMP_NUM_VOIE,
         			TYPE_VOIE.COD_DDTEFP						AS COD_DDTEFP_TYPE_VOIE,
         			CASE WHEN (SELECT COD_MENTION_PARTICULIERE FROM MENTION_PARTICULIERE WHERE	ADRESSE.ID_MENTION_PARTICULIERE = MENTION_PARTICULIERE.ID_MENTION_PARTICULIERE) = 'BP'
         				  THEN
         					  ADRESSE.LIB_MENTION_PARTICULIERE
         				  ELSE
         					  NULL
         				  END
         			AS LIB_MENTION_PARTICULIERE,
         			HEXAPOSTE.COD_INSEE_COMMUNE,
         			PAYS.COD_DDTEFP							AS COD_PAYS,
         			ADRESSE.LIB_COMP_VOIE,
         			TIERS.NUM_SIRET							AS NUM_SIRET_TIERS,
         			TIERS.COD_TIERS							AS COD_TIERS,
         			IDCC.COD_IDCC, 
         			IDCC.LIBL_IDCC,
         			NIVEAU.COD_DDTEFP						AS COD_DDTEFP_NIVEAU,
         			DIPLOME.COD_DDTEFP						AS COD_DDTEFP_DIPLOME, 
         			SITUATION_SALARIE.COD_DDTEFP			AS COD_DDTEFP_SITUATION_SALARIE,
         			SANCTION.COD_DDTEFP						AS COD_DDTEFP_SANCTION,
         			MOTIF_CLOTURE_PRO.COD_DDTEFP			AS COD_DDTEFP_MOTIF_CLOTURE_PRO,
         			MOTIF_CLOTURE_PRO.BLN_RUPTURE			AS BLN_RUPTURE,
         			TYPE_ISSUE_PRO.COD_TYPE_ISSUE_PRO		AS COD_DDTEFP_TYPE_ISSUE_PRO,
         			TYPE_CONTRAT.COD_DDTEFP					AS COD_DDTEFP_TYPE_CONTRAT,
         			SPECIALITE.COD_DDTEFP					AS COD_DDTEFP_SPECIALITE,
         			@NB_ORGANISMES_INTERVENANTS				AS NB_ORGANISMES_INTERVENANTS,
         			@NUM_SIRET_ORGANISME_PRINCIPAL			AS NUM_SIRET_ORGANISME_PRINCIPAL,
         			TYPOLOGIE_CONTRAT.COD_DDTEFP			AS COD_TYPOLOGIE_CONTRAT,
         			TYPE_MIN_SOCIAL.COD_DDTEFP				AS COD_MIN_SOCIAL

         	INTO	#TEMP_CONTRAT
         	FROM	CONTRAT_PRO
         			LEFT  JOIN ETABLISSEMENT		ON ETABLISSEMENT.ID_ETABLISSEMENT	= CONTRAT_PRO.ID_ETABLISSEMENT
         			INNER JOIN ADRESSE				ON ETABLISSEMENT.ID_ADRESSE_PRINCIPALE = ADRESSE.ID_ADRESSE 
         												AND ETABLISSEMENT.ID_ETABLISSEMENT = ADRESSE.ID_ETABLISSEMENT
         			LEFT JOIN	HEXAPOSTE			ON HEXAPOSTE.ID_HEXAPOSTE = ADRESSE.ID_HEXAPOSTE
         			LEFT JOIN	PAYS				ON PAYS.ID_PAYS = ADRESSE.ID_PAYS
         			LEFT JOIN  COMP_NUM_ADR			ON ADRESSE.ID_COMP_NUM_ADR = COMP_NUM_ADR.ID_COMP_NUM_ADR
         			LEFT JOIN TYPE_VOIE				ON TYPE_VOIE.ID_TYPE_VOIE = ADRESSE.ID_TYPE_VOIE

         			LEFT JOIN  ADHERENT				ON ADHERENT.ID_ADHERENT				= ETABLISSEMENT.ID_ADHERENT
         			LEFT JOIN CLASSIFICATION		ON CONTRAT_PRO.ID_CLASSIFICATION	= CLASSIFICATION.ID_CLASSIFICATION
         			LEFT JOIN TYPE_CONTRAT_PRO		ON CONTRAT_PRO.ID_TYPE_CONTRAT_PRO = TYPE_CONTRAT_PRO.ID_TYPE_CONTRAT_PRO
         			LEFT JOIN MODULE_PRO			ON CONTRAT_PRO.ID_CONTRAT_PRO = MODULE_PRO.ID_CONTRAT_PRO
         												AND  MODULE_PRO.BLN_PRINCIPAL = 1
         			LEFT JOIN ETABLISSEMENT_OF		ON MODULE_PRO.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF
         			LEFT JOIN INDIVIDU	TUTEUR		ON CONTRAT_PRO.ID_TUTEUR = TUTEUR.ID_INDIVIDU
         			INNER JOIN SALARIE_PRO			ON CONTRAT_PRO.ID_SALARIE_PRO = SALARIE_PRO.ID_SALARIE_PRO

         			INNER JOIN ADRESSE		AS ADRESSE_SALARIE_PRO		ON ADRESSE_SALARIE_PRO.ID_ADRESSE = SALARIE_PRO.ID_ADRESSE 
         			LEFT JOIN	HEXAPOSTE	AS HEXAPOSTE_SALARIE_PRO	ON HEXAPOSTE_SALARIE_PRO.ID_HEXAPOSTE = ADRESSE_SALARIE_PRO.ID_HEXAPOSTE
         			LEFT JOIN	PAYS		AS PAYS_SALARIE_PRO 		ON PAYS_SALARIE_PRO.ID_PAYS = ADRESSE_SALARIE_PRO.ID_PAYS
         			LEFT JOIN  COMP_NUM_ADR	AS COMP_NUM_ADR_SALARIE_PRO	ON ADRESSE_SALARIE_PRO.ID_COMP_NUM_ADR = COMP_NUM_ADR_SALARIE_PRO.ID_COMP_NUM_ADR
         			LEFT JOIN TYPE_VOIE		AS TYPE_VOIE_SALARIE_PRO	ON TYPE_VOIE_SALARIE_PRO.ID_TYPE_VOIE = ADRESSE_SALARIE_PRO.ID_TYPE_VOIE

         			INNER JOIN INDIVIDU				ON SALARIE_PRO.ID_INDIVIDU = INDIVIDU.ID_INDIVIDU
         			LEFT JOIN NATIONALITE			ON INDIVIDU.ID_NATIONALITE = NATIONALITE.ID_NATIONALITE
         			LEFT JOIN TIERS					ON CONTRAT_PRO.ID_TIERS_DDTE = TIERS.ID_TIERS
         			LEFT JOIN IDCC					ON CONTRAT_PRO.ID_IDCC = IDCC.ID_IDCC
         			LEFT JOIN NIVEAU				ON SALARIE_PRO.ID_NIVEAU = NIVEAU.ID_NIVEAU
         			LEFT JOIN DIPLOME				ON SALARIE_PRO.ID_DIPLOME = DIPLOME.ID_DIPLOME 
         			LEFT JOIN SITUATION_SALARIE		ON SALARIE_PRO.ID_SITUATION_SALARIE = SITUATION_SALARIE.ID_SITUATION_SALARIE
         			LEFT JOIN SANCTION				ON CONTRAT_PRO.ID_SANCTION = SANCTION.ID_SANCTION
         			LEFT JOIN MOTIF_CLOTURE_PRO		ON CONTRAT_PRO.ID_MOTIF_CLOTURE_PRO = MOTIF_CLOTURE_PRO.ID_MOTIF_CLOTURE_PRO
         			LEFT JOIN TYPE_ISSUE_PRO		ON CONTRAT_PRO.ID_TYPE_ISSUE_PRO = TYPE_ISSUE_PRO.ID_TYPE_ISSUE_PRO
         			LEFT JOIN TYPE_CONTRAT			ON CONTRAT_PRO.ID_TYPE_CONTRAT = TYPE_CONTRAT.ID_TYPE_CONTRAT

         			LEFT JOIN THEME					ON CONTRAT_PRO.ID_THEME = THEME.ID_THEME 
         			LEFT JOIN SPECIALITE			ON THEME.ID_SPECIALITE = SPECIALITE.ID_SPECIALITE

         			LEFT JOIN TYPOLOGIE_CONTRAT		ON TYPOLOGIE_CONTRAT.ID_TYPOLOGIE_CONTRAT = CONTRAT_PRO.ID_TYPOLOGIE_CONTRAT
         			LEFT JOIN TYPE_MIN_SOCIAL		ON TYPE_MIN_SOCIAL.ID_TYPE_MIN_SOCIAL = SALARIE_PRO.ID_TYPE_MIN_SOCIAL

         	WHERE	CONTRAT_PRO.ID_CONTRAT_PRO	= @ID_CONTRAT_PRO

         	SELECT  UTILISATEUR.LIB_NOM				AS LIB_NOM_UTILISATEUR, 
         			UTILISATEUR.LIB_PNM				AS LIB_PNM_UTILISATEUR,	
         			UTILISATEUR.NUM_TEL				AS NUM_TEL_UTILISATEUR, 
         			UTILISATEUR.EMAIL				AS EMAIL_UTILISATEUR, 
         			AGENCE.NUM_FAX					AS NUM_FAX_AGENCE,
         			AGENCE.NUM_TEL					AS NUM_TEL_AGENCE, 
         			AGENCE.COD_POSTAL				AS COD_POSTAL_AGENCE,
         			AGENCE.LIB_VILLE				AS LIB_VILLE_AGENCE, 
         			AGENCE.LIB_ADR1					AS LIB_ADR1_AGENCE, 
         			HEXAPOSTE.COD_INSEE_COMMUNE		AS COD_INSEE_COMMUNE_AGENCE, 
         			AGENCE.LIB_NOM_CONSEILLER		AS LIB_NOM_CONSEILLER, 
                     AGENCE.LIB_PNM_CONSEILLER		AS LIB_PNM_CONSEILLER
         	INTO	#TEMP_OPERATEUR
         	FROM    CONTRAT_PRO 
         			INNER JOIN UTILISATEUR ON CONTRAT_PRO.ID_UTILISATEUR = UTILISATEUR.ID_UTILISATEUR 
         			INNER JOIN AGENCE ON UTILISATEUR.ID_AGENCE = AGENCE.ID_AGENCE 
         			INNER JOIN HEXAPOSTE ON AGENCE.ID_HEXAPOSTE = HEXAPOSTE.ID_HEXAPOSTE
         	WHERE	CONTRAT_PRO.ID_CONTRAT_PRO	= @ID_CONTRAT_PRO

         	SELECT	ADHERENT.DAT_CREATION				AS DAT_CREATION_ADHERENT,
         			NAF.COD_NAF							AS COD_NAF, 
         			ADRESSE.NUM_TEL						AS NUM_TEL_ENTREPRENEUR,	
         			ADRESSE.NUM_FAX						AS NUM_FAX_ENTREPRENEUR, 
         			NR31.EMAIL_PRO						AS EMAIL_PRO_ENTREPRENEUR,
         			ADRESSE.NUM_VOIE					AS NUM_VOIE_ENTREPRENEUR,
         			COMP_NUM_ADR.COD_DDTEFP				AS COD_DDTEFP_ENTREPRENEUR,
         			CASE WHEN (SELECT COD_MENTION_PARTICULIERE 
         						FROM MENTION_PARTICULIERE 
         						WHERE	ADRESSE.ID_MENTION_PARTICULIERE = MENTION_PARTICULIERE.ID_MENTION_PARTICULIERE) 
         						= 'BP'
         				  THEN
         					  ADRESSE.LIB_MENTION_PARTICULIERE
         				  ELSE
         					  NULL
         			END									AS LIB_MENTION_PARTICULIERE_ENTREPRENEUR, 
         			ADRESSE.LIB_CP_CEDEX				AS LIB_CP_CEDEX_ENTREPRENEUR, 
         			ADRESSE.LIB_VIL_CEDEX				AS LIB_VIL_CEDEX_ENTREPRENEUR,
         			HEXAPOSTE.COD_INSEE_COMMUNE			AS COD_INSEE_COMMUNE_ENTREPRENEUR, 
         			PAYS.COD_DDTEFP						AS COD_PAYS_ENTREPRENEUR, 
         			ADRESSE.LIB_ADR						AS LIB_ADR_ENTREPRENEUR,  
         			ADRESSE.LIB_COMP_VOIE				AS LIB_COMP_VOIE_ENTREPRENEUR,
         			TYPE_VOIE.COD_DDTEFP				AS COD_DDTEFP_TYPE_VOIE_ENTREPRENEUR
         	INTO	#TEMP_ENTREPRENEUR
         	FROM    CONTRAT_PRO 
         			LEFT JOIN ETABLISSEMENT ON CONTRAT_PRO.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT 
         			LEFT JOIN NR31 ON ETABLISSEMENT.ID_ETABLISSEMENT = NR31.ID_ETABLISSEMENT
         								AND NR31.BLN_PRINCIPAL = 1
         			LEFT JOIN ADHERENT ON ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT 

         			LEFT JOIN NAF ON ETABLISSEMENT.ID_NAF = NAF.ID_NAF 
         			LEFT JOIN  ADRESSE ON ETABLISSEMENT.ID_ETABLISSEMENT = ADRESSE.ID_ETABLISSEMENT
         									AND ETABLISSEMENT.ID_ADRESSE_PRINCIPALE = ADRESSE.ID_ADRESSE
         			LEFT JOIN TYPE_VOIE ON TYPE_VOIE.ID_TYPE_VOIE = ADRESSE.ID_TYPE_VOIE
         			LEFT JOIN HEXAPOSTE ON ADRESSE.ID_HEXAPOSTE = HEXAPOSTE.ID_HEXAPOSTE 
         			LEFT JOIN PAYS ON ADRESSE.ID_PAYS = PAYS.ID_PAYS 
         			LEFT JOIN COMP_NUM_ADR ON ADRESSE.ID_COMP_NUM_ADR = COMP_NUM_ADR.ID_COMP_NUM_ADR
         	WHERE	CONTRAT_PRO.ID_CONTRAT_PRO	= @ID_CONTRAT_PRO

         	SELECT  CONTACT.LIB_NOM_CONTACT				AS LIB_NOM_CONTACT_ENTREPRENEUR, 
         			CONTACT.LIB_PNM_CONTACT				AS LIB_PNM_CONTACT_ENTREPRENEUR, 
         			CIVILITE.COD_DDTEFP					AS COD_DDTEFP_CIVILITE_CONTACT_ENTREPRENEUR, 
         			NAF.COD_NAF							AS COD_NAF_CONTACT_ENTREPRENEUR,
         			NR31.NUM_TEL						AS NUM_TEL_CONTACT_ENTREPRENEUR, 
         			NR31.NUM_FAX						AS NUM_FAX_CONTACT_ENTREPRENEUR, 
         			NR31.EMAIL_PRO						AS EMAIL_PRO_CONTACT_ENTREPRENEUR, 
         			ADRESSE.NUM_VOIE					AS NUM_VOIE_CONTACT_ENTREPRENEUR, 
         			COMP_NUM_ADR.COD_DDTEFP				AS COD_DDTEFP_CONTACT_ENTREPRENEUR, 
         			TYPE_VOIE.COD_DDTEFP				AS COD_DDTEF_TYPE_VOIE_CONTACT_ENTREPRENEUR,
         			CASE WHEN (SELECT COD_MENTION_PARTICULIERE 
         						FROM MENTION_PARTICULIERE 
         						WHERE	ADRESSE.ID_MENTION_PARTICULIERE = MENTION_PARTICULIERE.ID_MENTION_PARTICULIERE) 
         						= 'BP'
         				  THEN
         					  ADRESSE.LIB_MENTION_PARTICULIERE
         				  ELSE
         					  NULL
         			END									AS LIB_MENTION_PARTICULIERE_CONTACT_ENTREPRENEUR, 
         			ADRESSE.LIB_CP_CEDEX				AS LIB_CP_CEDEX_CONTACT_ENTREPRENEUR, 
         			ADRESSE.LIB_VIL_CEDEX				AS LIB_VIL_CEDEX_CONTACT_ENTREPRENEUR, 
         			HEXAPOSTE.COD_INSEE_COMMUNE			AS COD_INSEE_COMMUNE_CONTACT_ENTREPRENEUR, 
         			PAYS.COD_DDTEFP						AS COD_PAYS_CONTACT_ENTREPRENEUR,
         			ADRESSE.LIB_ADR						AS LIB_ADR_CONTACT_ENTREPRENEUR, 
         			ADRESSE.LIB_COMP_VOIE				AS LIB_COMP_VOIE_CONTACT_ENTREPRENEUR
         	INTO	#TEMP_CONTACT_ENTREPRENEUR
         	FROM    CONTRAT_PRO 
         			LEFT JOIN ETABLISSEMENT ON CONTRAT_PRO.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT 
         			LEFT JOIN ADHERENT ON ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT 

         			LEFT JOIN NR31  ON ETABLISSEMENT.ID_ETABLISSEMENT = NR31.ID_ETABLISSEMENT 
         						AND NR31.BLN_PRINCIPAL = 1
         			LEFT JOIN ADRESSE ON NR31.ID_ADRESSE = ADRESSE.ID_ADRESSE 
         			LEFT JOIN CONTACT ON NR31.ID_CONTACT = CONTACT.ID_CONTACT
         			LEFT JOIN CIVILITE ON CONTACT.ID_CIVILITE = CIVILITE.ID_CIVILITE 
         			LEFT JOIN TYPE_VOIE ON ADRESSE.ID_TYPE_VOIE = TYPE_VOIE.ID_TYPE_VOIE
         			LEFT JOIN HEXAPOSTE ON ADRESSE.ID_HEXAPOSTE = HEXAPOSTE.ID_HEXAPOSTE 
         			LEFT JOIN PAYS  ON PAYS.ID_PAYS = ADRESSE.ID_PAYS 
         			LEFT JOIN COMP_NUM_ADR ON ADRESSE.ID_COMP_NUM_ADR = COMP_NUM_ADR.ID_COMP_NUM_ADR 
         			LEFT JOIN NAF ON ETABLISSEMENT.ID_NAF = NAF.ID_NAF
         	WHERE		CONTRAT_PRO.ID_CONTRAT_PRO	= @ID_CONTRAT_PRO

         	SELECT	* INTO #TMP_HISTO
         	FROM	#TEMP_CONTRAT
         			FULL OUTER JOIN #TEMP_OPERATEUR	ON 1=1
         			FULL OUTER JOIN #TEMP_ENTREPRENEUR ON 1=1
         			FULL OUTER JOIN #TEMP_CONTACT_ENTREPRENEUR ON 1=1

         	INSERT INTO DARES_CONTRAT_DGEFP
         	(
         	ID_CONTRAT_PRO	,
         	NUM_AVENANT	,
         	DAT_CREATION	,
         	DAT_ENVOI_DGEFP	,
         	BLN_EXONERATION_CHARGES	,
         	NUM_ENREGISTREMENT_DDTE	,
         	DAT_DEPOT_DDTE	,
         	DAT_ENREGISTREMENT_DDTE	,

         	BLN_INITIAL	,
         	BLN_MODIFICATION	,
         	BLN_AVENANT	,
         	DAT_DEB_CONTRAT	,
         	DAT_FIN_CONTRAT	,
         	NUM_DUREE_HEBDO_TRAVAIL	,
         	NUM_DUREE_PERIODE_ESSAI	,
         	NUM_DUREE_CONTRAT	,
         	NB_UNITE_FORMATION	,
         	COD_CLASSIFICATION	,
         	COEF_CLASSIFICATION	,
         	MNT_SALAIRE_BRUT_MENSUEL	,
         	COD_TYPE_CONTRAT	,
         	DAT_SIGNATURE_CONTRAT	,
         	LIB_RAISON_SOCIALE_ADH	,
         	NUM_SIRET_ADH	,
         	LIB_ADR1_ADH	,
         	LIB_ADR2_ADH	,
         	LIB_CP_CEDEX_ADH	,
         	LIB_VIL_CEDEX_ADH	,
         	NUM_SIRET_OF	,
         	NOM_INDIVIDU_TUTEUR	,
         	PRENOM_INDIVIDU_TUTEUR	,
         	LIB_QUALIF_TUTEUR	,
         	NOM_FICHIER_XML	,
         	STATUT_HISTO	,
         	MOTIF_CONTROL_CONFORMITE	,
         	COMMENTAIRE_COMMANDITAIRE	,
         	ETAT_TRAITEMENT_HISTO	,
         	NUM_DEPOT_DDTE	,
         	LIB_LIEU_FORMATION	,
         	DAT_EXAMEN	,
         	LIBL_QUALIFICATION_VISEE	,
         	NB_ORGANISMES_INTERVENANTS	,
         	NUM_SIRET_ORGANISME_PRINCIPAL	,
         	EMAIL_PRO_ENTREPRENEUR	,
         	COD_NAF	,
         	COD_DDTEFP_COMP_NUM_ADR_ENTREPRENEUR	,
         	NUM_VOIE_ENTREPRENEUR	,
         	LIB_ADR_ENTREPRENEUR	,
         	LIB_COMP_VOIE_ENTREPRENEUR	,
         	LIB_CP_CEDEX_ENTREPRENEUR	,
         	LIB_VIL_CEDEX_ENTREPRENEUR	,
         	LIB_MENTION_PARTICULIERE_ENTREPRENEUR	,
         	COD_INSEE_COMMUNE_ENTREPRENEUR	,
         	COD_PAYS_ENTREPRENEUR	,
         	COD_DDTEFP_TYPE_VOIE_ENTREPRENEUR	,
         	LIB_CAISSE_RETRAITE	,
         	NUM_FAX_ENTREPRENEUR	,
         	NUM_TEL_ENTREPRENEUR	,
         	LIB_ORGANISME_PREVOYANCE	,
         	NUM_NB_SALARIE_ETABLISSEMENT	,
         	DAT_CLOTURE	,
         	BLN_PARTICIPATION_FINANCIERE	,
         	COD_DDTEFP_DIPLOME	,
         	COD_DDTEFP_NIVEAU	,
         	COD_DDTEFP_NATIONALITE	,
         	COD_DDTEFP_COMP_NUM_VOIE_SALARIE_PRO	,
         	BLN_MASCULIN	,
         	DAT_NAISSANCE	,
         	LIB_ADR1_SALARIE_PRO	,
         	LIB_ADR2_SALARIE_PRO	,
         	LIB_MENTION_PARTICULIERE_SALARIE_PRO	,
         	LIB_VIL_CEDEX_SALARIE_PRO	,
         	LIB_CP_CEDEX_SALARIE_PRO	,
         	COD_INSEE_COMMUNE_SALARIE_PRO	,
         	NUM_VOIE_SALARIE_PRO	,
         	COD_PAYS_SALARIE_PRO	,
         	LIB_DERNIERE_CERTIF_PROF	,
         	LIB_DERNIER_EMPLOI_OCCUPE	,
         	COD_IDE	,
         	PRENOM_INDIVIDU	,
         	NOM_INDIVIDU	,
         	NUM_DUREE_SITUATION	,
         	COD_DDTEFP_SITUATION_SALARIE	,
         	BLN_TRAVAILLEUR_HANDICAPE	,
         	OBTENTION_QUALIFICATION	,
         	COD_DDTEFP_MOTIF_CLOTURE_PRO	,
         	COD_DDTEFP_TYPE_VOIE_SALARIE_PRO	,
         	COD_DDTEFP_TYPE_ISSUE_PRO	,
         	COD_DDTEFP_SANCTION	,
         	LIB_EMPLOI_OCCUPE	,
         	NB_UNITE_TOTALE	,
         	COD_DDTEFP_SPECIALITE	,
         	COD_IDCC	,
         	LIBL_IDCC	,
         	COD_TYPOLOGIE_PRO ,
         	COD_MINIMUM_SOCIAL,
         	NUM_DUREE_HEBDO_TRAVAIL_HEURES,
         	NUM_DUREE_HEBDO_TRAVAIL_MINUTES )

         SELECT
         ID_CONTRAT_PRO	,
         NUM_DERNIER_AVENANT	,
         DAT_CREATION	,
         DAT_CREATION	,
         BLN_EXONERATION_CHARGES	,
         NUM_ENREGISTREMENT_DDTE,
         DAT_DEPOT_DDTE	,
         DAT_ENREGISTREMENT_DDTE	,
         BLN_INITIAL=	CASE NUM_DERNIER_AVENANT WHEN NULL THEN 1 ELSE NULL END,
         BLN_MODIFICATION = NULL,	
         BLN_AVENANT =CASE NUM_DERNIER_AVENANT WHEN NULL THEN NULL ELSE 1 END,
         DAT_DEB_CONTRAT	,
         DAT_FIN_CONTRAT	,
         NUM_DUREE_HEBDO_TRAVAIL	,
         NUM_DUREE_PERIODE_ESSAI	,
         NUM_DUREE_CONTRAT	,
         NB_UNITE_FORMATION	,
         COD_CLASSIFICATION 	,
         COEF_CLASSIFICATION ,
         MNT_SALAIRE_BRUT_MENSUEL	,
         COD_TYPE_CONTRAT_PRO	,
         DAT_SIGNATURE_CONTRAT	,
         LIB_RAISON_SOCIALE_ADH 	,
         NUM_SIRET_ADH 	,
         LIB_ADR1_ADH 	,
         LIB_ADR2_ADH 	,
         LIB_CP_CEDEX_ADH 	,
         LIB_VIL_CEDEX_ADH 	,
         ISNULL(NUM_SIRET_OF, '')	,
         NOM_INDIVIDU_TUTEUR 	,
         PRENOM_INDIVIDU_TUTEUR	,
         LIB_QUALIF_TUTEUR 	,
         'XML.XML'	,
         30	,
         NULL	,
         NULL	,
         1	,
         NUM_ENREGISTREMENT_DDTE		,
         LIB_LIEU_FORMATION ,
         DAT_EXAMEN	,
         LIBL_QUALIFICATION_VISEE	,
         NB_ORGANISMES_INTERVENANTS	,
         NUM_SIRET_ORGANISME_PRINCIPAL	,
         EMAIL_PRO_ENTREPRENEUR 	,
         COD_NAF 	,
         COD_DDTEFP_COMP_NUM_VOIE 	,
         NUM_VOIE_ENTREPRENEUR	,
         LIB_ADR_ENTREPRENEUR	,
         LIB_COMP_VOIE_ENTREPRENEUR ,
         LIB_CP_CEDEX_ENTREPRENEUR ,
         LIB_VIL_CEDEX_ENTREPRENEUR 	,
         LIB_MENTION_PARTICULIERE_ENTREPRENEUR	 ,
         COD_INSEE_COMMUNE_ENTREPRENEUR 	,
         COD_PAYS_ENTREPRENEUR,
