         CREATE PROCEDURE INS_EVENEMENT_ADMIN__REJET_CONTRAT_PRO__SS_SUITE
         	@ID_CONTRAT_PRO	INT
         AS 
         	DECLARE @ID_TYPE INT, @LIB VARCHAR(50)

         	IF (EXISTS(SELECT * FROM CONTRAT_PRO I	INNER JOIN ETAT_CONTRAT_PRO E		ON E.ID_ETAT_CONTRAT_PRO = I.ID_ETAT_CONTRAT_PRO
         											INNER JOIN MOTIF_REJET_CONTRAT MRC	ON MRC.ID_CONTRAT_PRO		= I.ID_CONTRAT_PRO
         											INNER JOIN MOTIF_REJET_PRO MRP		ON MRP.ID_MOTIF_REJET_PRO	= MRC.ID_MOTIF_REJET_PRO
         						WHERE I.BLN_ACTIF = 1 AND E.COD_ETAT_CONTRAT_PRO = 'REJETE' AND I.ID_CONTRAT_PRO = @ID_CONTRAT_PRO AND
         								COD_MOTIF_REJET_PRO = '7') )
         		BEGIN
         			SELECT @ID_TYPE = ID_TYPE_EVENEMENT_ADMIN
         					FROM	TYPE_EVENEMENT_ADMIN 
         					WHERE	COD_TYPE_EVENEMENT_ADMIN = 'SANSSUIT'

         			INSERT INTO EVENEMENT_ADMIN
         				(
         					COD_EVENEMENT_ADMIN, ID_UTILISATEUR, BLN_ACTIF, 
         					ID_TYPE_EVENEMENT_ADMIN,	LIBL_EVENEMENT_ADMIN,	
         					DAT_EVENEMENT_ADMIN,		ID_CONTRAT_PRO
         				)

         			SELECT
         					'', I.ID_UTILISATEUR, 1,
         					@ID_TYPE, 'Sans suite', 
         					getdate(), I.ID_CONTRAT_PRO
         			FROM CONTRAT_PRO I
         				INNER JOIN ETAT_CONTRAT_PRO E	ON E.ID_ETAT_CONTRAT_PRO = I.ID_ETAT_CONTRAT_PRO
         			WHERE I.BLN_ACTIF = 1 AND E.COD_ETAT_CONTRAT_PRO = 'REJETE' AND
         					I.ID_CONTRAT_PRO = @ID_CONTRAT_PRO

         			UPDATE EVENEMENT_ADMIN SET COD_EVENEMENT_ADMIN = ID_EVENEMENT_ADMIN 
         				WHERE ID_EVENEMENT_ADMIN = @@IDENTITY AND ID_TYPE_EVENEMENT_ADMIN = @ID_TYPE
         		END

GO
 CREATE PROCEDURE [dbo].[UPD_BLN_OK_PIECE_MODULE_PEC]  

         @ID_MODULE_PEC INT
         AS
         BEGIN

         	DECLARE @NUMREG INT

         	SET @NUMREG = 0

         	SELECT
         		@NUMREG = COUNT(*)
         	FROM
         		ARRIVEE_PIECE_PEC
         		INNER JOIN PIECE_PEC	ON PIECE_PEC.ID_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_PIECE_PEC

         								AND PIECE_PEC.BLN_ACTIF = 1

         								AND
         								(
         									PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1
         									OR PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1
         								)
         								AND
         								(
         									ARRIVEE_PIECE_PEC.BLN_ACTIF = 0
         									OR ARRIVEE_PIECE_PEC.BLN_CONFORME = 0
         								)
         	WHERE	ARRIVEE_PIECE_PEC.ID_MODULE_PEC = @ID_MODULE_PEC

         	UPDATE MODULE_PEC
         	SET BLN_OK_PIECE = (CASE
         							WHEN @NUMREG = 0 THEN 1
         							ELSE 0
         						END)
         	WHERE ID_MODULE_PEC = @ID_MODULE_PEC

         	EXEC UPD_POSTE_COUT_REGLE__OK_PIECE	
         	@ID_MODULE_PEC			= @ID_MODULE_PEC,	
         	@ID_SESSION_PEC			= NULL,
         	@BLN_SESSION			= 0,
         	@ID_POSTE_COUT_REGLE	= NULL
         END

GO

         CREATE PROCEDURE [dbo].[InitPass]
         	@num_siret varchar(14),
         	@perimetre varchar(50) 
         AS

         declare @pass varchar(5)
         declare @passExist varchar(5)

         exec GetPass 5, 1, @pass output

         Set @passExist = null;

         SELECT TOP 1 @passExist = PASS FROM EXTRANET WHERE LEFT(EXTRANET.NUM_SIRET, 9 ) = LEFT( @num_siret, 9 ) AND PERIMETRE = 'COLLECTE'	

         if( @passExist IS NULL )
         BEGIN
         	if not exists (select 1 from EXTRANET where num_siret = @num_siret and perimetre = @perimetre)
         	begin

         		insert into EXTRANET
         		(NUM_SIRET, PERIMETRE, PASS)
         		values (@num_siret, @perimetre, @pass)
         		print 'compte cr‚‚ identifiant: ' + @num_siret + ' p‚rimŠtre: ' + @perimetre + ' password: ' + @pass
         	end
         END
         ELSE
         BEGIN
         	if not exists (select 1 from EXTRANET where num_siret = @num_siret and perimetre = @perimetre)
         	begin

         		insert into EXTRANET
         		(NUM_SIRET, PERIMETRE, PASS)
         		values (@num_siret, @perimetre, @passExist)
         		print 'Siren existant: ' + @num_siret + ' p‚rimŠtre: ' + @perimetre + ' password: ' + @pass
         	end
         	else
         	begin

         		update	EXTRANET
         		set		pass = @pass
         		where	LEFT(EXTRANET.NUM_SIRET, 9 ) = LEFT( @num_siret, 9 )
         		and		perimetre = @perimetre
         		print 'compte mis … jour identifiant: ' + @num_siret + ' p‚rimŠtre: ' + @perimetre + ' password: ' + @pass

         	end	
         END

GO
 CREATE PROCEDURE [dbo].[EDT_RELEVE_OPERATION]
          @ID_ETABLISSEMENT  INT,
          @ID_BENEFICIAIRE  INT,
          @TYPE_BENEFICIAIRE  INT,
          @ID_ADRESSE    INT,
          @ID_CONTACT    INT,
          @ID_TYPE_RELEVE   TINYINT = 3, 
          @ID_GROUPE_UO   INT,
          @DAT_DEBUT    VARCHAR(50),
          @DAT_FIN    VARCHAR(50) 
         WITH RECOMPILE

         AS
         BEGIN

          DECLARE
           @LIB_RAISON_SOCIALE VARCHAR(50),
           @TYP_CODE VARCHAR(50),
           @CODE VARCHAR(50),
           @ID_ADH INT,
           @ID_ETAB INT

          CREATE TABLE #ListAdherent
          (
           ID_ADHERENT INT,
           ID_ETABLISSEMENT INT
          )

          CREATE TABLE #ListSIRET
          (
           CODE_SIRET VARCHAR(50),
           CP VARCHAR(5),
           VILLE VARCHAR(50)
          )

          SELECT
           @ID_ADH = ID_ADHERENT
          FROM
           ETABLISSEMENT
          WHERE
           ID_ETABLISSEMENT = @ID_ETABLISSEMENT

          IF (@ID_TYPE_RELEVE = 1)
          BEGIN
           INSERT INTO
            #ListAdherent
           SELECT
            ADHERENT.ID_ADHERENT,
            ETABLISSEMENT.ID_ETABLISSEMENT
           FROM
            ADHERENT
            INNER JOIN ETABLISSEMENT
             ON ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
           WHERE
            ADHERENT.ID_ADHERENT = @ID_ADH
            AND ETABLISSEMENT.BLN_ACTIF = 1

           SELECT
            @LIB_RAISON_SOCIALE = coalesce(dbo.IS_EMPTY(ADHERENT.LIB_ENSEIGNE), ADHERENT.LIB_RAISON_SOCIALE),
            @CODE = ADHERENT.COD_ADHERENT
           FROM
            ADHERENT
           WHERE
            ADHERENT.ID_ADHERENT = @ID_ADH

           SET
            @TYP_CODE = 'ADHERENT'

           INSERT INTO
            #ListSIRET
           SELECT
            ETABLISSEMENT.NUM_SIRET, 
            ADRESSE.LIB_CP_CEDEX,
            ADRESSE.LIB_VIL_CEDEX  
           FROM
            ETABLISSEMENT 
            LEFT JOIN ADRESSE
             ON ETABLISSEMENT.ID_ADRESSE_PRINCIPALE = ADRESSE.ID_ADRESSE
           WHERE
            ETABLISSEMENT.BLN_ACTIF = 1
            AND ETABLISSEMENT.ID_ADHERENT = @ID_ADH

           SELECT
            @ID_ETAB = @ID_ETABLISSEMENT
          END

          ELSE IF (@ID_TYPE_RELEVE = 2)
          BEGIN
           INSERT INTO
            #ListAdherent
           VALUES
           (
            @ID_ADH,
            @ID_ETABLISSEMENT
           )

           SELECT TOP 1
            @LIB_RAISON_SOCIALE = COALESCE(dbo.IS_EMPTY(ETABLISSEMENT.LIB_ENSEIGNE), ADHERENT.LIB_RAISON_SOCIALE),
            @CODE = COD_ETABLISSEMENT
           FROM
            ADHERENT
            INNER JOIN ETABLISSEMENT
             ON ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
           WHERE
            ETABLISSEMENT.ID_ETABLISSEMENT = @ID_ETABLISSEMENT

           SET
            @TYP_CODE = 'ETABLISSEMENT'

           INSERT INTO
            #ListSIRET
           SELECT
            ETABLISSEMENT.NUM_SIRET,   
            ADRESSE.LIB_CP_CEDEX,
            ADRESSE.LIB_VIL_CEDEX
           FROM
            ETABLISSEMENT
            LEFT JOIN ADRESSE
             ON ETABLISSEMENT.ID_ADRESSE_PRINCIPALE = dbo.ADRESSE.ID_ADRESSE
           WHERE
            ETABLISSEMENT.ID_ETABLISSEMENT = @ID_ETABLISSEMENT

           SELECT
            @ID_ETAB = @ID_ETABLISSEMENT
          END

          ELSE IF (@ID_TYPE_RELEVE = 3)
          BEGIN
           INSERT INTO
            #ListAdherent
           SELECT
            ETABLISSEMENT.ID_ADHERENT,
            ETABLISSEMENT.ID_ETABLISSEMENT
           FROM
            ETABLISSEMENT 
           WHERE
            ETABLISSEMENT.ID_GROUPE = @ID_GROUPE_UO

           SELECT TOP 1
            @LIB_RAISON_SOCIALE = COALESCE(dbo.IS_EMPTY(LIB_ENSEIGNE_GROUPE), LIB_GROUPE),
            @CODE = COD_GROUPE
           FROM
            GROUPE 
           WHERE
            ID_GROUPE = @ID_GROUPE_UO

           SET
            @TYP_CODE = 'GROUPE'

           INSERT INTO
            #ListSIRET
           SELECT
            ETABLISSEMENT.NUM_SIRET, 
            ADRESSE.LIB_CP_CEDEX,
            ADRESSE.LIB_VIL_CEDEX  
           FROM
            ETABLISSEMENT 
            LEFT JOIN ADRESSE
             ON ETABLISSEMENT.ID_ADRESSE_PRINCIPALE = ADRESSE.ID_ADRESSE  
           WHERE
            ETABLISSEMENT.ID_GROUPE = @ID_GROUPE_UO

           SET
            @ID_ETAB = dbo.GetEtabRepresentatifDuGroupe(@ID_GROUPE_UO)
          END

          ELSE IF (@ID_TYPE_RELEVE = 4)
          BEGIN
           INSERT INTO
            #ListAdherent
           SELECT
            ADHERENT.ID_ADHERENT,
            RATTACHEMENT.ID_ETABLISSEMENT
           FROM
            ADHERENT
            INNER JOIN RATTACHEMENT
             ON ADHERENT.ID_ETABLISSEMENT_PRINCIPAL = RATTACHEMENT.ID_ETABLISSEMENT
           WHERE
            RATTACHEMENT.ID_UO = @ID_GROUPE_UO

           SELECT
            @LIB_RAISON_SOCIALE = LIB_NOM_UO,
            @CODE = COD_UO
           FROM
            UNITE_ORGANISATIONNELLE 
           WHERE
            ID_UO = @ID_GROUPE_UO

           SET
            @TYP_CODE = 'UO'

           SELECT
            @ID_ETAB = ID_ETABLISSEMENT_PRINCIPAL
           FROM
            UNITE_ORGANISATIONNELLE
           WHERE
            ID_UO = @ID_GROUPE_UO
          END;

          SELECT DISTINCT
           MIN(MVT_BUDGETAIRE.ID_MVT_BUDGETAIRE) AS ID_MVT_BUDGETAIRE,
           MIN(MVT_BUDGETAIRE.ID_TYPE_MOUVEMENT) AS ID_TYPE_MOUVEMENT,
           MIN(ETABLISSEMENT.ID_ADHERENT)   AS ID_ADHERENT,
           MIN(ETABLISSEMENT.ID_ETABLISSEMENT)  AS ID_ETABLISSEMENT,
           MIN(MVT_BUDGETAIRE.P_E_R)    AS P_E_R,
           MIN(EVENEMENT.ID_EVENEMENT)    AS ID_EVENEMENT, 
           MIN(TYPE_ENVELOPPE.ID_DISPOSITIF)  AS ID_DISPOSITIF,
           MIN(TYPE_ENVELOPPE.ID_MODE_FINANCEMENT) AS ID_MODE_FINANCEMENT,
           MIN(NR140.NUM_INTERNE)     AS NUM_INTERNE,
           MIN(MVT_BUDGETAIRE.DAT_MVT_BUDGETAIRE) AS DAT_MVT_BUDGETAIRE,
           MIN(MODULE_PEC.COD_MODULE_PEC + ' ' + SUBSTRING(TYPE_COUT.COD_TYPE_COUT,1,3) + ' ' + MODULE_PEC.LIBL_MODULE_PEC) AS LIBL_MVT_BUDGETAIRE,
           MIN(ORGANISME_FORMATION.LIB_SIGLE_OF) AS LIB_SIGLE_OF,
           MIN(MODULE_PEC.DAT_DEBUT)    AS DAT_DEBUT,
           MIN(MODULE_PEC.DAT_FIN)     AS DAT_FIN,
           MIN(MODULE_PEC.COD_MODULE_PEC)   AS COD_MODULE_PEC,

           SUM
           (
            CASE
             WHEN (MVT_BUDGETAIRE.ID_TYPE_FINANCEMENT = 1 OR TYPE_ENVELOPPE.ID_DISPOSITIF = 2)
               THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END) 
             ELSE 0
            END
           ) AS MNT_MVT_COMPTE_COURANT,

           SUM
           (
            CASE
             WHEN  MVT_BUDGETAIRE.ID_TYPE_FINANCEMENT = 2
              THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END) 
             ELSE  0 
            END
           ) AS MNT_MVT_FONDS_MUT,

           SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE *(case SENS WHEN 'D' THEN -1 ELSE 1 END)* dbo.ONEIF(TYPE_ENVELOPPE.ID_DISPOSITIF,8)) AS ENVELOPPE_PP,

           SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE*(case SENS WHEN 'D' THEN -1 ELSE 1 END) * dbo.ONEIF(TYPE_ENVELOPPE.ID_DISPOSITIF,3))AS ENVELOPPE_DIF,

           SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE*(case SENS WHEN 'D' THEN -1 ELSE 1 END) * dbo.ONEIF(ID_MODE_FINANCEMENT,2)) AS ENVELOPPE_FIN_PUB,

           SUM
           (
            CASE
             WHEN  MVT_BUDGETAIRE.ID_ENVELOPPE IS NOT NULL
              THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END)
            END
           )
           - 
           (
            SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END) * dbo.ONEIF(TYPE_ENVELOPPE.ID_DISPOSITIF,2))
            +

            SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END) * dbo.ONEIF(TYPE_ENVELOPPE.ID_DISPOSITIF,8))
            +

            SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END) * dbo.ONEIF(TYPE_ENVELOPPE.ID_DISPOSITIF,3))
            +

            SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END) * dbo.ONEIF(ID_MODE_FINANCEMENT,2))
           )
           AS ENVELOPPE_AUTRE,
           SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END)) AS MNT_TOTAL
          INTO
           #RELEVE_OPERATION_REGLE
          FROM
           NR140
           INNER JOIN ETABLISSEMENT
            ON NR140.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT
           LEFT JOIN GROUPE
            ON ETABLISSEMENT.ID_GROUPE = GROUPE.ID_GROUPE
           INNER JOIN MVT_BUDGETAIRE
            ON ETABLISSEMENT.ID_ETABLISSEMENT = MVT_BUDGETAIRE.ID_ETABLISSEMENT
           INNER JOIN TYPE_MOUVEMENT
            ON MVT_BUDGETAIRE.ID_TYPE_MOUVEMENT = TYPE_MOUVEMENT.ID_TYPE_MOUVEMENT
           INNER JOIN EVENEMENT
            ON EVENEMENT.ID_EVENEMENT = MVT_BUDGETAIRE.ID_EVENEMENT
           INNER JOIN POSTE_COUT_REGLE
            ON EVENEMENT.ID_POSTE_COUT_REGLE = POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE
           LEFT JOIN ENVELOPPE
            ON MVT_BUDGETAIRE.ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE
             AND ENVELOPPE.BLN_ACTIF = 1
           LEFT JOIN COMPTE
            ON MVT_BUDGETAIRE.ID_COMPTE = COMPTE.ID_COMPTE
             AND COMPTE.BLN_ACTIF = 1
           LEFT JOIN TYPE_ENVELOPPE
            ON ENVELOPPE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE
             AND TYPE_ENVELOPPE.BLN_ACTIF = 1
           INNER JOIN SOUS_TYPE_COUT
            ON POSTE_COUT_REGLE.ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT
             AND SOUS_TYPE_COUT.BLN_ACTIF = 1
           INNER JOIN TYPE_COUT
            ON SOUS_TYPE_COUT.ID_TYPE_COUT = TYPE_COUT.ID_TYPE_COUT
             AND TYPE_COUT.BLN_ACTIF = 1
           INNER JOIN MODULE_PEC
            ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC
             AND MODULE_PEC.ID_ACTION_PEC = NR140.ID_ACTION_PEC
             AND MODULE_PEC.BLN_ACTIF = 1
           LEFT JOIN ETABLISSEMENT_OF
            ON MODULE_PEC.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF
           LEFT JOIN ORGANISME_FORMATION
            ON ETABLISSEMENT_OF.ID_OF = ORGANISME_FORMATION.ID_OF
           INNER JOIN PARAMETRAGE_BUDGETAIRE
            ON TYPE_MOUVEMENT.ID_TYPE_MOUVEMENT = PARAMETRAGE_BUDGETAIRE.ID_TYPE_MOUVEMENT
          WHERE
           P_E_R = 'R'
           AND
           (

            (
             MVT_BUDGETAIRE.id_enveloppe IS NOT NULL
             AND PARAMETRAGE_BUDGETAIRE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE
            )
            OR

            (
             MVT_BUDGETAIRE.id_compte IS NOT NULL
             AND PARAMETRAGE_BUDGETAIRE.ID_TYPE_COMPTE = COMPTE.ID_TYPE_COMPTE
            )
           )
           AND MVT_BUDGETAIRE.ID_ETABLISSEMENT in (select id_etablissement from #ListAdherent)
           AND ((MVT_BUDGETAIRE.ID_TYPE_MOUVEMENT BETWEEN 4 AND 17) OR (MVT_BUDGETAIRE.ID_TYPE_MOUVEMENT= 22))
           AND
           (
            (
             @ID_TYPE_RELEVE <> 3 
             AND ((@DAT_DEBUT IS NULL OR DATEDIFF(DAY,MVT_BUDGETAIRE.DAT_MVT_BUDGETAIRE,@DAT_DEBUT) <= 0)) 
             AND ((@DAT_FIN  IS NULL OR DATEDIFF(DAY,MVT_BUDGETAIRE.DAT_MVT_BUDGETAIRE,@DAT_FIN ) >= 0)) 
            )
            OR @ID_TYPE_RELEVE = 3 
           )
          GROUP BY
           ETABLISSEMENT.ID_ETABLISSEMENT,
           EVENEMENT.ID_EVENEMENT

          UNION ALL

          SELECT DISTINCT
           MVT_BUDGETAIRE.ID_MVT_BUDGETAIRE AS ID_MVT_BUDGETAIRE,
           MVT_BUDGETAIRE.ID_TYPE_MOUVEMENT AS ID_TYPE_MOUVEMENT,
           ADHERENT.ID_ADHERENT AS ID_ADHERENT,
           ETABLISSEMENT.ID_ETABLISSEMENT AS ID_ETABLISSEMENT,
           P_E_R AS P_E_R,
           NULL AS ID_EVENEMENT,
           NULL as ID_DISPOSITIF,
           NULL AS ID_MODE_FINANCEMENT,
           NULL AS NUM_INTERNE,
           MVT_BUDGETAIRE.DAT_MVT_BUDGETAIRE AS DAT_MVT_BUDGETAIRE,
           MVT_BUDGETAIRE.LIBL_MVT_BUDGETAIRE AS LIBL_MVT_BUDGETAIRE,
           NULL AS LIB_SIGLE_OF,
           NULL AS DAT_DEBUT,
           NULL AS DAT_FIN,
           ' ' AS COD_MODULE_PEC,

           CASE
            WHEN  (MVT_BUDGETAIRE.ID_TYPE_FINANCEMENT = 1 OR MVT_BUDGETAIRE.ID_ACTIVITE = 2)
             THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END)
            ELSE  0
           END AS MNT_MVT_COMPTE_COURANT,
           CASE
            WHEN  MVT_BUDGETAIRE.ID_TYPE_FINANCEMENT = 2
             THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END)
            ELSE  0
           END AS MNT_MVT_FONDS_MUT,
           NULL AS ENVELOPPE_PP,
           NULL AS ENVELOPPE_DIF,
           NULL AS ENVELOPPE_FIN_PUB,
           NULL AS ENVELOPPE_AUTRE,
           cast(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END) as money) as MNT_TOTAL
          FROM
           MVT_BUDGETAIRE
           INNER JOIN ADHERENT
            ON ADHERENT.ID_ADHERENT = MVT_BUDGETAIRE.ID_ADHERENT
           INNER JOIN ETABLISSEMENT
            ON MVT_BUDGETAIRE.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT
           INNER JOIN TYPE_MOUVEMENT
            ON MVT_BUDGETAIRE.ID_TYPE_MOUVEMENT = TYPE_MOUVEMENT.ID_TYPE_MOUVEMENT 
           INNER JOIN PARAMETRAGE_BUDGETAIRE
            ON TYPE_MOUVEMENT.ID_TYPE_MOUVEMENT = PARAMETRAGE_BUDGETAIRE.ID_TYPE_MOUVEMENT
           LEFT JOIN TYPE_COMPTE
            ON PARAMETRAGE_BUDGETAIRE.ID_TYPE_COMPTE = TYPE_COMPTE.ID_TYPE_COMPTE
           INNER JOIN EVENEMENT
            ON MVT_BUDGETAIRE.ID_EVENEMENT = EVENEMENT.ID_EVENEMENT
          WHERE
           (
            EVENEMENT.ID_TRANSFERT IS NOT NULL
            OR EVENEMENT.ID_VERSEMENT IS NOT NULL
            OR EVENEMENT.ID_VIREMENT_COMPTE IS NOT NULL
           )
           AND
           (
            TYPE_COMPTE.ID_TYPE_COMPTE = 1 
            OR MVT_BUDGETAIRE.ID_ACTIVITE = 2 
           )
           AND P_E_R = 'R'
           AND MVT_BUDGETAIRE.ID_ETABLISSEMENT in (select id_etablissement from #ListAdherent)
           AND
           (
            (MVT_BUDGETAIRE.ID_TYPE_MOUVEMENT BETWEEN 4 AND 17)
            OR (MVT_BUDGETAIRE.ID_TYPE_MOUVEMENT = 22)
           )
           AND
           (
            (
             @ID_TYPE_RELEVE <> 3 
             AND ((@DAT_DEBUT IS NULL OR DATEDIFF(DAY,MVT_BUDGETAIRE.DAT_MVT_BUDGETAIRE,@DAT_DEBUT) <= 0))
             AND ((@DAT_FIN  IS NULL OR DATEDIFF(DAY,MVT_BUDGETAIRE.DAT_MVT_BUDGETAIRE,@DAT_FIN ) >= 0))
            )
            OR @ID_TYPE_RELEVE = 3 
           )

          SELECT
           MODULE_PEC.ID_MODULE_PEC,
           SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT,
           MVT_BUDGETAIRE.ID_TYPE_MOUVEMENT,
           MIN(NR140.NUM_INTERNE) AS NUM_INTERNE,
           MIN(ETABLISSEMENT.ID_ADHERENT) AS ID_ADHERENT,
           MIN(ETABLISSEMENT.ID_ETABLISSEMENT) AS ID_ETABLISSEMENT,
           MIN(MVT_BUDGETAIRE.P_E_R) AS P_E_R,
           MIN(MVT_BUDGETAIRE.ID_MVT_BUDGETAIRE) AS ID_MVT_BUDGETAIRE,
           MIN(MVT_BUDGETAIRE.DAT_MVT_BUDGETAIRE) AS DAT_MVT_BUDGETAIRE,
           MIN(MODULE_PEC.COD_MODULE_PEC + ' ' + SUBSTRING(TYPE_COUT.COD_TYPE_COUT,1,3) + ' ' + MODULE_PEC.LIBL_MODULE_PEC) AS LIBL_MVT_BUDGETAIRE,
           MIN(ORGANISME_FORMATION.LIB_SIGLE_OF) AS LIB_SIGLE_OF,
           MIN(MODULE_PEC.DAT_DEBUT) AS DAT_DEBUT,
           MIN(MODULE_PEC.DAT_FIN) AS DAT_FIN,
           MIN(MODULE_PEC.COD_MODULE_PEC) AS COD_MODULE_PEC,

           SUM
           (
            CASE
             WHEN  (MVT_BUDGETAIRE.ID_TYPE_FINANCEMENT = 1 OR TYPE_ENVELOPPE.ID_DISPOSITIF = 2)
              THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END)
             ELSE  0
            END
           ) AS MNT_MVT_COMPTE_COURANT,

           SUM
           (
            CASE
             WHEN  MVT_BUDGETAIRE.ID_TYPE_FINANCEMENT = 2
              THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END)
             ELSE  0 
            END
           ) AS MNT_MVT_FONDS_MUT,

           SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE *(case SENS WHEN 'D' THEN -1 ELSE 1 END)* dbo.ONEIF(TYPE_ENVELOPPE.ID_DISPOSITIF,8)) AS ENVELOPPE_PP,

           SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE*(case SENS WHEN 'D' THEN -1 ELSE 1 END) * dbo.ONEIF(TYPE_ENVELOPPE.ID_DISPOSITIF,3)) AS ENVELOPPE_DIF,

           SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE *(case SENS WHEN 'D' THEN -1 ELSE 1 END)* dbo.ONEIF(ID_MODE_FINANCEMENT,2)) AS ENVELOPPE_FIN_PUB,

           SUM
           (
            CASE
             WHEN  MVT_BUDGETAIRE.ID_ENVELOPPE IS NOT NULL
             THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END)
            END
           )
           -
           (

            SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END) * dbo.ONEIF(TYPE_ENVELOPPE.ID_DISPOSITIF,2))
            +

            SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END) * dbo.ONEIF(TYPE_ENVELOPPE.ID_DISPOSITIF,8))
            +

            SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END) * dbo.ONEIF(TYPE_ENVELOPPE.ID_DISPOSITIF,3))
            +

            SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END) * dbo.ONEIF(ID_MODE_FINANCEMENT,2))
           ) AS ENVELOPPE_AUTRE,
           SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE*(case SENS WHEN 'D' THEN -1 ELSE 1 END)) AS MNT_TOTAL
          INTO
           #RELEVE_OPERATION_ENGAGE
          FROM
           NR140
           INNER JOIN ETABLISSEMENT
            ON NR140.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT
           LEFT JOIN GROUPE
            ON ETABLISSEMENT.ID_GROUPE = GROUPE.ID_GROUPE
           INNER JOIN MVT_BUDGETAIRE
            ON ETABLISSEMENT.ID_ETABLISSEMENT = MVT_BUDGETAIRE.ID_ETABLISSEMENT
           INNER JOIN TYPE_MOUVEMENT
            ON MVT_BUDGETAIRE.ID_TYPE_MOUVEMENT = TYPE_MOUVEMENT.ID_TYPE_MOUVEMENT
           INNER JOIN EVENEMENT
            ON EVENEMENT.ID_EVENEMENT = MVT_BUDGETAIRE.ID_EVENEMENT
           INNER JOIN POSTE_COUT_ENGAGE 
            ON EVENEMENT.ID_POSTE_COUT_ENGAGE = POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE
           LEFT JOIN ENVELOPPE 
            ON MVT_BUDGETAIRE.ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE
           LEFT JOIN TYPE_ENVELOPPE 
            ON ENVELOPPE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE
           LEFT JOIN COMPTE 
            ON MVT_BUDGETAIRE.ID_COMPTE = COMPTE.ID_COMPTE AND COMPTE.BLN_ACTIF = 1
           INNER JOIN SOUS_TYPE_COUT 
            ON POSTE_COUT_ENGAGE.ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT
           INNER JOIN TYPE_COUT 
            ON SOUS_TYPE_COUT.ID_TYPE_COUT = TYPE_COUT.ID_TYPE_COUT
           INNER JOIN MODULE_PEC 
            ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_ENGAGE.ID_MODULE_PEC
             AND MODULE_PEC.ID_ACTION_PEC = NR140.ID_ACTION_PEC
           LEFT JOIN ETABLISSEMENT_OF 
            ON MODULE_PEC.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF 
           LEFT JOIN ORGANISME_FORMATION 
            ON ETABLISSEMENT_OF.ID_OF = ORGANISME_FORMATION.ID_OF
           INNER JOIN PARAMETRAGE_BUDGETAIRE
            ON TYPE_MOUVEMENT.ID_TYPE_MOUVEMENT = PARAMETRAGE_BUDGETAIRE.ID_TYPE_MOUVEMENT 
          WHERE
           MVT_BUDGETAIRE.P_E_R = 'E'
           AND
           (

            (
             MVT_BUDGETAIRE.id_enveloppe IS NOT NULL
             AND PARAMETRAGE_BUDGETAIRE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE
            )
            OR

            (
             MVT_BUDGETAIRE.ID_COMPTE IS NOT NULL
             AND PARAMETRAGE_BUDGETAIRE.ID_TYPE_COMPTE = COMPTE.ID_TYPE_COMPTE
            )
           )
           AND MVT_BUDGETAIRE.ID_ETABLISSEMENT in (select id_etablissement from #ListAdherent)
           AND
           (
            (
             @ID_TYPE_RELEVE <> 3 
             AND ((@DAT_DEBUT IS NULL OR DATEDIFF(DAY,MVT_BUDGETAIRE.DAT_MVT_BUDGETAIRE,@DAT_DEBUT) <= 0))
             AND ((@DAT_FIN  IS NULL OR DATEDIFF(DAY,MVT_BUDGETAIRE.DAT_MVT_BUDGETAIRE,@DAT_FIN ) >= 0))
            )
            OR @ID_TYPE_RELEVE = 3 
           )
          GROUP BY
           MVT_BUDGETAIRE.ID_ADHERENT,
           MVT_BUDGETAIRE.ID_ETABLISSEMENT,
           MODULE_PEC.ID_MODULE_PEC,
           SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT,
           MVT_BUDGETAIRE.ID_TYPE_MOUVEMENT

          SELECT
           MODULE_PEC.ID_MODULE_PEC,
           SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT,
           MVT_BUDGETAIRE.ID_TYPE_MOUVEMENT,
           MIN(NR140.NUM_INTERNE) AS NUM_INTERNE,
           MIN(ETABLISSEMENT.ID_ADHERENT) AS ID_ADHERENT,
           MIN(ETABLISSEMENT.ID_ETABLISSEMENT) AS ID_ETABLISSEMENT,
           MIN(MVT_BUDGETAIRE.P_E_R) AS P_E_R,
           MIN(MVT_BUDGETAIRE.ID_MVT_BUDGETAIRE) AS ID_MVT_BUDGETAIRE,
           MIN(MVT_BUDGETAIRE.DAT_MVT_BUDGETAIRE) AS DAT_MVT_BUDGETAIRE,
           MIN(MODULE_PEC.COD_MODULE_PEC + ' ' + SUBSTRING(TYPE_COUT.COD_TYPE_COUT,1,3) + ' ' + MODULE_PEC.LIBL_MODULE_PEC) AS LIBL_MVT_BUDGETAIRE,
           MIN(ORGANISME_FORMATION.LIB_SIGLE_OF) AS LIB_SIGLE_OF,
           MIN(MODULE_PEC.DAT_DEBUT) AS DAT_DEBUT,
           MIN(MODULE_PEC.DAT_FIN) AS DAT_FIN,
           MIN(MODULE_PEC.COD_MODULE_PEC) AS COD_MODULE_PEC,

           SUM
           (
            CASE
             WHEN  (MVT_BUDGETAIRE.ID_TYPE_FINANCEMENT = 1 OR TYPE_ENVELOPPE.ID_DISPOSITIF = 2)
              THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END)
             ELSE 0
            END
           ) AS MNT_MVT_COMPTE_COURANT,

           SUM
           (
            CASE
             WHEN  MVT_BUDGETAIRE.ID_TYPE_FINANCEMENT = 2
              THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END)
             ELSE  0 
            END
           ) AS MNT_MVT_FONDS_MUT,

           SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE *(case SENS WHEN 'D' THEN -1 ELSE 1 END)* dbo.ONEIF(TYPE_ENVELOPPE.ID_DISPOSITIF,8)) AS ENVELOPPE_PP,

           SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE*(case SENS WHEN 'D' THEN -1 ELSE 1 END) * dbo.ONEIF(TYPE_ENVELOPPE.ID_DISPOSITIF,3)) AS ENVELOPPE_DIF,

           SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE *(case SENS WHEN 'D' THEN -1 ELSE 1 END)* dbo.ONEIF(ID_MODE_FINANCEMENT,2)) AS ENVELOPPE_FIN_PUB,

           SUM
           (
            CASE
             WHEN  MVT_BUDGETAIRE.ID_ENVELOPPE IS NOT NULL
              THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END)
            END
           )
           -
           (

            SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END) * dbo.ONEIF(TYPE_ENVELOPPE.ID_DISPOSITIF,2))
            +

            SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END) * dbo.ONEIF(TYPE_ENVELOPPE.ID_DISPOSITIF,8))
            +

            SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END) * dbo.ONEIF(TYPE_ENVELOPPE.ID_DISPOSITIF,3))
            +

            SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE * (case SENS WHEN 'D' THEN -1 ELSE 1 END) * dbo.ONEIF(ID_MODE_FINANCEMENT,2))
           ) AS ENVELOPPE_AUTRE,
           SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE*(case SENS WHEN 'D' THEN -1 ELSE 1 END)) AS MNT_TOTAL
          INTO
           #RELEVE_OPERATION_PREVISIONNEL
          FROM
           NR140
           INNER JOIN ETABLISSEMENT
            ON NR140.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT
           LEFT JOIN GROUPE
            ON ETABLISSEMENT.ID_GROUPE = GROUPE.ID_GROUPE
           INNER JOIN MVT_BUDGETAIRE
            ON ETABLISSEMENT.ID_ETABLISSEMENT = MVT_BUDGETAIRE.ID_ETABLISSEMENT
           INNER JOIN TYPE_MOUVEMENT
            ON MVT_BUDGETAIRE.ID_TYPE_MOUVEMENT = TYPE_MOUVEMENT.ID_TYPE_MOUVEMENT
           INNER JOIN EVENEMENT
            ON EVENEMENT.ID_EVENEMENT = MVT_BUDGETAIRE.ID_EVENEMENT
           INNER JOIN POSTE_COUT_ENGAGE
            ON EVENEMENT.ID_POSTE_COUT_ENGAGE = POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE
           LEFT JOIN ENVELOPPE 
            ON MVT_BUDGETAIRE.ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE
           LEFT JOIN TYPE_ENVELOPPE 
            ON ENVELOPPE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE
           LEFT JOIN COMPTE 
            ON MVT_BUDGETAIRE.ID_COMPTE = COMPTE.ID_COMPTE AND COMPTE.BLN_ACTIF = 1
           INNER JOIN SOUS_TYPE_COUT 
            ON POSTE_COUT_ENGAGE.ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT
           INNER JOIN TYPE_COUT 
            ON SOUS_TYPE_COUT.ID_TYPE_COUT = TYPE_COUT.ID_TYPE_COUT
           INNER JOIN MODULE_PEC 
            ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_ENGAGE.ID_MODULE_PEC
            AND MODULE_PEC.ID_ACTION_PEC = NR140.ID_ACTION_PEC
           LEFT JOIN ETABLISSEMENT_OF 
            ON MODULE_PEC.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF 
           LEFT JOIN ORGANISME_FORMATION 
            ON ETABLISSEMENT_OF.ID_OF = ORGANISME_FORMATION.ID_OF
           INNER JOIN PARAMETRAGE_BUDGETAIRE 
            ON TYPE_MOUVEMENT.ID_TYPE_MOUVEMENT = PARAMETRAGE_BUDGETAIRE.ID_TYPE_MOUVEMENT 
          WHERE
           P_E_R = 'P'
           AND
           (

            (
             MVT_BUDGETAIRE.id_enveloppe IS NOT NULL
             AND PARAMETRAGE_BUDGETAIRE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE
            )
            OR

            (
             MVT_BUDGETAIRE.id_compte IS NOT NULL
             AND PARAMETRAGE_BUDGETAIRE.ID_TYPE_COMPTE = COMPTE.ID_TYPE_COMPTE
            )
           )
           AND MVT_BUDGETAIRE.ID_ETABLISSEMENT in (select id_etablissement from #ListAdherent)
           AND
           (
            (
             @ID_TYPE_RELEVE <> 3 
             AND ((@DAT_DEBUT IS NULL OR DATEDIFF(DAY,MVT_BUDGETAIRE.DAT_MVT_BUDGETAIRE,@DAT_DEBUT) <= 0)) 
             AND ((@DAT_FIN  IS NULL OR DATEDIFF(DAY,MVT_BUDGETAIRE.DAT_MVT_BUDGETAIRE,@DAT_FIN ) >= 0)) 
            )
            OR @ID_TYPE_RELEVE = 3 
           )
          GROUP BY
           MVT_BUDGETAIRE.ID_ADHERENT,
           MVT_BUDGETAIRE.ID_ETABLISSEMENT,
           MODULE_PEC.ID_MODULE_PEC,
           SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT,
           MVT_BUDGETAIRE.ID_TYPE_MOUVEMENT

          UNION ALL

          SELECT
           NULL AS ID_MODULE_PEC,
           NULL AS ID_SOUS_TYPE_COUT,
           MIN(MVT_BUDGETAIRE.ID_TYPE_MOUVEMENT) as ID_TYPE_MOUVEMENT,
           NULL AS NUM_INTERNE,
           MIN(ETABLISSEMENT.ID_ADHERENT) AS ID_ADHERENT,
           MIN(ETABLISSEMENT.ID_ETABLISSEMENT) AS ID_ETABLISSEMENT,
           MIN(MVT_BUDGETAIRE.P_E_R) AS P_E_R,
           MIN(MVT_BUDGETAIRE.ID_MVT_BUDGETAIRE) AS ID_MVT_BUDGETAIRE,
           MIN(MVT_BUDGETAIRE.DAT_MVT_BUDGETAIRE) AS DAT_MVT_BUDGETAIRE,
           MIN(MVT_BUDGETAIRE.LIBL_MVT_BUDGETAIRE) AS LIBL_MVT_BUDGETAIRE,
           NULL AS LIB_SIGLE_OF,
           NULL AS DAT_DEBUT,
           NULL AS DAT_FIN,
           ' ' AS COD_MODULE_PEC,
           SUM(CASE WHEN MVT_BUDGETAIRE.ID_TYPE_FINANCEMENT = 1  THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE*(case SENS WHEN 'D' THEN -1 ELSE 1 END) ELSE 0 END) AS MNT_MVT_COMPTE_COURANT,
           SUM(CASE WHEN MVT_BUDGETAIRE.ID_TYPE_FINANCEMENT = 2  THEN MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE*(case SENS WHEN 'D' THEN -1 ELSE 1 END) ELSE 0 END) AS MNT_MVT_FONDS_MUT,
           NULL AS ENVELOPPE_PP,
           NULL AS ENVELOPPE_DIF,
           NULL AS ENVELOPPE_FIN_PUB,
           NULL AS ENVELOPPE_AUTRE,
           SUM(MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE*(case SENS WHEN 'D' THEN -1 ELSE 1 END)) AS MNT_TOTAL

          FROM
           ETABLISSEMENT
           INNER JOIN GROUPE ON GROUPE.ID_GROUPE = ETABLISSEMENT.ID_GROUPE
           INNER JOIN MVT_BUDGETAIRE ON ETABLISSEMENT.ID_ETABLISSEMENT = MVT_BUDGETAIRE.ID_ETABLISSEMENT 
           INNER JOIN TYPE_MOUVEMENT ON MVT_BUDGETAIRE.ID_TYPE_MOUVEMENT = TYPE_MOUVEMENT.ID_TYPE_MOUVEMENT 
           INNER JOIN EVENEMENT ON EVENEMENT.ID_EVENEMENT = MVT_BUDGETAIRE.ID_EVENEMENT
           LEFT JOIN ENVELOPPE ON MVT_BUDGETAIRE.ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE
           LEFT JOIN TYPE_ENVELOPPE ON ENVELOPPE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE
           LEFT JOIN COMPTE ON MVT_BUDGETAIRE.ID_COMPTE = COMPTE.ID_COMPTE AND COMPTE.BLN_ACTIF = 1
           INNER JOIN VERSEMENT ON EVENEMENT.ID_VERSEMENT = VERSEMENT.ID_VERSEMENT
           INNER JOIN PARAMETRAGE_BUDGETAIRE ON TYPE_MOUVEMENT.ID_TYPE_MOUVEMENT = PARAMETRAGE_BUDGETAIRE.ID_TYPE_MOUVEMENT 
           INNER JOIN TYPE_COMPTE ON PARAMETRAGE_BUDGETAIRE.ID_TYPE_COMPTE = TYPE_COMPTE.ID_TYPE_COMPTE
          WHERE
           P_E_R = 'P'
           AND   (MVT_BUDGETAIRE.ID_COMPTE IS NOT NULL 
              OR  MVT_BUDGETAIRE.ID_ACTIVITE = 2 
              )
           AND  MVT_BUDGETAIRE.ID_ETABLISSEMENT in (select id_etablissement from #ListAdherent)
           AND  (
             ( @ID_TYPE_RELEVE <> 3 
             AND ((@DAT_DEBUT IS NULL OR DATEDIFF(DAY,MVT_BUDGETAIRE.DAT_MVT_BUDGETAIRE,@DAT_DEBUT) <= 0)) 
             AND ((@DAT_FIN  IS NULL OR DATEDIFF(DAY,MVT_BUDGETAIRE.DAT_MVT_BUDGETAIRE,@DAT_FIN ) >= 0)) 
             )
             OR (@ID_TYPE_RELEVE = 3) 
             )

          GROUP BY
           EVENEMENT.ID_VERSEMENT,
           MVT_BUDGETAIRE.ID_ADHERENT

          SELECT
           MIN(ID_ADHERENT) AS ID_ADHERENT,
           MIN(ID_ETABLISSEMENT) AS ID_ETABLISSEMENT,
           MIN(NUM_INTERNE) AS NUM_INTERNE,
           MIN(DAT_MVT_BUDGETAIRE) AS DAT_MVT_BUDGETAIRE,
           MIN(LIBL_MVT_BUDGETAIRE) AS LIBL_MVT_BUDGETAIRE,
           MIN(LIB_SIGLE_OF) AS LIB_SIGLE_OF,
           MIN(DAT_DEBUT) AS DAT_DEBUT,
           MIN(DAT_FIN) AS DAT_FIN,
           MIN(COD_MODULE_PEC) AS COD_MODULE_PEC,
           coalesce(SUM(MNT_TOTAL), 0) as MNT_TOTAL,
           coalesce(SUM(MNT_MVT_COMPTE_COURANT), 0) as MNT_MVT_COMPTE_COURANT,
           coalesce(SUM(MNT_MVT_FONDS_MUT), 0) as MNT_MVT_FONDS_MUT,
           coalesce(SUM(ENVELOPPE_PP), 0) as ENVELOPPE_PP,
           coalesce(SUM(ENVELOPPE_DIF), 0) as ENVELOPPE_DIF,
           coalesce(SUM(ENVELOPPE_FIN_PUB), 0) as ENVELOPPE_FIN_PUB,
           coalesce(SUM(ENVELOPPE_AUTRE), 0) as ENVELOPPE_AUTRE
          INTO
           #MVT_RESIDUEL_ENGAGE
          FROM
           #RELEVE_OPERATION_ENGAGE
          WHERE
           ((@DAT_DEBUT IS NULL OR DATEDIFF(DAY,DAT_MVT_BUDGETAIRE,@DAT_DEBUT) <= 0)) 
           AND ((@DAT_FIN  IS NULL OR DATEDIFF(DAY,DAT_MVT_BUDGETAIRE,@DAT_FIN ) >= 0))  
          GROUP BY
           ID_MODULE_PEC, ID_SOUS_TYPE_COUT
          HAVING
           (SUM(MNT_TOTAL) != 0)

          SELECT
           MIN(ID_ADHERENT) AS ID_ADHERENT,
           MIN(ID_ETABLISSEMENT) AS ID_ETABLISSEMENT,
           MIN(NUM_INTERNE) AS NUM_INTERNE,
           MIN(DAT_MVT_BUDGETAIRE) AS DAT_MVT_BUDGETAIRE,
           MIN(LIBL_MVT_BUDGETAIRE) AS LIBL_MVT_BUDGETAIRE,
           MIN(LIB_SIGLE_OF) AS LIB_SIGLE_OF,
           MIN(DAT_DEBUT) AS DAT_DEBUT,
           MIN(DAT_FIN) AS DAT_FIN,
           MIN(COD_MODULE_PEC) AS COD_MODULE_PEC,
           SUM(MNT_TOTAL) as MNT_TOTAL,
           SUM(MNT_MVT_COMPTE_COURANT) as MNT_MVT_COMPTE_COURANT,
           SUM(MNT_MVT_FONDS_MUT) as MNT_MVT_FONDS_MUT,
           SUM(ENVELOPPE_PP) as ENVELOPPE_PP,
           SUM(ENVELOPPE_DIF) as ENVELOPPE_DIF,
           SUM(ENVELOPPE_FIN_PUB) as ENVELOPPE_FIN_PUB,
           SUM(ENVELOPPE_AUTRE) as ENVELOPPE_AUTRE
          INTO
           #MVT_RESIDUEL_PREVISIONNEL
          FROM
           #RELEVE_OPERATION_PREVISIONNEL
          WHERE
           ((@DAT_DEBUT IS NULL OR DATEDIFF(DAY,DAT_MVT_BUDGETAIRE,@DAT_DEBUT) <= 0)) 
           AND   ((@DAT_FIN  IS NULL OR DATEDIFF(DAY,DAT_MVT_BUDGETAIRE,@DAT_FIN ) >= 0))  
          GROUP BY
           ID_MODULE_PEC,
           ID_SOUS_TYPE_COUT
          HAVING
           (SUM(MNT_TOTAL) != 0)

          SELECT
           SUM(MNT_TOTAL)    as MNT_TOTAL_REGLE,
           SUM(MNT_MVT_COMPTE_COURANT) as MNT_MVT_BUDGETAIRE_REGLE,
           SUM(MNT_MVT_FONDS_MUT)  as MNT_PLAN_FINANCEMENT_US_REGLE,
           SUM(ENVELOPPE_PP)   as ENVELOPPE_PP_REGLE,
           SUM(ENVELOPPE_DIF)   as ENVELOPPE_DIF_REGLE,
           SUM(ENVELOPPE_FIN_PUB)  as ENVELOPPE_FIN_PUB_REGLE,
           SUM(ENVELOPPE_AUTRE)  as ENVELOPPE_AUTRE_REGLE
          INTO
           #SOMME_REGLE
          FROM
           #RELEVE_OPERATION_REGLE
          WHERE
           ((@DAT_DEBUT IS NULL OR DATEDIFF(DAY,DAT_MVT_BUDGETAIRE,@DAT_DEBUT) <= 0)) 
           AND  ((@DAT_FIN  IS NULL OR DATEDIFF(DAY,DAT_MVT_BUDGETAIRE,@DAT_FIN ) >= 0)) 

          SELECT
           SUM(MNT_TOTAL)    as MNT_TOTAL_ENGAGE,
           SUM(MNT_MVT_COMPTE_COURANT) as MNT_MVT_BUDGETAIRE_ENGAGE,
           SUM(MNT_MVT_FONDS_MUT)  as MNT_PLAN_FINANCEMENT_US_ENGAGE,
           SUM(ENVELOPPE_PP)   as ENVELOPPE_PP_ENGAGE,
           SUM(ENVELOPPE_DIF)   as ENVELOPPE_DIF_ENGAGE,
           SUM(ENVELOPPE_FIN_PUB)  as ENVELOPPE_FIN_PUB_ENGAGE,
           SUM(ENVELOPPE_AUTRE)  as ENVELOPPE_AUTRE_ENGAGE
          INTO
           #SOMME_ENGAGE
          FROM
           #MVT_RESIDUEL_ENGAGE
          WHERE
           ((@DAT_DEBUT IS NULL OR DATEDIFF(DAY,DAT_MVT_BUDGETAIRE,@DAT_DEBUT) <= 0)) 
           AND ((@DAT_FIN  IS NULL OR DATEDIFF(DAY,DAT_MVT_BUDGETAIRE,@DAT_FIN ) >= 0))

          SELECT
           SUM(MNT_TOTAL)    as MNT_TOTAL_PREVISIONNEL,
           SUM(MNT_MVT_COMPTE_COURANT) as MNT_MVT_BUDGETAIRE_PREVISIONNEL,
           SUM(MNT_MVT_FONDS_MUT)  as MNT_PLAN_FINANCEMENT_US_PREVISIONNEL,
           SUM(ENVELOPPE_PP)   as ENVELOPPE_PP_PREVISIONNEL,
           SUM(ENVELOPPE_DIF)   as ENVELOPPE_DIF_PREVISIONNEL,
           SUM(ENVELOPPE_FIN_PUB)  as ENVELOPPE_FIN_PUB_PREVISIONNEL,
           SUM(ENVELOPPE_AUTRE)  as ENVELOPPE_AUTRE_PREVISIONNEL
          INTO
           #SOMME_PREVISIONNEL
          FROM
           #MVT_RESIDUEL_PREVISIONNEL
          WHERE
           ((@DAT_DEBUT IS NULL OR DATEDIFF(DAY,DAT_MVT_BUDGETAIRE,@DAT_DEBUT) <= 0)) 
           AND ((@DAT_FIN  IS NULL OR DATEDIFF(DAY,DAT_MVT_BUDGETAIRE,@DAT_FIN ) >= 0))

          SELECT distinct
           @DAT_FIN as DAT_FIN,
           SUM(MNT_MVT_COMPTE_COURANT) as MNT_COMPTE_TOTAL,
           SUM(MNT_MVT_FONDS_MUT) as MNT_FONDS_MUT_TOTAL   
          INTO
           #SOLDES_FINAUX_REGLE
          FROM
           #RELEVE_OPERATION_REGLE
          WHERE
           ((@DAT_FIN IS NULL OR DATEDIFF(DAY,DAT_MVT_BUDGETAIRE,@DAT_FIN) >= 0))

          SELECT distinct
           getDate() as DAT_EDITION,
           SUM(MNT_MVT_COMPTE_COURANT) as MNT_COMPTE_TOTAL,
           SUM(MNT_MVT_FONDS_MUT) as MNT_FONDS_MUT_TOTAL   
          INTO
           #SOLDES_FINAUX_REGLE_DATE_EDITION
          FROM
           #RELEVE_OPERATION_REGLE
          WHERE
           (DATEDIFF(DAY,DAT_MVT_BUDGETAIRE,GETDATE()) >= 0)

          SELECT distinct
           getDate() as DAT_EDITION,
           SUM(MNT_MVT_COMPTE_COURANT) as MNT_COMPTE_TOTAL,
           SUM(MNT_MVT_FONDS_MUT) as MNT_FONDS_MUT_TOTAL 
          INTO
           #SOLDES_FINAUX_ENGAGE_DATE_EDITION
          FROM
           #RELEVE_OPERATION_ENGAGE
          WHERE
           (DATEDIFF(DAY,DAT_MVT_BUDGETAIRE,getDate()) >= 0) 

          HAVING
           (SUM(MNT_TOTAL) != 0)

          SELECT distinct
           getDate() as DAT_EDITION,
           SUM(MNT_MVT_COMPTE_COURANT) as MNT_COMPTE_TOTAL,
           SUM(MNT_MVT_FONDS_MUT) as MNT_FONDS_MUT_TOTAL
          INTO
           #SOLDES_FINAUX_PREVISIONNEL_DATE_EDITION
          FROM
           #RELEVE_OPERATION_PREVISIONNEL       
          WHERE
           (DATEDIFF(DAY,DAT_MVT_BUDGETAIRE,getDate()) >= 0)

          HAVING
           (SUM(MNT_TOTAL) != 0);

          WITH XMLNAMESPACES (
           DEFAULT 'EDT_LETTRE_RELEVE_OPERATION'
          )

          SELECT
           dbo.GetXmlBenefiaireContact(@ID_BENEFICIAIRE, @TYPE_BENEFICIAIRE, @ID_ADRESSE, @ID_CONTACT) AS BENEFICIAIRE,
           (
            SELECT 

             UPPER(@TYP_CODE)     as TYP_CODE,
             @CODE        as COD_ADHERENT,
             CR.LIB_PNM       as LIB_PRENOM_CHARGE_RELATION,
             CR.LIB_NOM       as LIB_NOM_CHARGE_RELATION,
             CR.EMAIL,
             dbo.GetXmlAdrChargeRelation(@ID_ETABLISSEMENT) AS EMETTEUR,

             (
              SELECT CODE_SIRET,

                rtrim(case when patindex('%CEDEX%', VILLE) <> 0 then left(VILLE, patindex('%CEDEX%', VILLE)-1) else VILLE end) as VILLE
              FROM #ListSIRET
              FOR XML PATH('SIRET_ATTACHES'), TYPE
             ),

             rtrim(case when patindex('%CEDEX%', CR.LIB_VILLE) <> 0 then left(CR.LIB_VILLE, patindex('%CEDEX%', CR.LIB_VILLE)-1) else CR.LIB_VILLE end) as LIB_VILLE,
             dbo.GetFullDate(getdate())   as DATE,

             (
              SELECT top 1 dbo.GetContactSalutation(@ID_CONTACT, 1)
              FROM CIVILITE
              FOR XML PATH('POLITESSE_HAUT'), TYPE
             )

            FOR XML RAW('ENTETE'), ELEMENTS, TYPE
           ),
           (
            SELECT
             dbo.GetFullDate(@DAT_DEBUT)   as DAT_DEBUT,
             dbo.GetFullDate(@DAT_FIN)   as DAT_FIN,
             (
              SELECT top 1 dbo.GetContactSalutation(@ID_CONTACT, 1)
              FROM CIVILITE
              FOR XML PATH('POLITESSE_BAS'), TYPE
             )
            FOR XML RAW('CORPS'), ELEMENTS, TYPE
           ),
           (
            SELECT
             CM.LIB_PNM       as LIB_PNM_CONSEILLER,
             CM.LIB_NOM       as LIB_NOM_CONSEILLER
            FOR XML RAW('SIGNATURE'), ELEMENTS, TYPE
           ),
           (

            SELECT
             (

              SELECT
               (
                SELECT
                 [dbo].[GetShortDate](getdate()) AS DAT_EDITION,
                 [dbo].[GetShortDate](@DAT_DEBUT) AS DAT_DEBUT,
                 [dbo].[GetShortDate](@DAT_FIN) AS DAT_FIN,
                 @TYP_CODE AS TYP_CODE,
                 @LIB_RAISON_SOCIALE AS CODE
                FOR XML RAW('ENTETE_TABLEAU_REGLE'), ELEMENTS, TYPE

               ),
               (

                SELECT DISTINCT dbo.GetFrenchCurrencyFormat(CAST(COALESCE(MNT_MVT_COMPTE_COURANT,0.00) as money)) as MNT_COMPTE_TOTAL,
                  [dbo].[GetShortDate](@DAT_DEBUT) AS DAT_DEBUT
                FROM (select sum(COALESCE(MNT_MVT_COMPTE_COURANT,0.00))as MNT_MVT_COMPTE_COURANT from #RELEVE_OPERATION_REGLE where ((@DAT_DEBUT IS NULL) OR (DATEDIFF(DAY,DAT_MVT_BUDGETAIRE,@DAT_DEBUT) > 0))) t
                WHERE @ID_TYPE_RELEVE = 3 

                FOR XML RAW('SOLDES_INITIAUX_REGLE'), ELEMENTS, TYPE
               ),

               (
                select(
                  case when
                  (
                   select count(*)
                   FROM #RELEVE_OPERATION_REGLE
                   WHERE ((@DAT_DEBUT IS NULL OR DATEDIFF(DAY,DAT_MVT_BUDGETAIRE,@DAT_DEBUT) <= 0)) 
                   AND  ((@DAT_FIN  IS NULL OR DATEDIFF(DAY,DAT_MVT_BUDGETAIRE,@DAT_FIN ) >= 0))  
                  ) > 0
                   then
                   (
                    SELECT
                     CONVERT(VARCHAR,COD_ADHERENT) + ' ' + LIB_RAISON_SOCIALE AS COD_ADHERENT,
                     (
                      SELECT COALESCE(NUM_INTERNE, ' ') as NUM_INTERNE,
                        [dbo].[GetShorterDate](DAT_MVT_BUDGETAIRE) as DAT_MVT_BUDGETAIRE,
                        LIBL_MVT_BUDGETAIRE,
                        COALESCE(LIB_SIGLE_OF,' ') as SIGLE_OF,

                        'Du '+[dbo].[GetShorterDate](DAT_DEBUT) as DAT_DEBUT,
                        'au '+[dbo].[GetShorterDate](DAT_FIN) as DAT_FIN,

                        dbo.GetFrenchCurrencyFormat(CAST(COALESCE(MNT_TOTAL,0.00) AS MONEY)) as MNT_TOTAL,
                        dbo.GetFrenchCurrencyFormat(CAST(COALESCE(MNT_MVT_COMPTE_COURANT,0.00) as MONEY)) as MNT_MVT_BUDGETAIRE,               
                        dbo.GetFrenchCurrencyFormat(CAST(COALESCE(ENVELOPPE_PP,0.00)AS MONEY)) as ENVELOPPE_PP,
                        dbo.GetFrenchCurrencyFormat(CAST(COALESCE(ENVELOPPE_DIF,0.00)AS MONEY)) as ENVELOPPE_DIF,
                        dbo.GetFrenchCurrencyFormat(CAST(COALESCE(MNT_MVT_FONDS_MUT, 0.00) AS MONEY)) as MNT_PLAN_FINANCEMENT_US,
                        dbo.GetFrenchCurrencyFormat(CAST(COALESCE(ENVELOPPE_FIN_PUB,0.00) AS MONEY)) as ENVELOPPE_FIN_PUB,
                        dbo.GetFrenchCurrencyFormat(CAST(COALESCE(ENVELOPPE_AUTRE,0.00) AS MONEY)) as ENVELOPPE_AUTRE

                      FROM #RELEVE_OPERATION_REGLE
                      WHERE ((@DAT_DEBUT IS NULL OR DATEDIFF(DAY,DAT_MVT_BUDGETAIRE,@DAT_DEBUT) <= 0)) 
                      AND  ((@DAT_FIN  IS NULL OR DATEDIFF(DAY,DAT_MVT_BUDGETAIRE,@DAT_FIN ) >= 0))  
                      ORDER BY #RELEVE_OPERATION_REGLE.DAT_MVT_BUDGETAIRE ASC, #RELEVE_OPERATION_REGLE.COD_MODULE_PEC
                      FOR XML RAW('DETAIL_MOUVEMENT'), ELEMENTS, TYPE 
                     )
                    FOR XML RAW(''), ELEMENTS, TYPE,ROOT('MOUVEMENT_ADHERENT')       

                   )end
                  )
                FROM #ListAdherent as TEMP_ADHERENT
                INNER JOIN 
                  ADHERENT
                ON  ADHERENT.ID_ADHERENT = TEMP_ADHERENT.ID_ADHERENT
                WHERE TEMP_ADHERENT.ID_ETABLISSEMENT = @ID_ETAB
                FOR XML RAW(''), ELEMENTS, TYPE,ROOT('TABLEAU_REGLE')
               ),
               (
                SELECT dbo.GetFrenchCurrencyFormat(CAST(COALESCE(#SOMME_REGLE.MNT_TOTAL_REGLE,0.00) AS MONEY)) AS MNT_TOTAL_REGLE,
                  dbo.GetFrenchCurrencyFormat(CAST(COALESCE(#SOMME_REGLE.MNT_MVT_BUDGETAIRE_REGLE,0.00) AS MONEY)) AS MNT_MVT_BUDGETAIRE_REGLE,         
                  dbo.GetFrenchCurrencyFormat(CAST(COALESCE(#SOMME_REGLE.ENVELOPPE_PP_REGLE,0.00) AS MONEY)) AS ENVELOPPE_PP_REGLE,
                  dbo.GetFrenchCurrencyFormat(CAST(COALESCE(#SOMME_REGLE.ENVELOPPE_DIF_REGLE,0.00) AS MONEY)) AS ENVELOPPE_DIF_REGLE,
                  dbo.GetFrenchCurrencyFormat(CAST(COALESCE(#SOMME_REGLE.MNT_PLAN_FINANCEMENT_US_REGLE,0.00) AS MONEY)) AS MNT_PLAN_FINANCEMENT_US_REGLE,         
                  dbo.GetFrenchCurrencyFormat(CAST(COALESCE(#SOMME_REGLE.ENVELOPPE_FIN_PUB_REGLE,0.00) AS MONEY)) AS ENVELOPPE_FIN_PUB_REGLE,
                  dbo.GetFrenchCurrencyFormat(CAST(COALESCE(#SOMME_REGLE.ENVELOPPE_AUTRE_REGLE,0.00) AS MONEY)) AS ENVELOPPE_AUTRE_REGLE
                FROM #SOMME_REGLE
                FOR XML RAW('SOMME_REGLE'), ELEMENTS, TYPE
               ),
               ( 
                SELECT DISTINCT dbo.GetFrenchCurrencyFormat(CAST(COALESCE(MNT_COMPTE_TOTAL,0.00) as money)) as MNT_COMPTE_TOTAL
                FROM #SOLDES_FINAUX_REGLE
                WHERE @ID_TYPE_RELEVE = 3 
                FOR XML RAW('SOLDES_FINAUX_REGLE'), ELEMENTS, TYPE
               )
              FOR XML RAW('PARTIE_REGLE'), ELEMENTS, TYPE
             ),

             (

              SELECT
               (
                SELECT
                 [dbo].[GetShortDate](getdate()) AS DAT_EDITION,
                 [dbo].[GetShortDate](@DAT_DEBUT) AS DAT_DEBUT,
                 [dbo].[GetShortDate](@DAT_FIN) AS DAT_FIN,        
                 @TYP_CODE AS TYP_CODE,
                 @LIB_RAISON_SOCIALE AS CODE
                FOR XML RAW('ENTETE_TABLEAU_ENGAGE'), ELEMENTS, TYPE 

               ),

               (
                select(
                  case when
                  (
                   select count(*) 
                   FROM #MVT_RESIDUEL_ENGAGE
                   WHERE #MVT_RESIDUEL_ENGAGE.ID_ETABLISSEMENT in (select id_etablissement from #ListAdherent)
                  ) > 0
                   THEN
                    (
                     SELECT
                      CONVERT(VARCHAR,COD_ADHERENT) + ' ' + LIB_RAISON_SOCIALE AS COD_ADHERENT,
                      (
                       SELECT COALESCE(NUM_INTERNE, ' ') as NUM_INTERNE,
                         [dbo].[GetShorterDate](DAT_MVT_BUDGETAIRE) as DAT_MVT_BUDGETAIRE,      
                         LIBL_MVT_BUDGETAIRE,
                         COALESCE(LIB_SIGLE_OF,' ') as SIGLE_OF,

                         CASE WHEN DAT_DEBUT IS NULL
                           THEN NULL
                           ELSE 'Du '+[dbo].[GetShorterDate](DAT_DEBUT)
                          END
                          as DAT_DEBUT,

                         CASE WHEN DAT_FIN IS NULL
                           THEN NULL
                           ELSE 'au '+[dbo].[GetShorterDate](DAT_FIN)
                           END
                          as DAT_FIN,

                         dbo.GetFrenchCurrencyFormat(CAST(MNT_TOTAL as MONEY)) as MNT_TOTAL,
                         dbo.GetFrenchCurrencyFormat(CAST(MNT_MVT_COMPTE_COURANT as MONEY)) as MNT_MVT_BUDGETAIRE,                
                         COALESCE(dbo.GetFrenchCurrencyFormat(CAST(ENVELOPPE_PP as MONEY)),' ') as ENVELOPPE_PP,
                         COALESCE(dbo.GetFrenchCurrencyFormat(CAST(ENVELOPPE_DIF as MONEY)),' ') as ENVELOPPE_DIF,
                         COALESCE(dbo.GetFrenchCurrencyFormat(CAST(MNT_MVT_FONDS_MUT as MONEY)), ' ') as MNT_PLAN_FINANCEMENT_US,
                         COALESCE(dbo.GetFrenchCurrencyFormat(CAST(ENVELOPPE_FIN_PUB as MONEY)),' ') as ENVELOPPE_FIN_PUB,
                         COALESCE(dbo.GetFrenchCurrencyFormat(CAST(ENVELOPPE_AUTRE as MONEY)),' ') as ENVELOPPE_AUTRE
                       FROM #MVT_RESIDUEL_ENGAGE
                       ORDER BY #MVT_RESIDUEL_ENGAGE.DAT_MVT_BUDGETAIRE ASC, #MVT_RESIDUEL_ENGAGE.COD_MODULE_PEC
                       FOR XML RAW('DETAIL_MOUVEMENT'), ELEMENTS,TYPE
                      )
                    FOR XML RAW(''), ELEMENTS, TYPE,ROOT('MOUVEMENT_ADHERENT')       

                   )end
                  )
                FROM #ListAdherent
                INNER JOIN
                  ADHERENT 
                ON  ADHERENT.ID_ADHERENT = #ListAdherent.ID_ADHERENT
                WHERE #ListAdherent.ID_ETABLISSEMENT = @ID_ETAB
                FOR XML RAW(''), ELEMENTS, TYPE,ROOT('TABLEAU_ENGAGE')
               ),

              ( 
               SELECT dbo.GetFrenchCurrencyFormat(CAST(COALESCE(#SOMME_ENGAGE.MNT_TOTAL_ENGAGE,0.00) AS MONEY)) AS MNT_TOTAL_ENGAGE,
                 dbo.GetFrenchCurrencyFormat(CAST(COALESCE(#SOMME_ENGAGE.MNT_MVT_BUDGETAIRE_ENGAGE,0.00) AS MONEY)) AS MNT_MVT_BUDGETAIRE_ENGAGE,
                 dbo.GetFrenchCurrencyFormat(CAST(COALESCE(#SOMME_ENGAGE.ENVELOPPE_PP_ENGAGE,0.00) AS MONEY)) AS ENVELOPPE_PP_ENGAGE,        
                 dbo.GetFrenchCurrencyFormat(CAST(COALESCE(#SOMME_ENGAGE.ENVELOPPE_DIF_ENGAGE,0.00) AS MONEY)) AS ENVELOPPE_DIF_ENGAGE,
                 dbo.GetFrenchCurrencyFormat(CAST(COALESCE(#SOMME_ENGAGE.MNT_PLAN_FINANCEMENT_US_ENGAGE,0.00) AS MONEY)) AS MNT_PLAN_FINANCEMENT_US_ENGAGE,
                 dbo.GetFrenchCurrencyFormat(CAST(COALESCE(#SOMME_ENGAGE.ENVELOPPE_FIN_PUB_ENGAGE,0.00) AS MONEY)) AS ENVELOPPE_FIN_PUB_ENGAGE,
                 dbo.GetFrenchCurrencyFormat(CAST(COALESCE(#SOMME_ENGAGE.ENVELOPPE_AUTRE_ENGAGE,0.00) AS MONEY)) AS ENVELOPPE_AUTRE_ENGAGE
               FROM #SOMME_ENGAGE
               FOR XML RAW('SOMME_ENGAGE'), ELEMENTS, TYPE
              ), 

              (
               SELECT DISTINCT
                 dbo.GetFrenchCurrencyFormat(CAST(  COALESCE(( SELECT MNT_COMPTE_TOTAL FROM #SOLDES_FINAUX_REGLE_DATE_EDITION) ,0.00) +
                           COALESCE(( SELECT SUM(MNT_COMPTE_TOTAL) FROM #SOLDES_FINAUX_ENGAGE_DATE_EDITION) ,0.00) as MONEY)) AS MNT_COMPTE_TOTAL
               FROM #SOLDES_FINAUX_ENGAGE_DATE_EDITION
               WHERE @ID_TYPE_RELEVE = 3 
               FOR XML RAW('SOLDES_FINAUX_ENGAGE'), ELEMENTS, TYPE
              )
              FOR XML RAW('PARTIE_ENGAGE'), ELEMENTS, TYPE
             ),
             (

              SELECT
               (
                SELECT
                 [dbo].[GetShortDate](getdate()) AS DAT_EDITION,
                 [dbo].[GetShortDate](@DAT_DEBUT) AS DAT_DEBUT,
                 [dbo].[GetShortDate](@DAT_FIN) AS DAT_FIN,        
                 @TYP_CODE AS TYP_CODE,
                 @LIB_RAISON_SOCIALE AS CODE
                FOR XML RAW('ENTETE_TABLEAU_PREVISIONNEL'), ELEMENTS, TYPE 
               ),

               (
                select(
                  case when
                  (
                   select count(*) 
                   FROM #MVT_RESIDUEL_PREVISIONNEL
                   WHERE #MVT_RESIDUEL_PREVISIONNEL.ID_ETABLISSEMENT in (select id_etablissement from #ListAdherent)
                  ) > 0
                   THEN
                    (
                     SELECT
                      CONVERT(VARCHAR,COD_ADHERENT) + ' ' + LIB_RAISON_SOCIALE AS COD_ADHERENT,
                      (
                       SELECT COALESCE(NUM_INTERNE, ' ') as NUM_INTERNE,
                         [dbo].[GetShorterDate](DAT_MVT_BUDGETAIRE) as DAT_MVT_BUDGETAIRE,      
                         LIBL_MVT_BUDGETAIRE,
                         COALESCE(LIB_SIGLE_OF,' ') as SIGLE_OF,

                         CASE WHEN DAT_DEBUT IS NULL
                           THEN NULL
                           ELSE 'Du '+[dbo].[GetShorterDate](DAT_DEBUT)
                         END
                          as DAT_DEBUT,

                         CASE WHEN DAT_FIN IS NULL
                           THEN NULL
                           ELSE 'au '+[dbo].[GetShorterDate](DAT_FIN)
                         END
                          as DAT_FIN,

                         dbo.GetFrenchCurrencyFormat(CAST(MNT_TOTAL as MONEY)) as MNT_TOTAL,
                         dbo.GetFrenchCurrencyFormat(CAST(MNT_MVT_COMPTE_COURANT as MONEY)) as MNT_MVT_BUDGETAIRE,                
                         COALESCE(dbo.GetFrenchCurrencyFormat(CAST(ENVELOPPE_PP as MONEY)),' ') as ENVELOPPE_PP,
                         COALESCE(dbo.GetFrenchCurrencyFormat(CAST(ENVELOPPE_DIF as MONEY)),' ') as ENVELOPPE_DIF,
                         COALESCE(dbo.GetFrenchCurrencyFormat(CAST(MNT_MVT_FONDS_MUT as MONEY)), ' ') as MNT_PLAN_FINANCEMENT_US,
                         COALESCE(dbo.GetFrenchCurrencyFormat(CAST(ENVELOPPE_FIN_PUB as MONEY)),' ') as ENVELOPPE_FIN_PUB,
                         COALESCE(dbo.GetFrenchCurrencyFormat(CAST(ENVELOPPE_AUTRE as MONEY)),' ') as ENVELOPPE_AUTRE
                       FROM #MVT_RESIDUEL_PREVISIONNEL
                       ORDER BY #MVT_RESIDUEL_PREVISIONNEL.DAT_MVT_BUDGETAIRE,COD_MODULE_PEC 
                       FOR XML RAW('DETAIL_MOUVEMENT'), ELEMENTS,TYPE
                     )
                    FOR XML RAW(''), ELEMENTS, TYPE,ROOT('MOUVEMENT_ADHERENT')       

                   )end
                  )
                FROM #ListAdherent
                INNER JOIN 
                  ADHERENT 
                ON  ADHERENT.ID_ADHERENT = #ListAdherent.ID_ADHERENT
                WHERE #ListAdherent.ID_ETABLISSEMENT = @ID_ETAB
                FOR XML RAW(''), ELEMENTS, TYPE,ROOT('TABLEAU_PREVISIONNEL')
               ),

               (
                SELECT dbo.GetFrenchCurrencyFormat(CAST(COALESCE(#SOMME_PREVISIONNEL.MNT_TOTAL_PREVISIONNEL,0.00) AS MONEY)) AS MNT_TOTAL_PREVISIONNEL,
                  dbo.GetFrenchCurrencyFormat(CAST(COALESCE(#SOMME_PREVISIONNEL.MNT_MVT_BUDGETAIRE_PREVISIONNEL,0.00) AS MONEY)) AS MNT_MVT_BUDGETAIRE_PREVISIONNEL,      
                  dbo.GetFrenchCurrencyFormat(CAST(COALESCE(#SOMME_PREVISIONNEL.ENVELOPPE_PP_PREVISIONNEL,0.00) AS MONEY)) AS ENVELOPPE_PP_PREVISIONNEL,
                  dbo.GetFrenchCurrencyFormat(CAST(COALESCE(#SOMME_PREVISIONNEL.ENVELOPPE_DIF_PREVISIONNEL,0.00) AS MONEY)) AS ENVELOPPE_DIF_PREVISIONNEL,
                  dbo.GetFrenchCurrencyFormat(CAST(COALESCE(#SOMME_PREVISIONNEL.MNT_PLAN_FINANCEMENT_US_PREVISIONNEL,0.00) AS MONEY)) AS MNT_PLAN_FINANCEMENT_US_PREVISIONNEL,
                  dbo.GetFrenchCurrencyFormat(CAST(COALESCE(#SOMME_PREVISIONNEL.ENVELOPPE_FIN_PUB_PREVISIONNEL,0.00) AS MONEY)) AS ENVELOPPE_FIN_PUB_PREVISIONNEL,
                  dbo.GetFrenchCurrencyFormat(CAST(COALESCE(#SOMME_PREVISIONNEL.ENVELOPPE_AUTRE_PREVISIONNEL,0.00) AS MONEY)) AS ENVELOPPE_AUTRE_PREVISIONNEL

                FROM #SOMME_PREVISIONNEL
                FOR XML RAW('SOMME_PREVISIONNEL'), ELEMENTS, TYPE

               ),
               (
                SELECT DISTINCT
                  dbo.GetFrenchCurrencyFormat(CAST(COALESCE(( SELECT MNT_COMPTE_TOTAL FROM #SOLDES_FINAUX_REGLE_DATE_EDITION) ,0.00) +
                           COALESCE(( SELECT SUM(MNT_COMPTE_TOTAL) FROM #SOLDES_FINAUX_ENGAGE_DATE_EDITION) ,0.00) +
                              COALESCE(( SELECT SUM(MNT_COMPTE_TOTAL) FROM #SOLDES_FINAUX_PREVISIONNEL_DATE_EDITION) ,0.00) as MONEY)) AS MNT_COMPTE_TOTAL
                FROM #SOLDES_FINAUX_PREVISIONNEL_DATE_EDITION
                WHERE @ID_TYPE_RELEVE = 3
                FOR XML RAW('SOLDES_FINAUX_PREVISIONNEL'), ELEMENTS, TYPE
              )
              FOR XML RAW('PARTIE_PREVISIONNEL'), ELEMENTS, TYPE
             )
            FOR XML RAW('ANNEXE'), ELEMENTS, TYPE
           )
          FROM
           ADHERENT
           INNER JOIN ETABLISSEMENT
            ON ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
           INNER JOIN UTILISATEUR CR 
            ON ETABLISSEMENT.ID_CHARGEE_RELATION = CR.ID_UTILISATEUR
           INNER JOIN UTILISATEUR CM 
            ON ETABLISSEMENT.ID_CHARGEE_MISSION = CM.ID_UTILISATEUR
          WHERE
           ETABLISSEMENT.ID_ETABLISSEMENT = @ID_ETAB
          FOR XML RAW('LETTRE'), ELEMENTS
         END
GO

 CREATE PROCEDURE [dbo].[UPD_DISPOSITIF_STAGIAIRE]
          @ID_STAGIAIRE int,
          @ID_DISPOSITIF int,
          @NB_HEURES_PREVU decimal(18,2),
          @NB_HEURES_REALISEE decimal(18,2),
          @REFUS int,
          @ID_UNITE_STAGIAIRE int output,
          @ID_PUBLIC_PRIORITAIRE INT ,
          @ID_OBJET_FORMATION INT,
          @ID_ACTION_PRIORITAIRE INT ,
          @ID_CATEGORIE_ACTION INT, 
          @NB_HEURE_HTT decimal(18,2) ,
          @NB_HEURE_REM decimal(18,2)
         AS  

         BEGIN

          DECLARE 
           @ID_MODULE_PEC  INT,
           @ID_SESSION_PEC  INT

          IF @ID_STAGIAIRE = -1
          BEGIN
           SET @ID_UNITE_STAGIAIRE = 0
           RETURN
          END

          IF @ID_PUBLIC_PRIORITAIRE = -1
          BEGIN
           SET @ID_PUBLIC_PRIORITAIRE = NULL  
          END

          IF @ID_OBJET_FORMATION = -1
          BEGIN
           SET @ID_OBJET_FORMATION = NULL     
          END

          IF @ID_ACTION_PRIORITAIRE = -1
          BEGIN
           SET @ID_ACTION_PRIORITAIRE = NULL  
          END

          IF @ID_CATEGORIE_ACTION = -1
          BEGIN
           SET @ID_CATEGORIE_ACTION = NULL  
          END

          SELECT @ID_MODULE_PEC = ID_MODULE_PEC, 
            @ID_SESSION_PEC = ID_SESSION_PEC
          FROM STAGIAIRE_PEC
          WHERE ID_STAGIAIRE_PEC = @ID_STAGIAIRE

          IF (@REFUS IS NULL)
          BEGIN
           SET @REFUS = 0
          END

          IF isnull(@ID_UNITE_STAGIAIRE,0) = 0 
           or @ID_SESSION_PEC is not null 
          BEGIN
           SET @ID_UNITE_STAGIAIRE = null

           SELECT @ID_UNITE_STAGIAIRE = ID_UNITE_STAGIAIRE
           FROM UNITE_STAGIAIRE
           WHERE ID_STAGIAIRE_PEC = @ID_STAGIAIRE
            AND ID_DISPOSITIF = @ID_DISPOSITIF 

          END

          IF ISNULL(@ID_UNITE_STAGIAIRE,0) <> 0 
          BEGIN 

           DECLARE
            @BLN_REFUS_ORIGIN INT,
            @NB_HEURE_REGLE_ORIGIN DECIMAL(18,2)

           SELECT 
            @BLN_REFUS_ORIGIN = BLN_REFUS,
            @NB_HEURE_REGLE_ORIGIN = NB_HEURE_REGLE
           FROM
            UNITE_STAGIAIRE
           WHERE
            ID_UNITE_STAGIAIRE = @ID_UNITE_STAGIAIRE

           UPDATE
            UNITE_STAGIAIRE
           SET 
            NB_HEURE_ENGAGE   = @NB_HEURES_PREVU,
            NB_HEURE_REGLE   = @NB_HEURES_REALISEE,
            BLN_REFUS    = @REFUS,       
            ID_PUBLIC_PRIORITAIRE = @ID_PUBLIC_PRIORITAIRE,
            ID_OBJET_FORMATION  = @ID_OBJET_FORMATION,
            ID_ACTION_PRIORITAIRE = @ID_ACTION_PRIORITAIRE,
            ID_CATEGORIE_ACTION  = @ID_CATEGORIE_ACTION, 
            NB_HEURE_HTT   = @NB_HEURE_HTT,
            ID_DISPOSITIF   = @ID_DISPOSITIF,
            NB_HEURE_REM   = @NB_HEURE_REM
           WHERE
            ID_UNITE_STAGIAIRE = @ID_UNITE_STAGIAIRE

           IF ((@REFUS = 1) AND (ISNULL(@BLN_REFUS_ORIGIN,0) = 0))
            or
            @NB_HEURES_PREVU = 0 
           BEGIN

            UPDATE
             PLAN_FINANCEMENT_US
            SET
             MNT_PLAN_FINANCEMENT_US = 0, 
             MNT_PLAN_FINANCEMENT_US_THEORIQUE = 0
            FROM
             PLAN_FINANCEMENT_US PFUS
             INNER JOIN UNITE_STAGIAIRE US
              ON US.ID_UNITE_STAGIAIRE = PFUS.ID_UNITE_STAGIAIRE
             INNER JOIN  POSTE_COUT_ENGAGE PCE
              ON PFUS.ID_POSTE_COUT_ENGAGE  = PCE.ID_POSTE_COUT_ENGAGE
            WHERE
             PFUS.ID_UNITE_STAGIAIRE = @ID_UNITE_STAGIAIRE
             AND PCE.ID_MODULE_PEC = @ID_MODULE_PEC
             AND PCE.DAT_DESENGAGEMENT IS NULL 
             AND PCE.ID_ENGAGEMENT IS NULL
           END  

           IF ((@NB_HEURES_REALISEE <> @NB_HEURE_REGLE_ORIGIN)
            AND @ID_SESSION_PEC IS NOT NULL )
           BEGIN
            UPDATE
             POSTE_COUT_REGLE 
            SET 
             ID_ETAT_PEC = 14,
             BLN_OK_FINANCEMENT = 0
            WHERE 
             ID_SESSION_PEC = @ID_SESSION_PEC AND
                DAT_BAP IS NULL  
           END

           RETURN
          END
          ELSE 
          BEGIN
           INSERT INTO UNITE_STAGIAIRE
           (
            ID_STAGIAIRE_PEC,
            NB_HEURE_REM,
            COD_UNITE_STAGIAIRE,
            ID_DISPOSITIF,
            NB_HEURE_ENGAGE,
            NB_HEURE_REGLE,
            BLN_REFUS,
            ID_PUBLIC_PRIORITAIRE,
            ID_OBJET_FORMATION,
            ID_ACTION_PRIORITAIRE,
            ID_CATEGORIE_ACTION,
            NB_HEURE_HTT
           )
           VALUES
           (
            @ID_STAGIAIRE,
            @NB_HEURE_REM,
            0,
            @ID_DISPOSITIF,
            @NB_HEURES_PREVU,
            @NB_HEURES_REALISEE,
            @REFUS,
            @ID_PUBLIC_PRIORITAIRE,
            @ID_OBJET_FORMATION,
            @ID_ACTION_PRIORITAIRE,
            @ID_CATEGORIE_ACTION,
            @NB_HEURE_HTT
           )

           UPDATE
            UNITE_STAGIAIRE
           SET
            COD_UNITE_STAGIAIRE = ID_UNITE_STAGIAIRE
           WHERE
            ID_UNITE_STAGIAIRE = @@IDENTITY

           SET @ID_UNITE_STAGIAIRE = @@IDENTITY
          END 
         END
GO

         CREATE PROCEDURE [dbo].[LEC_GRP_ETAB_OF_RELANCE_PIECE_REGL_OF]
         	@ID_USER	INT,
         	@NBR		INT = NULL OUTPUT
         AS

         BEGIN

         	CREATE TABLE #TEMP_DESTINATAIRES 
         					(
         					ID_MODULE_PEC INT,
         					ID_SESSION_PEC INT,
         					COD_SESSION_PEC VARCHAR(17),					
         					ID_ETABLISSEMENT_OF INT,
         					ID_OF INT,
         					BLN_ACTIF TINYINT,
         					ID_ARRIVEE_PIECE_PEC INT,
         					DAT_RELANCE_REGLE_1 DATETIME,
         					DAT_RELANCE_REGLE_2 DATETIME,
         					DAT_RELANCE_REGLE_3 DATETIME
         					);

         	SELECT  DISTINCT ACTION_PEC.ID_ACTION_PEC,
         					 MODULE_PEC.ID_MODULE_PEC,
         					 SESSION_PEC.ID_SESSION_PEC,
         					 SESSION_PEC.COD_SESSION_PEC,
         					 POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE,
         					 ISNULL (POSTE_COUT_REGLE.BLN_FACTURE_DIRECTE, 0) AS BLN_FACTURE_DIRECTE,
         					 MODULE_PEC.ID_ETABLISSEMENT_OF,
         					 ETABLISSEMENT_OF.ID_OF

         	INTO	#TEMP_SESSIONS

         	FROM	ACTION_PEC 
         	JOIN	MODULE_PEC 
         	ON		ACTION_PEC.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC
         	JOIN	SESSION_PEC 
         	ON		MODULE_PEC.ID_MODULE_PEC = SESSION_PEC.ID_MODULE_PEC
         	JOIN	STAGIAIRE_PEC 
         	ON		SESSION_PEC.ID_SESSION_PEC = STAGIAIRE_PEC.ID_SESSION_PEC
         	JOIN	POSTE_COUT_REGLE 
         	ON		MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC
         	JOIN	ETABLISSEMENT_OF 
         	ON		MODULE_PEC.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF 
         	JOIN	ORGANISME_FORMATION 
         	ON		ETABLISSEMENT_OF.ID_OF = ORGANISME_FORMATION.ID_OF

         	WHERE	ACTION_PEC.BLN_ACTIF = 1
         	AND		ACTION_PEC.DAT_CLOTURE IS NULL
         	AND		MODULE_PEC.BLN_ACTIF = 1
         	AND		SESSION_PEC.BLN_ACTIF = 1
         	AND		POSTE_COUT_REGLE.BLN_ACTIF = 1
         	AND		(MODULE_PEC.BLN_OK_PIECE = 0 OR POSTE_COUT_REGLE.BLN_OK_PIECE = 0)
         	AND		coalesce(ACTION_PEC.ID_UTILISATEUR_BAE, @ID_USER) = @ID_USER
         	ORDER BY ACTION_PEC.ID_ACTION_PEC, MODULE_PEC.ID_MODULE_PEC, POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE

         	INSERT INTO #TEMP_DESTINATAIRES
         	SELECT  DISTINCT #TEMP_SESSIONS.ID_MODULE_PEC,
         					 #TEMP_SESSIONS.ID_SESSION_PEC,
         					 #TEMP_SESSIONS.COD_SESSION_PEC,
         					 #TEMP_SESSIONS.ID_ETABLISSEMENT_OF,
         				     #TEMP_SESSIONS.ID_OF,
         					 ARRIVEE_PIECE_PEC.BLN_ACTIF,
         					 ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC,					 
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1,
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2,
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3

         	FROM    #TEMP_SESSIONS 
         			INNER JOIN ARRIVEE_PIECE_PEC ON #TEMP_SESSIONS.ID_POSTE_COUT_REGLE = ARRIVEE_PIECE_PEC.ID_POSTE_COUT_REGLE
         											AND (ARRIVEE_PIECE_PEC.ID_MODULE_PEC = #TEMP_SESSIONS.ID_MODULE_PEC)
         			INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         			INNER JOIN POSTE_COUT_REGLE ON POSTE_COUT_REGLE.ID_MODULE_PEC = #TEMP_SESSIONS.ID_MODULE_PEC										

         	WHERE		(PIECE_PEC.BLN_POSTE_COUT_REGLE = 1)
         			AND (#TEMP_SESSIONS.BLN_FACTURE_DIRECTE = 1)
         			AND (PIECE_PEC.BLN_ACTIF = 1)
         			AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         			AND	(
         				(ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) 
         				OR 
         				((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) 
         					AND ( EXISTS (select 1 from NR210 
         											inner join MOTIF_NON_CONFORM_PIECE 
         											on NR210.ID_MOTIF_NON_CONFORM_PIECE=MOTIF_NON_CONFORM_PIECE.ID_MOTIF_NON_CONFORM_PIECE and BLN_OF = 1 
         											WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))
         				)
         			)

         	INSERT INTO #TEMP_DESTINATAIRES
         	SELECT  DISTINCT #TEMP_SESSIONS.ID_MODULE_PEC,
         					 #TEMP_SESSIONS.ID_SESSION_PEC,
         					 #TEMP_SESSIONS.COD_SESSION_PEC,
         					 #TEMP_SESSIONS.ID_ETABLISSEMENT_OF,
         				     #TEMP_SESSIONS.ID_OF,
         					 ARRIVEE_PIECE_PEC.BLN_ACTIF,
         					 ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC,
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1,
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2,
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3

         	FROM    #TEMP_SESSIONS
         			INNER JOIN ARRIVEE_PIECE_PEC ON #TEMP_SESSIONS.ID_MODULE_PEC = ARRIVEE_PIECE_PEC.ID_MODULE_PEC 
         			INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC AND (PIECE_PEC.BLN_STAGIAIRE = 0)

         	WHERE		(PIECE_PEC.BLN_MODULE = 1)
         			AND (#TEMP_SESSIONS.BLN_FACTURE_DIRECTE = 1)
         			AND (PIECE_PEC.BLN_ACTIF = 1)
         			AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         			AND	(
         				(ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) 
         				OR 
         				((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) 
         					AND ( EXISTS (select 1 from NR210 
         											inner join MOTIF_NON_CONFORM_PIECE 
         											on NR210.ID_MOTIF_NON_CONFORM_PIECE=MOTIF_NON_CONFORM_PIECE.ID_MOTIF_NON_CONFORM_PIECE and BLN_OF = 1 
         											WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))
         				)
         			)

         	INSERT INTO #TEMP_DESTINATAIRES
         	SELECT  DISTINCT #TEMP_SESSIONS.ID_MODULE_PEC,
         					 #TEMP_SESSIONS.ID_SESSION_PEC,
         					 #TEMP_SESSIONS.COD_SESSION_PEC,
         					 #TEMP_SESSIONS.ID_ETABLISSEMENT_OF,
         				     #TEMP_SESSIONS.ID_OF,
         					 ARRIVEE_PIECE_PEC.BLN_ACTIF,
         					 ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC,
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1,
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2,
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3

         	FROM    #TEMP_SESSIONS
         			INNER JOIN ARRIVEE_PIECE_PEC ON #TEMP_SESSIONS.ID_SESSION_PEC = ARRIVEE_PIECE_PEC.ID_SESSION_PEC
         											AND (#TEMP_SESSIONS.ID_MODULE_PEC = ARRIVEE_PIECE_PEC.ID_MODULE_PEC) 
         			INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC 

         	WHERE		(PIECE_PEC.BLN_SESSION = 1)
         			AND (#TEMP_SESSIONS.BLN_FACTURE_DIRECTE = 1)
         			AND (PIECE_PEC.BLN_ACTIF = 1)
         			AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         			AND	(
         				(ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) 
         				OR 
         				((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) 
         					AND ( EXISTS (select 1 from NR210 
         											inner join MOTIF_NON_CONFORM_PIECE 
         											on NR210.ID_MOTIF_NON_CONFORM_PIECE=MOTIF_NON_CONFORM_PIECE.ID_MOTIF_NON_CONFORM_PIECE and BLN_OF = 1 
         											WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))
         				)
         			)

         	INSERT INTO #TEMP_DESTINATAIRES
         	SELECT  DISTINCT #TEMP_SESSIONS.ID_MODULE_PEC,
         					 #TEMP_SESSIONS.ID_SESSION_PEC,
         					 #TEMP_SESSIONS.COD_SESSION_PEC,
         					 #TEMP_SESSIONS.ID_ETABLISSEMENT_OF,
         				     #TEMP_SESSIONS.ID_OF,
                              ARRIVEE_PIECE_PEC.BLN_ACTIF,
         					 ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC,					 
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1,
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2,
         					 ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3

         	FROM	#TEMP_SESSIONS
         			INNER JOIN STAGIAIRE_PEC ON #TEMP_SESSIONS.ID_MODULE_PEC = STAGIAIRE_PEC.ID_MODULE_PEC 
         			INNER JOIN ETABLISSEMENT ON STAGIAIRE_PEC.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT 
         			INNER JOIN ADHERENT ON ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT  
         			INNER JOIN ARRIVEE_PIECE_PEC ON ADHERENT.ID_ADHERENT = ARRIVEE_PIECE_PEC.ID_ADHERENT
         											AND (ARRIVEE_PIECE_PEC.ID_MODULE_PEC = #TEMP_SESSIONS.ID_MODULE_PEC)
         			INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC

         	WHERE		(PIECE_PEC.BLN_ADHERENT = 1)
         			AND (PIECE_PEC.BLN_ACTIF = 1)
         			AND (#TEMP_SESSIONS.BLN_FACTURE_DIRECTE = 1)
         			AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         			AND	(
         				(ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) 
         				OR 
         				((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) 
         					AND ( EXISTS (select 1 from NR210 
         											inner join MOTIF_NON_CONFORM_PIECE 
         											on NR210.ID_MOTIF_NON_CONFORM_PIECE=MOTIF_NON_CONFORM_PIECE.ID_MOTIF_NON_CONFORM_PIECE and BLN_OF = 1 
         											WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))
         				)
         			)

         		SELECT DISTINCT #TEMP_DESTINATAIRES.ID_ETABLISSEMENT_OF, 
         				#TEMP_DESTINATAIRES.ID_OF,
         				#TEMP_DESTINATAIRES.COD_SESSION_PEC as _SESSION_PEC
         		INTO #TMP1
         		FROM	#TEMP_DESTINATAIRES
         				CROSS JOIN PARAMETRES

         		WHERE		 (((#TEMP_DESTINATAIRES.DAT_RELANCE_REGLE_1 IS NULL) 
         						AND (#TEMP_DESTINATAIRES.DAT_RELANCE_REGLE_2 IS NULL) 
         						AND (#TEMP_DESTINATAIRES.DAT_RELANCE_REGLE_3 IS NULL))

         					OR ((#TEMP_DESTINATAIRES.DAT_RELANCE_REGLE_1 IS NOT NULL)
         						AND (GETDATE()-#TEMP_DESTINATAIRES.DAT_RELANCE_REGLE_1 >= PARAMETRES.DELAI_RELANCE_PEC)
         						AND (#TEMP_DESTINATAIRES.DAT_RELANCE_REGLE_2 IS NULL) 
         						AND (#TEMP_DESTINATAIRES.DAT_RELANCE_REGLE_3 IS NULL))

         					OR ((#TEMP_DESTINATAIRES.DAT_RELANCE_REGLE_2 IS NOT NULL)
         						AND (GETDATE()-#TEMP_DESTINATAIRES.DAT_RELANCE_REGLE_2 >= PARAMETRES.DELAI_RELANCE_PEC)  
         						AND (#TEMP_DESTINATAIRES.DAT_RELANCE_REGLE_3 IS NULL)))
         		ORDER BY #TEMP_DESTINATAIRES.ID_ETABLISSEMENT_OF, #TEMP_DESTINATAIRES.COD_SESSION_PEC

         	IF @NBR IS NULL
         	BEGIN
         			SELECT	* 
         			FROM	#TMP1
         	END
         	ELSE
         	BEGIN
         		SELECT	@NBR = COUNT( *) 
         		FROM	#TMP1 
         	END

         END
GO
 CREATE PROCEDURE [dbo].[EDT_SYNTH_COMPTE_PLAN_FORMATION]
          @ID_GROUPE INT,
          @DAT_DEBUT VARCHAR(50),
          @DAT_FIN VARCHAR(50),
          @BLN_DEBUG TINYINT = 0
         AS

         BEGIN
          DECLARE
           @LIB_GROUPE VARCHAR(100),
           @NUM_ANNEE VARCHAR(4)

          SELECT
           @LIB_GROUPE = LIB_GROUPE + ' (' + COD_GROUPE + ')'
          FROM
           GROUPE
          WHERE
           ID_GROUPE = @ID_GROUPE  

          SET
           @NUM_ANNEE = YEAR([dbo].[GetShortDate](@DAT_DEBUT))  

          SELECT
           MVT.ID_MVT_BUDGETAIRE,
           MVT.ID_TYPE_MOUVEMENT,
           MVT.ID_PERIODE_FISC,
           TM.LIBC_TYPE_MOUVEMENT,
           MVT.DAT_MVT_BUDGETAIRE,
           MVT.LIBL_MVT_BUDGETAIRE,
           MVT.MNT_MVT_BUDGETAIRE,
           MVT.ID_EVENEMENT,
           MVT.ID_COMPTE,
           MVT.P_E_R,
           VERSEMENT.DAT_SAISIE AS DAT_SAISIE_VERSEMENT,
           VERSEMENT.ID_VERSEMENT,
           PERIODE.NUM_ANNEE AS ANNEE_IMPUT,
           PS.ID_TYPE_VERSEMENT,
           PS.ID_POSTE_VERSEMENT,
           TV.COD_TYPE_VERSEMENT,
           TE.ID_TYPE_EVENEMENT,
           TE.COD_TYPE_EVENEMENT,
           MVT.ID_ENVELOPPE,
           MVT.ID_MODULE_PEC,
           MVT.ID_CONTRAT_PRO,

           ID_SOUS_TYPE_COUT = ISNULL(PCR.ID_SOUS_TYPE_COUT, PCE.ID_SOUS_TYPE_COUT)
          INTO
           #TOUTE_MVT_BUDGETAIRE
          FROM
           MVT_BUDGETAIRE MVT
           INNER JOIN EVENEMENT
            ON MVT.ID_EVENEMENT  = EVENEMENT.ID_EVENEMENT
           INNER JOIN TYPE_EVENEMENT TE
            ON TE.ID_TYPE_EVENEMENT = EVENEMENT.ID_TYPE_EVENEMENT
           INNER JOIN TYPE_MOUVEMENT TM
            ON TM.ID_TYPE_MOUVEMENT = MVT.ID_TYPE_MOUVEMENT
           LEFT JOIN VERSEMENT
            ON VERSEMENT.ID_VERSEMENT = EVENEMENT.ID_VERSEMENT
           LEFT JOIN POSTE_VERSEMENT PS
            ON PS.ID_VERSEMENT   = VERSEMENT.ID_VERSEMENT
             AND MVT.ID_PERIODE_FISC=ps.ID_PERIODE
           LEFT JOIN PERIODE
            ON PERIODE.ID_PERIODE = PS.ID_PERIODE
           LEFT JOIN TYPE_VERSEMENT TV
            ON TV.ID_TYPE_VERSEMENT = PS.ID_TYPE_VERSEMENT
           LEFT JOIN ENVELOPPE
            ON MVT.ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE
           LEFT JOIN POSTE_COUT_ENGAGE PCE
            ON PCE.ID_POSTE_COUT_ENGAGE = EVENEMENT.ID_POSTE_COUT_ENGAGE

           LEFT JOIN POSTE_COUT_REGLE PCR
            ON PCR.ID_POSTE_COUT_REGLE = EVENEMENT.ID_POSTE_COUT_REGLE
          WHERE
           MVT.ID_GROUPE = @ID_GROUPE
           AND MVT.DAT_MVT_BUDGETAIRE >= [dbo].[GetShortDate](@DAT_DEBUT)
           AND MVT.DAT_MVT_BUDGETAIRE <= [dbo].[GetShortDate](@DAT_FIN)
           AND ABS(MVT.MNT_MVT_BUDGETAIRE ) > 0

          SELECT
           MVT.ID_MVT_BUDGETAIRE,
           MVT.ID_ADHERENT,
           MVT.ID_TYPE_MOUVEMENT,
           TYPE_MOUVEMENT.LIBC_TYPE_MOUVEMENT,
           MVT.ID_EVENEMENT,
           MVT.DAT_MVT_BUDGETAIRE,
           LIBL_TYPE_FINANCEMENT,
           PERIODE.NUM_ANNEE,
           TE.ID_TYPE_EVENEMENT,
           MNT_MVT_GROUPE = MNT_MVT_BUDGETAIRE * (CASE SENS WHEN 'C' THEN 1 ELSE -1 END),
           MNT_DEBIT = MNT_MVT_BUDGETAIRE * (CASE SENS WHEN 'D' THEN 1 ELSE 0 END),
           MNT_CREDIT = MNT_MVT_BUDGETAIRE * (CASE SENS WHEN 'D' THEN 0 ELSE 1 END),
           LIBL_MVT_BUDGETAIRE,
           LIBL_PERIODE = 'Ann‚e Rbt. P10+ ' + CAST(NUM_ANNEE AS VARCHAR),
           P_E_R,
           TAG = CAST(NULL AS VARCHAR(50))
          INTO
           #TMP_MVT_BUD_ENG_ET_REGLE
          FROM
           MVT_BUDGETAIRE MVT
           INNER JOIN EVENEMENT
            ON MVT.ID_EVENEMENT = EVENEMENT.ID_EVENEMENT
           INNER JOIN COMPTE
            ON MVT.ID_COMPTE = COMPTE.ID_COMPTE
           INNER JOIN TYPE_COMPTE
            ON COMPTE.ID_TYPE_COMPTE = TYPE_COMPTE.ID_TYPE_COMPTE
           INNER JOIN TYPE_MOUVEMENT
            ON MVT.ID_TYPE_MOUVEMENT = TYPE_MOUVEMENT.ID_TYPE_MOUVEMENT
           INNER JOIN PARAMETRAGE_BUDGETAIRE
            ON PARAMETRAGE_BUDGETAIRE.ID_TYPE_MOUVEMENT = TYPE_MOUVEMENT.ID_TYPE_MOUVEMENT
             AND PARAMETRAGE_BUDGETAIRE.ID_TYPE_COMPTE = TYPE_COMPTE.ID_TYPE_COMPTE
           INNER JOIN PERIODE
            ON COMPTE.ID_PERIODE = PERIODE.ID_PERIODE
           INNER JOIN TYPE_FINANCEMENT
            ON COMPTE.ID_TYPE_FINANCEMENT = TYPE_FINANCEMENT.ID_TYPE_FINANCEMENT
           INNER JOIN TYPE_EVENEMENT TE
            ON TE.ID_TYPE_EVENEMENT = EVENEMENT.ID_TYPE_EVENEMENT
          WHERE
           COMPTE.ID_GROUPE = @ID_GROUPE
           AND COMPTE.ID_TYPE_FINANCEMENT = 1   
           AND DAT_MVT_BUDGETAIRE >= @DAT_DEBUT
           AND DAT_MVT_BUDGETAIRE <= @DAT_FIN
           AND MVT.ID_COMPTE IS NOT NULL
           AND ABS(MVT.MNT_MVT_BUDGETAIRE ) > 0
          ORDER BY
           COMPTE.ID_TYPE_FINANCEMENT,
           NUM_ANNEE,
           DAT_MVT_BUDGETAIRE,
           P_E_R

          DECLARE
           @SOLDE_ENGAGEMENT_INITIAL  DECIMAL(18,2),
           @MNT_RELIQUAT_PREVISIONNEL_INITIAL DECIMAL(18,2),
           @MNT_I_P DECIMAL(18,2),
           @MNT_I_E DECIMAL(18,2),
           @MNT_I_R DECIMAL(18,2),
           @ID_CPT INT

          SELECT
           MNT_MVT_BUDGETAIRE_CALCULE = MVT.MNT_MVT_BUDGETAIRE * (CASE PB.SENS WHEN 'D' THEN -1 ELSE 1 END),
           MNT_DEBIT  = MVT.MNT_MVT_BUDGETAIRE * (CASE PB.SENS WHEN 'D' THEN 1 ELSE 0 END),
           MNT_CREDIT = MVT.MNT_MVT_BUDGETAIRE * (CASE PB.SENS WHEN 'D' THEN 0 ELSE 1 END),
           DAT_MVT_BUDGETAIRE = MVT.DAT_MVT_BUDGETAIRE,
           PER = MVT.P_E_R,
           COMPTE.ID_COMPTE
          INTO
           #TMP_MVT_INITIAL
          FROM
           COMPTE,
           MVT_BUDGETAIRE MVT,
           PARAMETRAGE_BUDGETAIRE PB,
           TYPE_COMPTE,
           PERIODE,
           TYPE_MOUVEMENT  
          WHERE
           @ID_GROUPE IS NOT NULL
           AND COMPTE.ID_GROUPE = @ID_GROUPE
           AND MVT.ID_COMPTE = COMPTE.ID_COMPTE
           AND COMPTE.ID_PERIODE = PERIODE.ID_PERIODE
           AND COMPTE.ID_TYPE_FINANCEMENT    = 1   
           AND MVT.DAT_MVT_BUDGETAIRE < @DAT_DEBUT
           AND TYPE_MOUVEMENT.ID_TYPE_MOUVEMENT = MVT.ID_TYPE_MOUVEMENT
           AND PB.ID_TYPE_MOUVEMENT  = MVT.ID_TYPE_MOUVEMENT
           AND COMPTE.ID_TYPE_COMPTE = TYPE_COMPTE.ID_TYPE_COMPTE
           AND PB.ID_TYPE_COMPTE = TYPE_COMPTE.ID_TYPE_COMPTE

          SELECT
           @MNT_I_P = ISNULL(SUM(MNT_MVT_BUDGETAIRE_CALCULE)  , 0)
          FROM
           #TMP_MVT_INITIAL
          WHERE
           DAT_MVT_BUDGETAIRE < @DAT_DEBUT AND PER = 'P'

          SET
           @MNT_RELIQUAT_PREVISIONNEL_INITIAL = @MNT_I_P

          SELECT
           @MNT_I_E = ISNULL(SUM(MNT_MVT_BUDGETAIRE_CALCULE) , 0)
          FROM
           #TMP_MVT_INITIAL
          WHERE
           DAT_MVT_BUDGETAIRE < @DAT_DEBUT AND PER = 'E'

          SELECT
           @MNT_I_R = ISNULL(SUM(MNT_MVT_BUDGETAIRE_CALCULE) , 0)
          FROM
           #TMP_MVT_INITIAL
          WHERE
           DAT_MVT_BUDGETAIRE < @DAT_DEBUT AND PER = 'R'

          SET
           @MNT_I_E = @MNT_I_E + @MNT_I_R

          SET
           @MNT_I_P = @MNT_I_P + @MNT_I_E

          SELECT
           @SOLDE_ENGAGEMENT_INITIAL = @MNT_I_E

          SELECT
           #TOUTE_MVT_BUDGETAIRE.ID_TYPE_MOUVEMENT,
           #TOUTE_MVT_BUDGETAIRE.LIBC_TYPE_MOUVEMENT,
           sum(#TOUTE_MVT_BUDGETAIRE.MNT_MVT_BUDGETAIRE) as MNT_MVT_BUDGETAIRE,

           #TOUTE_MVT_BUDGETAIRE.DAT_SAISIE_VERSEMENT,
           VERSEMENT.ID_VERSEMENT,
           #TOUTE_MVT_BUDGETAIRE.ANNEE_IMPUT,
           #TOUTE_MVT_BUDGETAIRE.ID_TYPE_VERSEMENT,
           #TOUTE_MVT_BUDGETAIRE .COD_TYPE_EVENEMENT,
           VERSEMENT.DAT_ENCAISSEMENT,
           #TOUTE_MVT_BUDGETAIRE.P_E_R,
           MODE_VERSEMENT.LIBL_MODE_VERSEMENT
          INTO
           #TMP_VERSEMENT1
          FROM
           #TOUTE_MVT_BUDGETAIRE
           INNER JOIN ENVELOPPE
            ON #TOUTE_MVT_BUDGETAIRE.ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE
           INNER JOIN TYPE_ENVELOPPE
            ON TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE = ENVELOPPE.ID_TYPE_ENVELOPPE
             AND TYPE_ENVELOPPE.ID_ACTIVITE NOT IN (select id_activite from GET_IDS_ACTIVITE_BY_COD_TYPE_ACTIVITE('PROF')) 
           INNER JOIN VERSEMENT
            ON #TOUTE_MVT_BUDGETAIRE.ID_VERSEMENT = VERSEMENT.ID_VERSEMENT
           INNER JOIN POSTE_VERSEMENT
            ON #TOUTE_MVT_BUDGETAIRE.ID_POSTE_VERSEMENT = POSTE_VERSEMENT .ID_POSTE_VERSEMENT
           INNER JOIN MODE_VERSEMENT
            ON VERSEMENT.ID_MODE_VERSEMENT = MODE_VERSEMENT.ID_MODE_VERSEMENT
          WHERE
           #TOUTE_MVT_BUDGETAIRE.COD_TYPE_VERSEMENT = 'VOLONT' 
           AND  #TOUTE_MVT_BUDGETAIRE.LIBL_MVT_BUDGETAIRE LIKE '%volontaire%'
           AND  #TOUTE_MVT_BUDGETAIRE.ID_PERIODE_FISC=POSTE_VERSEMENT.ID_PERIODE
           AND  TYPE_ENVELOPPE.BLN_COLLECTE = 1
           AND  VERSEMENT.BLN_ACTIF   = 1
          GROUP BY
           VERSEMENT.ID_VERSEMENT,
           POSTE_VERSEMENT.ID_PERIODE,
           #TOUTE_MVT_BUDGETAIRE.ID_TYPE_MOUVEMENT,
           #TOUTE_MVT_BUDGETAIRE.LIBC_TYPE_MOUVEMENT,
           #TOUTE_MVT_BUDGETAIRE.DAT_SAISIE_VERSEMENT,
           VERSEMENT.ID_VERSEMENT,
           #TOUTE_MVT_BUDGETAIRE.ANNEE_IMPUT,
           #TOUTE_MVT_BUDGETAIRE.ID_TYPE_VERSEMENT,
           #TOUTE_MVT_BUDGETAIRE .COD_TYPE_EVENEMENT,
           VERSEMENT.DAT_ENCAISSEMENT,
           #TOUTE_MVT_BUDGETAIRE.P_E_R,
           MODE_VERSEMENT.LIBL_MODE_VERSEMENT

          UPDATE
           #TMP_MVT_BUD_ENG_ET_REGLE
          SET
           TAG = '1 -VERSEMENT VOLONTAIRE'
          FROM
           #TMP_MVT_BUD_ENG_ET_REGLE
           INNER JOIN #TOUTE_MVT_BUDGETAIRE
            ON #TMP_MVT_BUD_ENG_ET_REGLE.ID_MVT_BUDGETAIRE = #TOUTE_MVT_BUDGETAIRE.ID_MVT_BUDGETAIRE
          WHERE
           COD_TYPE_VERSEMENT = 'VOLONT' 
           AND #TOUTE_MVT_BUDGETAIRE.LIBL_MVT_BUDGETAIRE LIKE '%volontaire%' 
           AND TAG IS NULL

          SELECT DISTINCT
           C.ID_TYPE_MOUVEMENT,
           C.LIBC_TYPE_MOUVEMENT,
           T.MNT_MVT_BUDGETAIRE,
           T.DAT_SAISIE_VERSEMENT,
           T.ID_VERSEMENT,
           T.ANNEE_IMPUT,
           T.ID_TYPE_VERSEMENT,
           T.P_E_R
          INTO
           #TMP_VERSEMENT2
          FROM
           #TMP_MVT_BUD_ENG_ET_REGLE C
           INNER JOIN #TOUTE_MVT_BUDGETAIRE T
            ON C.ID_MVT_BUDGETAIRE = T.ID_MVT_BUDGETAIRE
          WHERE
           TAG = '1 -VERSEMENT VOLONTAIRE'
           AND T.COD_TYPE_VERSEMENT = 'VOLONT' 
           AND T.ID_COMPTE IS NOT NULL

          SELECT
           UPPER (A.LIBL_MODE_VERSEMENT) + ' - ' + CAST(A.ID_VERSEMENT  AS VARCHAR(15)) AS LIB_VERSEMENT,
           A.ANNEE_IMPUT,
           CASE A.P_E_R
            WHEN  'P'
             THEN A.DAT_ENCAISSEMENT
            ELSE  NULL
           END AS DAT_PREV,
           CASE A.P_E_R
            WHEN  'P'
             THEN A.MNT_MVT_BUDGETAIRE
            ELSE  0.00
           END AS MNT_PREV,
           CASE A.P_E_R
            WHEN  'P'
             THEN NULL
            ELSE  A.DAT_SAISIE_VERSEMENT
           END AS DAT_SAISIE_VERSEMENT,
           CASE A.P_E_R
            WHEN  'P'
             THEN 0.00
            ELSE  A.MNT_MVT_BUDGETAIRE
           END AS MNT_VERSE_HT,
           CASE A.P_E_R
            WHEN  'P'
             THEN 0.00
            ELSE  B.MNT_MVT_BUDGETAIRE
           END AS MNT_MOBILISABLE_HT
          INTO
           #FINAL_VERSEMENT_PART1
          FROM
           #TMP_VERSEMENT1 A
           INNER JOIN #TMP_VERSEMENT2 B
            ON A.ID_VERSEMENT = B.ID_VERSEMENT
             AND A.ANNEE_IMPUT = B.ANNEE_IMPUT
             AND A.P_E_R = B.P_E_R
          WHERE
           (
            A.DAT_ENCAISSEMENT IS NOT NULL
            AND A.P_E_R = 'P'
           )
           OR A.P_E_R = 'R'

          IF (@BLN_DEBUG = 1)
          BEGIN

           SELECT
            '#TMP_VERSEMENT1',
            *
           FROM
            #TMP_VERSEMENT1 A
           WHERE
            (
             A.DAT_ENCAISSEMENT IS NOT NULL
             AND A.P_E_R = 'P'
            )
            OR A.P_E_R = 'R'
            AND ID_VERSEMENT = 86043

           SELECT
            '#TMP_VERSEMENT2',
            *
           FROM
            #TMP_VERSEMENT2
           WHERE
            ID_VERSEMENT = 86043

           SELECT
            '#FINAL_VERSEMENT_PART1',
            *
           FROM
            #FINAL_VERSEMENT_PART1
           WHERE
            LIB_VERSEMENT LIKE '%86043%'
          END

          DECLARE
           @RELIQUATS_PLAN_FORMATION_PART2 DECIMAL(18,2),
           @RELIQUATS_PLAN_FORMATION_DEBUT DECIMAL(18,2)

          UPDATE
           #TMP_MVT_BUD_ENG_ET_REGLE
          SET
           TAG = '2 RELIQUAT PLAN DE FORMATION'
          FROM
           #TMP_MVT_BUD_ENG_ET_REGLE
           INNER JOIN #TOUTE_MVT_BUDGETAIRE
            ON #TMP_MVT_BUD_ENG_ET_REGLE.ID_MVT_BUDGETAIRE = #TOUTE_MVT_BUDGETAIRE.ID_MVT_BUDGETAIRE
          WHERE
           COD_TYPE_VERSEMENT = 'OBLIG'  
           AND #TMP_MVT_BUD_ENG_ET_REGLE.P_E_R = 'R'
           AND TAG IS NULL

          SELECT
           @RELIQUATS_PLAN_FORMATION_PART2 = SUM(MNT_MVT_GROUPE)
          FROM
           #TMP_MVT_BUD_ENG_ET_REGLE
          WHERE
           TAG = '2 RELIQUAT PLAN DE FORMATION'

          IF (@BLN_DEBUG = 1)
          BEGIN
           SELECT
            '2 RELIQUAT PLAN DE FORMATION',
            *
           FROM
            #TMP_MVT_BUD_ENG_ET_REGLE
           WHERE
            TAG = '2 RELIQUAT PLAN DE FORMATION'
          END

          DECLARE
           @TOTAL_FONDS_RECREDITES_PART31 DECIMAL(18,2),
           @TOTAL_FONDS_RECREDITES_PART32 DECIMAL(18,2),
           @TOTAL_FONDS_RECREDITES DECIMAL(18,2)

          UPDATE
           #TMP_MVT_BUD_ENG_ET_REGLE
          SET
           TAG = '3 - RECREDITE ANNEE N'
          FROM
           #TMP_MVT_BUD_ENG_ET_REGLE
           INNER JOIN #TOUTE_MVT_BUDGETAIRE
            ON #TMP_MVT_BUD_ENG_ET_REGLE.ID_MVT_BUDGETAIRE = #TOUTE_MVT_BUDGETAIRE.ID_MVT_BUDGETAIRE
          WHERE
           #TMP_MVT_BUD_ENG_ET_REGLE.P_E_R = 'E'
           AND NUM_ANNEE >= @NUM_ANNEE
           AND TAG IS NULL
           AND
           (
            EXISTS
            (
             SELECT
              ID_MODULE_PEC,
              SUM(MNT_MVT_BUDGETAIRE)
             FROM
              #TOUTE_MVT_BUDGETAIRE TMP_E
             WHERE
              TMP_E.ID_MODULE_PEC = #TOUTE_MVT_BUDGETAIRE.ID_MODULE_PEC
              AND TMP_E.ID_SOUS_TYPE_COUT = #TOUTE_MVT_BUDGETAIRE.ID_SOUS_TYPE_COUT
              AND TMP_E.COD_TYPE_EVENEMENT IN ('CLOTACT', 'CLOMOPEC', 'ANCLOPEC') 
             GROUP BY
              ID_MODULE_PEC
             HAVING
              CAST(ABS(SUM(MNT_MVT_BUDGETAIRE)) AS DECIMAL(18,2)) > 0
            )
           )

          UPDATE
           #TMP_MVT_BUD_ENG_ET_REGLE
          SET
           TAG = '3 - RECREDITE ANNEE N'
          FROM
           #TMP_MVT_BUD_ENG_ET_REGLE
           INNER JOIN #TOUTE_MVT_BUDGETAIRE
            ON #TMP_MVT_BUD_ENG_ET_REGLE.ID_MVT_BUDGETAIRE = #TOUTE_MVT_BUDGETAIRE.ID_MVT_BUDGETAIRE
          WHERE
           #TMP_MVT_BUD_ENG_ET_REGLE.P_E_R IN ('E', 'R')
           AND #TOUTE_MVT_BUDGETAIRE.ID_MODULE_PEC IS NOT NULL
           AND NUM_ANNEE >= @NUM_ANNEE
           AND TAG IS NULL
           AND
           (
            NOT EXISTS
            (
             SELECT 1
             FROM
              #TOUTE_MVT_BUDGETAIRE TMP_E
             WHERE
              TMP_E.ID_MODULE_PEC = #TOUTE_MVT_BUDGETAIRE.ID_MODULE_PEC
              AND TMP_E.ID_SOUS_TYPE_COUT = #TOUTE_MVT_BUDGETAIRE.ID_SOUS_TYPE_COUT
              AND TMP_E.COD_TYPE_EVENEMENT IN ('ENGAGMT')
              AND TMP_E.DAT_MVT_BUDGETAIRE <= #TOUTE_MVT_BUDGETAIRE.DAT_MVT_BUDGETAIRE
            )
           )
           AND COD_TYPE_EVENEMENT NOT IN ('ENGAGMT', 'REGLEMT' , 'REGCOURT')
           AND
           (
            NOT EXISTS
            (
             SELECT 1
             FROM
              #TOUTE_MVT_BUDGETAIRE TMP_E
             WHERE
              TMP_E.ID_MODULE_PEC = #TOUTE_MVT_BUDGETAIRE.ID_MODULE_PEC
              AND TMP_E.ID_SOUS_TYPE_COUT = #TOUTE_MVT_BUDGETAIRE.ID_SOUS_TYPE_COUT
              AND LIBL_MVT_BUDGETAIRE LIKE 'REP%'  
            )
           )

          IF (@BLN_DEBUG = 1)
          BEGIN
           SELECT
            #TMP_MVT_BUD_ENG_ET_REGLE.TAG,
            #TMP_MVT_BUD_ENG_ET_REGLE.NUM_ANNEE,
            #TMP_MVT_BUD_ENG_ET_REGLE.DAT_MVT_BUDGETAIRE,
            #TMP_MVT_BUD_ENG_ET_REGLE.LIBL_MVT_BUDGETAIRE,
            #TMP_MVT_BUD_ENG_ET_REGLE.MNT_MVT_GROUPE,
            #TMP_MVT_BUD_ENG_ET_REGLE.P_E_R,
            COD_MODULE_PEC
           FROM
            #TMP_MVT_BUD_ENG_ET_REGLE
            INNER JOIN #TOUTE_MVT_BUDGETAIRE
             ON #TMP_MVT_BUD_ENG_ET_REGLE.ID_MVT_BUDGETAIRE = #TOUTE_MVT_BUDGETAIRE.ID_MVT_BUDGETAIRE
            INNER JOIN MODULE_PEC
             ON #TOUTE_MVT_BUDGETAIRE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC

           ORDER BY
            #TMP_MVT_BUD_ENG_ET_REGLE.NUM_ANNEE,
            #TMP_MVT_BUD_ENG_ET_REGLE.DAT_MVT_BUDGETAIRE
          END

          SELECT
           @TOTAL_FONDS_RECREDITES_PART31 = SUM(MNT_MVT_GROUPE)
          FROM
           #TMP_MVT_BUD_ENG_ET_REGLE
          WHERE
           TAG = '3 - RECREDITE ANNEE N'

          UPDATE
           #TMP_MVT_BUD_ENG_ET_REGLE
          SET
           TAG = '3 - RECREDITE ANNEES ANTERIEURES'
          FROM
           #TMP_MVT_BUD_ENG_ET_REGLE
           INNER JOIN #TOUTE_MVT_BUDGETAIRE
            ON #TMP_MVT_BUD_ENG_ET_REGLE.ID_MVT_BUDGETAIRE = #TOUTE_MVT_BUDGETAIRE.ID_MVT_BUDGETAIRE
          WHERE
           #TMP_MVT_BUD_ENG_ET_REGLE.P_E_R IN ('E', 'R')
           AND #TOUTE_MVT_BUDGETAIRE.ID_MODULE_PEC IS NOT NULL
           AND NUM_ANNEE < @NUM_ANNEE
           AND TAG IS NULL
           AND
           (
            NOT EXISTS
            (
             SELECT 1
             FROM
              #TOUTE_MVT_BUDGETAIRE TMP_E
             WHERE
              TMP_E.ID_MODULE_PEC = #TOUTE_MVT_BUDGETAIRE.ID_MODULE_PEC
              AND TMP_E.ID_SOUS_TYPE_COUT = #TOUTE_MVT_BUDGETAIRE.ID_SOUS_TYPE_COUT
              AND TMP_E.COD_TYPE_EVENEMENT IN ('ENGAGMT')
              AND TMP_E.DAT_MVT_BUDGETAIRE < #TOUTE_MVT_BUDGETAIRE.DAT_MVT_BUDGETAIRE
            )
           )
           AND COD_TYPE_EVENEMENT NOT IN ('ENGAGMT', 'REGLEMT' , 'REGCOURT')
           AND
           (
            NOT EXISTS
            (
             SELECT 1
             FROM
              #TOUTE_MVT_BUDGETAIRE TMP_E
             WHERE
              TMP_E.ID_MODULE_PEC = #TOUTE_MVT_BUDGETAIRE.ID_MODULE_PEC
              AND TMP_E.ID_SOUS_TYPE_COUT = #TOUTE_MVT_BUDGETAIRE.ID_SOUS_TYPE_COUT
              AND LIBL_MVT_BUDGETAIRE LIKE 'REP%'  
            )
           )

          SELECT
           @TOTAL_FONDS_RECREDITES_PART32 = SUM(MNT_MVT_GROUPE)
          FROM
           #TMP_MVT_BUD_ENG_ET_REGLE
          WHERE
           TAG = '3 - RECREDITE ANNEES ANTERIEURES'

          SELECT
           @TOTAL_FONDS_RECREDITES = ISNULL(@TOTAL_FONDS_RECREDITES_PART31,0) + ISNULL(@TOTAL_FONDS_RECREDITES_PART32,0)

          DECLARE
           @MNT_ENGAGE_ET_REGLE DECIMAL(18,2),
           @MNT_ENGAGE_ET_NON_REGLE DECIMAL(18,2),
           @MNT_ENGAGE_COMPL DECIMAL(18,2)

          UPDATE
           #TMP_MVT_BUD_ENG_ET_REGLE
          SET
           TAG = '5.1 FORMATIONS ENGAGEES ET REGLEES'
          FROM
           #TMP_MVT_BUD_ENG_ET_REGLE
           INNER JOIN #TOUTE_MVT_BUDGETAIRE
            ON #TMP_MVT_BUD_ENG_ET_REGLE.ID_MVT_BUDGETAIRE = #TOUTE_MVT_BUDGETAIRE.ID_MVT_BUDGETAIRE
          WHERE
           ID_MODULE_PEC IS NOT NULL
           AND COD_TYPE_EVENEMENT IN ('REGLEMT' , 'REGCOURT')
           AND #TMP_MVT_BUD_ENG_ET_REGLE.P_E_R = 'R'
           AND TAG IS NULL
           AND
           (
            EXISTS
            (
             SELECT 1
             FROM
              #TOUTE_MVT_BUDGETAIRE TMP_E
             WHERE
              TMP_E.ID_MODULE_PEC = #TOUTE_MVT_BUDGETAIRE.ID_MODULE_PEC
              AND TMP_E.ID_SOUS_TYPE_COUT = #TOUTE_MVT_BUDGETAIRE.ID_SOUS_TYPE_COUT
              AND
              (
               TMP_E.COD_TYPE_EVENEMENT IN  ('ENGAGMT')
               OR LIBL_MVT_BUDGETAIRE LIKE 'REP%'  
              )
            )
           )

          SELECT
           @MNT_ENGAGE_ET_REGLE = - SUM(MNT_MVT_GROUPE)
          FROM
           #TMP_MVT_BUD_ENG_ET_REGLE
          WHERE
           TAG = '5.1 FORMATIONS ENGAGEES ET REGLEES'

          SELECT
           NUM_ANNEE,
           MNT_REGLE = -SUM(MNT_MVT_GROUPE)
          INTO
           #FOR_ENGAGE_ET_REGLE
          FROM
           #TMP_MVT_BUD_ENG_ET_REGLE
          WHERE
           TAG = '5.1 FORMATIONS ENGAGEES ET REGLEES'
          GROUP BY
           NUM_ANNEE

          UPDATE
           #TMP_MVT_BUD_ENG_ET_REGLE
          SET
           TAG = '5.2 FORMATIONS ENGAGEES ET NON REGLEES'
          FROM
           #TMP_MVT_BUD_ENG_ET_REGLE
           INNER JOIN #TOUTE_MVT_BUDGETAIRE
            ON #TMP_MVT_BUD_ENG_ET_REGLE.ID_MVT_BUDGETAIRE = #TOUTE_MVT_BUDGETAIRE.ID_MVT_BUDGETAIRE
          WHERE
           ID_MODULE_PEC IS NOT NULL
           AND #TMP_MVT_BUD_ENG_ET_REGLE.P_E_R = 'E'
           AND
           (
            EXISTS
            (
             SELECT 1
             FROM
              #TOUTE_MVT_BUDGETAIRE TMP_E
             WHERE
              TMP_E.ID_MODULE_PEC = #TOUTE_MVT_BUDGETAIRE.ID_MODULE_PEC
              AND TMP_E.ID_SOUS_TYPE_COUT = #TOUTE_MVT_BUDGETAIRE.ID_SOUS_TYPE_COUT
              AND
              (
               TMP_E.COD_TYPE_EVENEMENT IN ('ENGAGMT')
               OR LIBL_MVT_BUDGETAIRE LIKE 'REP%'  
              )
            )
           )
           AND TAG IS NULL

          SELECT
           @MNT_ENGAGE_ET_NON_REGLE = -SUM(MNT_MVT_GROUPE)
          FROM
           #TMP_MVT_BUD_ENG_ET_REGLE
          WHERE
           TAG = '5.2 FORMATIONS ENGAGEES ET NON REGLEES'

          SELECT
           NUM_ANNEE,
           MNT_REGLE = -SUM(MNT_MVT_GROUPE)
          INTO
           #FOR_ENGAGE_ET_NON_REGLE
          FROM
           #TMP_MVT_BUD_ENG_ET_REGLE
          WHERE
           TAG = '5.2 FORMATIONS ENGAGEES ET NON REGLEES'
          GROUP BY
           NUM_ANNEE

          UPDATE
           #TMP_MVT_BUD_ENG_ET_REGLE
          SET
           TAG = '5.3 REGLEMENTS COMPLEMENTAIRES'
          FROM
           #TMP_MVT_BUD_ENG_ET_REGLE
           INNER JOIN #TOUTE_MVT_BUDGETAIRE
            ON #TMP_MVT_BUD_ENG_ET_REGLE.ID_MVT_BUDGETAIRE = #TOUTE_MVT_BUDGETAIRE.ID_MVT_BUDGETAIRE
          WHERE
           ID_MODULE_PEC IS NOT NULL
           AND COD_TYPE_EVENEMENT IN ('REGLEMT' , 'REGCOURT')
           AND #TMP_MVT_BUD_ENG_ET_REGLE.P_E_R IN ('E', 'R')
           AND TAG IS NULL

          SET
           @MNT_ENGAGE_COMPL = 0

          SELECT
           @MNT_ENGAGE_COMPL = -SUM(MNT_MVT_GROUPE)
          FROM
           #TMP_MVT_BUD_ENG_ET_REGLE
          WHERE
           TAG = '5.3 REGLEMENTS COMPLEMENTAIRES'

          IF (@BLN_DEBUG = 1)
          BEGIN
           SELECT
            COD_MODULE_PEC,
            ID_SOUS_TYPE_COUT,
            NUM_ANNEE,
            DAT_CLOTURE,
            MNT_ENGAGE,
            MNT_REGLE,
            MNT_SOLDE = MNT_REGLE - MNT_ENGAGE
           FROM
            #TMP_MVT_REGLE_COMPLEMENTAIRE
            INNER JOIN MODULE_PEC
             ON #TMP_MVT_REGLE_COMPLEMENTAIRE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
            INNER JOIN ACTION_PEC
             ON MODULE_PEC.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC
          END

          DECLARE
           @MNT_VERSEMENT_PREV DECIMAL(18,2),
           @MNT_FORMATION_PREV DECIMAL(18,2),
           @MNT_SOLD_PREV  DECIMAL(18,2),
           @MNT_VERSEMENT_OBLIG_DIFFERE DECIMAL(18,2)

          SELECT
           @MNT_VERSEMENT_PREV = SUM(MNT_PREV) 
          FROM
           #FINAL_VERSEMENT_PART1

          UPDATE
           #TMP_MVT_BUD_ENG_ET_REGLE 
          SET
           TAG = '6 VERSEMENT OBLIGATOIRE DIFFERE'
          FROM
           #TMP_MVT_BUD_ENG_ET_REGLE 
           INNER JOIN #TOUTE_MVT_BUDGETAIRE
            ON #TMP_MVT_BUD_ENG_ET_REGLE.ID_MVT_BUDGETAIRE = #TOUTE_MVT_BUDGETAIRE.ID_MVT_BUDGETAIRE
          WHERE
           #TMP_MVT_BUD_ENG_ET_REGLE.P_E_R = 'P'
           AND COD_TYPE_VERSEMENT = 'OBLIG'
           AND TAG IS NULL

          SELECT
           @MNT_VERSEMENT_OBLIG_DIFFERE = SUM(MNT_MVT_GROUPE)
          FROM
           #TMP_MVT_BUD_ENG_ET_REGLE
          WHERE
           TAG = '6 VERSEMENT OBLIGATOIRE DIFFERE'

          UPDATE
           #TMP_MVT_BUD_ENG_ET_REGLE 
          SET
           TAG = '6 FORMATION PREVISIONNEL'
          FROM
           #TMP_MVT_BUD_ENG_ET_REGLE 
           INNER JOIN #TOUTE_MVT_BUDGETAIRE
            ON #TMP_MVT_BUD_ENG_ET_REGLE.ID_MVT_BUDGETAIRE = #TOUTE_MVT_BUDGETAIRE.ID_MVT_BUDGETAIRE
          WHERE
           #TMP_MVT_BUD_ENG_ET_REGLE.P_E_R = 'P'
           AND ID_MODULE_PEC IS NOT NULL
           AND TAG IS NULL

          SELECT
           @MNT_FORMATION_PREV = SUM(MNT_MVT_GROUPE)
          FROM
           #TMP_MVT_BUD_ENG_ET_REGLE
          WHERE
           TAG = '6 FORMATION PREVISIONNEL'

          SET
           @MNT_SOLD_PREV = ISNULL(@MNT_RELIQUAT_PREVISIONNEL_INITIAL, 0)
           + ISNULL(@MNT_VERSEMENT_PREV,0)
           + ISNULL(@MNT_VERSEMENT_OBLIG_DIFFERE, 0)
           + ISNULL(@MNT_FORMATION_PREV,0)

          UPDATE
           #TMP_MVT_BUD_ENG_ET_REGLE 
          SET
           TAG = '4 REGUL'
          FROM
           #TMP_MVT_BUD_ENG_ET_REGLE 
           INNER JOIN #TOUTE_MVT_BUDGETAIRE
            ON #TMP_MVT_BUD_ENG_ET_REGLE.ID_MVT_BUDGETAIRE = #TOUTE_MVT_BUDGETAIRE.ID_MVT_BUDGETAIRE 
          WHERE
           #TMP_MVT_BUD_ENG_ET_REGLE.P_E_R IN ('E', 'R')
           AND TAG IS NULL 

          CREATE TABLE #REGULARISATION_PART4
          (
           DAT_REGUL DATETIME NULL,
           LIB_REGULARISATION VARCHAR(70),
           MNT_REGULARISATION DECIMAL(18,2)
          )

          INSERT INTO
           #REGULARISATION_PART4
          SELECT
           DAT_MVT_BUDGETAIRE AS DAT_REGUL,
           LIBL_MVT_BUDGETAIRE + '(' + CAST(NUM_ANNEE AS VARCHAR(4) ) + ')' AS LIB_REGULARISATION,
           ISNULL(MNT_MVT_GROUPE,0) AS MNT_REGULARISATION
          FROM
           #TMP_MVT_BUD_ENG_ET_REGLE
          WHERE
           TAG = '4 REGUL'
           AND #TMP_MVT_BUD_ENG_ET_REGLE.ID_TYPE_EVENEMENT NOT IN (32,33)
          ORDER BY
           DAT_MVT_BUDGETAIRE,
           LIBC_TYPE_MOUVEMENT

          INSERT INTO #REGULARISATION_PART4
          (
           LIB_REGULARISATION,
           MNT_REGULARISATION
          )
          SELECT
           CASE ID_TYPE_EVENEMENT
            WHEN  33
             THEN 'Fonds prescrits '
            ELSE  'Fonds Mutualis‚s suppl‚mentaires '
           END
           + CAST(NUM_ANNEE AS VARCHAR(4)) AS LIB_REGULARISATION,
           SUM(MNT_MVT_GROUPE) AS MNT_REGULARISATION
          FROM
           #TMP_MVT_BUD_ENG_ET_REGLE
          WHERE
           TAG = '4 REGUL'
           AND #TMP_MVT_BUD_ENG_ET_REGLE.ID_TYPE_EVENEMENT IN (32,33)
          GROUP BY
           #TMP_MVT_BUD_ENG_ET_REGLE.ID_TYPE_EVENEMENT,
           #TMP_MVT_BUD_ENG_ET_REGLE.NUM_ANNEE

          IF (@BLN_DEBUG = 1)
          BEGIN
           SELECT
            TAG,
            LIBL_MVT_BUDGETAIRE,
            P_E_R,
            MNT_MVT_GROUPE,
            *
           FROM
            #TMP_MVT_BUD_ENG_ET_REGLE
           WHERE
            #TMP_MVT_BUD_ENG_ET_REGLE.P_E_R IN ('E', 'R')
           ORDER BY
            #TMP_MVT_BUD_ENG_ET_REGLE.NUM_ANNEE,
            #TMP_MVT_BUD_ENG_ET_REGLE.DAT_MVT_BUDGETAIRE

           SELECT
            #TMP_MVT_BUD_ENG_ET_REGLE.TAG,
            #TMP_MVT_BUD_ENG_ET_REGLE.NUM_ANNEE,
            #TMP_MVT_BUD_ENG_ET_REGLE.DAT_MVT_BUDGETAIRE,
            #TMP_MVT_BUD_ENG_ET_REGLE.LIBL_MVT_BUDGETAIRE,
            #TMP_MVT_BUD_ENG_ET_REGLE.MNT_MVT_GROUPE,
            #TMP_MVT_BUD_ENG_ET_REGLE.P_E_R,
            COD_MODULE_PEC
           FROM
            #TMP_MVT_BUD_ENG_ET_REGLE
            INNER JOIN #TOUTE_MVT_BUDGETAIRE
             ON #TMP_MVT_BUD_ENG_ET_REGLE.ID_MVT_BUDGETAIRE = #TOUTE_MVT_BUDGETAIRE.ID_MVT_BUDGETAIRE
            INNER JOIN MODULE_PEC
             ON #TOUTE_MVT_BUDGETAIRE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
           WHERE
            #TMP_MVT_BUD_ENG_ET_REGLE.P_E_R IN ('E', 'R')
           ORDER BY
            #TMP_MVT_BUD_ENG_ET_REGLE.NUM_ANNEE,
            #TMP_MVT_BUD_ENG_ET_REGLE.DAT_MVT_BUDGETAIRE
          END

          IF (@BLN_DEBUG = 1)
          BEGIN
           SELECT
            TAG,
            ID_MODULE_PEC,
            ID_SOUS_TYPE_COUT,
            #TMP_MVT_BUD_ENG_ET_REGLE.DAT_MVT_BUDGETAIRE,
            #TMP_MVT_BUD_ENG_ET_REGLE.LIBL_MVT_BUDGETAIRE,
            MNT_MVT_GROUPE
           FROM
            #TMP_MVT_BUD_ENG_ET_REGLE
            INNER JOIN #TOUTE_MVT_BUDGETAIRE
             ON #TMP_MVT_BUD_ENG_ET_REGLE.ID_MVT_BUDGETAIRE = #TOUTE_MVT_BUDGETAIRE.ID_MVT_BUDGETAIRE
           WHERE
            TAG = '5.1 FORMATIONS ENGAGEES ET REGLEES'
            AND NUM_ANNEE = 2009
           ORDER BY
            2,
            3

           SELECT
            TAG,
            ID_MODULE_PEC,
            ID_SOUS_TYPE_COUT,
            #TMP_MVT_BUD_ENG_ET_REGLE.DAT_MVT_BUDGETAIRE,
            #TMP_MVT_BUD_ENG_ET_REGLE.LIBL_MVT_BUDGETAIRE,
            MNT_MVT_GROUPE
           FROM
            #TMP_MVT_BUD_ENG_ET_REGLE
            INNER JOIN #TOUTE_MVT_BUDGETAIRE
             ON #TMP_MVT_BUD_ENG_ET_REGLE.ID_MVT_BUDGETAIRE = #TOUTE_MVT_BUDGETAIRE.ID_MVT_BUDGETAIRE
           WHERE
            TAG = '5.2 FORMATIONS ENGAGEES ET NON REGLEES'
            AND NUM_ANNEE = 2009
           ORDER BY
            2,
            3
          END

          IF (@BLN_DEBUG = 2)
          BEGIN
           SELECT
            TAG,
            ID_MODULE_PEC,
            ID_SOUS_TYPE_COUT,
            #TMP_MVT_BUD_ENG_ET_REGLE.DAT_MVT_BUDGETAIRE,
            #TMP_MVT_BUD_ENG_ET_REGLE.LIBL_MVT_BUDGETAIRE,
            MNT_MVT_GROUPE
           FROM
            #TMP_MVT_BUD_ENG_ET_REGLE
            INNER JOIN #TOUTE_MVT_BUDGETAIRE
             ON #TMP_MVT_BUD_ENG_ET_REGLE.ID_MVT_BUDGETAIRE = #TOUTE_MVT_BUDGETAIRE.ID_MVT_BUDGETAIRE
           WHERE
            NUM_ANNEE = 2009
           ORDER BY
            #TMP_MVT_BUD_ENG_ET_REGLE.DAT_MVT_BUDGETAIRE,
            #TMP_MVT_BUD_ENG_ET_REGLE.ID_MVT_BUDGETAIRE

           SELECT
            COD_MODULE_PEC,
            ID_SOUS_TYPE_COUT,
            TAG,
            SUM(CAST(MNT_MVT_GROUPE AS DECIMAL(18,2))),
            MIN(#TMP_MVT_BUD_ENG_ET_REGLE.DAT_MVT_BUDGETAIRE),
            MAX(#TMP_MVT_BUD_ENG_ET_REGLE.DAT_MVT_BUDGETAIRE)
           FROM
            #TMP_MVT_BUD_ENG_ET_REGLE
            INNER JOIN #TOUTE_MVT_BUDGETAIRE
             ON #TMP_MVT_BUD_ENG_ET_REGLE.ID_MVT_BUDGETAIRE = #TOUTE_MVT_BUDGETAIRE.ID_MVT_BUDGETAIRE
            INNER JOIN MODULE_PEC
             ON #TOUTE_MVT_BUDGETAIRE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
           WHERE
            NUM_ANNEE = 2009

            AND #TMP_MVT_BUD_ENG_ET_REGLE.P_E_R IN ('E', 'R')
           GROUP BY
            TAG,
            COD_MODULE_PEC,
            ID_SOUS_TYPE_COUT
           HAVING
            ABS(SUM(CAST(MNT_MVT_GROUPE AS DECIMAL(18,2)))) > 0
           ORDER BY
            1,
            2,
            3
          END

          DECLARE
           @TOTAL_MOB_PLAN DECIMAL(18,2)

          SELECT
           @TOTAL_MOB_PLAN =
            ISNULL(@SOLDE_ENGAGEMENT_INITIAL,0)
            + ISNULL((SELECT SUM(MNT_MOBILISABLE_HT) FROM #FINAL_VERSEMENT_PART1),0)
            + ISNULL((@RELIQUATS_PLAN_FORMATION_PART2),0)
            + ISNULL(@TOTAL_FONDS_RECREDITES,0)
            + ISNULL((SELECT  SUM(MNT_REGULARISATION) FROM #REGULARISATION_PART4),0)

          DECLARE
           @MNT_SOLD_DISPO_PLAN DECIMAL(18,2),
           @MNT_SOLD_DISPO_PLAN_THEORIQUE DECIMAL(18,2)

          SELECT
           MNT_MVT_BUDGETAIRE_CALCULE = MVT.MNT_MVT_BUDGETAIRE * (CASE PB.SENS WHEN 'D' THEN -1 ELSE 1 END),
           MNT_DEBIT = MVT.MNT_MVT_BUDGETAIRE * (CASE PB.SENS WHEN 'D' THEN 1 ELSE 0 END),
           MNT_CREDIT = MVT.MNT_MVT_BUDGETAIRE * (CASE PB.SENS WHEN 'D' THEN 0 ELSE 1 END),
           DAT_MVT_BUDGETAIRE = MVT.DAT_MVT_BUDGETAIRE,
           PER = MVT.P_E_R,
           COMPTE.ID_COMPTE
          INTO
           #TMP_MVT_INITIAL_FIN
          FROM
           COMPTE
           INNER JOIN MVT_BUDGETAIRE MVT
            ON MVT.ID_COMPTE = COMPTE.ID_COMPTE
           INNER JOIN TYPE_MOUVEMENT
            ON TYPE_MOUVEMENT.ID_TYPE_MOUVEMENT = MVT.ID_TYPE_MOUVEMENT
           INNER JOIN TYPE_COMPTE
            ON COMPTE.ID_TYPE_COMPTE = TYPE_COMPTE.ID_TYPE_COMPTE
           INNER JOIN PARAMETRAGE_BUDGETAIRE PB
            ON PB.ID_TYPE_MOUVEMENT  = MVT.ID_TYPE_MOUVEMENT
             AND PB.ID_TYPE_COMPTE = TYPE_COMPTE.ID_TYPE_COMPTE
           INNER JOIN PERIODE
            ON COMPTE.ID_PERIODE = PERIODE.ID_PERIODE
          WHERE
           @ID_GROUPE IS NOT NULL
           AND COMPTE.ID_GROUPE = @ID_GROUPE
           AND COMPTE.ID_TYPE_FINANCEMENT = 1   
           AND MVT.DAT_MVT_BUDGETAIRE <= @DAT_FIN

          SELECT   
           @MNT_I_P = SUM(MNT_MVT_BUDGETAIRE_CALCULE)  
          FROM
           #TMP_MVT_INITIAL_FIN   
          WHERE
           DAT_MVT_BUDGETAIRE <= @DAT_FIN
           AND PER = 'P'

          SELECT   
           @MNT_I_E = SUM(MNT_MVT_BUDGETAIRE_CALCULE)  
          FROM
           #TMP_MVT_INITIAL_FIN   
          WHERE   
           DAT_MVT_BUDGETAIRE <= @DAT_FIN
           AND PER = 'E'

          SELECT   
           @MNT_I_R = SUM(MNT_MVT_BUDGETAIRE_CALCULE)  
          FROM
           #TMP_MVT_INITIAL_FIN   
          WHERE   
           DAT_MVT_BUDGETAIRE <= @DAT_FIN
           AND PER = 'R'  

          SET
           @MNT_I_E = @MNT_I_E + @MNT_I_R
          SET
           @MNT_I_P = @MNT_I_P + @MNT_I_E

          SELECT @MNT_SOLD_DISPO_PLAN_THEORIQUE = ISNULL(@MNT_I_E, 0)   

          SET
           @MNT_SOLD_DISPO_PLAN = 0
          SET
           @MNT_SOLD_DISPO_PLAN = ISNULL(@TOTAL_MOB_PLAN,0) - ISNULL(@MNT_ENGAGE_ET_REGLE,0) - ISNULL(@MNT_ENGAGE_ET_NON_REGLE, 0) - ISNULL(@MNT_ENGAGE_COMPL, 0)

          SET
           @DAT_FIN   = dbo.GetMinDate(GETDATE(), @DAT_FIN)
          SET
           @DAT_DEBUT = dbo.GetMinDate(@DAT_DEBUT, @DAT_FIN)

          DECLARE
           @ANNEE_DEBUT INT,
           @ANNEE_FIN INT
          SET
           @ANNEE_DEBUT = YEAR([dbo].[GetShortDate](@DAT_DEBUT))-1
          SET
           @ANNEE_FIN = YEAR([dbo].[GetShortDate](@DAT_FIN)) -1;

          WITH XMLNAMESPACES (
           DEFAULT 'EDT_SYNTHESE_CMPT_PLAN_FORMATION'
          )

          SELECT    
          (
           SELECT
            dbo.[GetShortDate](@DAT_DEBUT) AS DATE_DEBUT,
            dbo.[GetShortDate](@DAT_FIN)  AS DATE_FIN,
            @LIB_GROUPE AS LIB_GROUPE,
            dbo.[GetShortDate](@DAT_DEBUT) AS DAT_SOLD_DISPONIBLE,
            dbo.GetFrenchCurrencyFormat(CAST(COALESCE(@SOLDE_ENGAGEMENT_INITIAL,0.00) AS MONEY))  AS MNT_SOLD_DISPONIBLE
           FOR XML RAW ('ENTETE'),ELEMENTS, TYPE),

           (
            SELECT
            (
             SELECT
              LIB_VERSEMENT,
              ISNULL(CAST(ANNEE_IMPUT AS VARCHAR(4)), '-') AS ANNEE_IMPUT,
              ISNULL(dbo.GetShortDate(DAT_SAISIE_VERSEMENT), '-') AS DAT_VERS,
              CASE MNT_VERSE_HT
               WHEN  0.00
                THEN NULL
               ELSE  dbo.GetFrenchCurrencyFormat(CAST(COALESCE(MNT_VERSE_HT,0.00) AS MONEY))
              END AS MNT_VERSE_HT,
              CASE MNT_MOBILISABLE_HT
               WHEN  0.00
                THEN NULL
               ELSE  dbo.GetFrenchCurrencyFormat(CAST(COALESCE(MNT_MOBILISABLE_HT,0.00) AS MONEY))
              END AS MNT_MOBILISABLE_HT
             FROM
              #FINAL_VERSEMENT_PART1
             ORDER BY
              COALESCE(DAT_SAISIE_VERSEMENT, DAT_PREV),
              LIB_VERSEMENT
             FOR XML RAW('LIST_VERSEMENT'), ELEMENTS, TYPE
            )
            FOR XML RAW('VERSEMENT'), ELEMENTS, TYPE),

            (
             SELECT
              dbo.GetFrenchCurrencyFormat(CAST(COALESCE(SUM(MNT_VERSE_HT),0.00) AS MONEY))  AS TOTAL_MNT_VERSE_HT,
              dbo.GetFrenchCurrencyFormat(CAST(COALESCE(SUM(MNT_MOBILISABLE_HT),0.00) AS MONEY)) AS TOTAL_MNT_MOBILISABLE_HT
             FROM
              #FINAL_VERSEMENT_PART1
             FOR XML RAW('TOTAL_LIST_VERSEMENT'), ELEMENTS, TYPE
            ),

            (
             SELECT
              NUM_ANNEE,
              CASE
               WHEN  NUM_ANNEE >= 2012
                THEN '30 juin '
               ELSE  '30 sept. '
              END + CAST(NUM_ANNEE + 1 as VARCHAR(4))  AS RELIQUAT_LIB_MOIS,
              dbo.GetFrenchCurrencyFormat(cast(SUM(MNT_MVT_GROUPE) as MONEY)) as MNT_RELIQUAT
             FROM
              #TMP_MVT_BUD_ENG_ET_REGLE
             WHERE
              LIBL_MVT_BUDGETAIRE like 'VO Reliquat normal%'
             GROUP BY
              NUM_ANNEE
             ORDER BY
              NUM_ANNEE
             FOR XML RAW('RELIQUATS'), ELEMENTS, TYPE
            ),

            dbo.GetFrenchCurrencyFormat(CAST(COALESCE(@TOTAL_FONDS_RECREDITES,0.00) AS MONEY))  AS TOTAL_FONDS_RECREDITES,
            YEAR([dbo].[GetShortDate](@DAT_DEBUT)) AS ANNEE_FONDS_RECREDITES_SUR,
            dbo.[GetShortDate](@DAT_DEBUT) AS DAT_FONDS_RECREDITES_SUR,
            dbo.GetFrenchCurrencyFormat(CAST(COALESCE(@TOTAL_FONDS_RECREDITES_PART31,0.00) AS MONEY))  AS MNT_FONDS_RECREDITES_SUR,
            dbo.GetFrenchCurrencyFormat(CAST(COALESCE(@TOTAL_FONDS_RECREDITES_PART32,0.00) AS MONEY))  AS MNT_FONDS_RECREDITES_ANT,

            (
             SELECT
             (
              SELECT
               ISNULL(dbo.GetShortDate(DAT_REGUL), '') AS DAT_REGUL,
               LIB_REGULARISATION AS LIB_REGULARISATION,
               dbo.GetFrenchCurrencyFormat(CAST(COALESCE(MNT_REGULARISATION,0.00) AS MONEY)) AS MNT_REGULARISATION
              FROM
               #REGULARISATION_PART4
              FOR XML RAW('LIST_REGULARISATION'), ELEMENTS, TYPE
             )
             FOR XML RAW('REGULARISATION'), ELEMENTS, TYPE
            ),

            dbo.GetFrenchCurrencyFormat(CAST(COALESCE( @TOTAL_MOB_PLAN ,0.00) AS MONEY)) AS MNT_MOBILISABLE_PLAN,      

            (
             SELECT  

              dbo.GetFrenchCurrencyFormat(CAST(COALESCE(-@MNT_ENGAGE_ET_REGLE, 0.00) AS MONEY)) AS MNT_ENGAGE_ET_REGLE,  
              (
               SELECT   
                CAST(NUM_ANNEE AS VARCHAR(4)) as NUM_ANNEE_FOR,
                dbo.GetFrenchCurrencyFormat(CAST(COALESCE(-MNT_REGLE,0.00)AS MONEY)) AS MNT_REGLE
               FROM
                #FOR_ENGAGE_ET_REGLE
               FOR XML RAW('FOR_ENGAGE_ET_REGLE'), ELEMENTS, TYPE
              ),

              dbo.GetFrenchCurrencyFormat(CAST(COALESCE(-@MNT_ENGAGE_ET_NON_REGLE, 0.00) AS MONEY)) AS MNT_ENGAGE_ET_NON_REGLE,
              (
               SELECT
                CAST(NUM_ANNEE AS VARCHAR(4)) as NUM_ANNEE_FOR, dbo.GetFrenchCurrencyFormat(CAST(COALESCE(-MNT_REGLE,0.00)AS MONEY)) AS MNT_REGLE
               FROM
                #FOR_ENGAGE_ET_NON_REGLE      
               FOR XML RAW('FOR_ENGAGE_ET_NON_REGLE'), ELEMENTS, TYPE
              ),

              dbo.GetFrenchCurrencyFormat(CAST(COALESCE(-@MNT_ENGAGE_COMPL ,0.00) AS MONEY)) AS MNT_ENGAGE_COMPL
              FOR XML RAW('ENGAGEMENT'), ELEMENTS, TYPE
            ),

            dbo.GetFrenchCurrencyFormat(CAST(
             - COALESCE(@MNT_ENGAGE_ET_REGLE, 0.00)
             - COALESCE(@MNT_ENGAGE_ET_NON_REGLE, 0.00)
             - COALESCE(@MNT_ENGAGE_COMPL, 0.00)
            AS MONEY)) AS MNT_FINANCEMENT_PLAN,

            dbo.GetShortDate(@DAT_FIN) AS DAT_SOLD_DISPO_PLAN,       
            dbo.GetFrenchCurrencyFormat(CAST(COALESCE(@MNT_SOLD_DISPO_PLAN,0.00) AS MONEY))  AS MNT_SOLD_DISPO_PLAN,

            dbo.GetShortDate(@DAT_FIN) AS DATE_SOLD_REEL,
            dbo.GetFrenchCurrencyFormat(CAST(COALESCE(@MNT_I_R,0.00) AS MONEY)) AS MNT_SOLD_REEL,

            dbo.GetFrenchCurrencyFormat(CAST(COALESCE(@MNT_SOLD_DISPO_PLAN_THEORIQUE,0.00) AS MONEY))  AS MNT_SOLD_DISPO_PLAN_THEORIQUE
            FOR XML RAW('LETTRE'), ELEMENTS,TYPE
         END
GO

         CREATE PROCEDURE dbo.TRY_UPDATE_VERSEMENT_EXTRANET
         	@REF_EXTRANET VARCHAR(20),
         	@ID_MODE_VERSEMENT INT,
         	@LIB_BANQUE VARCHAR(50),
         	@NUM_CHEQUE VARCHAR(10),
         	@DAT_VALIDATION_EXTRANET DATETIME,
         	@ID_VERSEMENT INT OUT
         AS
         BEGIN
         	SET @ID_VERSEMENT = 0
         	DECLARE
         		@ID_BORDEREAU INT,
         		@ID_MODE_VERS_EXISTANT INT = NULL

         	SELECT
         		@ID_VERSEMENT = ID_VERSEMENT,
         		@ID_BORDEREAU = ID_BORDEREAU,
         		@ID_MODE_VERS_EXISTANT = ID_MODE_VERSEMENT
         	FROM
         		VERSEMENT
         	WHERE
         		REF_EXTRANET = @REF_EXTRANET

         	IF	(
         		@ID_VERSEMENT > 0
         		AND
         		@ID_BORDEREAU IS NULL
         		AND
         		@ID_MODE_VERS_EXISTANT = 3
         		)
         		BEGIN

         			DECLARE
         				@ID_BANQUE INT,
         				@NB_BANQUE INT = 0

         			SELECT
         				@NB_BANQUE = COUNT(ID_BANQUE)
         			FROM
         				BANQUE
         			WHERE
         				LIBL_BANQUE LIKE '%' + @LIB_BANQUE + '%'

         			IF @NB_BANQUE = 1
         				BEGIN
         					SELECT
         						@ID_BANQUE = ID_BANQUE,
         						@LIB_BANQUE = LIBL_BANQUE
         					FROM
         						BANQUE
         					WHERE
         						LIBL_BANQUE LIKE '%' + @LIB_BANQUE + '%'
         				END
         			ELSE
         				BEGIN
         					SELECT
         						@ID_BANQUE = ID_BANQUE,
         						@LIB_BANQUE = LIBL_BANQUE
         					FROM
         						BANQUE
         					WHERE
         						COD_BANQUE = 'ND'
         						AND
         						BLN_ACTIF = 1
         				END

         			UPDATE
         				VERSEMENT
         			SET
         				ID_MODE_VERSEMENT = @ID_MODE_VERSEMENT,
         				ID_BANQUE = @ID_BANQUE,
         				LIB_BANQUE = @LIB_BANQUE,
         				NUM_CHEQUE = @NUM_CHEQUE,
         				DAT_VALIDATION_EXTRANET = @DAT_VALIDATION_EXTRANET,
         				DAT_MODIF = GETDATE()
         			WHERE
         				ID_VERSEMENT = @ID_VERSEMENT
         		END
         END
GO

         CREATE PROCEDURE [dbo].[BATCH_INS_SUIVI_COMPTABLE_ENGAGEMENT_PERIODE]
         (@ID_ENGAGEMENT_MODULE_CPTA_PRO integer)
         AS 
         DECLARE
         @ID_MODULE_PRO					int,
         @NB_UNITE_TOTALE				float,
         @NB_UNITE_EVALUATION			float,
         @NB_UNITE_ACCOMPAGNEMENT		float,
         @MONTANT_ENGAGE					float,

         @NB_UNITE_TOTALE_ANNEE			float,
         @NB_UNITE_EVALUATION_ANNEE		float,
         @NB_UNITE_ACCOMPAGNEMENT_ANNEE	float,
         @MONTANT_ENGAGE_ANNEE			float,

         @NB_UNITE_TOTALE_CUMUL			float,
         @NB_UNITE_EVALUATION_CUMUL		float,
         @NB_UNITE_ACCOMPAGNEMENT_CUMUL	float,
         @MONTANT_ENGAGE_CUMUL			float,

         @DAT_CREATION					datetime,
         @BLN_ACTIF						tinyint,
         @ID_PERIODE						int,
         @DAT_DEBUT						datetime,
         @DAT_FIN						datetime,
         @DAT_DEB_PERIODE				datetime,
         @DAT_FIN_PERIODE				datetime,
         @NB_JOUR_TOT_MODULE				int,
         @NB_JOUR_AN						int,
         @ANNEE							int

         BEGIN
         	SELECT 	@ID_MODULE_PRO				= ENGAGEMENT_MODULE_CPTA_PRO.ID_MODULE_PRO,
         			@NB_UNITE_TOTALE			= ENGAGEMENT_MODULE_CPTA_PRO.NB_UNITE_TOTALE,
         			@NB_UNITE_ACCOMPAGNEMENT	= ENGAGEMENT_MODULE_CPTA_PRO.NB_UNITE_ACCOMPAGNEMENT,
         			@NB_UNITE_EVALUATION		= ENGAGEMENT_MODULE_CPTA_PRO.NB_UNITE_EVALUATION,
         			@MONTANT_ENGAGE				= ENGAGEMENT_MODULE_CPTA_PRO.MONTANT_ENGAGE,
         			@BLN_ACTIF					= ENGAGEMENT_MODULE_CPTA_PRO.BLN_ACTIF,
         			@DAT_CREATION				= ENGAGEMENT_MODULE_CPTA_PRO.DAT_CREATION,
         			@DAT_DEBUT					= MODULE_PRO.DAT_DEBUT,
         			@DAT_FIN					= MODULE_PRO.DAT_FIN
         	FROM ENGAGEMENT_MODULE_CPTA_PRO, MODULE_PRO
         	WHERE ID_ENGAGEMENT_MODULE_CPTA_PRO				= @ID_ENGAGEMENT_MODULE_CPTA_PRO		
         	AND ENGAGEMENT_MODULE_CPTA_PRO .ID_MODULE_PRO	=  MODULE_PRO .ID_MODULE_PRO 

         	SELECT @NB_JOUR_TOT_MODULE = DATEDIFF(day, @DAT_DEBUT, @DAT_FIN + 1)

         	SET @NB_UNITE_TOTALE_CUMUL			= 0
         	SET @NB_UNITE_EVALUATION_CUMUL		= 0
         	SET @NB_UNITE_ACCOMPAGNEMENT_CUMUL	= 0
         	SET @MONTANT_ENGAGE_CUMUL			= 0

         	SET @ANNEE = YEAR(@DAT_DEBUT)

         	WHILE  @ANNEE <= YEAR(@DAT_FIN)
         	BEGIN
         		SET @ID_PERIODE = NULL
         		SELECT	@ID_PERIODE = ID_PERIODE
         		FROM	PERIODE	
         		WHERE	ID_TYPE_PERIODE = 1
         		AND		NUM_ANNEE = @ANNEE 

         		IF @ID_PERIODE IS NOT NULL
         		BEGIN
         			IF @ANNEE = YEAR(@DAT_DEBUT)
         			BEGIN
         				SET @DAT_DEB_PERIODE = @DAT_DEBUT
         			END
         			ELSE
         			BEGIN
         				SET @DAT_DEB_PERIODE = CONVERT(DATETIME, '01/01/' + CAST(@ANNEE AS VARCHAR), 103)
         			END

         			IF @ANNEE = YEAR(@DAT_FIN)
         			BEGIN
         				SET @DAT_FIN_PERIODE = @DAT_FIN
         			END
         			ELSE
         			BEGIN
         				SET @DAT_FIN_PERIODE = CONVERT(DATETIME, '01/01/' + CAST(@ANNEE+1 AS VARCHAR), 103)
         			END

         			SELECT @NB_JOUR_AN = DATEDIFF(day, @DAT_DEB_PERIODE, @DAT_FIN_PERIODE + 1)

         			SET @NB_UNITE_TOTALE_ANNEE			= ROUND(@NB_UNITE_TOTALE			* @NB_JOUR_AN / @NB_JOUR_TOT_MODULE, 2)
         			SET @NB_UNITE_EVALUATION_ANNEE		= ROUND(@NB_UNITE_EVALUATION		* @NB_JOUR_AN / @NB_JOUR_TOT_MODULE, 2)
         			SET @NB_UNITE_ACCOMPAGNEMENT_ANNEE	= ROUND(@NB_UNITE_ACCOMPAGNEMENT	* @NB_JOUR_AN / @NB_JOUR_TOT_MODULE, 2)
         			SET @MONTANT_ENGAGE_ANNEE			= ROUND(@MONTANT_ENGAGE				* @NB_JOUR_AN / @NB_JOUR_TOT_MODULE, 2)

         			IF @ANNEE = YEAR(@DAT_FIN)
         			BEGIN
         				SET @NB_UNITE_TOTALE_ANNEE			= ROUND(@NB_UNITE_TOTALE			- @NB_UNITE_TOTALE_CUMUL, 2)
         				SET @NB_UNITE_EVALUATION_ANNEE		= ROUND(@NB_UNITE_EVALUATION		- @NB_UNITE_EVALUATION_CUMUL, 2)
         				SET @NB_UNITE_ACCOMPAGNEMENT_ANNEE	= ROUND(@NB_UNITE_ACCOMPAGNEMENT	- @NB_UNITE_ACCOMPAGNEMENT_CUMUL, 2)
         				SET @MONTANT_ENGAGE_ANNEE			= ROUND(@MONTANT_ENGAGE			- @MONTANT_ENGAGE_CUMUL, 2)
         			END

         			SET @NB_UNITE_TOTALE_CUMUL			= @NB_UNITE_TOTALE_CUMUL			+ @NB_UNITE_TOTALE_ANNEE
         			SET @NB_UNITE_EVALUATION_CUMUL		= @NB_UNITE_EVALUATION_CUMUL		+ @NB_UNITE_EVALUATION_ANNEE		
         			SET @NB_UNITE_ACCOMPAGNEMENT_CUMUL	= @NB_UNITE_ACCOMPAGNEMENT_CUMUL	+ @NB_UNITE_ACCOMPAGNEMENT_ANNEE
         			SET @MONTANT_ENGAGE_CUMUL			= @MONTANT_ENGAGE_CUMUL				+ @MONTANT_ENGAGE_ANNEE

         			INSERT INTO ENGAGEMENT_MODULE_CPTA_PRO_PERIODE
         			(
         				ID_ENGAGEMENT_MODULE_CPTA_PRO, ID_PERIODE,	
         				NB_UNITE_TOTALE, NB_UNITE_ACCOMPAGNEMENT, NB_UNITE_EVALUATION, MONTANT_ENGAGE,
         				BLN_ACTIF, DAT_CREATION
         			)
         			VALUES
         			(
         				@ID_ENGAGEMENT_MODULE_CPTA_PRO, @ID_PERIODE,	
         				@NB_UNITE_TOTALE_ANNEE, @NB_UNITE_ACCOMPAGNEMENT_ANNEE, @NB_UNITE_EVALUATION_ANNEE, @MONTANT_ENGAGE_ANNEE,
         				@BLN_ACTIF, @DAT_CREATION
         			)
         		END

         		SET @ANNEE  = @ANNEE +1
         	END

         END
GO
CREATE PROCEDURE INIT_PARAMETRAGE_ANNUEL_2015

         AS
         BEGIN

          print '2015 - INIT - param‚trage annuel.sql'
          declare @num_annee int, @id_periode int
          set @num_annee = 2015

          declare @num_annee_precedente int
          set @num_annee_precedente = @num_annee-1

          select @id_periode = id_periode from PERIODE where NUM_ANNEE = @num_annee and ID_TYPE_PERIODE  =1

          if not exists (select 1 from PERIODE_BRANCHE where id_periode = @id_periode)
          insert into periode_branche
          (ID_PERIODE, ID_BRANCHE, PRC_MUTUALISATION_VERSEMENT_RELIQUAT)
          select @id_periode, id_branche, PRC_MUTUALISATION_VERSEMENT_RELIQUAT
          from PERIODE_BRANCHE t1
          join PERIODE t2
          on  t1.id_periode = t2.id_periode
          where t2.NUM_ANNEE = @num_annee_precedente

          EXEC CREATION_NOUVELLE_ANNEE @num_annee, 'N'

          EXEC MAJ_ASSUJETIS_ANNEE @num_annee_precedente, @num_annee

          EXEC MAJ_EFFECTIF_ANNEE @num_annee

          EXEC MAJ_ENVELOPPES 2014
          EXEC MAJ_ENVELOPPES 2013
          EXEC MAJ_ENVELOPPES 2012

          EXEC MAJ_OPERATIONS_FINANCIERES @num_annee

          declare @id_option int

          select @id_periode = id_periode
          from periode 
          where id_type_periode = 1
          and  num_annee = @num_annee

          select @id_option = id_option
          from options
          where cod_option = 'NON'

          insert into r20bis
          (ID_GROUPE, ID_PERIODE, ID_OPTION, PRC_OPTION, PRC_FRAIS_GESTION)
          select distinct t1.id_groupe, @id_periode, @id_option, 0, 0
          from etablissement t1
          join groupe t2
          on  t1.id_groupe = t2.id_groupe
          where t1.bln_actif = 1
          and  t2.bln_actif = 1
          and  not exists (select 1 from r20bis where id_groupe = t1.id_groupe and id_periode = @id_periode)

          declare @objet varchar(100), @commande_sql varchar(2000), @res int

          declare recompile_curseur cursor for
          SELECT distinct object_name(object_id)
          FROM sys.sql_dependencies 
          WHERE referenced_major_id in (OBJECT_ID('OPERATION_FINANCIERE'), OBJECT_ID('PARAMETRE_GLOBAL'), OBJECT_ID('PARAMETRE_APPEL'), OBJECT_ID('R20'), OBJECT_ID('ENVELOPPE'))
          AND  object_name(object_id) not like 'INS%'
          AND  object_name(object_id) not like 'UPD%'

          open recompile_curseur
          fetch next from recompile_curseur into @objet
          while @@fetch_status = 0
          BEGIN
           set @commande_sql = 'sp_recompile ' + @objet
           EXEC (@commande_sql)
           if @res <> 0 print 'echec recompilation ' + @objet
           fetch next from recompile_curseur into @objet
          END

          close recompile_curseur
          deallocate recompile_curseur

          TRUNCATE TABLE [PARAMETRE_EXERCICE_MODULE]
          INSERT INTO [PARAMETRE_EXERCICE_MODULE]
               ([DAT_DEBUT]
               ,[DAT_FIN]
               ,[NUM_VALEUR])
            VALUES
               ('20150101'
               ,'20150125'    
               ,'-1')

          declare @id_periode_smic int

          update PERIODE 
          set  BLN_EN_COURS = 0,
            DAT_DEB_PERIODE = CONVERT(datetime, '01-06-2014 00:00:00'),
            DAT_FIN_PERIODE = CONVERT(datetime, '31-12-2014 23:59:59')
          where ID_TYPE_PERIODE = 4
          and  NUM_ANNEE = 2014

          if not exists (select 1 from periode where id_type_periode = 4 and NUM_ANNEE = 2015)
          BEGIN
           insert into periode
           (ID_TYPE_PERIODE, COD_PERIODE, NUM_ANNEE, DAT_DEB_PERIODE, DAT_FIN_PERIODE, BLN_ACTIF, BLN_EN_COURS, DAT_CREATION, ID_UTILISATEUR, BLN_PRIORITAIRE)
           SELECT
           ID_TYPE_PERIODE  = 4, 
           COD_PERIODE   = '2015', 
           NUM_ANNEE   = 2015, 
           DAT_DEB_PERIODE  = CONVERT(datetime, '01-01-2015 00:00:00'), 
           DAT_FIN_PERIODE  = CONVERT(datetime, '31-12-9999 00:00:00'), 
           BLN_ACTIF   = 1, 
           BLN_EN_COURS  = 1, 
           DAT_CREATION  = getdate(),
           ID_UTILISATEUR  = 82,
           BLN_PRIORITAIRE  = 1 

          END

           select @id_periode_smic = id_periode
           from PERIODE
           where ID_TYPE_PERIODE = 4
           and  NUM_ANNEE  = 2015
           AND  BLN_EN_COURS = 1

          if (@id_periode_smic IS NOT NULL) AND (not exists (select 1 from tau_smic where id_periode = @id_periode_smic))
          BEGIN
           insert into TAU_SMIC
           (ID_PERIODE, MNT_SMIC_HORAIRE_BRUT)
           values
           (@id_periode_smic, 9.61)
          END

          update PERIODE
          set  BLN_FINANCEMENT_DISPO = 1
          where ID_TYPE_PERIODE = 1
          and  NUM_ANNEE = @num_annee

          EXEC MAJ_CALENDRIER 2015

          update PERIODE
          set  DAT_CONSTITUTION_POT_MUT= CONVERT(DATETIME, '01/07/'+ CAST(NUM_ANNEE+1 AS VARCHAR), 103)
          where ID_TYPE_PERIODE = 1
          and  NUM_ANNEE >= 2014

         END
GO
CREATE PROCEDURE MAJ_CALENDRIER    
          @ANNEE INT    
         AS     
         BEGIN    
          IF EXISTS (SELECT DISTINCT 1 FROM CALENDRIER WHERE ANNEE = @ANNEE)    
          BEGIN    
           SELECT 'Ann‚e ' + CAST(@ANNEE AS VARCHAR) + ' d‚j… initialis‚e.'    
           RETURN    
          END    

          DECLARE     
           @TEMPS_DATE DATETIME,    
           @TEMPS_FIN DATETIME,    
           @CANNEE VARCHAR(4),    
           @JOUR_OUVRE_BANQ BIT,    
           @TEMPS_JOURDESEMAINE TINYINT,    
           @TEMPS_ANNEE SMALLINT,    
           @TEMPS_MOIS SMALLINT,    
           @TEMPS_JOUR SMALLINT,    
           @TEMPS_FERIE VARCHAR(20)    

          SET DATEFIRST 1    

          SET DATEFORMAT ymd    SET @CANNEE = CAST(@ANNEE AS VARCHAR)   
          SET @TEMPS_DATE = @CANNEE + '0101'     
          SET @TEMPS_FIN = @CANNEE + '1231'    

          WHILE @TEMPS_DATE <= @TEMPS_FIN    
          BEGIN    
           BEGIN TRANSACTION    

           SET @TEMPS_ANNEE = YEAR(@TEMPS_DATE)    
           SET @TEMPS_MOIS = MONTH(@TEMPS_DATE)    
           SET @TEMPS_JOUR = DAY(@TEMPS_DATE)    
           SET @TEMPS_JOURDESEMAINE = datepart(weekday,@TEMPS_DATE)    

           IF @TEMPS_JOURDESEMAINE IN (6,7)    
            SET @JOUR_OUVRE_BANQ = 0    
           ELSE    
            SET @JOUR_OUVRE_BANQ = 1    

           IF @JOUR_OUVRE_BANQ = 1    
            IF (@TEMPS_JOUR = 1 AND @TEMPS_MOIS = 1 ) 
            OR (@TEMPS_JOUR = 25 AND @TEMPS_MOIS = 3 ) 
            OR (@TEMPS_JOUR = 28 AND @TEMPS_MOIS = 3 ) 
            OR (@TEMPS_JOUR = 1 AND @TEMPS_MOIS = 5 ) 
            OR (@TEMPS_JOUR = 25 AND @TEMPS_MOIS = 12) 
            OR (@TEMPS_JOUR = 26 AND @TEMPS_MOIS = 12) 
            SET @JOUR_OUVRE_BANQ = 0       

           INSERT INTO CALENDRIER    
           (    
            DATE_J,    
            ANNEE,    
            MOIS,    
            JOURS,    
            OUVRE_BANQ    
           )    
           VALUES    
           (    
            @TEMPS_DATE,    
            @TEMPS_ANNEE,    
            @TEMPS_MOIS,    
            @TEMPS_JOUR,    
            @JOUR_OUVRE_BANQ    
           )    

           SET @TEMPS_DATE = @TEMPS_DATE + 1    

           COMMIT TRANSACTION     
          END    
         END
GO

         CREATE PROCEDURE [dbo].MAJ_OPERATIONS_FINANCIERES
          @ANNEE INT  
         AS  

         BEGIN  
          DECLARE  
           @ANNEE_ID_PERIODE INT,  
           @ANNEE_TEXTE  VARCHAR(4)  

          SELECT  
           @ANNEE_ID_PERIODE = ID_PERIODE  
          FROM  
           PERIODE  
          WHERE  
           ID_TYPE_PERIODE = 1  
           AND NUM_ANNEE = @ANNEE  

          SELECT  
           @ANNEE_TEXTE = convert(varchar(4), @ANNEE)  

          DELETE  
           T1  
          FROM  
           PLAN_FINANCEMENT_OPERATION T1  
           INNER JOIN OPERATION_FINANCIERE T2  
            ON T1.ID_OPERATION_FINANCIERE = T2.ID_OPERATION_FINANCIERE  
          WHERE  
           T2.ID_PERIODE = @ANNEE_ID_PERIODE  

          DELETE  
           T1  
          FROM  
           NR152 T1  
           INNER JOIN OPERATION_FINANCIERE T2  
            ON T1.ID_OPERATION_FINANCIERE = T2.ID_OPERATION_FINANCIERE  
          WHERE  
           T2.ID_PERIODE = @ANNEE_ID_PERIODE  

          UPDATE  
           ACTION_PEC  
          SET  
           ID_OPERATION_FINANCIERE = NULL  
          WHERE  
           ID_OPERATION_FINANCIERE IN  
           (  
            SELECT  
             ID_OPERATION_FINANCIERE  
            FROM  
             OPERATION_FINANCIERE  
            WHERE  
             ID_PERIODE = @ANNEE_ID_PERIODE  
           )  

          DELETE  
          FROM  
           OPERATION_FINANCIERE  
          WHERE  
           ID_PERIODE = @ANNEE_ID_PERIODE  

          INSERT INTO OPERATION_FINANCIERE  
          (  
           COD_OPERATION_FINANCIERE,  
           LIBC_OPERATION_FINANCIERE,  
           LIBL_OPERATION_FINANCIERE,  
           DAT_DEBUT,  
           DAT_FIN,  
           DAT_CREATION,  
           BLN_DEFAUT,  
           BLN_ACTIF,  
           DAT_MODIF,  
           ID_PERIODE,  
           ID_AGENCE,  
           ID_BRANCHE,  
           ID_DISPOSITIF,  
           ID_UTILISATEUR,  
           COM_MODE_FINANCEMENT  
          )  
          SELECT  
           'x',  
           BRANCHE.PREFIXE_EDI + SUBSTRING(@ANNEE_TEXTE, 3, 2) + DISPOSITIF.COD_DISPOSITIF + ' ' + AGENCE.COD_AGENCE,  
           BRANCHE.PREFIXE_EDI + SUBSTRING(@ANNEE_TEXTE, 3, 2) + DISPOSITIF.COD_DISPOSITIF + ' ' + AGENCE.COD_AGENCE,  
           '01/01/' + @ANNEE_TEXTE + ' 00:00:00',  
           '31/12/' + @ANNEE_TEXTE + ' 00:00:00',  
           getdate(),  
           BLN_DEFAUT = CASE WHEN DISPOSITIF.COD_DISPOSITIF = 'CSP' THEN 0 ELSE 1 END,  
           1,  
           getdate(),  
           @ANNEE_ID_PERIODE,  
           AGENCE.ID_AGENCE,  
           BRANCHE.ID_BRANCHE,  
           DISPOSITIF.ID_DISPOSITIF,  
           82,  
           NULL  
          FROM  
           AGENCE  
           CROSS JOIN BRANCHE  
           CROSS JOIN DISPOSITIF  
          WHERE  
           AGENCE.BLN_ACTIF = 1  
           AND BRANCHE.BLN_ACTIF = 1  
           AND DISPOSITIF.BLN_ACTIF = 1  
           AND not exists  
            (  
             SELECT  
              1  
             FROM  
              OPERATION_FINANCIERE  
             WHERE  
              ID_PERIODE = @ANNEE_ID_PERIODE  
              AND ID_AGENCE = AGENCE.ID_AGENCE  
              AND ID_BRANCHE = BRANCHE.ID_BRANCHE  
              AND ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF  
            )  
           AND DISPOSITIF.COD_DISPOSITIF NOT IN  
           (  
            'POE', 

            'DIFPRIO', 'DIFNONP', 'DIFPORT', 'PLPPDIF', 'P50+'  
           )  

          INSERT INTO NR152  
          (  
           ID_OPERATION_FINANCIERE,  
           ID_TYPE_FINANCEMENT,  
           ID_ENVELOPPE  
          )  

          SELECT  
           OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE,  
           TYPE_FINANCEMENT.ID_TYPE_FINANCEMENT,  
           NULL  
          FROM  
           OPERATION_FINANCIERE  
           INNER JOIN DISPOSITIF  
            ON OPERATION_FINANCIERE.ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF  
           INNER JOIN BRANCHE  
            ON OPERATION_FINANCIERE.ID_BRANCHE  = BRANCHE.ID_BRANCHE  
           CROSS JOIN TYPE_FINANCEMENT  
          WHERE  
           DISPOSITIF.COD_DISPOSITIF in ('P10-49', 'P50-299', 'P300+')  
           AND OPERATION_FINANCIERE.BLN_ACTIF = 1  
           AND OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
           AND 
           (  
            TYPE_FINANCEMENT.COD_TYPE_FINANCEMENT IN (3, 4)  
           )  
           AND NOT EXISTS  
           (  
            SELECT  
             1  
            FROM  
             NR152  
            WHERE  
             ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
             AND  ID_TYPE_FINANCEMENT = TYPE_FINANCEMENT.ID_TYPE_FINANCEMENT  
             AND  ID_ENVELOPPE IS NULL  
           )  

          INSERT INTO PLAN_FINANCEMENT_OPERATION  
          (  
           ID_OPERATION_FINANCIERE,  
           ID_SOUS_TYPE_COUT,  
           ID_ENVELOPPE,  
           ID_TYPE_FINANCEMENT,  
           BLN_FINANCE,  
           ID_ACTIVITE  
          )  
          SELECT   
           ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE,  
           ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT,  
           ID_ENVELOPPE = NULL,  
           ID_TYPE_FINANCEMENT = NR152.ID_TYPE_FINANCEMENT,  
           1,  
           ID_ACTIVITE = CASE  
            WHEN  ID_TYPE_FINANCEMENT = 4  
             THEN ACTIVITE.ID_ACTIVITE  
            WHEN  ID_TYPE_FINANCEMENT = 3  
             THEN (SELECT ID_ACTIVITE FROM ACTIVITE WHERE COD_ACTIVITE = 'VOL')  
           END  
          FROM  
           OPERATION_FINANCIERE  
           INNER JOIN DISPOSITIF  
            ON OPERATION_FINANCIERE .ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF   
           INNER JOIN ACTIVITE  
            ON ACTIVITE.ID_ACTIVITE = DISPOSITIF.ID_ACTIVITE  
           INNER JOIN NR152  
            ON OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE = NR152.ID_OPERATION_FINANCIERE  
           CROSS JOIN SOUS_TYPE_COUT  
          WHERE  
           SOUS_TYPE_COUT.BLN_ACTIF = 1  
           AND  DISPOSITIF .COD_DISPOSITIF in ('P10-49', 'P50-299', 'P300+')  
           AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
           AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
           AND  
           (  
            (  

             NR152.ID_TYPE_FINANCEMENT IN (3)  
             AND SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT NOT IN ('FFRECONV')  
            )  
            OR  
            (  

             NR152.ID_TYPE_FINANCEMENT IN (4)  
             AND SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT IN ('CP', 'INGE', 'ACTEVAL', 'FCT')  
             AND DISPOSITIF .COD_DISPOSITIF IN ('P10-49', 'P50-299')  
            )  
           )  
           AND  NOT EXISTS  
            (  
             SELECT  
              1  
             FROM  
              PLAN_FINANCEMENT_OPERATION  
             WHERE  
              ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
              AND  ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
              AND  ID_ENVELOPPE IS NULL  
              AND  ID_TYPE_FINANCEMENT = NR152.ID_TYPE_FINANCEMENT  
              AND  ID_ACTIVITE = ACTIVITE.ID_ACTIVITE  
            )  

          INSERT INTO NR152  
          ([ID_OPERATION_FINANCIERE]  
          ,[ID_TYPE_FINANCEMENT]  
          ,[ID_ENVELOPPE])  

          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,TYPE_FINANCEMENT.ID_TYPE_FINANCEMENT  
          ,NULL  
          FROM OPERATION_FINANCIERE   
          INNER JOIN DISPOSITIF ON OPERATION_FINANCIERE .ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF   
          INNER JOIN BRANCHE  ON OPERATION_FINANCIERE .ID_BRANCHE  = BRANCHE.ID_BRANCHE   
          CROSS JOIN  TYPE_FINANCEMENT  
          WHERE DISPOSITIF .COD_DISPOSITIF in ('P-10')  
          AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND 

          (  
          TYPE_FINANCEMENT.COD_TYPE_FINANCEMENT IN (3, 4)  
          )  
          AND  not exists   
          (  
          select 1  
          from NR152   
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_TYPE_FINANCEMENT = TYPE_FINANCEMENT.ID_TYPE_FINANCEMENT  
          and  ID_ENVELOPPE is null  
          )  

          INSERT INTO PLAN_FINANCEMENT_OPERATION  
          ([ID_OPERATION_FINANCIERE]  
          ,[ID_SOUS_TYPE_COUT]  
          ,[ID_ENVELOPPE]  
          ,[ID_TYPE_FINANCEMENT]  
          ,[BLN_FINANCE]  
          ,[ID_ACTIVITE])  
          SELECT   
          ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          ,ID_ENVELOPPE = NULL  
          ,ID_TYPE_FINANCEMENT = NR152.ID_TYPE_FINANCEMENT  
          ,1  
          ,ID_ACTIVITE=  
          CASE WHEN ID_TYPE_FINANCEMENT = 4 THEN ACTIVITE.ID_ACTIVITE  
          WHEN ID_TYPE_FINANCEMENT = 3 THEN (SELECT ID_ACTIVITE FROM ACTIVITE WHERE COD_ACTIVITE = 'VOL')  
          END  
          FROM OPERATION_FINANCIERE  
          INNER JOIN DISPOSITIF ON OPERATION_FINANCIERE .ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF   
          INNER JOIN ACTIVITE ON ACTIVITE.ID_ACTIVITE = DISPOSITIF.ID_ACTIVITE  
          INNER JOIN NR152 ON  OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE = NR152.ID_OPERATION_FINANCIERE  
          CROSS JOIN  
          SOUS_TYPE_COUT  
          WHERE SOUS_TYPE_COUT.BLN_ACTIF = 1  
          AND  DISPOSITIF .COD_DISPOSITIF in ('P-10')  
          AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND (  
          (  

          NR152.ID_TYPE_FINANCEMENT IN (4)  
          AND  
          SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT in ('CP', 'INGE', 'ACTEVAL', 'FCT', 'REM')  
          )  
          OR  
          (  

          NR152.ID_TYPE_FINANCEMENT IN (3)  
          AND  
          SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT NOT IN ('FFRECONV')  
          )  
          )     
          AND  not exists (select 1  
          from PLAN_FINANCEMENT_OPERATION  
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          and  ID_ENVELOPPE is null  
          and  ID_TYPE_FINANCEMENT = NR152.ID_TYPE_FINANCEMENT  
          and  ID_ACTIVITE = ACTIVITE.ID_ACTIVITE  
          )  

          INSERT INTO NR152  
          ([ID_OPERATION_FINANCIERE]  
          ,[ID_TYPE_FINANCEMENT]  
          ,[ID_ENVELOPPE])  

          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,NULL  
          ,ENVELOPPE.ID_ENVELOPPE  
          FROM OPERATION_FINANCIERE  
          INNER JOIN DISPOSITIF  ON OPERATION_FINANCIERE .ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF   
          INNER JOIN TYPE_ENVELOPPE ON  TYPE_ENVELOPPE.ID_BRANCHE = OPERATION_FINANCIERE.ID_BRANCHE  
          AND TYPE_ENVELOPPE.ID_AGENCE = OPERATION_FINANCIERE.ID_AGENCE  
          AND TYPE_ENVELOPPE.ID_DISPOSITIF = OPERATION_FINANCIERE.ID_DISPOSITIF   
          INNER JOIN ENVELOPPE  ON  ENVELOPPE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE  
          AND ENVELOPPE.ID_PERIODE = OPERATION_FINANCIERE.ID_PERIODE  
          AND ENVELOPPE.BLN_ACTIF = 1  
          WHERE DISPOSITIF.COD_DISPOSITIF = 'CONTPRO' 
          AND  TYPE_ENVELOPPE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND  not exists (select 1   
          from NR152   
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_TYPE_FINANCEMENT is null  
          and  ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE  
          )  

          INSERT INTO PLAN_FINANCEMENT_OPERATION  
          (  
          [ID_OPERATION_FINANCIERE]  
          ,[ID_SOUS_TYPE_COUT]  
          ,[ID_ENVELOPPE]  
          ,[ID_TYPE_FINANCEMENT]  
          ,[BLN_FINANCE]  
          ,[ID_ACTIVITE]  
          )  

          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          ,NR152.ID_ENVELOPPE  
          ,NULL  
          ,1  
          ,NULL  
          FROM OPERATION_FINANCIERE  
          INNER JOIN NR152 ON  OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE = NR152.ID_OPERATION_FINANCIERE  
          INNER JOIN ENVELOPPE ON  NR152.ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE  
          INNER JOIN TYPE_ENVELOPPE ON  TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE = ENVELOPPE.ID_TYPE_ENVELOPPE  
          INNER JOIN DISPOSITIF ON  TYPE_ENVELOPPE.ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF  
          CROSS JOIN SOUS_TYPE_COUT  
          WHERE SOUS_TYPE_COUT.BLN_ACTIF = 1  
          AND  NR152.ID_ENVELOPPE IS NOT NULL  
          AND  DISPOSITIF.COD_DISPOSITIF = 'CONTPRO' 
          AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND  SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT IN ('CP')  
