           DAT_MODIF					= getdate(),  
           ID_PERIODE				= @ANNEE_ID_PERIODE,  
           ID_AGENCE					= AGENCE.ID_AGENCE,  
           ID_BRANCHE				= BRANCHE.ID_BRANCHE,  
           ID_DISPOSITIF				= DISPOSITIF.ID_DISPOSITIF,  
           82,  
           NULL  
          FROM  
           AGENCE  
           CROSS JOIN BRANCHE  
           CROSS JOIN DISPOSITIF  
          WHERE  
           AGENCE.BLN_ACTIF = 1  
           AND BRANCHE.BLN_ACTIF = 1  
           AND DISPOSITIF.BLN_ACTIF = 1  
           AND not exists  
            (  
             SELECT  
              1  
             FROM  
              OPERATION_FINANCIERE  
             WHERE  
              ID_PERIODE = @ANNEE_ID_PERIODE  
              AND ID_AGENCE = AGENCE.ID_AGENCE  
              AND ID_BRANCHE = BRANCHE.ID_BRANCHE  
              AND ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF  
              AND LIBC_OPERATION_FINANCIERE LIKE '%' + DISPOSITIF.COD_DISPOSITIF + ' CO %'
            )  
           AND DISPOSITIF.COD_DISPOSITIF IN  
           (  
            'POE'
           )  

         INSERT INTO OPERATION_FINANCIERE  
          (  
           COD_OPERATION_FINANCIERE,  
           LIBC_OPERATION_FINANCIERE,  
           LIBL_OPERATION_FINANCIERE,  
           DAT_DEBUT,  
           DAT_FIN,  
           DAT_CREATION,  
           BLN_DEFAUT,  
           BLN_ACTIF,  
           DAT_MODIF,  
           ID_PERIODE,  
           ID_AGENCE,  
           ID_BRANCHE,  
           ID_DISPOSITIF,  
           ID_UTILISATEUR,  
           COM_MODE_FINANCEMENT  
          )  
          SELECT  
           COD_OPERATION_FINANCIERE	= 'x',  
           LIBC_OPERATION_FINANCIERE = BRANCHE.PREFIXE_EDI + SUBSTRING(@ANNEE_TEXTE, 3, 2) + DISPOSITIF.COD_DISPOSITIF + ' CO ' + AGENCE.COD_AGENCE,  
           LIBL_OPERATION_FINANCIERE = BRANCHE.PREFIXE_EDI + SUBSTRING(@ANNEE_TEXTE, 3, 2) + DISPOSITIF.COD_DISPOSITIF + ' CO ' + AGENCE.COD_AGENCE,  
           DAT_DEBUT					= '01/01/' + @ANNEE_TEXTE + ' 00:00:00',  
           DAT_FIN					= '31/12/' + @ANNEE_TEXTE + ' 00:00:00',  
           DAT_CREATION				= getdate(),  
           BLN_DEFAUT				= 0 ,  
           BLN_ACTIF					= 1,  
           DAT_MODIF					= getdate(),  
           ID_PERIODE				= @ANNEE_ID_PERIODE,  
           ID_AGENCE					= AGENCE.ID_AGENCE,  
           ID_BRANCHE				= BRANCHE.ID_BRANCHE,  
           ID_DISPOSITIF				= DISPOSITIF.ID_DISPOSITIF,  
           82,  
           NULL  
          FROM  
           AGENCE  
           CROSS JOIN BRANCHE  
           CROSS JOIN DISPOSITIF  
          WHERE  
           AGENCE.BLN_ACTIF = 1  
           AND BRANCHE.BLN_ACTIF = 1  
           AND DISPOSITIF.BLN_ACTIF = 1  
           AND not exists  
            (  
             SELECT  
              1  
             FROM  
              OPERATION_FINANCIERE  
             WHERE  
              ID_PERIODE = @ANNEE_ID_PERIODE  
              AND ID_AGENCE = AGENCE.ID_AGENCE  
              AND ID_BRANCHE = BRANCHE.ID_BRANCHE  
              AND ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF  
              AND LIBC_OPERATION_FINANCIERE LIKE '%'+DISPOSITIF.COD_DISPOSITIF + ' CO %'
            )  
           AND DISPOSITIF.COD_DISPOSITIF IN  
           (  
            'POE'
           )    

          INSERT INTO NR152  
          ([ID_OPERATION_FINANCIERE]  
          ,[ID_TYPE_FINANCEMENT]  
          ,[ID_ENVELOPPE])  

          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,NULL  
          ,ENVELOPPE.ID_ENVELOPPE  
          FROM OPERATION_FINANCIERE  
          INNER JOIN TYPE_ENVELOPPE ON  TYPE_ENVELOPPE.ID_AGENCE = OPERATION_FINANCIERE.ID_AGENCE  
          INNER JOIN DISPOSITIF ON TYPE_ENVELOPPE.ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF   
          INNER JOIN   ENVELOPPE ON  ENVELOPPE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE  
          AND  ENVELOPPE.ID_PERIODE = OPERATION_FINANCIERE.ID_PERIODE  
          AND  ENVELOPPE.BLN_ACTIF = 1  
          WHERE DISPOSITIF.COD_DISPOSITIF IN ('POE')  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND OPERATION_FINANCIERE.ID_BRANCHE = TYPE_ENVELOPPE.ID_BRANCHE
          AND OPERATION_FINANCIERE.ID_DISPOSITIF = TYPE_ENVELOPPE.ID_DISPOSITIF
           AND  not exists (select 1   
          from NR152   
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_TYPE_FINANCEMENT is null  
          and  ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE  
          )  

          INSERT INTO PLAN_FINANCEMENT_OPERATION  
          ([ID_OPERATION_FINANCIERE]  
          ,[ID_SOUS_TYPE_COUT]  
          ,[ID_ENVELOPPE]  
          ,[ID_TYPE_FINANCEMENT]  
          ,[BLN_FINANCE]  
          ,[ID_ACTIVITE])  

          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          ,NR152.ID_ENVELOPPE  
          ,NULL  
          ,1  
          ,NULL  
          FROM OPERATION_FINANCIERE  
          INNER JOIN NR152 ON  OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE = NR152.ID_OPERATION_FINANCIERE  
          INNER JOIN ENVELOPPE ON  NR152.ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE  
          INNER JOIN TYPE_ENVELOPPE ON  TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE = ENVELOPPE.ID_TYPE_ENVELOPPE  
          INNER JOIN DISPOSITIF ON  TYPE_ENVELOPPE.ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF  
          CROSS JOIN    SOUS_TYPE_COUT  
          WHERE DISPOSITIF.COD_DISPOSITIF IN ('POE')  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND  SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT IN ('CP')  
          AND  not exists (select 1  
          from PLAN_FINANCEMENT_OPERATION  
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          and  ID_ENVELOPPE = NR152.ID_ENVELOPPE  
          and  ID_TYPE_FINANCEMENT is null  
          )  

          INSERT INTO [dbo].[OPERATION_FINANCIERE]  
          ([COD_OPERATION_FINANCIERE]  
          ,[LIBC_OPERATION_FINANCIERE]  
          ,[LIBL_OPERATION_FINANCIERE]  
          ,[DAT_DEBUT]  
          ,[DAT_FIN]  
          ,[DAT_CREATION]  
          ,[BLN_DEFAUT]  
          ,[BLN_ACTIF]  
          ,[DAT_MODIF]  
          ,[ID_PERIODE]  
          ,[ID_AGENCE]  
          ,[ID_BRANCHE]  
          ,[ID_DISPOSITIF]  
          ,[ID_UTILISATEUR]  
          ,[COM_MODE_FINANCEMENT])  
          SELECT  
          'x'  
          ,'MULTI BR-DISPO' + SUBSTRING(@ANNEE_TEXTE, 3, 2) + ' ' + LEFT(AGENCE.COD_AGENCE  , 2)
          ,'MULTIBR MULTI DISPO ' + SUBSTRING(@ANNEE_TEXTE, 3, 2) + ' ' + AGENCE.COD_AGENCE  
          ,'01/01/' + @ANNEE_TEXTE + ' 00:00:00'  
          ,'31/12/' + @ANNEE_TEXTE + ' 00:00:00'  
          ,getdate()  
          ,0  
          ,1  
          ,getdate()  
          ,@ANNEE_ID_PERIODE  
          ,AGENCE.ID_AGENCE  
          ,ID_BRANCHE=NULL  
          ,ID_DISPOSITIF=NULL  
          ,82  
          ,NULL  
          FROM AGENCE  
          WHERE AGENCE.BLN_ACTIF = 1  
          AND  not exists (select 1   
          from [OPERATION_FINANCIERE]   
          where [LIBL_OPERATION_FINANCIERE] like 'MULTIBR MULTI DISPO ' + SUBSTRING(@ANNEE_TEXTE, 3, 2) + ' ' + AGENCE.COD_AGENCE  
          )  

          INSERT INTO NR152  
          ([ID_OPERATION_FINANCIERE]  
          ,[ID_TYPE_FINANCEMENT]  
          ,[ID_ENVELOPPE])  

          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,NULL  
          ,ENVELOPPE.ID_ENVELOPPE  
          FROM OPERATION_FINANCIERE  
          INNER JOIN TYPE_ENVELOPPE ON  TYPE_ENVELOPPE.ID_AGENCE = OPERATION_FINANCIERE.ID_AGENCE  
          INNER JOIN DISPOSITIF ON TYPE_ENVELOPPE.ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF   
          INNER JOIN   ENVELOPPE ON  ENVELOPPE.ID_TYPE_ENVELOPPE = TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE  
          AND  ENVELOPPE.ID_PERIODE = OPERATION_FINANCIERE.ID_PERIODE  
          AND  ENVELOPPE.BLN_ACTIF = 1  
          WHERE [LIBL_OPERATION_FINANCIERE] like 'MULTIBR MULTI DISPO ' + SUBSTRING(@ANNEE_TEXTE, 3, 2)+'%'  
          AND  TYPE_ENVELOPPE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND DISPOSITIF.COD_DISPOSITIF IN ('PPPRIO', 'FORMTUT', 'FONCTUT', 'CPF')  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND  not exists (select 1   
          from NR152   
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_TYPE_FINANCEMENT is null  
          and  ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE  
          )  
          UNION  

          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,TYPE_FINANCEMENT.ID_TYPE_FINANCEMENT  
          ,NULL  
          FROM OPERATION_FINANCIERE  
          CROSS JOIN TYPE_FINANCEMENT  
          WHERE [LIBL_OPERATION_FINANCIERE] like 'MULTIBR MULTI DISPO ' + SUBSTRING(@ANNEE_TEXTE, 3, 2)+'%'  
          AND OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND 
          (  
          TYPE_FINANCEMENT.COD_TYPE_FINANCEMENT IN (3, 4)  
          )  
          AND  not exists (select 1   
          from NR152   
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_TYPE_FINANCEMENT = TYPE_FINANCEMENT.ID_TYPE_FINANCEMENT  
          and  ID_ENVELOPPE is null  
          )  

          INSERT INTO PLAN_FINANCEMENT_OPERATION  
          ([ID_OPERATION_FINANCIERE]  
          ,[ID_SOUS_TYPE_COUT]  
          ,[ID_ENVELOPPE]  
          ,[ID_TYPE_FINANCEMENT]  
          ,[BLN_FINANCE]  
          ,[ID_ACTIVITE])  

          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          ,NULL  
          ,NR152.ID_TYPE_FINANCEMENT     
          ,1  
          ,ACTIVITE.ID_ACTIVITE  
          FROM OPERATION_FINANCIERE  
          INNER JOIN NR152 ON  OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE = NR152.ID_OPERATION_FINANCIERE   CROSS JOIN   SOUS_TYPE_COUT  
          CROSS JOIN   ACTIVITE   
          WHERE   
          [LIBL_OPERATION_FINANCIERE] like 'MULTIBR MULTI DISPO ' + SUBSTRING(@ANNEE_TEXTE, 3, 2)+'%'  
          AND  SOUS_TYPE_COUT.BLN_ACTIF = 1  
          AND  ACTIVITE.COD_ACTIVITE in ('-10', '10-49', '50-299', 'VOL')   
          AND  NR152.ID_TYPE_FINANCEMENT IS NOT NULL  
          AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND (  
         	 (  

         	 NR152.ID_TYPE_FINANCEMENT IN (3)  
         	 AND  
         	 ACTIVITE.COD_ACTIVITE in ('VOL')   
         	 AND  
         	 SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT NOT IN ('FFRECONV')  
         	 )  
         	 OR  
         	 (  

         	 NR152.ID_TYPE_FINANCEMENT IN  (4)  
         	 AND  
         	 ACTIVITE.COD_ACTIVITE in ('10-49', '50-299')   
         	 AND  
         	 SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT IN ('CP')  
         	 )  
         	 OR  
         	 (  

         	 NR152.ID_TYPE_FINANCEMENT IN  (4)  
         	 AND  
         	 ACTIVITE.COD_ACTIVITE in ('-10')   
         	 AND  
         	 SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT IN ('CP', 'REM')  
         	 )  
          )   
          AND  not exists (select 1  
          from PLAN_FINANCEMENT_OPERATION  
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          and  ID_ENVELOPPE is null  
          and  ID_TYPE_FINANCEMENT = NR152.ID_TYPE_FINANCEMENT  
          and  ID_ACTIVITE = ACTIVITE.ID_ACTIVITE  
          )  
          UNION  

          SELECT OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          ,SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          ,NR152.ID_ENVELOPPE  
          ,NULL  
          ,1  
          ,NULL  
          FROM OPERATION_FINANCIERE  
          INNER JOIN NR152 ON  OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE = NR152.ID_OPERATION_FINANCIERE  
          INNER JOIN ENVELOPPE ON  NR152.ID_ENVELOPPE = ENVELOPPE.ID_ENVELOPPE  
          INNER JOIN TYPE_ENVELOPPE ON  TYPE_ENVELOPPE.ID_TYPE_ENVELOPPE = ENVELOPPE.ID_TYPE_ENVELOPPE  
          INNER JOIN DISPOSITIF ON  TYPE_ENVELOPPE.ID_DISPOSITIF = DISPOSITIF.ID_DISPOSITIF  
          CROSS JOIN    SOUS_TYPE_COUT  
          WHERE  [LIBL_OPERATION_FINANCIERE] like 'MULTIBR MULTI DISPO ' + SUBSTRING(@ANNEE_TEXTE, 3, 2)+'%'  
          AND  SOUS_TYPE_COUT.BLN_ACTIF = 1  
          AND  NR152.ID_ENVELOPPE IS NOT NULL  
          AND  OPERATION_FINANCIERE.BLN_ACTIF = 1  
          AND  OPERATION_FINANCIERE.ID_PERIODE = @ANNEE_ID_PERIODE  
          AND   
          (   
          (  
          DISPOSITIF.COD_DISPOSITIF IN ('CPF')  
          AND   
          SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT NOT IN ('AF', 'FFRECONV', 'REMFORM')  
          )  
          OR  
          (  
          DISPOSITIF.COD_DISPOSITIF IN ('PPPRIO')  
          AND   
          NOT SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT IN ('FFRECONV')  
          )  
          OR  
          (  
          DISPOSITIF.COD_DISPOSITIF IN ('FORMTUT')  
          AND   
          SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT IN ('CP', 'INGE', 'REM', 'REPHEB', 'TRANSP', 'FCT', 'FFORM', 'REMFORM')  
          )  
          OR  
          (  
          DISPOSITIF.COD_DISPOSITIF IN ('FONCTUT')  
          AND   
          SOUS_TYPE_COUT.COD_SOUS_TYPE_COUT IN ('REM', 'TRANSP')   
          )  
          )  
          AND  not exists (select 1  
          from PLAN_FINANCEMENT_OPERATION  
          where ID_OPERATION_FINANCIERE = OPERATION_FINANCIERE.ID_OPERATION_FINANCIERE  
          and  ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT  
          and  ID_ENVELOPPE = NR152.ID_ENVELOPPE  
          and  ID_TYPE_FINANCEMENT is null  
          )  

          UPDATE  
           OPERATION_FINANCIERE  
          SET  
           COD_OPERATION_FINANCIERE = ID_OPERATION_FINANCIERE  
          WHERE  
           COD_OPERATION_FINANCIERE = 'x'  

         END

GO

         CREATE PROCEDURE [dbo].[LEC_GRP_LST_DOSSIERS_FACTURE]

         @LIST_ID_FACTURE  VARCHAR(MAX)

         AS
         BEGIN

         DECLARE			@pos        int
         DECLARE         @nextpos    int
         DECLARE			@valuelen   int

         CREATE TABLE #LstFacture (ID int) 

            SET @pos = 0
            SET @nextpos = 1

            WHILE @nextpos > 0
            BEGIN
               SELECT @nextpos = charindex(',', @LIST_ID_FACTURE, @pos + 1)
               SELECT @valuelen = CASE WHEN @nextpos > 0
                                       THEN @nextpos
                                       ELSE len(@LIST_ID_FACTURE) + 1
                                  END - @pos - 1
               INSERT INTO #LstFacture (ID)
                  VALUES (convert(int, substring(@LIST_ID_FACTURE, @pos + 1, @valuelen)))
               SELECT @pos = @nextpos
            END

         SELECT 
         	FACTURE.ID_FACTURE,
         	FACTURE.NUM_FACTURE,
         	FACTURE.MNT_HT,
         	FACTURE.MNT_TTC,
         	FACTURE.DAT_EMISSION,
         	TYPE_FACTURE.COD_TYPE_FACTURE,
         	[TRANSACTION].ID_TRANSACTION AS TRANSACTION_ID_TRANSACTION,
         	SESSION_PEC.COD_SESSION_PEC AS COD_SESSION,
         	ORGANISME_FORMATION.LIB_RAISON_SOCIALE,
         	MODULE_PEC.LIBL_MODULE_PEC AS LIBL_MODULE,	

         	CONVERT(VARCHAR, SESSION_PEC.DAT_DEBUT, 103) AS DAT_DEBUT,
         	CONVERT(VARCHAR, SESSION_PEC.DAT_FIN, 103) AS DAT_FIN,
         	SOUS_TYPE_COUT.LIBL_SOUS_TYPE_COUT,	
         	ROUND(POSTE_COUT_REGLE.MNT_REGLE_HT,2) as MNT_ATTESTE_HT,
         	CONVERT(VARCHAR, POSTE_COUT_REGLE.DAT_BAP,103) AS DAT_BAP,
         	REGLEMENT.NUM_VIREMENT,
         	CONVERT(VARCHAR,REGLEMENT.DAT_VALID_REGLEMENT,103) AS DAT_VALID_REGLEMENT,

         	CASE WHEN (REGLEMENT.DAT_VALID_REGLEMENT IS NOT NULL) THEN
         		ROUND(POSTE_COUT_REGLE.MNT_REGLE_HT,2)
         	ELSE
         		0.00 
         	END
         	AS MNT_REGLE_HT,	

         	CASE WHEN (REGLEMENT.DAT_VALID_REGLEMENT IS NOT NULL) THEN
         		ROUND(POSTE_COUT_REGLE.MNT_REGLE_TTC,2)
         	ELSE
         		0.00 
         	END
         	AS MNT_REGLE_TTC,

         	[TRANSACTION].ID_ETABLISSEMENT_OF_BENEF AS TRANSACTION_ID_ETABLISSEMENT_OF_BENEF,
         	[TRANSACTION].ID_TIERS_BENEF AS TRANSACTION_ID_TIERS_BENEF,
         	[TRANSACTION].ID_ETABLISSEMENT_BENEF AS TRANSACTION_ID_ETABLISSEMENT_BENEF

         INTO #TMP_PEC
         FROM POSTE_COUT_REGLE		
         LEFT JOIN FACTURE				ON FACTURE.ID_FACTURE = POSTE_COUT_REGLE.ID_FACTURE
         LEFT JOIN SESSION_PEC			ON POSTE_COUT_REGLE.ID_SESSION_PEC = SESSION_PEC.ID_SESSION_PEC 
         LEFT JOIN MODULE_PEC			ON POSTE_COUT_REGLE.ID_MODULE_PEC =	MODULE_PEC.ID_MODULE_PEC
         LEFT JOIN ETABLISSEMENT_OF		ON MODULE_PEC.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF
         LEFT JOIN SOUS_TYPE_COUT		ON POSTE_COUT_REGLE.ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT
         LEFT JOIN REGLEMENT				ON POSTE_COUT_REGLE.ID_REGLEMENT = REGLEMENT.ID_REGLEMENT
         LEFT JOIN ADHERENT				ON FACTURE.ID_EMETTEUR_ADHERENT = ADHERENT.ID_ADHERENT
         LEFT JOIN ORGANISME_FORMATION	ON ETABLISSEMENT_OF.ID_OF = ORGANISME_FORMATION.ID_OF
         LEFT JOIN [TRANSACTION]			ON FACTURE.ID_TRANSACTION = [TRANSACTION].ID_TRANSACTION 
         LEFT JOIN TYPE_FACTURE			ON FACTURE.ID_TYPE_FACTURE = TYPE_FACTURE.ID_TYPE_FACTURE
         WHERE 
         POSTE_COUT_REGLE.BLN_ACTIF = 1 AND

         POSTE_COUT_REGLE.ID_FACTURE  IN (SELECT ID FROM #LstFacture)

         SELECT DISTINCT
         	FACTURE.ID_FACTURE,
         	FACTURE.NUM_FACTURE,
         	FACTURE.MNT_HT,
         	FACTURE.MNT_TTC,
         	FACTURE.DAT_EMISSION,
         	TYPE_FACTURE.COD_TYPE_FACTURE,
         	[TRANSACTION].ID_TRANSACTION AS TRANSACTION_ID_TRANSACTION,
         	SESSION_PRO.COD_SESSION_PRO AS COD_SESSION,
         	ORGANISME_FORMATION.LIB_RAISON_SOCIALE,
         	MODULE_PRO.LIBL_MODULE_PRO AS LIBL_MODULE,

         	CONVERT(VARCHAR, SESSION_PRO.DAT_DEBUT, 103) AS DAT_DEBUT,
         	CONVERT(VARCHAR, SESSION_PRO.DAT_FIN, 103) AS DAT_FIN,
         	'CPRO'	AS LIBL_SOUS_TYPE_COUT,

         	CASE WHEN (FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_OF) 
         	THEN
         		ROUND((SESSION_PRO.MNT_VERSE_HT_OF),2)
         	ELSE
         		ROUND((SESSION_PRO.MNT_VERSE_HT_ADH),2)
         	END
         	AS MNT_ATTESTE_HT,

         	CASE WHEN (FACTURE.ID_FACTURE =SESSION_PRO.ID_FACTURE_OF) 
         	THEN	CONVERT(VARCHAR, SESSION_PRO.DAT_BAP_OF , 103)  
         	ELSE	CONVERT(VARCHAR, SESSION_PRO.DAT_BAP_ADH , 103)   
         	END		AS	DAT_BAP,

         	CASE WHEN (FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_OF) 
         		THEN
         			(SELECT REGLEMENT_PRO.NUM_VIREMENT
         			FROM REGLEMENT_PRO RP, SESSION_PRO SP
         			WHERE	SP.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO AND
         			SP.ID_REGLEMENT_PRO_OF = RP.ID_REGLEMENT_PRO)	
         		ELSE
         			(SELECT REGLEMENT_PRO.NUM_VIREMENT
         			FROM REGLEMENT_PRO RP, SESSION_PRO SP
         			WHERE	SP.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO AND
         			SP.ID_REGLEMENT_PRO_ADH = RP.ID_REGLEMENT_PRO)
         	END		
         	AS 	NUM_VIREMENT,

         	CONVERT(VARCHAR,
         	CASE WHEN (FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_OF) 
         		THEN
         			(SELECT REGLEMENT_PRO.DAT_VALID_REGLEMENT
         			FROM REGLEMENT_PRO RP, SESSION_PRO SP
         			WHERE	SP.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO AND
         			SP.ID_REGLEMENT_PRO_OF = RP.ID_REGLEMENT_PRO)	
         		ELSE
         			(SELECT	REGLEMENT_PRO.DAT_VALID_REGLEMENT
         			FROM	REGLEMENT_PRO RP, SESSION_PRO SP
         			WHERE	SP.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO AND
         					SP.ID_REGLEMENT_PRO_ADH = RP.ID_REGLEMENT_PRO)
         	END,103)
         	AS DAT_VALID_REGLEMENT,

         	CASE WHEN (DAT_VALID_REGLEMENT IS NOT NULL) THEN
         		CASE WHEN (FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_OF) 
         		THEN
         			ROUND((SESSION_PRO.MNT_VERSE_HT_OF),2)
         		ELSE
         			ROUND((SESSION_PRO.MNT_VERSE_HT_ADH),2)
         		END
         	ELSE
         		0.00
         	END
         	AS MNT_REGLE_HT,

         	ROUND(
         	CASE WHEN (DAT_VALID_REGLEMENT IS NOT NULL) THEN					
         		CASE WHEN (FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_OF) 

         		THEN

         			ROUND((SESSION_PRO.MNT_VERSE_HT_OF + SESSION_PRO.MNT_VERSE_TVA_OF ),2)
         		ELSE

         			ROUND((SESSION_PRO.MNT_VERSE_HT_ADH + SESSION_PRO.MNT_VERSE_TVA_ADH ),2)
         		END
         	ELSE
         		0.00
         	END,2)
         	AS MNT_REGLE_TTC,

         	[TRANSACTION].ID_ETABLISSEMENT_OF_BENEF AS TRANSACTION_ID_ETABLISSEMENT_OF_BENEF,
         	[TRANSACTION].ID_TIERS_BENEF AS TRANSACTION_ID_TIERS_BENEF,
         	[TRANSACTION].ID_ETABLISSEMENT_BENEF AS TRANSACTION_ID_ETABLISSEMENT_BENEF

         INTO #TMP_PRO
         FROM 	SESSION_PRO	
         INNER JOIN FACTURE				ON FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_OF 

         LEFT JOIN MODULE_PRO			ON SESSION_PRO.ID_MODULE_PRO =	MODULE_PRO.ID_MODULE_PRO
         LEFT JOIN ETABLISSEMENT_OF		ON MODULE_PRO.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF
         LEFT JOIN ORGANISME_FORMATION	ON ETABLISSEMENT_OF.ID_OF = ORGANISME_FORMATION.ID_OF
         LEFT JOIN REGLEMENT_PRO			ON REGLEMENT_PRO.ID_REGLEMENT_PRO = ID_REGLEMENT_PRO_OF 

         LEFT JOIN ADHERENT				ON FACTURE.ID_EMETTEUR_ADHERENT = ADHERENT.ID_ADHERENT
         LEFT JOIN [TRANSACTION]			ON FACTURE.ID_TRANSACTION = [TRANSACTION].ID_TRANSACTION 
         LEFT JOIN TYPE_FACTURE			ON FACTURE.ID_TYPE_FACTURE = TYPE_FACTURE.ID_TYPE_FACTURE
         WHERE 

         FACTURE.ID_FACTURE IN  ( SELECT ID FROM #LstFacture)

         UNION 

         SELECT DISTINCT
         	FACTURE.ID_FACTURE,
         	FACTURE.NUM_FACTURE,
         	FACTURE.MNT_HT,
         	FACTURE.MNT_TTC,
         	FACTURE.DAT_EMISSION,
         	TYPE_FACTURE.COD_TYPE_FACTURE,
         	[TRANSACTION].ID_TRANSACTION AS TRANSACTION_ID_TRANSACTION,
         	SESSION_PRO.COD_SESSION_PRO AS COD_SESSION,
         	ORGANISME_FORMATION.LIB_RAISON_SOCIALE,
         	MODULE_PRO.LIBL_MODULE_PRO AS LIBL_MODULE,

         	CONVERT(VARCHAR, SESSION_PRO.DAT_DEBUT, 103) AS DAT_DEBUT,
         	CONVERT(VARCHAR, SESSION_PRO.DAT_FIN, 103) AS DAT_FIN,
         	'CPRO'	AS LIBL_SOUS_TYPE_COUT,

         	CASE WHEN (FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_OF) 
         	THEN
         		ROUND((SESSION_PRO.MNT_VERSE_HT_OF),2)
         	ELSE
         		ROUND((SESSION_PRO.MNT_VERSE_HT_ADH),2)
         	END
         	AS MNT_ATTESTE_HT,

         	CASE WHEN (FACTURE.ID_FACTURE =SESSION_PRO.ID_FACTURE_OF) 
         	THEN	CONVERT(VARCHAR, SESSION_PRO.DAT_BAP_OF , 103)  
         	ELSE	CONVERT(VARCHAR, SESSION_PRO.DAT_BAP_ADH , 103)   
         	END		AS	DAT_BAP,

         	CASE WHEN (FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_OF) 
         		THEN
         			(SELECT REGLEMENT_PRO.NUM_VIREMENT
         			FROM REGLEMENT_PRO RP, SESSION_PRO SP
         			WHERE	SP.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO AND
         			SP.ID_REGLEMENT_PRO_OF = RP.ID_REGLEMENT_PRO)	
         		ELSE
         			(SELECT REGLEMENT_PRO.NUM_VIREMENT
         			FROM REGLEMENT_PRO RP, SESSION_PRO SP
         			WHERE	SP.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO AND
         			SP.ID_REGLEMENT_PRO_ADH = RP.ID_REGLEMENT_PRO)
         	END		
         	AS 	NUM_VIREMENT,

         	CONVERT(VARCHAR,
         	CASE WHEN (FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_OF) 
         		THEN
         			(SELECT REGLEMENT_PRO.DAT_VALID_REGLEMENT
         			FROM REGLEMENT_PRO RP, SESSION_PRO SP
         			WHERE	SP.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO AND
         			SP.ID_REGLEMENT_PRO_OF = RP.ID_REGLEMENT_PRO)	
         		ELSE
         			(SELECT	REGLEMENT_PRO.DAT_VALID_REGLEMENT
         			FROM	REGLEMENT_PRO RP, SESSION_PRO SP
         			WHERE	SP.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO AND
         					SP.ID_REGLEMENT_PRO_ADH = RP.ID_REGLEMENT_PRO)
         	END,103)
         	AS DAT_VALID_REGLEMENT,

         	CASE WHEN (DAT_VALID_REGLEMENT IS NOT NULL) THEN
         		CASE WHEN (FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_OF) 
         		THEN
         			ROUND((SESSION_PRO.MNT_VERSE_HT_OF),2)
         		ELSE
         			ROUND((SESSION_PRO.MNT_VERSE_HT_ADH),2)
         		END
         	ELSE
         		ROUND(0.00,2)
         	END
         	AS MNT_REGLE_HT,

         	CASE WHEN (DAT_VALID_REGLEMENT IS NOT NULL) THEN					
         		CASE WHEN (FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_OF) 

         		THEN

         			ROUND((SESSION_PRO.MNT_VERSE_HT_OF + SESSION_PRO.MNT_VERSE_TVA_OF ),2)
         		ELSE

         			ROUND((SESSION_PRO.MNT_VERSE_HT_ADH + SESSION_PRO.MNT_VERSE_TVA_ADH ),2)
         		END
         	ELSE
         		ROUND(0.00,2)
         	END
         	AS MNT_REGLE_TTC,

         	[TRANSACTION].ID_ETABLISSEMENT_OF_BENEF AS TRANSACTION_ID_ETABLISSEMENT_OF_BENEF,
         	[TRANSACTION].ID_TIERS_BENEF AS TRANSACTION_ID_TIERS_BENEF,
         	[TRANSACTION].ID_ETABLISSEMENT_BENEF AS TRANSACTION_ID_ETABLISSEMENT_BENEF

         FROM 	SESSION_PRO	
         INNER JOIN FACTURE				ON 
         								   FACTURE.ID_FACTURE = SESSION_PRO.ID_FACTURE_ADHERENT 
         LEFT JOIN MODULE_PRO			ON SESSION_PRO.ID_MODULE_PRO =	MODULE_PRO.ID_MODULE_PRO
         LEFT JOIN ETABLISSEMENT_OF		ON MODULE_PRO.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF
         LEFT JOIN ORGANISME_FORMATION	ON ETABLISSEMENT_OF.ID_OF = ORGANISME_FORMATION.ID_OF
         LEFT JOIN REGLEMENT_PRO			ON 
         								   REGLEMENT_PRO.ID_REGLEMENT_PRO = ID_REGLEMENT_PRO_ADH 								   
         LEFT JOIN ADHERENT				ON FACTURE.ID_EMETTEUR_ADHERENT = ADHERENT.ID_ADHERENT
         LEFT JOIN [TRANSACTION]			ON FACTURE.ID_TRANSACTION = [TRANSACTION].ID_TRANSACTION 
         LEFT JOIN TYPE_FACTURE			ON FACTURE.ID_TYPE_FACTURE = TYPE_FACTURE.ID_TYPE_FACTURE
         WHERE 

         FACTURE.ID_FACTURE IN  ( SELECT ID FROM #LstFacture)

         SELECT #TMP_PEC.* 
         INTO #TMP_LSTDOSFACTURE
         FROM  #TMP_PEC

         UNION ALL

         SELECT #TMP_PRO.* FROM  #TMP_PRO

         DROP TABLE		#LstFacture

         SELECT
         #TMP_LSTDOSFACTURE.ID_FACTURE,
         #TMP_LSTDOSFACTURE.TRANSACTION_ID_TRANSACTION,
         #TMP_LSTDOSFACTURE.COD_SESSION,
         #TMP_LSTDOSFACTURE.LIB_RAISON_SOCIALE ,
         #TMP_LSTDOSFACTURE.LIBL_MODULE,
         #TMP_LSTDOSFACTURE.DAT_DEBUT,
         #TMP_LSTDOSFACTURE.DAT_FIN,
         #TMP_LSTDOSFACTURE.LIBL_SOUS_TYPE_COUT ,
         CONVERT(MONEY , #TMP_LSTDOSFACTURE.MNT_ATTESTE_HT, 1) AS MNT_ATTESTE_HT,
         #TMP_LSTDOSFACTURE.DAT_BAP,
         #TMP_LSTDOSFACTURE.NUM_VIREMENT,
         #TMP_LSTDOSFACTURE.DAT_VALID_REGLEMENT,
         CONVERT(MONEY , #TMP_LSTDOSFACTURE.MNT_REGLE_HT,1) AS MNT_REGLE_HT,
         CONVERT(MONEY , #TMP_LSTDOSFACTURE.MNT_REGLE_TTC,1) AS MNT_REGLE_TTC,
         #TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_OF_BENEF,
         #TMP_LSTDOSFACTURE.TRANSACTION_ID_TIERS_BENEF,
         #TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_BENEF,

         	CASE WHEN (#TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_BENEF	IS NOT NULL)THEN	
         		(SELECT	ADH.LIB_RAISON_SOCIALE 
         		FROM	ADHERENT ADH, ETABLISSEMENT ETA 
         		WHERE	ETA.ID_ETABLISSEMENT =  #TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_BENEF    AND	
         				ETA.ID_ADHERENT = ADH.ID_ADHERENT)				
         	ELSE

         		CASE WHEN(#TMP_LSTDOSFACTURE.TRANSACTION_ID_TIERS_BENEF IS NOT NULL)THEN
         			(SELECT TIE.LIB_NOM
         			 FROM TIERS TIE 
         			 WHERE	TIE.ID_TIERS = #TMP_LSTDOSFACTURE.TRANSACTION_ID_TIERS_BENEF)

         		ELSE
         			(SELECT O_F.LIB_RAISON_SOCIALE
         			 FROM ORGANISME_FORMATION O_F,  ETABLISSEMENT_OF ETA_OF	 
         			 WHERE 
         			 #TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_OF_BENEF = ETA_OF.ID_ETABLISSEMENT_OF AND
         			 O_F.ID_OF = ETA_OF.ID_OF) 								
         		END
         	END
         	AS BENEFECIAIRE,

         	CASE WHEN (#TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_BENEF	IS NOT NULL)THEN	
         		(SELECT	ADR.LIB_ADR
         		FROM	ADHERENT ADH, ETABLISSEMENT ETA, ADRESSE ADR
         		WHERE	ETA.ID_ETABLISSEMENT =  #TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_BENEF    AND	
         				ETA.ID_ADHERENT = ADH.ID_ADHERENT								AND
         				ETA.ID_ADRESSE_PRINCIPALE = ADR.ID_ADRESSE)				
         	ELSE

         		CASE WHEN(#TMP_LSTDOSFACTURE.TRANSACTION_ID_TIERS_BENEF IS NOT NULL)THEN
         			(SELECT ADR.LIB_ADR
         			 FROM	TIERS TIE,ADRESSE ADR
         			 WHERE	TIE.ID_TIERS = #TMP_LSTDOSFACTURE.TRANSACTION_ID_TIERS_BENEF AND 
         					TIE.ID_ADRESSE_PRINCIPALE = ADR.ID_ADRESSE )

         		ELSE
         			(SELECT ADR.LIB_ADR
         			 FROM ORGANISME_FORMATION O_F, ADRESSE ADR , ETABLISSEMENT_OF ETA_OF
         			 WHERE O_F.ID_OF = #TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_OF_BENEF AND
         			 #TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_OF_BENEF = ETA_OF.ID_ETABLISSEMENT_OF AND
         			 O_F.ID_OF = ETA_OF.ID_OF AND
         			 O_F.ID_ADRESSE_PRINCIPALE = ADR.ID_ADRESSE)		
         		END
         	END
         	AS LIB_ADR,

         	CASE WHEN (#TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_BENEF	IS NOT NULL)THEN	
         		(SELECT	ADR.LIB_CP_CEDEX
         		FROM	ADHERENT ADH, ETABLISSEMENT ETA, ADRESSE ADR
         		WHERE	ETA.ID_ETABLISSEMENT =  #TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_BENEF    AND	
         				ETA.ID_ADHERENT = ADH.ID_ADHERENT								AND
         				ETA.ID_ADRESSE_PRINCIPALE = ADR.ID_ADRESSE)				
         	ELSE

         		CASE WHEN(#TMP_LSTDOSFACTURE.TRANSACTION_ID_TIERS_BENEF IS NOT NULL)THEN
         			(SELECT ADR.LIB_CP_CEDEX
         			 FROM	TIERS TIE,ADRESSE ADR
         			 WHERE	TIE.ID_TIERS = #TMP_LSTDOSFACTURE.TRANSACTION_ID_TIERS_BENEF AND 
         					TIE.ID_ADRESSE_PRINCIPALE = ADR.ID_ADRESSE )

         		ELSE
         			(SELECT ADR.LIB_CP_CEDEX
         			 FROM ORGANISME_FORMATION O_F, ADRESSE ADR, ETABLISSEMENT_OF ETA_OF
         			 WHERE O_F.ID_OF = #TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_OF_BENEF AND
         			 #TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_OF_BENEF = ETA_OF.ID_ETABLISSEMENT_OF AND
         			 O_F.ID_OF = ETA_OF.ID_OF AND
         			 O_F.ID_ADRESSE_PRINCIPALE = ADR.ID_ADRESSE)		
         		END
         	END
         	AS COD_POSTAL,

         	CASE WHEN (#TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_BENEF	IS NOT NULL)THEN	
         		(SELECT	ADR.LIB_VIL_CEDEX
         		FROM	ADHERENT ADH, ETABLISSEMENT ETA, ADRESSE ADR
         		WHERE	ETA.ID_ETABLISSEMENT =  #TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_BENEF    AND	
         				ETA.ID_ADHERENT = ADH.ID_ADHERENT								AND
         				ETA.ID_ADRESSE_PRINCIPALE = ADR.ID_ADRESSE)				
         	ELSE

         		CASE WHEN(#TMP_LSTDOSFACTURE.TRANSACTION_ID_TIERS_BENEF IS NOT NULL)THEN
         			(SELECT ADR.LIB_VIL_CEDEX
         			 FROM	TIERS TIE,ADRESSE ADR
         			 WHERE	TIE.ID_TIERS = #TMP_LSTDOSFACTURE.TRANSACTION_ID_TIERS_BENEF AND 
         					TIE.ID_ADRESSE_PRINCIPALE = ADR.ID_ADRESSE )

         		ELSE
         			(SELECT ADR.LIB_VIL_CEDEX
         			 FROM ORGANISME_FORMATION O_F, ADRESSE ADR
         			 WHERE O_F.ID_OF = #TMP_LSTDOSFACTURE.TRANSACTION_ID_ETABLISSEMENT_OF_BENEF AND
         			 O_F.ID_ADRESSE_PRINCIPALE = ADR.ID_ADRESSE)		
         		END
         	END
         	AS LIB_VILLE,

         	''''+ #TMP_LSTDOSFACTURE.COD_SESSION as COD_SESSION_EXPORT,
         	''''+ CAST(#TMP_LSTDOSFACTURE.NUM_FACTURE AS VARCHAR) AS NUM_FACTURE,	
         	CONVERT(MONEY , #TMP_LSTDOSFACTURE.MNT_HT,1) AS MNT_HT,
         	CONVERT(MONEY , #TMP_LSTDOSFACTURE.MNT_TTC,1) AS MNT_TTC,	
         	CONVERT(VARCHAR,#TMP_LSTDOSFACTURE.DAT_EMISSION,103) AS DAT_EMISSION,	
         	#TMP_LSTDOSFACTURE.COD_TYPE_FACTURE

         FROM #TMP_LSTDOSFACTURE
         ORDER BY #TMP_LSTDOSFACTURE.NUM_FACTURE 
         END

GO
 CREATE PROCEDURE INIT_PARAMETRAGE_ANNUEL_2016

         AS
         BEGIN

         	print '2016 - INIT - param‚trage annuel.sql'
         	declare @num_annee int, @id_periode int
         	set @num_annee = 2016

         	declare @num_annee_precedente int
         	set @num_annee_precedente = @num_annee-1

         	select @id_periode = id_periode from PERIODE where NUM_ANNEE = @num_annee and ID_TYPE_PERIODE  =1

         	if not exists (select 1 from PERIODE_BRANCHE where id_periode = @id_periode)
         	BEGIN
         		insert into periode_branche
         		(ID_PERIODE, ID_BRANCHE, PRC_MUTUALISATION_VERSEMENT_RELIQUAT, PRC_MS_MIN_REMBOURSEMENT_FRAIS_GESTION, PRC_MS_MIN_DOTATION_ABONDEMENT_VO)
         		select	@id_periode, id_branche, PRC_MUTUALISATION_VERSEMENT_RELIQUAT, PRC_MS_MIN_REMBOURSEMENT_FRAIS_GESTION, PRC_MS_MIN_DOTATION_ABONDEMENT_VO
         		from	PERIODE_BRANCHE t1
         		join	PERIODE t2
         		on		t1.id_periode = t2.id_periode
         		where	t2.NUM_ANNEE = @num_annee_precedente
         	END

         	EXEC MAJ_EFFECTIF_ANNEE @num_annee

         	EXEC MAJ_OPERATIONS_FINANCIERES @num_annee

         	declare @id_option	int

         	select	@id_periode = id_periode
         	from	periode 
         	where	id_type_periode = 1
         	and		num_annee = @num_annee

         	select	@id_option = id_option
         	from	options
         	where	cod_option = 'NON'

         	insert into r20bis
         	(ID_GROUPE, ID_PERIODE, ID_OPTION, PRC_OPTION, PRC_FRAIS_GESTION)
         	select	distinct t1.id_groupe, @id_periode, @id_option, 0, 0
         	from	etablissement t1
         	join	groupe t2
         	on		t1.id_groupe = t2.id_groupe
         	where	t1.bln_actif = 1
         	and		t2.bln_actif = 1
         	and		not exists (select 1 from r20bis where id_groupe = t1.id_groupe and id_periode = @id_periode)

         	declare @objet varchar(100), @commande_sql varchar(2000), @res int

         	declare recompile_curseur cursor for
         	SELECT	distinct object_name(object_id)
         	FROM	sys.sql_dependencies 
         	WHERE	referenced_major_id in (OBJECT_ID('OPERATION_FINANCIERE'), OBJECT_ID('PARAMETRE_GLOBAL'), OBJECT_ID('PARAMETRE_APPEL'), OBJECT_ID('R20'), OBJECT_ID('ENVELOPPE'))
         	AND		object_name(object_id) not like 'INS%'
         	AND		object_name(object_id) not like 'UPD%'

         	open recompile_curseur
         	fetch next from recompile_curseur into @objet
         	while @@fetch_status = 0
         	BEGIN
         		set @commande_sql = 'sp_recompile ' + @objet
         		EXEC (@commande_sql)
         		if @res <> 0 print 'echec recompilation ' + @objet
         		fetch next from recompile_curseur into @objet
         	END

         	close recompile_curseur
         	deallocate recompile_curseur

         	TRUNCATE TABLE [PARAMETRE_EXERCICE_MODULE]
         	INSERT INTO [PARAMETRE_EXERCICE_MODULE]
         			   ([DAT_DEBUT]
         			   ,[DAT_FIN]
         			   ,[NUM_VALEUR])
         		 VALUES
         			   ('20160101'
         			   ,'20160131'				
         			   ,'-1')

         	declare @id_periode_smic int

         	update	PERIODE 
         	set		BLN_EN_COURS = 0,
         			DAT_FIN_PERIODE = CONVERT(datetime, '31-12-2015 23:59:59')
         	where	ID_TYPE_PERIODE = 4
         	and		NUM_ANNEE = 2015

         	if not exists (select * from periode where id_type_periode = 4 and NUM_ANNEE = 2016)
         	BEGIN
         		insert into periode
         		(ID_TYPE_PERIODE, COD_PERIODE, NUM_ANNEE, DAT_DEB_PERIODE, DAT_FIN_PERIODE, BLN_ACTIF, BLN_EN_COURS, DAT_CREATION, ID_UTILISATEUR, BLN_PRIORITAIRE)
         		SELECT
         		ID_TYPE_PERIODE		= 4, 
         		COD_PERIODE			= '2016', 
         		NUM_ANNEE			= 2016, 
         		DAT_DEB_PERIODE		= CONVERT(datetime, '01-01-2016 00:00:00'), 
         		DAT_FIN_PERIODE		= CONVERT(datetime, '31-12-9999 00:00:00'), 
         		BLN_ACTIF			= 1, 
         		BLN_EN_COURS		= 1, 
         		DAT_CREATION		= getdate(),
         		ID_UTILISATEUR		= 82,
         		BLN_PRIORITAIRE		= 1 

         	END
         	select	@id_periode_smic = id_periode
         	from	PERIODE
         	where	ID_TYPE_PERIODE = 4
         	and		NUM_ANNEE		= 2016
         	AND		BLN_EN_COURS	= 1
         	if not exists (select 1 from tau_smic where id_periode = @id_periode_smic)
         	BEGIN
         		insert into TAU_SMIC
         		(ID_PERIODE, MNT_SMIC_HORAIRE_BRUT)
         		values
         		(@id_periode_smic, 9.67)
         	END

         	update	PERIODE
         	set		BLN_FINANCEMENT_DISPO = 1
         	where	ID_TYPE_PERIODE = 1
         	and		NUM_ANNEE = @num_annee

         	EXEC MAJ_CALENDRIER 2016

         	update	PERIODE
         	set		DAT_CONSTITUTION_POT_MUT= CONVERT(DATETIME, '01/07/'+ CAST(NUM_ANNEE+1 AS VARCHAR), 103)
         	where	ID_TYPE_PERIODE = 1
         	and		NUM_ANNEE = 2016

         END
GO

         CREATE PROCEDURE [dbo].[UPD_LETTRE_PEC_ENGAGEMENT_OF]
         	@IDS_MODULE_PEC TEXT	
         AS

         BEGIN

         	DECLARE @Item varchar(50);

         	CREATE TABLE #List(Item varchar(50) collate French_CI_AI)

         	DECLARE @Delimiter char
         	SET @Delimiter = ','
         	WHILE CHARINDEX(@Delimiter,@IDS_MODULE_PEC,0) <> 0
         	BEGIN
         		SELECT
         			@Item=RTRIM(LTRIM(SUBSTRING(@IDS_MODULE_PEC,1,CHARINDEX(@Delimiter,@IDS_MODULE_PEC,0)-1))),
         			@IDS_MODULE_PEC=RTRIM(LTRIM(SUBSTRING(@IDS_MODULE_PEC,CHARINDEX(@Delimiter,@IDS_MODULE_PEC,0)+1,DATALENGTH(@IDS_MODULE_PEC))))

         		IF LEN(@Item) > 0
         			INSERT INTO #List SELECT @Item
         	END

         	IF DATALENGTH(@IDS_MODULE_PEC) > 0
         		INSERT INTO #List SELECT @IDS_MODULE_PEC 

         	UPDATE MODULE_PEC
         	SET DAT_LETTRE_PEC_ENGAGEMENT_OF = GETDATE()
         	WHERE COD_MODULE_PEC IN (SELECT Item FROM #List)
         END

GO

         CREATE  PROCEDURE [dbo].[BATCH_INS_SUIVI_COMPTABLE_ENGAGEMENT]
         (@ID_MODULE_PRO integer  = NULL)
         AS 

         BEGIN
         DECLARE 
         	@ID_ENGAGEMENT_MODULE_CPTA_PRO	int,
         	@ID_TYPE_ENGAGEMENT_CPTA		int,
         	@DAT_BAE						datetime,
         	@NB_UNITE_TOTALE				float,
         	@NB_UNITE_EVALUATION			float,
         	@NB_UNITE_ACCOMPAGNEMENT		float,
         	@MNT_MODULE_HT					float,
         	@MNT_ATTESTE_HT					float,
         	@DAT_CLOTURE					datetime,
         	@BLN_ACTIF						tinyint,
         	@NUM_CAS						int

         CREATE TABLE #TMP01
         (
         	NUM_CAS				int,
         	ID_MODULE_PRO			int, 
         	ID_TYPE_ENGAGEMENT_CPTA	int, 
         	DAT_BAE					datetime, 
         	NB_UNITE_TOTALE			float, 
         	NB_UNITE_EVALUATION		float, 
         	NB_UNITE_ACCOMPAGNEMENT	float, 
         	MNT_MODULE_HT			float
         )

         INSERT INTO #TMP01
         SELECT	1, ID_MODULE_PRO, ID_TYPE_ENGAGEMENT_PRO, DAT_BAE, NB_UNITE_TOTALE, NB_UNITE_EVALUATION, NB_UNITE_ACCOMPAGNEMENT, MNT_MODULE_HT
         FROM	MODULE_PRO, ENGAGEMENT_PRO
         WHERE	MODULE_PRO.ID_ENGAGEMENT_PRO = ENGAGEMENT_PRO.ID_ENGAGEMENT_PRO 
         AND NOT EXISTS 
         			(	SELECT	1 
         				FROM	ENGAGEMENT_MODULE_CPTA_PRO 
         				WHERE	ENGAGEMENT_MODULE_CPTA_PRO .ID_MODULE_PRO = MODULE_PRO .ID_MODULE_PRO 
         				AND		ID_TYPE_ENGAGEMENT_CPTA IN (1, 2)
         			)
         AND	ID_MODULE_PRO = ISNULL(@ID_MODULE_PRO, ID_MODULE_PRO)

         INSERT INTO #TMP01
         SELECT	2, ID_MODULE_PRO, 4 , GETDATE(), -NB_UNITE_TOTALE, -NB_UNITE_EVALUATION, -NB_UNITE_ACCOMPAGNEMENT, -MNT_MODULE_HT
         FROM	MODULE_PRO, ENGAGEMENT_PRO
         WHERE	MODULE_PRO.ID_ENGAGEMENT_PRO = ENGAGEMENT_PRO.ID_ENGAGEMENT_PRO 
         AND		BLN_ACTIF = 0
         AND NOT EXISTS 
         			(	SELECT	1 
         				FROM	ENGAGEMENT_MODULE_CPTA_PRO 
         				WHERE	ENGAGEMENT_MODULE_CPTA_PRO .ID_MODULE_PRO = MODULE_PRO .ID_MODULE_PRO 
         				AND		ID_TYPE_ENGAGEMENT_CPTA IN (4)
         			)
         AND	ID_MODULE_PRO = ISNULL(@ID_MODULE_PRO, ID_MODULE_PRO)

         INSERT INTO #TMP01
         SELECT	3, ID_MODULE_PRO, 3 , GETDATE(), NB_UNITE_TOTALE, NB_UNITE_EVALUATION, NB_UNITE_ACCOMPAGNEMENT, MNT_MODULE_HT
         FROM	MODULE_PRO, ENGAGEMENT_PRO
         WHERE	MODULE_PRO.ID_ENGAGEMENT_PRO = ENGAGEMENT_PRO.ID_ENGAGEMENT_PRO 
         AND		DAT_CLOTURE IS NOT NULL
         AND NOT EXISTS 
         			(	SELECT	1 
         				FROM	ENGAGEMENT_MODULE_CPTA_PRO 
         				WHERE	ENGAGEMENT_MODULE_CPTA_PRO .ID_MODULE_PRO = MODULE_PRO .ID_MODULE_PRO 
         				AND		ID_TYPE_ENGAGEMENT_CPTA IN (3)
         			)
         AND	ID_MODULE_PRO = ISNULL(@ID_MODULE_PRO, ID_MODULE_PRO)

         INSERT INTO #TMP01
         SELECT	4, MODULE_PRO.ID_MODULE_PRO, 5 , GETDATE(), MODULE_PRO.NB_UNITE_TOTALE, MODULE_PRO.NB_UNITE_EVALUATION, MODULE_PRO.NB_UNITE_ACCOMPAGNEMENT, MODULE_PRO.MNT_MODULE_HT
         FROM	MODULE_PRO, ENGAGEMENT_PRO, CONTRAT_PRO
         WHERE	MODULE_PRO.ID_ENGAGEMENT_PRO = ENGAGEMENT_PRO.ID_ENGAGEMENT_PRO 
         AND		MODULE_PRO .ID_CONTRAT_PRO = CONTRAT_PRO .ID_CONTRAT_PRO 
         AND		MODULE_PRO.DAT_CLOTURE IS NULL
         AND		CONTRAT_PRO.DAT_CLOTURE IS NOT NULL
         AND		MODULE_PRO.BLN_ACTIF = 1
         AND NOT EXISTS 
         			(	SELECT	1 
         				FROM	ENGAGEMENT_MODULE_CPTA_PRO 
         				WHERE	ENGAGEMENT_MODULE_CPTA_PRO .ID_MODULE_PRO = MODULE_PRO .ID_MODULE_PRO 
         				AND		ID_TYPE_ENGAGEMENT_CPTA IN (5)
         			)
         AND	ID_MODULE_PRO = ISNULL(@ID_MODULE_PRO, ID_MODULE_PRO)

         DECLARE cu_engagement_module CURSOR FOR
         SELECT	NUM_CAS,
         		ID_MODULE_PRO			, 
         		ID_TYPE_ENGAGEMENT_CPTA	, 
         		DAT_BAE					, 
         		NB_UNITE_TOTALE			, 
         		NB_UNITE_EVALUATION		, 
         		NB_UNITE_ACCOMPAGNEMENT	, 
         		MNT_MODULE_HT			
         FROM #TMP01
         ORDER BY NUM_CAS

         OPEN cu_engagement_module 

         FETCH cu_engagement_module 
         INTO @NUM_CAS, @ID_MODULE_PRO, @ID_TYPE_ENGAGEMENT_CPTA, @DAT_BAE, @NB_UNITE_TOTALE, @NB_UNITE_EVALUATION, @NB_UNITE_ACCOMPAGNEMENT, @MNT_MODULE_HT

         WHILE (@@fetch_status <> -1)
         BEGIN

         	IF @NUM_CAS = 3

         	BEGIN

         		SELECT	
         		@NB_UNITE_TOTALE			= -(@NB_UNITE_TOTALE			- NB_UNITE_TOTALE			)	, 
         		@NB_UNITE_ACCOMPAGNEMENT	= -(@NB_UNITE_ACCOMPAGNEMENT	- NB_UNITE_ACCOMPAGNEMENT	)	, 
         		@NB_UNITE_EVALUATION		= -(@NB_UNITE_EVALUATION		- NB_UNITE_EVALUATION		)	, 
         		@MNT_MODULE_HT				= -(@MNT_MODULE_HT				- MONTANT_ENGAGE			)	
         		FROM	ENGAGEMENT_MODULE_CPTA_PRO
         		WHERE	ID_MODULE_PRO = @ID_MODULE_PRO
         		AND		ID_TYPE_ENGAGEMENT_CPTA IN (1, 2)

         	END

         	IF @NUM_CAS = 4

         	BEGIN

         		SELECT	@MNT_ATTESTE_HT	= ISNULL(SUM(MNT_ATTESTE_HT), 0)
         		FROM	SESSION_PRO
         		WHERE	ID_MODULE_PRO	= @ID_MODULE_PRO

         		SELECT	
         		@NB_UNITE_TOTALE			= 0	, 
         		@NB_UNITE_ACCOMPAGNEMENT	= 0	, 
         		@NB_UNITE_EVALUATION		= 0	, 
         		@MNT_MODULE_HT				= -(@MNT_MODULE_HT				- @MNT_ATTESTE_HT)	

         	END

         	IF @NB_UNITE_TOTALE +@NB_UNITE_ACCOMPAGNEMENT+ @NB_UNITE_EVALUATION	+ @MNT_MODULE_HT <> 0
         	BEGIN

         		INSERT INTO ENGAGEMENT_MODULE_CPTA_PRO
         		(	
         			COD_ENGAGEMENT_MODULE_CPTA_PRO, ID_MODULE_PRO, ID_TYPE_ENGAGEMENT_CPTA,
         			NB_UNITE_TOTALE, NB_UNITE_ACCOMPAGNEMENT, NB_UNITE_EVALUATION, MONTANT_ENGAGE,
         			BLN_ACTIF, DAT_CREATION 
         		)
         		VALUES
         		(	
         			99 , @ID_MODULE_PRO, @ID_TYPE_ENGAGEMENT_CPTA, 
         			@NB_UNITE_TOTALE, @NB_UNITE_ACCOMPAGNEMENT, @NB_UNITE_EVALUATION, @MNT_MODULE_HT,
         			1, @DAT_BAE 
         		)
         		SET @ID_ENGAGEMENT_MODULE_CPTA_PRO = @@identity

         		UPDATE	ENGAGEMENT_MODULE_CPTA_PRO  
         		SET		COD_ENGAGEMENT_MODULE_CPTA_PRO = @ID_ENGAGEMENT_MODULE_CPTA_PRO 
         		WHERE	ID_ENGAGEMENT_MODULE_CPTA_PRO = @ID_ENGAGEMENT_MODULE_CPTA_PRO

         		EXEC BATCH_INS_SUIVI_COMPTABLE_ENGAGEMENT_PERIODE @ID_ENGAGEMENT_MODULE_CPTA_PRO 
         	END

         	FETCH cu_engagement_module 
         	INTO @NUM_CAS, @ID_MODULE_PRO, @ID_TYPE_ENGAGEMENT_CPTA, @DAT_BAE, @NB_UNITE_TOTALE, @NB_UNITE_EVALUATION, @NB_UNITE_ACCOMPAGNEMENT, @MNT_MODULE_HT

         END

         CLOSE cu_engagement_module 
         DEALLOCATE cu_engagement_module 

         END
GO
CREATE PROCEDURE [dbo].[MVT_BUDGETAIRE_COLLECTE_GENERATION]  

          @ID_EVENEMENT  INT
         AS
         DECLARE 
          @COD_TYPE_EVENEMENT varchar(8) ,
          @ID_TYPE_MOUVEMENT int   ,
          @P_E_R    varchar(1) ,
          @LIB_PB_EVENEMENT varchar(100)

         BEGIN

          IF EXISTS (SELECT 1 FROM MVT_BUDGETAIRE WHERE ID_EVENEMENT = @ID_EVENEMENT)
          BEGIN
           SELECT  'Pb : Mvt Budgetaires deja generes pour cet evenement ', *
           FROM EVENEMENT
           WHERE ID_EVENEMENT = @ID_EVENEMENT  

           SET @LIB_PB_EVENEMENT = 'D‚tection tentative de generation de Mvt Budgetaires deja generes pour cet versement'

           INSERT INTO PB_EVENEMENT_MVT_BUDGETAIRE_COLLECTE
           (
           ID_EVENEMENT   ,
           LIB_PB_EVENEMENT  , 
           LIBL_EVENEMENT   , 
           DAT_EVENEMENT   , 
           ID_TYPE_EVENEMENT  , 
           ID_VERSEMENT   ,
           COM_EVENEMENT   
           )
           SELECT
            ID_EVENEMENT   ,
            LIB_PB_EVENEMENT  = @LIB_PB_EVENEMENT,
            LIBL_EVENEMENT   , 
            DAT_EVENEMENT   , 
            ID_TYPE_EVENEMENT  , 
            ID_VERSEMENT   ,
            COM_EVENEMENT   = 'Batch Reg‚n‚ration MVT BUDGETAIRE (PS [MVT_BUDGETAIRE_COLLECTE_GENERATION]) : D‚tection tentative de g‚n‚ration de Mvt Budgetaires deja g‚n‚r‚s pour ce versement'
           FROM EVENEMENT
           WHERE ID_EVENEMENT = @ID_EVENEMENT 

          END
          ELSE
          BEGIN

           SELECT @COD_TYPE_EVENEMENT = TYPE_EVENEMENT .COD_TYPE_EVENEMENT 
           FROM EVENEMENT 
           INNER JOIN TYPE_EVENEMENT ON TYPE_EVENEMENT.ID_TYPE_EVENEMENT = EVENEMENT.ID_TYPE_EVENEMENT 
           WHERE ID_EVENEMENT = @ID_EVENEMENT

           IF @COD_TYPE_EVENEMENT IN ( 'VERSEMEN', 'REGUL', 'REVERSE')
           BEGIN

            EXEC MVT_BUDGETAIRE_COLLECTE_ALIM_ENVELOPPE_COLLECTE @ID_EVENEMENT

            EXEC MVT_BUDGETAIRE_COLLECTE_ABONDEMENT_COMPTE @ID_EVENEMENT

           END

           IF @COD_TYPE_EVENEMENT IN ( 'IMPAYE')
           BEGIN

            EXEC MVT_BUDGETAIRE_COLLECTE_IMPAYE @ID_EVENEMENT
           END

          END
         END
GO

         CREATE PROCEDURE [dbo].[LEC_PRE_BON_A_PAYER]

         @ID_UTILISATEUR  INT
         AS
         BEGIN

         	UPDATE
         		POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = NULL
         	FROM
         		POSTE_COUT_REGLE
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         		AND POSTE_COUT_REGLE.ID_ETAT_PEC = 1
         		AND POSTE_COUT_REGLE.ID_TYPE_VALIDATION = 8
         		AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR

         	UPDATE
         		POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 4
         	FROM
         		POSTE_COUT_REGLE
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         		AND POSTE_COUT_REGLE.ID_ETAT_PEC = 3
         		AND POSTE_COUT_REGLE.ID_TYPE_VALIDATION = 8
         		AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR

         	UPDATE
         		POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 8,
         		ID_ETAT_PEC = 4,
         		BLN_OK_FINANCEMENT = 0
         	FROM
         		POSTE_COUT_REGLE
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         		AND (
         			 abs(round(POSTE_COUT_REGLE.MNT_REGLE_HT - (SELECT
         															isnull(sum (MNT_PLAN_FINANCEMENT_US), 0)
         														FROM PLAN_FINANCEMENT_US
         														WHERE ID_POSTE_COUT_REGLE = POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE), 2))>= 0.01
         		OR BLN_OK_FINANCEMENT IS NULL
         		)
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 8,
         		ID_ETAT_PEC = 11,
         		BLN_OK_FINANCEMENT = 0
         	FROM POSTE_COUT_REGLE
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND abs(round(POSTE_COUT_REGLE.MNT_REGLE_TVA - (SELECT
         														isnull(sum (MNT_PLAN_FINANCEMENT_US_TVA), 0)
         													FROM PLAN_FINANCEMENT_US
         													WHERE ID_POSTE_COUT_REGLE = POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE), 2))>= 0.01
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR

         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 8,
         		ID_ETAT_PEC = (SELECT
         						   ID_ETAT_PEC
         					   FROM ETAT_PEC
         					   WHERE COD_ETAT_PEC ='TVAMQ'),
         		BLN_OK_FINANCEMENT = 0
         	FROM POSTE_COUT_REGLE
         		 INNER JOIN FACTURE F
         			ON F.ID_FACTURE = POSTE_COUT_REGLE.ID_FACTURE
         	WHERE
         		F.ID_TYPE_TVA IS NULL
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 8,
         		ID_ETAT_PEC = 11,
         		BLN_OK_FINANCEMENT = 0
         	FROM POSTE_COUT_REGLE
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND abs(round(POSTE_COUT_REGLE.MNT_REGLE_TTC - (POSTE_COUT_REGLE.MNT_REGLE_HT + POSTE_COUT_REGLE.MNT_REGLE_TVA), 2))>= 0.01
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR

         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 8,
         		ID_ETAT_PEC = 12,
         		BLN_OK_FINANCEMENT = 0
         	FROM POSTE_COUT_REGLE
         		 INNER JOIN F_C2P_AUDIT_FINANCEMENTREGLEMENTNONAUTORISE() A ON A.ID_POSTE_COUT_REGLE = POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR

         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 8
         	FROM POSTE_COUT_REGLE
         		 INNER JOIN MODULE_PEC ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND (
         		 POSTE_COUT_REGLE.ID_ETAT_PEC = 2
         	  OR POSTE_COUT_REGLE.ID_ETAT_PEC = 4

         	  OR POSTE_COUT_REGLE.BLN_OK_PIECE = 0
         	  OR MODULE_PEC.BLN_OK_PIECE = 0
         	  )
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR

         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 8,
         		POSTE_COUT_REGLE.ID_ETAT_PEC = 6
         	FROM POSTE_COUT_REGLE
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	AND POSTE_COUT_REGLE.ID_TRANSACTION IS NULL

         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 8,
         		POSTE_COUT_REGLE.ID_ETAT_PEC = 6
         	FROM
         		POSTE_COUT_REGLE
         		INNER JOIN [TRANSACTION]
         			ON	[TRANSACTION].ID_TRANSACTION = POSTE_COUT_REGLE.ID_TRANSACTION
         				AND [TRANSACTION].BLN_ACTIF = 1 
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         		AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         		AND
         		(
         			ISNULL(NULLIF([TRANSACTION].NUM_IBAN, ''),null)IS NULL 
         			OR ISNULL(NULLIF([TRANSACTION].BIC, ''),null)IS NULL
         		)

         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 8,
         		POSTE_COUT_REGLE.ID_ETAT_PEC = 10
         	FROM POSTE_COUT_REGLE
         		 INNER JOIN MODULE_PEC  ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC
         		 INNER JOIN ACTION_PEC  ON ACTION_PEC.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC
         		 INNER JOIN [TRANSACTION] ON [TRANSACTION].ID_TRANSACTION = POSTE_COUT_REGLE.ID_TRANSACTION 
         		 LEFT  JOIN REPRISE_MODULE_NESSIE	ON
         												REPRISE_MODULE_NESSIE.ID_ETABLISSEMENT_OF = [TRANSACTION].ID_ETABLISSEMENT_OF_DEST
         											AND REPRISE_MODULE_NESSIE.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC

         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	AND POSTE_COUT_REGLE.BLN_FACTURE_DIRECTE = 0
         	AND [TRANSACTION].ID_ETABLISSEMENT_DEST NOT IN (SELECT
         														A.ID_ETABLISSEMENT
         													FROM
         														ETABLISSEMENT A
         														INNER JOIN ETABLISSEMENT B ON B.ID_ADHERENT=A.ID_ADHERENT
         													WHERE
         														  B.ID_ETABLISSEMENT =POSTE_COUT_REGLE.ID_ETABLISSEMENT
         													  AND (
         														  A.BLN_ACTIF=1
         													   OR A.ID_ETABLISSEMENT =B.ID_ETABLISSEMENT) 
         		)
         	 OR
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	AND POSTE_COUT_REGLE.BLN_FACTURE_DIRECTE = 1
         	AND [TRANSACTION].ID_ETABLISSEMENT_OF_DEST NOT IN (SELECT
         														   AOF.ID_ETABLISSEMENT_OF
         													   FROM
         														   ETABLISSEMENT_OF AOF
         														   INNER JOIN ETABLISSEMENT_OF BOF ON BOF.ID_OF=AOF.ID_OF
         													   WHERE
         															 BOF.ID_ETABLISSEMENT_OF =MODULE_PEC.ID_ETABLISSEMENT_OF
         														 AND (
         															 AOF.BLN_ACTIF=1
         														  OR AOF.ID_ETABLISSEMENT_OF =BOF.ID_ETABLISSEMENT_OF) 
         		)
         	AND coalesce(ACTION_PEC.BLN_REPRISE_ADHOC, 0) = 0

         	AND ( 
         		 ACTION_PEC.BLN_REPRISE_NESSIE = 1
         	 AND REPRISE_MODULE_NESSIE.ID_ACTION_PEC IS NULL
         	  OR ACTION_PEC.BLN_REPRISE_NESSIE = 0
         		)

         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 8,
         		POSTE_COUT_REGLE.ID_ETAT_PEC = 10
         	FROM POSTE_COUT_REGLE
         		 INNER JOIN MODULE_PEC  ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC
         		 INNER JOIN [TRANSACTION] ON [TRANSACTION].ID_TRANSACTION = POSTE_COUT_REGLE.ID_TRANSACTION
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	AND [TRANSACTION].BLN_ACTIF = 0

         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 4
         	FROM POSTE_COUT_REGLE
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND POSTE_COUT_REGLE.ID_TYPE_VALIDATION IS NULL
         	AND (
         		 POSTE_COUT_REGLE.ID_ETAT_PEC = 1
         	 AND POSTE_COUT_REGLE.BLN_A_CONTROLER = 1
         	  OR POSTE_COUT_REGLE.ID_ETAT_PEC = 3
         		)
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR

         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 4,
         		ID_ETAT_PEC = 7
         	FROM POSTE_COUT_REGLE
         		 INNER JOIN [TRANSACTION] ON [TRANSACTION].ID_TRANSACTION = POSTE_COUT_REGLE.ID_TRANSACTION
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND POSTE_COUT_REGLE.ID_TYPE_VALIDATION IS NULL
         	AND POSTE_COUT_REGLE.ID_ETAT_PEC = 1
         	AND [TRANSACTION].BLN_TRANSACTION_REGLEMENT_PRINCIPAL = 0
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR

         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 4,
         		ID_ETAT_PEC = 8
         	FROM POSTE_COUT_REGLE
         		 INNER JOIN [TRANSACTION] ON [TRANSACTION].ID_TRANSACTION = POSTE_COUT_REGLE.ID_TRANSACTION
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND POSTE_COUT_REGLE.ID_TYPE_VALIDATION IS NULL
         	AND POSTE_COUT_REGLE.ID_ETAT_PEC = 1
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	AND (
         		dateadd(MM, 3, [TRANSACTION].DAT_CREATION) >= getdate()
         	 OR dateadd(MM, 3, [TRANSACTION].DAT_MODIF) >= getdate() );

         	WITH PCR_OF_NOUVEAU
         		AS (
         		SELECT
         			POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE
         		FROM
         			POSTE_COUT_REGLE
         			INNER JOIN MODULE_PEC ON MODULE_PEC.ID_MODULE_PEC=POSTE_COUT_REGLE.ID_MODULE_PEC
         			INNER JOIN ETABLISSEMENT_OF ON ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF=MODULE_PEC.ID_ETABLISSEMENT_OF
         			INNER JOIN ORGANISME_FORMATION ON
         											  ORGANISME_FORMATION.ID_OF=ETABLISSEMENT_OF.ID_OF
         										  AND dateadd(MM, 3, ORGANISME_FORMATION.DAT_CREATION)>=getdate()
         		WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND POSTE_COUT_REGLE.ID_TYPE_VALIDATION IS NULL
         	AND (
         		 POSTE_COUT_REGLE.ID_ETAT_PEC = 1
         	  OR POSTE_COUT_REGLE.ID_ETAT_PEC = 3
         		)
         	AND POSTE_COUT_REGLE.BLN_FACTURE_DIRECTE = 1
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         		UNION
         		SELECT
         			POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE
         		FROM
         			POSTE_COUT_REGLE
         			INNER JOIN MODULE_PEC ON MODULE_PEC.ID_MODULE_PEC=POSTE_COUT_REGLE.ID_MODULE_PEC
         			INNER JOIN ETABLISSEMENT_OF ON ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF=MODULE_PEC.ID_ETABLISSEMENT_OF
         			INNER JOIN ORGANISME_FORMATION ON
         											  ORGANISME_FORMATION.ID_OF=ETABLISSEMENT_OF.ID_OF
         										  AND (
         			SELECT
         				count(DISTINCT PCR.ID_POSTE_COUT_REGLE)
         			FROM
         				POSTE_COUT_REGLE PCR
         				INNER JOIN MODULE_PEC MP ON MP.ID_MODULE_PEC=PCR.ID_MODULE_PEC
         				INNER JOIN ETABLISSEMENT_OF EOF ON EOF.ID_ETABLISSEMENT_OF=MP.ID_ETABLISSEMENT_OF
         				INNER JOIN ORGANISME_FORMATION ORF ON
         													  ORF.ID_OF=EOF.ID_OF
         												  AND ORF.ID_OF=ORGANISME_FORMATION.ID_OF
         				INNER JOIN REGLEMENT ON
         										PCR.ID_REGLEMENT IS NOT NULL
         									AND REGLEMENT.ID_REGLEMENT=PCR.ID_REGLEMENT
         									AND REGLEMENT.DAT_VALID_REGLEMENT IS NOT NULL)<10
         		WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND POSTE_COUT_REGLE.ID_TYPE_VALIDATION IS NULL
         	AND (
         		 POSTE_COUT_REGLE.ID_ETAT_PEC = 1
         	  OR POSTE_COUT_REGLE.ID_ETAT_PEC = 3
         		)
         	AND POSTE_COUT_REGLE.BLN_FACTURE_DIRECTE = 1
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         		)
         		UPDATE     POSTE_COUT_REGLE
         		SET
         			ID_TYPE_VALIDATION = 4,
         			ID_ETAT_PEC = 9
         		FROM
         			POSTE_COUT_REGLE
         			INNER JOIN PCR_OF_NOUVEAU
         				ON PCR_OF_NOUVEAU.ID_POSTE_COUT_REGLE = POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE

         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 4,
         		ID_ETAT_PEC = 8
         	FROM POSTE_COUT_REGLE
         		 INNER JOIN [TRANSACTION] ON
         									[TRANSACTION].ID_TRANSACTION = POSTE_COUT_REGLE.ID_TRANSACTION
         								AND [TRANSACTION].BLN_ACTIF = 1 
         	WHERE
         		POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND ID_TYPE_VALIDATION = 8
         	AND POSTE_COUT_REGLE.ID_ETAT_PEC = 6
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	AND ISNULL(NULLIF([TRANSACTION].NUM_IBAN, ''),null)IS NOT NULL
         	AND ISNULL(NULLIF([TRANSACTION].BIC, ''),null)IS NOT NULL

         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 4,
         		ID_ETAT_PEC = 1
         	FROM POSTE_COUT_REGLE
         		 INNER JOIN DBO.POSTE_COUT_ENGAGE
         	ON
         	  POSTE_COUT_ENGAGE.ID_SOUS_TYPE_COUT = POSTE_COUT_REGLE.ID_SOUS_TYPE_COUT
           AND POSTE_COUT_ENGAGE.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC
         	WHERE
         		ID_TYPE_VALIDATION = 8
         	AND POSTE_COUT_REGLE.ID_ETAT_PEC = 13
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	AND POSTE_COUT_REGLE.DAT_BAP IS NULL
         	AND POSTE_COUT_ENGAGE.ID_ENGAGEMENT IS NOT NULL
         	AND POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL

         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 8,
         		ID_ETAT_PEC = 13
         	WHERE
         		POSTE_COUT_REGLE.ID_ETAT_PEC = 1
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	AND POSTE_COUT_REGLE.DAT_BAP IS NULL
         	AND NOT EXISTS
         		(SELECT
         			 POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE
         		 FROM POSTE_COUT_ENGAGE
         		 WHERE
         				POSTE_COUT_ENGAGE.ID_SOUS_TYPE_COUT = POSTE_COUT_REGLE.ID_SOUS_TYPE_COUT
         			AND POSTE_COUT_ENGAGE.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC
         			AND POSTE_COUT_ENGAGE.ID_ENGAGEMENT IS NOT NULL
         			AND POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL)

         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION	= 8	,	
         		ID_ETAT_PEC			= 12,	
         		BLN_OK_FINANCEMENT	= 0
         	FROM POSTE_COUT_REGLE
         	INNER JOIN SESSION_PEC		ON SESSION_PEC.ID_SESSION_PEC		= POSTE_COUT_REGLE.ID_SESSION_PEC
         	INNER JOIN STAGIAIRE_PEC	ON STAGIAIRE_PEC.ID_SESSION_PEC		= POSTE_COUT_REGLE.ID_SESSION_PEC
         	INNER JOIN UNITE_STAGIAIRE	ON UNITE_STAGIAIRE.ID_STAGIAIRE_PEC	= STAGIAIRE_PEC.ID_STAGIAIRE_PEC
         	INNER JOIN DISPOSITIF		ON UNITE_STAGIAIRE .ID_DISPOSITIF	= DISPOSITIF.ID_DISPOSITIF 
         	WHERE 
         	(

         		COD_DISPOSITIF IN ('DIFPRIO', 'DIFPORT', 'PLPPDIF')
         		AND 
         		UNITE_STAGIAIRE .NB_HEURE_REGLE > 0
         	)
         	AND 
         	(	
         		YEAR(SESSION_PEC.DAT_DEBUT) >= 2016  
         	)
         	AND POSTE_COUT_REGLE.DAT_BAP		IS NULL
         	AND POSTE_COUT_REGLE.ID_SESSION		IS NULL
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR

         	UPDATE POSTE_COUT_REGLE
         	SET
         		ID_TYPE_VALIDATION = 1
         	FROM POSTE_COUT_REGLE
         	WHERE
         		ID_TYPE_VALIDATION IS NULL
         	AND POSTE_COUT_REGLE.ID_SESSION IS NULL
         	AND POSTE_COUT_REGLE.ID_UTILISATEUR = @ID_UTILISATEUR
         	return 0
         END

GO

         CREATE PROCEDURE dbo.GetPass
         	@passlen int = 5, 
         	@charset int = 2, 
         	@password varchar(8000) output
         AS
         BEGIN
         	set nocount on
         	if (@passlen > 8000 or @passlen < 1)
         	 select @passlen = 10

         	declare @string varchar(256), @numbers varchar(10), @extra varchar(50),
         	 @stringlen int, @index int

         	select @string = 'ABCDEFGHJKLMNPQRSTUVWXYZ' 
         	select @numbers = '23456789'
         	select @extra = '">_!@#$%&=?<>' 

         	if @charset = 2
         	 select @string = @string + @numbers + @extra
         	else if @charset = 1
         	 select @string = @string + @numbers

         	select @stringlen = len(@string)

         	select @password = ''

         	while (@passlen > 0)
         	begin

         	 select @index = (abs(checksum(newid())) % @stringlen) + 1
         	 select @password = @password + substring(@string, @index, 1)
         	 select @passlen = @passlen - 1
         	end

         END
GO
 CREATE PROCEDURE [dbo].[EDIT_ETAT_CONTROLE_DE_SAISIE_COLLECTE]
          @IDS_BORDEREAU VARCHAR(500) 
          WITH RECOMPILE 
         AS

         BEGIN
          DECLARE
           @LIB_NOM   VARCHAR(35),
           @LIB_PNM   VARCHAR(35),
           @ID_BORDEREAU  INT,
           @COD_BORDEREAU  INT,
           @COD_ADHERENT  INT,
           @LIB_RAISON_SOCIALE VARCHAR(50),
           @ID_POSTE_VERSEMENT INT,
           @ID_VERSEMENT  INT,
           @LIB_BANQUE   VARCHAR(50),
           @NUM_CHEQUE   VARCHAR(10),
           @DAT_SAISIE   DATETIME,
           @ID_PERIODE   INT,
           @TOTAL_HT   FLOAT,
           @GRP_TYPE_VERSEMENT VARCHAR(2),
           @CHQ_CPT   INT,
           @OLD_COD_BORDEREAU INT,
           @OLD_ID_VERSEMENT INT

          SET @OLD_COD_BORDEREAU = 0
          SET @OLD_ID_VERSEMENT = 0
          SET @CHQ_CPT = 0

          CREATE TABLE #TMP_DATA
          (
           LIB_NOM    VARCHAR(35),
           LIB_PNM    VARCHAR(35),
           GRP_TYPE_VERSEMENT VARCHAR(2),
           ID_BORDEREAU  INT,
           COD_BORDEREAU  INT,
           COD_ADHERENT  INT,
           LIB_RAISON_SOCIALE VARCHAR(50),
           ID_POSTE_VERSEMENT INT,
           LIB_BANQUE   VARCHAR(50),
           NUM_CHEQUE   VARCHAR(10),
           DAT_SAISIE   DATETIME,
           ID_PERIODE   INT,
           TOTAL_HT   DECIMAL(18,2),
           NUM_CHEQ   INT
          )

          SELECT
           [DATA] ITEM
          INTO
           #LIST
          FROM
           dbo.F_SPLIT(@IDS_BORDEREAU, ',')

          DECLARE CURSOR_DATA CURSOR FOR
          SELECT
           U.LIB_NOM,
           U.LIB_PNM,
           TV.GRP_TYPE_VERSEMENT,
           B.ID_BORDEREAU,
           B.COD_BORDEREAU,
           ADH.COD_ADHERENT,
           ADH.LIB_RAISON_SOCIALE,
           PV.ID_POSTE_VERSEMENT,
           V.ID_VERSEMENT,
           V.LIB_BANQUE,
           V.NUM_CHEQUE,
           V.DAT_SAISIE,
           PV.ID_PERIODE,
           SUM(PIMP.MNT_HT) as TOTAL_HT
          FROM
           BORDEREAU B
           INNER JOIN UTILISATEUR U
            ON B.ID_UTILISATEUR = U.ID_UTILISATEUR
           INNER JOIN VERSEMENT V
            ON V.ID_BORDEREAU = B.ID_BORDEREAU
           INNER JOIN POSTE_VERSEMENT PV
            ON PV.ID_VERSEMENT = V.ID_VERSEMENT
           INNER JOIN TYPE_VERSEMENT TV
            ON PV.ID_TYPE_VERSEMENT = TV.ID_TYPE_VERSEMENT
           INNER JOIN ADHERENT ADH
            ON PV.ID_ADHERENT_BENEFICIAIRE = ADH.ID_ADHERENT
           INNER JOIN POSTE_IMPUTATION PIMP
            ON PIMP.ID_POSTE_VERSEMENT = PV.ID_POSTE_VERSEMENT
           INNER JOIN PERIODE P
            ON P.ID_PERIODE = PV.ID_PERIODE
           INNER JOIN #List
            ON B.ID_BORDEREAU = #List.Item 
          WHERE
           PV.BLN_ACTIF = 1
           AND V.BLN_ACTIF = 1
          GROUP BY
           U.LIB_NOM,
           U.LIB_PNM,
           B.ID_BORDEREAU,
           B.COD_BORDEREAU,
           TV.GRP_TYPE_VERSEMENT,
           ADH.COD_ADHERENT,
           ADH.LIB_RAISON_SOCIALE,
           V.ID_VERSEMENT,
           PV.ID_POSTE_VERSEMENT,
           V.LIB_BANQUE,
           V.NUM_CHEQUE,
           V.DAT_SAISIE,
           PV.ID_PERIODE
          ORDER BY
           V.ID_VERSEMENT,
           PV.ID_POSTE_VERSEMENT,
           ADH.COD_ADHERENT

          OPEN CURSOR_DATA
          FETCH NEXT FROM CURSOR_DATA
          INTO
           @LIB_NOM,
           @LIB_PNM,
           @GRP_TYPE_VERSEMENT,
           @ID_BORDEREAU,
           @COD_BORDEREAU,
           @COD_ADHERENT,
           @LIB_RAISON_SOCIALE,
           @ID_POSTE_VERSEMENT,
           @ID_VERSEMENT,
           @LIB_BANQUE,
           @NUM_CHEQUE,
           @DAT_SAISIE,
           @ID_PERIODE,
           @TOTAL_HT

          WHILE @@FETCH_STATUS = 0
          BEGIN
           IF (@COD_BORDEREAU <> @OLD_COD_BORDEREAU)
           BEGIN
            SET @CHQ_CPT = 0
            SET @OLD_COD_BORDEREAU = @COD_BORDEREAU
           END

           IF (@ID_VERSEMENT <> @OLD_ID_VERSEMENT)
           BEGIN
            SET @CHQ_CPT = @CHQ_CPT + 1
           END

           INSERT INTO
            #TMP_DATA
           VALUES
           (
            @LIB_NOM,
            @LIB_PNM,
            @GRP_TYPE_VERSEMENT,
            @ID_BORDEREAU,
            @COD_BORDEREAU,
            @COD_ADHERENT,
            @LIB_RAISON_SOCIALE,
            @ID_POSTE_VERSEMENT, 
            @LIB_BANQUE,
            @NUM_CHEQUE,
            @DAT_SAISIE,
            @ID_PERIODE,
            @TOTAL_HT,  
            @CHQ_CPT
           )

           FETCH NEXT FROM CURSOR_DATA
           INTO
            @LIB_NOM,
            @LIB_PNM,
            @GRP_TYPE_VERSEMENT,
            @ID_BORDEREAU,
            @COD_BORDEREAU,
            @COD_ADHERENT,
            @LIB_RAISON_SOCIALE,
            @ID_POSTE_VERSEMENT,
            @ID_VERSEMENT,
            @LIB_BANQUE,
            @NUM_CHEQUE,
            @DAT_SAISIE,
            @ID_PERIODE,
            @TOTAL_HT
          END
          CLOSE CURSOR_DATA
          DEALLOCATE CURSOR_DATA

          SELECT
           B.ID_BORDEREAU,
           PV.ID_POSTE_VERSEMENT,
           PIMP.ID_POSTE_IMPUTATION, 
           TA.ID_TYPE_ACTIVITE, 
           A.COD_ACTIVITE,  
           TASS.ID_CHAMP_APPLICATION,
           PIMP.MNT_HT, 
           PIMP.MNT_TVA, 
           PIMP.MNT_TTC 
          INTO
           #TEMP
          FROM
           BORDEREAU B
           INNER JOIN #List
            ON B.ID_BORDEREAU = #List.Item
           INNER JOIN VERSEMENT V
            ON V.ID_BORDEREAU = B.ID_BORDEREAU
           INNER JOIN POSTE_VERSEMENT PV
            ON PV.ID_VERSEMENT = V.ID_VERSEMENT
           LEFT OUTER JOIN R20
            ON R20.ID_PERIODE = PV.ID_PERIODE
             AND R20.ID_ADHERENT = PV.ID_ADHERENT_BENEFICIAIRE
           LEFT OUTER JOIN TYPE_ASSUJETISSEMENT TASS
            ON R20.ID_TYPE_ASSUJETISSEMENT = TASS.ID_TYPE_ASSUJETISSEMENT
           INNER JOIN POSTE_IMPUTATION PIMP
            ON PIMP.ID_POSTE_VERSEMENT = PV.ID_POSTE_VERSEMENT
           INNER JOIN ACTIVITE A
            ON PIMP.ID_ACTIVITE = A.ID_ACTIVITE
           INNER JOIN TYPE_ACTIVITE TA
            ON A.ID_TYPE_ACTIVITE =  TA.ID_TYPE_ACTIVITE
          WHERE
           PV.BLN_ACTIF = 1
           AND V.BLN_ACTIF = 1
          ORDER BY
           B.ID_BORDEREAU,
           PV.ID_POSTE_VERSEMENT

          SELECT
           #TEMP.ID_BORDEREAU,
           #TEMP.ID_POSTE_VERSEMENT,
           sum(#TEMP.MNT_HT) AS MNT_HT_DSP,
           sum(#TEMP.MNT_TVA) AS MNT_TVA_DSP,
           sum(#TEMP.MNT_TTC) AS MNT_TTC_DSP
          INTO
           #TEMP_DSP
          FROM
           #TEMP
          WHERE
           #TEMP.COD_ACTIVITE = 'DSP'
          GROUP BY
           #TEMP.ID_BORDEREAU,
           #TEMP.ID_POSTE_VERSEMENT   

          SELECT
           #TEMP.ID_BORDEREAU,
           #TEMP.ID_POSTE_VERSEMENT,
           sum(#TEMP.MNT_HT) AS MNT_HT_PRO,
           sum(#TEMP.MNT_TVA) AS MNT_TVA_PRO,
           sum(#TEMP.MNT_TTC) AS MNT_TTC_PRO
          INTO
           #TEMP_PRO
          FROM
           #TEMP
          WHERE
           #TEMP.COD_ACTIVITE = 'PRO'
          GROUP BY
           #TEMP.ID_BORDEREAU,
           #TEMP.ID_POSTE_VERSEMENT

          SELECT
           ID_BORDEREAU,
           ID_POSTE_VERSEMENT,
           sum(MNT_HT) AS MNT_HT_MOINS_10_PLAN,
           sum(MNT_TVA) AS MNT_TVA_MOINS_10_PLAN,
           sum(MNT_TTC) AS MNT_TTC_MOINS_10_PLAN
          INTO
           #TEMP_MOINS_10_PLAN
          FROM
           #TEMP
          WHERE
           COD_ACTIVITE = '-10'
          GROUP BY
           ID_BORDEREAU,
           ID_POSTE_VERSEMENT

          SELECT
           ID_BORDEREAU,
           ID_POSTE_VERSEMENT,
           sum(MNT_HT) AS MNT_HT_1049_PLAN,
           sum(MNT_TVA) AS MNT_TVA_1049_PLAN,
           sum(MNT_TTC) AS MNT_TTC_1049_PLAN
          INTO
           #TEMP_1049_PLAN
          FROM
           #TEMP
          WHERE
           COD_ACTIVITE IN ('10-49','C10-49')
          GROUP BY
           ID_BORDEREAU,
           ID_POSTE_VERSEMENT

          SELECT
           ID_BORDEREAU,
           ID_POSTE_VERSEMENT,
           sum(MNT_HT) AS MNT_HT_50_PLUS_PLAN,
           sum(MNT_TVA) AS MNT_TVA_50_PLUS_PLAN,
           sum(MNT_TTC) AS MNT_TTC_50_PLUS_PLAN
          INTO
           #TEMP_50_PLUS_PLAN
          FROM
           #TEMP
          WHERE
           COD_ACTIVITE IN ('50+','C50+')
          GROUP BY
           ID_BORDEREAU,
           ID_POSTE_VERSEMENT

          SELECT
           ID_BORDEREAU,
           ID_POSTE_VERSEMENT,
           sum(MNT_HT) AS MNT_HT_AUTRE,
           sum(MNT_TVA) AS MNT_TVA_AUTRE,
           sum(MNT_TTC) AS MNT_TTC_AUTRE
          INTO
           #TEMP_AUTRE
          FROM
           #TEMP
          WHERE
           COD_ACTIVITE NOT IN ('DSP', 'PRO','-10','10-49','C10-49','50+','C50+')
          GROUP BY
           ID_BORDEREAU,
           ID_POSTE_VERSEMENT

          SELECT
           #TMP_DATA.LIB_NOM,
           #TMP_DATA.LIB_PNM,
           #TMP_DATA.GRP_TYPE_VERSEMENT,
           #TMP_DATA.ID_BORDEREAU,
           #TMP_DATA.COD_BORDEREAU,
           #TMP_DATA.COD_ADHERENT,
           #TMP_DATA.LIB_RAISON_SOCIALE,
           #TMP_DATA.ID_POSTE_VERSEMENT,
           #TMP_DATA.LIB_BANQUE,
           #TMP_DATA.NUM_CHEQUE,
           #TMP_DATA.DAT_SAISIE,
           #TMP_DATA.TOTAL_HT,
           #TMP_DATA.NUM_CHEQ,
           PERIODE.NUM_ANNEE NUM_ANNEE,
           #TEMP_PRO.MNT_HT_PRO,
           #TEMP_DSP.MNT_HT_DSP,
           #TEMP_MOINS_10_PLAN.MNT_HT_MOINS_10_PLAN,
           #TEMP_AUTRE.MNT_HT_AUTRE,
           #TEMP_1049_PLAN.MNT_HT_1049_PLAN,
           #TEMP_50_PLUS_PLAN.MNT_HT_50_PLUS_PLAN,
           (ISNULL(#TEMP_DSP.MNT_HT_DSP,0)
           + ISNULL(#TEMP_PRO.MNT_HT_PRO,0)
           + ISNULL(#TEMP_MOINS_10_PLAN.MNT_HT_MOINS_10_PLAN,0)
           + ISNULL(#TEMP_1049_PLAN.MNT_HT_1049_PLAN,0)
           + ISNULL(#TEMP_50_PLUS_PLAN.MNT_HT_50_PLUS_PLAN,0)
           + ISNULL(#TEMP_AUTRE.MNT_HT_AUTRE,0)) MNT_HT,
           (ISNULL(#TEMP_DSP.MNT_TVA_DSP,0)
           + ISNULL(#TEMP_PRO.MNT_TVA_PRO,0)
           + ISNULL(#TEMP_MOINS_10_PLAN.MNT_TVA_MOINS_10_PLAN,0)
           + ISNULL(#TEMP_1049_PLAN.MNT_TVA_1049_PLAN,0)
           + ISNULL(#TEMP_50_PLUS_PLAN.MNT_TVA_50_PLUS_PLAN,0)
           + ISNULL(#TEMP_AUTRE.MNT_TVA_AUTRE,0)) MNT_TVA,
           (ISNULL(#TEMP_DSP.MNT_TTC_DSP,0)
           + ISNULL(#TEMP_PRO.MNT_TTC_PRO,0)
           + ISNULL(#TEMP_MOINS_10_PLAN.MNT_TTC_MOINS_10_PLAN,0)
           + ISNULL(#TEMP_1049_PLAN.MNT_TTC_1049_PLAN,0)
           + ISNULL(#TEMP_50_PLUS_PLAN.MNT_TTC_50_PLUS_PLAN,0)
           + ISNULL(#TEMP_AUTRE.MNT_TTC_AUTRE,0)) MNT_TTC
          FROM
           #TMP_DATA
           LEFT OUTER JOIN #TEMP_DSP
            ON #TMP_DATA.ID_POSTE_VERSEMENT = #TEMP_DSP.ID_POSTE_VERSEMENT
           LEFT OUTER JOIN #TEMP_PRO
            ON #TMP_DATA.ID_POSTE_VERSEMENT = #TEMP_PRO.ID_POSTE_VERSEMENT
           LEFT OUTER JOIN #TEMP_MOINS_10_PLAN
            ON #TMP_DATA.ID_POSTE_VERSEMENT = #TEMP_MOINS_10_PLAN.ID_POSTE_VERSEMENT 
           LEFT OUTER JOIN #TEMP_1049_PLAN
            ON #TMP_DATA.ID_POSTE_VERSEMENT = #TEMP_1049_PLAN.ID_POSTE_VERSEMENT
           LEFT OUTER JOIN #TEMP_50_PLUS_PLAN
            ON #TMP_DATA.ID_POSTE_VERSEMENT = #TEMP_50_PLUS_PLAN.ID_POSTE_VERSEMENT
           LEFT OUTER JOIN #TEMP_AUTRE
            ON #TMP_DATA.ID_POSTE_VERSEMENT = #TEMP_AUTRE.ID_POSTE_VERSEMENT
           INNER JOIN PERIODE
            ON #TMP_DATA.ID_PERIODE = PERIODE.ID_PERIODE
          ORDER BY
           #TMP_DATA.ID_BORDEREAU,#TMP_DATA.ID_POSTE_VERSEMENT

          DROP TABLE #TEMP
         END
GO

         CREATE PROCEDURE [dbo].[BATCH_LETTRAGE_FACTURES]
         	@ID_FACTURE int
         AS
         BEGIN
         	IF EXISTS(SELECT * FROM tempdb..sysobjects WHERE id=OBJECT_ID('tempdb..#FACTURES_A_LETTRER'))
         	BEGIN
         		DROP TABLE #FACTURES_A_LETTRER  
         	END

         	SELECT
         		ID_FACTURE, COD_AVOIR
         	INTO
         		#FACTURES_A_LETTRER  
         	FROM
         		VUE_LETTRAGE_FACTURE
         	WHERE 
         	(
         		BLN_LETTRE = 0 
         		AND BLN_NON_LETTRE_A_TORT = 1
         		AND ID_FACTURE = ISNULL(@ID_FACTURE, ID_FACTURE)
         	)

         	UPDATE
         		FACTURE
         	SET
         		BLN_LETTRE = 1
         	FROM
         		FACTURE 
         		INNER JOIN #FACTURES_A_LETTRER
         			ON	FACTURE.ID_FACTURE = #FACTURES_A_LETTRER.ID_FACTURE

         	UPDATE
         		FACTURE
         	SET
         		BLN_LETTRE = 1
         	FROM
         		FACTURE 
         		INNER JOIN #FACTURES_A_LETTRER
         			ON	FACTURE.ID_FACTURE_ASSOCIEE_AVOIR = #FACTURES_A_LETTRER.ID_FACTURE

         	INSERT INTO
         		COMMENTAIRES
         		(
         			[TYPE_OBJET],
         			[ID_OBJET],
         			[DATE],
         			[COMMENTAIRE],
         			[ID_UTILISATEUR]
         		)
              SELECT
         		7, 
         		ID_FACTURE_ASSOCIEE_AVOIR,
         		GetDate(),
         		'lettr‚ par enregistrement de l''AVOIR nø ' + COD_FACTURE,
         		82
         	FROM
         		FACTURE
         		INNER JOIN #FACTURES_A_LETTRER
         			ON	FACTURE.ID_FACTURE_ASSOCIEE_AVOIR = #FACTURES_A_LETTRER.ID_FACTURE

         END
GO
 CREATE PROC SearchAllTables
          (
           @SearchStr nvarchar(100)
          )
          AS
          BEGIN

           CREATE TABLE #Results (ColumnName nvarchar(370), ColumnValue nvarchar(3630))

           SET NOCOUNT ON

           DECLARE @TableName nvarchar(256), @ColumnName nvarchar(128), @SearchStr2 nvarchar(110)
           SET  @TableName = ''
           SET @SearchStr2 = QUOTENAME('%' + @SearchStr + '%','''')

           WHILE @TableName IS NOT NULL
           BEGIN
            SET @ColumnName = ''
            SET @TableName =
            (
             SELECT MIN(QUOTENAME(TABLE_SCHEMA) + '.' + QUOTENAME(TABLE_NAME))
             FROM  INFORMATION_SCHEMA.TABLES
             WHERE   TABLE_TYPE = 'BASE TABLE'
              AND QUOTENAME(TABLE_SCHEMA) + '.' + QUOTENAME(TABLE_NAME) > @TableName
              AND OBJECTPROPERTY(
                OBJECT_ID(
                 QUOTENAME(TABLE_SCHEMA) + '.' + QUOTENAME(TABLE_NAME)
                  ), 'IsMSShipped'
                       ) = 0
            )

            WHILE (@TableName IS NOT NULL) AND (@ColumnName IS NOT NULL)
            BEGIN
             SET @ColumnName =
             (
              SELECT MIN(QUOTENAME(COLUMN_NAME))
              FROM  INFORMATION_SCHEMA.COLUMNS
              WHERE   TABLE_SCHEMA = PARSENAME(@TableName, 2)
               AND TABLE_NAME = PARSENAME(@TableName, 1)
               AND DATA_TYPE IN ('char', 'varchar', 'nchar', 'nvarchar')
               AND QUOTENAME(COLUMN_NAME) > @ColumnName
             )

             IF @ColumnName IS NOT NULL
             BEGIN
              INSERT INTO #Results
              EXEC
              (
               'SELECT ''' + @TableName + '.' + @ColumnName + ''', LEFT(' + @ColumnName + ', 3630)
               FROM ' + @TableName + ' (NOLOCK) ' +
               ' WHERE ' + @ColumnName + ' LIKE ' + @SearchStr2
              )
             END
            END 
           END

           SELECT ColumnName, ColumnValue FROM #Results ORDER BY ColumnValue
          END
GO

         CREATE PROCEDURE [dbo].[DETACHER_REGLT_PRO_DE_SESSION] 
         	@ID_REGLEMENT_PRO INT,
         	@ID_SESSION_PRO INT
         AS
         BEGIN

         	DECLARE @DAT_VALID_REGLEMENT datetime
         	SET @DAT_VALID_REGLEMENT = null
         	SELECT @DAT_VALID_REGLEMENT = DAT_VALID_REGLEMENT 
         	FROM REGLEMENT_PRO 
         	WHERE ID_REGLEMENT_PRO = @ID_REGLEMENT_PRO

         	if (@DAT_VALID_REGLEMENT is null)
         	begin

         		UPDATE SESSION_PRO 
         		SET
         							ID_REGLEMENT_PRO_ADH= NULL
         		WHERE ID_REGLEMENT_PRO_ADH = @ID_REGLEMENT_PRO
         			AND ID_SESSION_PRO <> @ID_SESSION_PRO

         		UPDATE SESSION_PRO
         		SET
         							ID_REGLEMENT_PRO_OF= NULL
         		WHERE ID_REGLEMENT_PRO_OF = @ID_REGLEMENT_PRO
         			AND ID_SESSION_PRO <> @ID_SESSION_PRO
         	end
         END

GO

         CREATE PROCEDURE [dbo].[LEC_PRC_VIR_PRO_SELECTIONNEES_ANNULEES]
         AS
         BEGIN
         	DECLARE @PRC AS decimal(18,2)

         	DECLARE @NUMERATEUR AS decimal(18,2)
         	DECLARE @DENOMINATEUR AS decimal(18,2)
         	SET @NUMERATEUR = 
         	(
         		SELECT 	COUNT(REGLEMENT_PRO.ID_REGLEMENT_PRO)
         		FROM	REGLEMENT_PRO
         		WHERE	REGLEMENT_PRO.BLN_EN_COURS = 1 AND
         				REGLEMENT_PRO.BLN_CRITERE = 1 AND
         				REGLEMENT_PRO.BLN_ACTIF = 0
         	)

         	SET @DENOMINATEUR = 
         	(
         		SELECT 	COUNT(REGLEMENT_PRO.ID_REGLEMENT_PRO)
         		FROM	REGLEMENT_PRO
         		WHERE	REGLEMENT_PRO.BLN_EN_COURS = 1 AND
         				REGLEMENT_PRO.BLN_CRITERE = 1
         	)

         	IF @DENOMINATEUR = 0
         		SET @PRC = 0

         	IF @DENOMINATEUR != 0 
         		SET @PRC = @NUMERATEUR/@DENOMINATEUR

         	SELECT 'Return Value' = COALESCE(ROUND(@PRC,2),0)
         END

GO

         CREATE PROCEDURE [dbo].[LEC_NB_POSTE_COUT_AVEC_ENGAGEMENT]
         	@ID_MODULE_PEC int
         AS
         BEGIN

         	DECLARE @NB AS INT
         	SET @NB = 0

         	SELECT  @NB = COUNT(*)
         	FROM    MODULE_PEC 
         			INNER JOIN POSTE_COUT_ENGAGE ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_ENGAGE.ID_MODULE_PEC 
         			INNER JOIN ENGAGEMENT ON POSTE_COUT_ENGAGE.ID_ENGAGEMENT = ENGAGEMENT.ID_ENGAGEMENT 
         			INNER JOIN TYPE_ENGAGEMENT ON ENGAGEMENT.ID_TYPE_ENGAGEMENT = TYPE_ENGAGEMENT.ID_TYPE_ENGAGEMENT
         	WHERE		ENGAGEMENT.DAT_BAE IS NOT NULL
         			AND TYPE_ENGAGEMENT.ID_TYPE_ENGAGEMENT IN ( 1,3)
         			AND POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL
         			AND MODULE_PEC.ID_MODULE_PEC = @ID_MODULE_PEC

         	SELECT 'Return Value' = COALESCE(@NB,0)
         END

GO

         CREATE PROCEDURE [dbo].[LEC_GRP_PIECES_STAGIAIRE_NOUVEAU] 	

         	@BLN_STAGIAIRE_SESSION INT	
         AS
         BEGIN

         SET @BLN_STAGIAIRE_SESSION = ISNULL(@BLN_STAGIAIRE_SESSION,0)

         SELECT  
         		ID_PIECE_PEC,	
         		LIBL_PIECE_PEC,
         		COD_PIECE_PEC,
         		ID_DISPOSITIF 
         FROM	PIECE_PEC	
         WHERE
         		BLN_ADHERENT = 0 and
         		BLN_SESSION = @BLN_STAGIAIRE_SESSION and
         		BLN_MODULE = (CASE WHEN (@BLN_STAGIAIRE_SESSION = 1) THEN 0 ELSE 1 END) and
         		BLN_POSTE_COUT_REGLE = 0 and
         		BLN_STAGIAIRE = 1 and 
         		BLN_ACTIF = 1 

         END

GO

         CREATE PROCEDURE dbo.CREER_REGULARISATION_PV_PI
         	@ID_ADHERENT_EMETTEUR INTEGER,    
         	@ID_TIERS_EMETTEUR INTEGER,    
         	@ID_ETABLISSEMENT_EMETTEUR INTEGER,  
         	@MNT_VERSEMENT DECIMAL(18,2),  
         	@ID_TYPE_VERSEMENT INT, 
         	@ID_PERIODE INT,  
         	@ID_ACTIVITE INT,  
         	@DONT_FPSPP DECIMAL(18,2)  
         AS  
         BEGIN
         	INSERT INTO VERSEMENT
         	(
         		ID_ADHERENT_EMETTEUR,
         		ID_TIERS_EMETTEUR,
         		ID_ETABLISSEMENT_EMETTEUR,
         		ID_MODE_VERSEMENT,
         		COD_VERSEMENT,
         		DAT_CREATION,
         		MNT_VERSEMENT ,
         		BLN_PB_IMPUTATION ,
         		BLN_ACTIF ,
         		ID_UTILISATEUR ,
         		DAT_SAISIE ,
         		ID_STATUT_VERSEMENT ,
         		BLN_IMPAYE ,
         		BLN_ECHEANCIER ,
         		COM_VERSEMENT
         	)
         	VALUES
         	(
         		@ID_ADHERENT_EMETTEUR,
         		@ID_TIERS_EMETTEUR,
         		@ID_ETABLISSEMENT_EMETTEUR,
         		2,
         		0, 
         		GETDATE(),
         		@MNT_VERSEMENT,
         		0 ,
         		1 ,
         		82 ,
         		getdate(),
         		1 ,
         		0 ,
         		0 ,
         		'R‚gularisation automatique'
         	)

         	DECLARE
         		@ID_VERSEMENT INT

         	SET @ID_VERSEMENT =  scope_identity()

         	UPDATE
         		VERSEMENT
         	SET
         		COD_VERSEMENT = @ID_VERSEMENT
         	WHERE
         		ID_VERSEMENT = @ID_VERSEMENT

         	DECLARE
         		@ID_POSTE_VERSEMENT INT
         	EXEC
         		@ID_POSTE_VERSEMENT = INS_POSTE_VERSEMENT
         		@ID_VERSEMENT = @ID_VERSEMENT, 
         		@ID_ADHERENT_BENEFICIAIRE = @ID_ADHERENT_EMETTEUR, 
         		@ID_TYPE_VERSEMENT = @ID_TYPE_VERSEMENT, 
         		@ID_PERIODE = @ID_PERIODE, 
         		@LIBL_POSTE_VERSEMENT = NULL, 
         		@MNT_POSTE_VERSEMENT = @MNT_VERSEMENT, 
         		@BLN_PB_IMPUTATION = 0, 
         		@BLN_ACTIF = 1, 
         		@ID_ETABLISSEMENT_BENEFICIAIRE = @ID_ETABLISSEMENT_EMETTEUR 

         	DECLARE
         		@ID_POSTE_IMPUTATION INT

         	EXEC
         		@ID_POSTE_IMPUTATION = INS_POSTE_IMPUTATION
         		@ID_ACTIVITE = @ID_ACTIVITE, 
         		@ID_POSTE_VERSEMENT = @ID_POSTE_VERSEMENT, 
         		@ID_VIREMENT_INTERNE_COLLECTE = NULL, 
         		@MNT_HT = @MNT_VERSEMENT, 
         		@MNT_TVA = 0, 
         		@MNT_TTC = @MNT_VERSEMENT, 
         		@DAT_MAJ_CPT_ADH = NULL, 
         		@ID_VIREMENT_INTERNE_COLLECTE_IMPAYE = NULL, 
         		@DONT_REGLE_FPSPP = @DONT_FPSPP 

         	INSERT INTO EVENEMENT
         	(
         		LIBL_EVENEMENT,
         		DAT_EVENEMENT,
         		ID_TYPE_EVENEMENT,
         		ID_VERSEMENT
         	)
         	VALUES
         	(
         		'R‚gularisation Automatique' ,
         		getdate(),
         		5,
         		@ID_VERSEMENT
         	)
         END
GO

         CREATE PROCEDURE [dbo].[LEC_GRP_DEMANDES_CHIFFRAGE]
         	@ID_MODULE int,
         	@ID_POSTE_COUT_REGLE int,
         	@BLN_CREATION bit,
         	@ID_SESSION_PEC int,
         	@ID_ADHERENT int,

         	@ID_ETABLISSEMENT int

         AS
         BEGIN
         	IF @BLN_CREATION IS NULL
         	BEGIN
         		SET @BLN_CREATION = 0
         	END

         	IF @BLN_CREATION = 0
         	BEGIN
         		DECLARE @MNT_REGLE_HT decimal(18,2)
         		DECLARE @NUM_DUREE_HEURE int
         		DECLARE @NUM_STAGIAIRE int
         		DECLARE @SUM_HEURE_STAGIAIRE float

         		SELECT @NUM_DUREE_HEURE = NUM_DUREE_HEURE FROM
         		MODULE_PEC WHERE ID_MODULE_PEC = @ID_MODULE

         		IF (@NUM_DUREE_HEURE IS NULL)
         		BEGIN
         			SET @NUM_DUREE_HEURE = 1
         		END

         		SELECT @MNT_REGLE_HT = MNT_REGLE_HT FROM
         		POSTE_COUT_REGLE WHERE ID_POSTE_COUT_REGLE = @ID_POSTE_COUT_REGLE

         		SELECT @SUM_HEURE_STAGIAIRE = SUM(NB_HEURE_ENGAGE)
         		FROM STAGIAIRE_PEC
         		WHERE ID_MODULE_PEC = @ID_MODULE

         		IF (@MNT_REGLE_HT IS NULL)
         		BEGIN
         			SET @MNT_REGLE_HT = 0
         		END

         		SELECT @NUM_STAGIAIRE = COUNT(*) FROM
         		STAGIAIRE_PEC WHERE ID_MODULE_PEC = @ID_MODULE

         		IF (@NUM_STAGIAIRE IS NULL)
         		BEGIN
         			SET @NUM_STAGIAIRE = 0
         		END

         		Select DISTINCT
         			UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE,
         			STAGIAIRE_PEC.ID_STAGIAIRE_PEC,
         			ADHERENT.LIB_RAISON_SOCIALE AS ADHERENT,
         			INDIVIDU.NOM_INDIVIDU + ' ' + INDIVIDU.PRENOM_INDIVIDU AS STAGIAIRE,
         			DISPOSITIF.LIBL_DISPOSITIF AS DISPOSITIF,
         			UNITE_STAGIAIRE.NB_HEURE_ENGAGE AS NB_HEURE,
         			UNITE_STAGIAIRE.NB_HEURE_REGLE As NB_HEURE_REGLE,
         			case when (@SUM_HEURE_STAGIAIRE > 0)
         				then (@MNT_REGLE_HT * UNITE_STAGIAIRE.NB_HEURE_REGLE) / @SUM_HEURE_STAGIAIRE
         				else 0
         			end AS CALCULATE_TOTAL,
         			0 AS TOTAL,
         			STAGIAIRE_PEC.NB_HEURE_ENGAGE As NB_HEURE_TOTAL,
         			STAGIAIRE_PEC.NB_HEURE_REGLE As NB_HEURE_REGLE_TOTAL,
         			STAGIAIRE_PEC.ID_ETABLISSEMENT,
         			ETABLISSEMENT.ID_ADHERENT,
         			DISPOSITIF.ID_DISPOSITIF,
         			ISNULL(@ID_POSTE_COUT_REGLE,0) AS ID_POSTE_COUT_REGLE,
         			ISNULL(UNITE_STAGIAIRE.NB_HEURE_REM,0) AS NB_HEURE_REM
         		FROM
         			UNITE_STAGIAIRE

         				INNER JOIN STAGIAIRE_PEC		ON UNITE_STAGIAIRE.ID_STAGIAIRE_PEC = STAGIAIRE_PEC.ID_STAGIAIRE_PEC
         				INNER JOIN DISPOSITIF			ON DISPOSITIF.ID_DISPOSITIF = UNITE_STAGIAIRE.ID_DISPOSITIF
         				INNER JOIN  INDIVIDU				ON INDIVIDU.ID_INDIVIDU = STAGIAIRE_PEC.ID_INDIVIDU
         				LEFT JOIN ETABLISSEMENT			ON ETABLISSEMENT.ID_ETABLISSEMENT = STAGIAIRE_PEC.ID_ETABLISSEMENT
         				LEFT JOIN ADHERENT				ON ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         		WHERE
         			STAGIAIRE_PEC.ID_MODULE_PEC = @ID_MODULE
         			AND (@ID_SESSION_PEC is null OR STAGIAIRE_PEC.ID_SESSION_PEC = @ID_SESSION_PEC)
         			AND (@ID_ADHERENT is null or ADHERENT.ID_ADHERENT = @ID_ADHERENT)

         			AND (@ID_ETABLISSEMENT is null or ETABLISSEMENT.ID_ETABLISSEMENT = @ID_ETABLISSEMENT)

         			AND UNITE_STAGIAIRE.NB_HEURE_REGLE > 0
         			AND UNITE_STAGIAIRE.BLN_REFUS = 0
         		ORDER BY
         			INDIVIDU.NOM_INDIVIDU + ' ' + INDIVIDU.PRENOM_INDIVIDU
         	END
         	ELSE
         	BEGIN
         		SELECT DISTINCT
         			UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE,
         			STAGIAIRE_PEC.ID_STAGIAIRE_PEC,
         			ADHERENT.LIB_RAISON_SOCIALE AS ADHERENT,
         			INDIVIDU.NOM_INDIVIDU + ' ' + INDIVIDU.PRENOM_INDIVIDU AS STAGIAIRE,
         			DISPOSITIF.LIBL_DISPOSITIF AS DISPOSITIF,
         			UNITE_STAGIAIRE.NB_HEURE_ENGAGE AS NB_HEURE,
         			UNITE_STAGIAIRE.NB_HEURE_REGLE AS NB_HEURE_REGLE,
         			0 AS CALCULATE_TOTAL,
         			0 AS TOTAL,
         			STAGIAIRE_PEC.NB_HEURE_ENGAGE AS NB_HEURE_TOTAL,
         			STAGIAIRE_PEC.NB_HEURE_REGLE AS NB_HEURE_REGLE_TOTAL,
         			STAGIAIRE_PEC.ID_ETABLISSEMENT,
         			ETABLISSEMENT.ID_ADHERENT,
         			DISPOSITIF.ID_DISPOSITIF,
         			0 AS ID_POSTE_COUT_REGLE,
         			ISNULL(UNITE_STAGIAIRE.NB_HEURE_REM,0) AS NB_HEURE_REM
         		FROM
         			UNITE_STAGIAIRE
         				INNER JOIN STAGIAIRE_PEC	ON STAGIAIRE_PEC.ID_STAGIAIRE_PEC = UNITE_STAGIAIRE.ID_STAGIAIRE_PEC
         				INNER JOIN DISPOSITIF		ON DISPOSITIF.ID_DISPOSITIF = UNITE_STAGIAIRE.ID_DISPOSITIF
         				INNER JOIN INDIVIDU			ON INDIVIDU.ID_INDIVIDU = STAGIAIRE_PEC.ID_INDIVIDU
         				INNER JOIN ETABLISSEMENT	ON ETABLISSEMENT.ID_ETABLISSEMENT = STAGIAIRE_PEC.ID_ETABLISSEMENT
         				INNER JOIN ADHERENT			ON ADHERENT.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
         		WHERE
         			STAGIAIRE_PEC.ID_MODULE_PEC = @ID_MODULE
         			AND UNITE_STAGIAIRE.NB_HEURE_REGLE > 0
         			AND UNITE_STAGIAIRE.BLN_REFUS = 0
         			AND	(@ID_SESSION_PEC is null OR STAGIAIRE_PEC.ID_SESSION_PEC = @ID_SESSION_PEC)
         			AND (@ID_ADHERENT is null or ADHERENT.ID_ADHERENT =@ID_ADHERENT)

         			AND (@ID_ETABLISSEMENT is null or ETABLISSEMENT.ID_ETABLISSEMENT = @ID_ETABLISSEMENT)

         		ORDER BY
         			INDIVIDU.NOM_INDIVIDU + ' ' + INDIVIDU.PRENOM_INDIVIDU
         	END
         END   

GO

         CREATE PROCEDURE [dbo].[LEC_NB_POSTE_COUT_AVEC_REGLEMENT]
         	@ID_MODULE_PEC int
         AS
         BEGIN

         	DECLARE @NB AS INT
         	SET @NB = 0

         	SELECT  @NB = COUNT(*)
         	FROM    MODULE_PEC 
         			INNER JOIN POSTE_COUT_REGLE ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC 

         	WHERE		POSTE_COUT_REGLE.DAT_BAP IS NOT NULL
         			AND MODULE_PEC.ID_MODULE_PEC = @ID_MODULE_PEC

         	SELECT 'Return Value' = COALESCE(@NB,0)
         END

GO
 CREATE PROCEDURE [dbo].[UPD_STAGIAIRE_MODULE_PEC]

          @ID_MODULE_PEC     INT,
          @ID_INDIVIDU     INT,
          @ID_ETABLISSEMENT    INT,
          @TYPE_CONTACT     INT,
          @CATEGORIE_ACTION    INT,
          @CSP       INT,
          @CLASSIFICATION     INT,
          @ID_STATUT      INT,
          @HORARIE_MENSUEL    DECIMAL(18,2),
          @DUREE_PREVUE     DECIMAL(18,2),
          @DUREE_REALISEE     DECIMAL(18,2),
          @MATRICULE      VARCHAR(20),
          @AGENCE       VARCHAR(35),
          @DR        VARCHAR(35),
          @BRUT_CHARGE     DECIMAL(18,2),
          @FORMATEUR_INTERNE    INT,
          @NB_HEURES      DECIMAL(18,2),
          @COM_STAGIAIRE     VARCHAR(255),
          @BLN_TEMPS_PARTIEL    TINYINT,
          @CENTRE_COUT     VARCHAR(50),
          @ID_CODE_INSEE     INT,
          @ID_FAMILLE_PROFESSIONNELLE  INT,
          @SALAIRE_HORAIRE_NET   DECIMAL(18,2),
          @SALAIRE_HORAIRE_BRUT_CHARGE DECIMAL(18,2),
          @MONTANT_BRUT_CHARGE   DECIMAL(18,2),
          @DATE_EMBAUCHE     DATETIME,
          @ID_NIVEAU_AVENANT    INT,
          @ANALYTIQUE_STAGIAIRE   VARCHAR(20),
          @ID_STAGIAIRE_TUTEUR   INT,
          @TIME_STAMP      TIMESTAMP,
          @ID_STAGIAIRE     INT OUTPUT,
          @ID_SESSION      INT,
          @ID_BRANCHE      INT,
          @ID_GROUPE      INT,
          @ID_ACTIVITE     INT,
          @NB_HEURE_REM     DECIMAL(18,2),
          @FONCTION      VARCHAR(100),
          @ID_SUIVI_STAGIAIRE_OBJECTIF_ISSU INT,
          @ID_SUIVI_STAGIAIRE_IMMEDIAT INT,
          @ID_SUIVI_STAGIAIRE_TROIS_MOIS INT
         AS  
         BEGIN 
          IF (@ID_FAMILLE_PROFESSIONNELLE = -1)
          BEGIN
           SET @ID_FAMILLE_PROFESSIONNELLE = NULL
          END

          IF (@ID_CODE_INSEE = -1)
          BEGIN
           SET @ID_CODE_INSEE = NULL
          END

          IF (@TYPE_CONTACT = -1)
          BEGIN
           SET @TYPE_CONTACT = NULL
          END

          IF (@CLASSIFICATION = -1)
          BEGIN
           SET @CLASSIFICATION = NULL
          END

          IF (@ID_ACTIVITE < 0)
          BEGIN
           SET @ID_ACTIVITE = NULL
          END

          DECLARE
           @COUNT INT

          SELECT
           @COUNT = COUNT(*)
          FROM
           STAGIAIRE_PEC
          WHERE
           ID_STAGIAIRE_PEC = @ID_STAGIAIRE
           AND ID_MODULE_PEC = @ID_MODULE_PEC

          IF (@COUNT > 0)
          BEGIN
           DECLARE
            @ID_ETABLISSEMENT_OLD INT

           SELECT
            @ID_ETABLISSEMENT_OLD = ID_ETABLISSEMENT
           FROM
            STAGIAIRE_PEC
           WHERE
            ID_STAGIAIRE_PEC = @ID_STAGIAIRE

           UPDATE
            STAGIAIRE_PEC
           SET
            ID_INDIVIDU = @ID_INDIVIDU,
            ID_MODULE_PEC = @ID_MODULE_PEC,
            ID_TYPE_CONTRAT = @TYPE_CONTACT,
            ID_CATEGORIE_ACTION = @CATEGORIE_ACTION,
            ID_CLASSIFICATION = @CLASSIFICATION,
            ID_CSP    = @CSP,
            ID_STATUT   = @ID_STATUT ,
            ID_ETABLISSEMENT = @ID_ETABLISSEMENT,
            BLN_FORMATEUR_INTERNE = @FORMATEUR_INTERNE,
            NB_HEURES_HORS_TT  = @NB_HEURES,
            NUM_DUREE_MENSUELLE_TRAVAIL = @HORARIE_MENSUEL,
            NB_HEURE_ENGAGE  = @DUREE_PREVUE,
            NB_HEURE_REGLE  = @DUREE_REALISEE,
            MATRICULE_SALARIE = @MATRICULE,
            LIB_AGENCE   = @AGENCE,
            LIB_DR    = @DR,
            SALAIRE_HORAIRE_CHARGE = @BRUT_CHARGE,
            COM_STAGIAIRE_PEC = @COM_STAGIAIRE,
            BLN_TEMPS_PARTIEL = @BLN_TEMPS_PARTIEL,
            CENTRE_COUT = @CENTRE_COUT,
            ID_CODE_INSEE = @ID_CODE_INSEE,
            ID_FAMILLE_PROFESSIONNELLE = @ID_FAMILLE_PROFESSIONNELLE,
            SALAIRE_HORAIRE_NET = @SALAIRE_HORAIRE_NET,
            SALAIRE_HORAIRE_BRUT_CHARGE = @SALAIRE_HORAIRE_BRUT_CHARGE,
            MONTANT_BRUT_CHARGE = @MONTANT_BRUT_CHARGE,
            DATE_EMBAUCHE = @DATE_EMBAUCHE,
            ANALYTIQUE_STAGIAIRE = @ANALYTIQUE_STAGIAIRE,
            ID_STAGIAIRE_TUTEUR = @ID_STAGIAIRE_TUTEUR,
            ID_BRANCHE = @ID_BRANCHE,
            ID_GROUPE = @ID_GROUPE,
            ID_NIVEAU_AVENANT = @ID_NIVEAU_AVENANT,
            NB_HEURE_REM = @NB_HEURE_REM,
            FONCTION   = @FONCTION,
            ID_SUIVI_STAGIAIRE_OBJECTIF_ISSU = @ID_SUIVI_STAGIAIRE_OBJECTIF_ISSU ,
            ID_SUIVI_STAGIAIRE_IMMEDIAT = @ID_SUIVI_STAGIAIRE_IMMEDIAT,
            ID_SUIVI_STAGIAIRE_TROIS_MOIS = @ID_SUIVI_STAGIAIRE_TROIS_MOIS 
           WHERE
            ID_STAGIAIRE_PEC = @ID_STAGIAIRE 

           PRINT @FORMATEUR_INTERNE

           IF ( @FORMATEUR_INTERNE > 0)
           BEGIN
            UPDATE
             SP
            SET
             SP.ID_STAGIAIRE_TUTEUR = @ID_STAGIAIRE
            FROM
             STAGIAIRE_PEC SP
             INNER JOIN MODULE_PEC MP
              ON MP.ID_MODULE_PEC = SP.ID_MODULE_PEC
            WHERE
             MP.ID_ACTION_PEC IN (SELECT ID_ACTION_PEC FROM MODULE_PEC WHERE ID_MODULE_PEC = @ID_MODULE_PEC)
             AND MP.ID_MODULE_PEC <> @ID_MODULE_PEC
           END 

           IF (@ID_NIVEAU_AVENANT = 0)
           BEGIN
            UPDATE
             STAGIAIRE_PEC
            SET
             ID_NIVEAU_AVENANT = NULL
            WHERE
             ID_STAGIAIRE_PEC = @ID_STAGIAIRE 
           END

           IF (@ID_SESSION IS NULL OR @ID_SESSION = 0)
           BEGIN
            UPDATE
             POSTE_COUT_ENGAGE
            SET
             BLN_OK_FINANCEMENT = 0
            WHERE
             ID_MODULE_PEC = @ID_MODULE_PEC
             AND DAT_DESENGAGEMENT IS NULL
             AND ID_ENGAGEMENT IS NULL 
           END

           IF ((@ID_ETABLISSEMENT_OLD <> @ID_ETABLISSEMENT) OR @DUREE_PREVUE = 0)
           BEGIN
            IF (@ID_ETABLISSEMENT_OLD <> @ID_ETABLISSEMENT)
            BEGIN

             IF (@ID_ACTIVITE IS NULL)
             BEGIN

              SELECT
               @ID_ACTIVITE = ID_ACTIVITE
              FROM
               STAGIAIRE_PEC
              WHERE
               STAGIAIRE_PEC.ID_MODULE_PEC = @ID_MODULE_PEC
               AND STAGIAIRE_PEC.ID_ETABLISSEMENT = @ID_ETABLISSEMENT
               AND STAGIAIRE_PEC.ID_STAGIAIRE_PEC <> @ID_STAGIAIRE
               AND STAGIAIRE_PEC.ID_SESSION_PEC IS NULL
              ORDER BY
               ID_STAGIAIRE_PEC

              IF (@ID_ACTIVITE IS NULL)
               SELECT
                @ID_ACTIVITE = R19.ID_ACTIVITE 
               FROM
                MODULE_PEC 
                INNER JOIN ETABLISSEMENT
                 ON ETABLISSEMENT.ID_ETABLISSEMENT = @ID_ETABLISSEMENT
                INNER JOIN R19
                 ON R19.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT
                  AND R19.ID_PERIODE = MODULE_PEC.ID_PERIODE
                  AND R19.ID_ACTIVITE IN (SELECT ID_ACTIVITE FROM GET_IDS_ACTIVITE_BY_COD_TYPE_ACTIVITE('PLAN')) 
               WHERE
                MODULE_PEC.ID_MODULE_PEC = @ID_MODULE_PEC 

              IF (@ID_ACTIVITE IS NULL) 
              BEGIN
               RAISERROR(N'Impossible d''attacher un ou plusieurs stagiaires : leur adh‚rent n''a pas d''activit‚', 16, 1)
              END

             END  

             UPDATE
              STAGIAIRE_PEC
             SET
              ID_ACTIVITE = @ID_ACTIVITE
             WHERE
              ID_STAGIAIRE_PEC = @ID_STAGIAIRE
            END

            DECLARE
             @SUM_PFUS DECIMAL(18,2)

            SELECT
             @SUM_PFUS = -1 * SUM(MNT_PLAN_FINANCEMENT_US)
            FROM
             PLAN_FINANCEMENT_US
             INNER JOIN  UNITE_STAGIAIRE
              ON UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE = PLAN_FINANCEMENT_US.ID_UNITE_STAGIAIRE
            WHERE
             UNITE_STAGIAIRE.ID_STAGIAIRE_PEC = @ID_STAGIAIRE

            UPDATE
             PLAN_FINANCEMENT_US
            SET
             MNT_PLAN_FINANCEMENT_US = 0,
             MNT_PLAN_FINANCEMENT_US_TVA = 0,
             COM_PLAN_FINANCEMENT_US = 'REMIS · 0 PENDANT CHANGEMENT D''TABLISSEMENT'
            FROM
             PLAN_FINANCEMENT_US
             INNER JOIN  UNITE_STAGIAIRE
              ON UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE = PLAN_FINANCEMENT_US.ID_UNITE_STAGIAIRE
             INNER JOIN POSTE_COUT_ENGAGE
              ON POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE = PLAN_FINANCEMENT_US.ID_POSTE_COUT_ENGAGE
            WHERE
             UNITE_STAGIAIRE.ID_STAGIAIRE_PEC = @ID_STAGIAIRE
             AND
             (
              MNT_PLAN_FINANCEMENT_US <>0
              OR MNT_PLAN_FINANCEMENT_US_TVA <> 0
             )
             AND DAT_DESENGAGEMENT IS NULL
             AND ID_ENGAGEMENT IS NULL
           END

           SELECT
            S.ID_STAGIAIRE_PEC
           INTO
            #SEARCH_SESSION
           FROM
            STAGIAIRE_PEC S
            INNER JOIN ETABLISSEMENT E1
             ON E1.ID_ETABLISSEMENT = S.ID_ETABLISSEMENT
            INNER JOIN STAGIAIRE_PEC S2
             ON S2.ID_MODULE_PEC = S.ID_MODULE_PEC
              AND S2.ID_INDIVIDU  = S.ID_INDIVIDU
              AND S2.ID_SESSION_PEC IS NULL
            INNER JOIN ETABLISSEMENT E2
             ON E2.ID_ETABLISSEMENT = S2.ID_ETABLISSEMENT
              AND E2.ID_ADHERENT = E1.ID_ADHERENT
           WHERE
            S2.ID_STAGIAIRE_PEC = @ID_STAGIAIRE AND 
            S.ID_SESSION_PEC IS NOT NULL

           IF (EXISTS (SELECT * FROM #SEARCH_SESSION))
           BEGIN
            UPDATE
             STAGIAIRE_PEC
            SET 
             ID_TYPE_CONTRAT  = @TYPE_CONTACT,
             ID_CATEGORIE_ACTION = @CATEGORIE_ACTION,
             ID_CLASSIFICATION = @CLASSIFICATION,
             ID_CSP    = @CSP,
             ID_STATUT   = @ID_STATUT ,
             ID_ETABLISSEMENT = @ID_ETABLISSEMENT,
             NUM_DUREE_MENSUELLE_TRAVAIL = @HORARIE_MENSUEL,
             SALAIRE_HORAIRE_CHARGE  = @BRUT_CHARGE,
             MATRICULE_SALARIE = @MATRICULE,
             LIB_AGENCE   = @AGENCE,
             LIB_DR    = @DR,
             NB_HEURE_REM  = @NB_HEURE_REM,
             FONCTION   = @FONCTION,
             ID_SUIVI_STAGIAIRE_OBJECTIF_ISSU = @ID_SUIVI_STAGIAIRE_OBJECTIF_ISSU ,
             ID_SUIVI_STAGIAIRE_IMMEDIAT = @ID_SUIVI_STAGIAIRE_IMMEDIAT,
             ID_SUIVI_STAGIAIRE_TROIS_MOIS = @ID_SUIVI_STAGIAIRE_TROIS_MOIS 
            WHERE
             ID_STAGIAIRE_PEC IN (SELECT ID_STAGIAIRE_PEC FROM #SEARCH_SESSION)
           END
          END
          ELSE
          BEGIN
           EXEC INS_STAGIAIRE_MODULE_PEC
            @ID_MODULE_PEC,
            @ID_INDIVIDU,
            @ID_ETABLISSEMENT,
            @TYPE_CONTACT,
            @CATEGORIE_ACTION,
            @CSP,
            @CLASSIFICATION,
            @MATRICULE,
            @ID_STATUT,
            @AGENCE,
            @DR,
            @FORMATEUR_INTERNE,
            @HORARIE_MENSUEL,
            @DUREE_PREVUE,
            @DUREE_REALISEE,
            @NB_HEURES,
            @BRUT_CHARGE,
            @COM_STAGIAIRE,
            @BLN_TEMPS_PARTIEL,
            @CENTRE_COUT,
            @ID_CODE_INSEE,
            @ID_FAMILLE_PROFESSIONNELLE,
            @SALAIRE_HORAIRE_NET,    
            @SALAIRE_HORAIRE_BRUT_CHARGE,
            @MONTANT_BRUT_CHARGE,
            @DATE_EMBAUCHE,
            @ID_NIVEAU_AVENANT,    
            @ANALYTIQUE_STAGIAIRE,
            @ID_STAGIAIRE_TUTEUR,
            @ID_STAGIAIRE OUTPUT,
            @ID_SESSION,
            @ID_BRANCHE,
            @ID_GROUPE,   
            @ID_ACTIVITE,
            @NB_HEURE_REM,
            @FONCTION,
            @ID_SUIVI_STAGIAIRE_OBJECTIF_ISSU ,
            @ID_SUIVI_STAGIAIRE_IMMEDIAT ,
            @ID_SUIVI_STAGIAIRE_TROIS_MOIS 
          END
         END

GO

CREATE PROCEDURE [dbo].[UPD_BON_A_PAYER]
	@BAP tinyint,
	@ID_POSTE_COUT_REGLE	int,
	@ID_SESSION				int,
	@DAT_BAP				datetime,
	@ID_TYPE_VALIDATION		int
AS  
         BEGIN

         	declare @ID_PCE int
         	set @ID_PCE = null
         	select @ID_PCE = POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE
	from POSTE_COUT_ENGAGE
		inner join POSTE_COUT_REGLE on 
			(POSTE_COUT_ENGAGE.ID_SOUS_TYPE_COUT = POSTE_COUT_REGLE.ID_SOUS_TYPE_COUT AND
			POSTE_COUT_ENGAGE.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC)
	where	
		POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE = @ID_POSTE_COUT_REGLE AND
		POSTE_COUT_ENGAGE.ID_ENGAGEMENT IS NOT NULL AND
		POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL

         	if @ID_PCE is not null
         	begin
         		UPDATE POSTE_COUT_REGLE
         		SET	
         			ID_SESSION = @ID_SESSION,

         			DAT_BAP = case when (DAT_BAP is null) then @DAT_BAP else DAT_BAP end,
         			ID_TYPE_VALIDATION = @ID_TYPE_VALIDATION
         		WHERE 
         			ID_POSTE_COUT_REGLE = @ID_POSTE_COUT_REGLE

         			and ID_TYPE_VALIDATION <> 8

         		if (@@rowcount =0)
         			UPDATE POSTE_COUT_REGLE
         			SET	ID_SESSION = ID_SESSION
         			WHERE ID_POSTE_COUT_REGLE = @ID_POSTE_COUT_REGLE
         	end

         	else
         		UPDATE POSTE_COUT_REGLE    
		SET 
			ID_TYPE_VALIDATION = 8, 
			ID_ETAT_PEC = 13    
		WHERE 
         			ID_POSTE_COUT_REGLE = @ID_POSTE_COUT_REGLE
         END

GO
 CREATE PROCEDURE [dbo].[INS_STAGIAIRE_MODULE_PEC]
          @ID_MODULE_PEC  int,
          @ID_INDIVIDU  int,
          @ID_ETABLISSEMENT int,
          @TYPE_CONTACT  int,
          @CATEGORIE_ACTION int,
          @CSP    int,
          @CLASSIFICATION  int,
          @MATRICULE   varchar(20),
          @ID_STATUT   int,
          @AGENCE    varchar(35),
          @DR     varchar(35),
          @FORMATEUR_INTERNE int,
          @HORARIE_MENSUEL decimal(18,2),
          @DUREE_PREVUE  decimal(18,2),
          @DUREE_REALISEE  decimal(18,2),
          @NB_HEURES   decimal(18,2),
          @BRUT_CHARGE  decimal(18,2),
          @COM_STAGIAIRE  varchar(255),
          @BLN_TEMPS_PARTIEL tinyint,
          @CENTRE_COUT  varchar(50),
          @ID_CODE_INSEE  int,
          @ID_FAMILLE_PROFESSIONNELLE int,
          @SALAIRE_HORAIRE_NET decimal(18,2),
          @SALAIRE_HORAIRE_BRUT_CHARGE decimal(18,2),
          @MONTANT_BRUT_CHARGE decimal(18,2),
          @DATE_EMBAUCHE  datetime,
          @ID_NIVEAU_AVENANT int,
          @ANALYTIQUE_STAGIAIRE varchar(20),
          @ID_STAGIAIRE_TUTEUR int,
          @ID_STAGIAIRE  int output,
          @ID_SESSION   int,
          @ID_BRANCHE   int,
          @ID_GROUPE   int,
          @ID_ACTIVITE  INT,
          @NB_HEURE_REM  decimal(18,2),
          @FONCTION   varchar(100),
          @ID_SUIVI_STAGIAIRE_OBJECTIF_ISSU INT,
          @ID_SUIVI_STAGIAIRE_IMMEDIAT INT,
          @ID_SUIVI_STAGIAIRE_TROIS_MOIS INT
         AS  

         BEGIN

          IF (@ID_ACTIVITE < 0)
          BEGIN
           SET @ID_ACTIVITE = NULL
          END

          if (@ID_ACTIVITE IS NULL)
           select @ID_ACTIVITE = ID_ACTIVITE
           from stagiaire_pec
           where stagiaire_pec.id_module_pec = @ID_MODULE_PEC
           and stagiaire_pec.id_etablissement = @ID_ETABLISSEMENT
           and stagiaire_pec.id_session_pec is null
           order by id_stagiaire_pec

          if (@ID_ACTIVITE IS NULL) 
           select @ID_ACTIVITE = R19.ID_ACTIVITE 
           from MODULE_PEC 
            inner join ETABLISSEMENT on (ETABLISSEMENT.ID_ETABLISSEMENT = @ID_ETABLISSEMENT)
            inner join R19 on ( R19.ID_ADHERENT = ETABLISSEMENT.ID_ADHERENT AND 
                 R19.ID_PERIODE = MODULE_PEC.ID_PERIODE and 
                 R19.ID_ACTIVITE  in (select id_activite from GET_IDS_ACTIVITE_BY_COD_TYPE_ACTIVITE('PLAN')) 
                 )
           where MODULE_PEC.ID_MODULE_PEC = @ID_MODULE_PEC 

          IF (@ID_ACTIVITE IS NULL) 
          BEGIN
           RAISERROR(N'Impossible d''attacher un ou plusieurs stagiaires : leur adh‚rent n''a pas d''activit‚', 16, 1)
          END

         INSERT INTO STAGIAIRE_PEC with (rowlock)
          (
           COD_STAGIAIRE_PEC,
           ID_INDIVIDU,
           ID_MODULE_PEC,
           ID_TYPE_CONTRAT,
           ID_CATEGORIE_ACTION,
           ID_CLASSIFICATION,
           ID_CSP,
           ID_STATUT,
           ID_ETABLISSEMENT,
           BLN_FORMATEUR_INTERNE,
           NB_HEURES_HORS_TT,
           NUM_DUREE_MENSUELLE_TRAVAIL,
           NB_HEURE_ENGAGE,
           NB_HEURE_REGLE,
           MATRICULE_SALARIE,
           LIB_AGENCE,
           LIB_DR,
           SALAIRE_HORAIRE_CHARGE,
           COM_STAGIAIRE_PEC,
           BLN_TEMPS_PARTIEL,
           CENTRE_COUT,
           ID_CODE_INSEE,
           ID_FAMILLE_PROFESSIONNELLE,
           SALAIRE_HORAIRE_NET,
           SALAIRE_HORAIRE_BRUT_CHARGE,
           MONTANT_BRUT_CHARGE,
           DATE_EMBAUCHE,
           ID_NIVEAU_AVENANT,
           ANALYTIQUE_STAGIAIRE,
           ID_STAGIAIRE_TUTEUR,
           ID_SESSION_PEC,
           ID_BRANCHE,
           ID_GROUPE,
           ID_ACTIVITE,
           NB_HEURE_REM,
           FONCTION,
           ID_SUIVI_STAGIAIRE_OBJECTIF_ISSU ,
           ID_SUIVI_STAGIAIRE_IMMEDIAT,
           ID_SUIVI_STAGIAIRE_TROIS_MOIS 
          )  
         VALUES  
          (
           0,
           @ID_INDIVIDU,
           @ID_MODULE_PEC,
           @TYPE_CONTACT,
           @CATEGORIE_ACTION,
           @CLASSIFICATION,
           @CSP,
           @ID_STATUT,
           @ID_ETABLISSEMENT,
           @FORMATEUR_INTERNE,
           @NB_HEURES,
           @HORARIE_MENSUEL,
           @DUREE_PREVUE,
           @DUREE_REALISEE,
           @MATRICULE ,
           @AGENCE ,
           @DR, 
           @BRUT_CHARGE,
           @COM_STAGIAIRE,
           @BLN_TEMPS_PARTIEL,
           @CENTRE_COUT,
           @ID_CODE_INSEE,
           @ID_FAMILLE_PROFESSIONNELLE,
           @SALAIRE_HORAIRE_NET,
           @SALAIRE_HORAIRE_BRUT_CHARGE,
           @MONTANT_BRUT_CHARGE,
           @DATE_EMBAUCHE,
           @ID_NIVEAU_AVENANT,
           @ANALYTIQUE_STAGIAIRE,
           @ID_STAGIAIRE_TUTEUR,
           @ID_SESSION,
           @ID_BRANCHE,
           @ID_GROUPE,
           @ID_ACTIVITE,
           @NB_HEURE_REM,
           @FONCTION,
           @ID_SUIVI_STAGIAIRE_OBJECTIF_ISSU ,
           @ID_SUIVI_STAGIAIRE_IMMEDIAT ,
           @ID_SUIVI_STAGIAIRE_TROIS_MOIS 
          )

         DECLARE @ID_STAGIAIRE_PEC INT
         SET @ID_STAGIAIRE_PEC = @@IDENTITY
         UPDATE STAGIAIRE_PEC
         SET  COD_STAGIAIRE_PEC = @ID_STAGIAIRE_PEC
         WHERE ID_STAGIAIRE_PEC = @ID_STAGIAIRE_PEC

         IF (@ID_SESSION is null or @ID_SESSION = 0)
         BEGIN
          UPDATE POSTE_COUT_ENGAGE SET BLN_OK_FINANCEMENT = 0
           WHERE ID_MODULE_PEC = @ID_MODULE_PEC
            AND DAT_DESENGAGEMENT IS NULL
            AND ID_ENGAGEMENT IS NULL 

         END
         SET @ID_STAGIAIRE = @ID_STAGIAIRE_PEC

         PRINT @FORMATEUR_INTERNE

         IF ( @FORMATEUR_INTERNE > 0)
         BEGIN
          UPDATE sp
          SET sp.ID_STAGIAIRE_TUTEUR = @ID_STAGIAIRE
          FROM STAGIAIRE_PEC sp
          INNER JOIN MODULE_PEC mp on mp.ID_MODULE_PEC = sp.ID_MODULE_PEC
          WHERE mp.ID_ACTION_PEC in (SELECT ID_ACTION_PEC FROM MODULE_PEC WHERE ID_MODULE_PEC = @ID_MODULE_PEC)
          AND mp.ID_MODULE_PEC <> @ID_MODULE_PEC
         END 

         SELECT @ID_STAGIAIRE AS ID

         END
GO

         CREATE PROCEDURE [dbo].[INS_TYPE_EVENEMENT_ADMIN]
         			@COD_TYPE_EVENEMENT_ADMIN	VARCHAR(20),
         			@LIBC_TYPE_EVENEMENT_ADMIN	VARCHAR(20), 
         			@LIBL_TYPE_EVENEMENT_ADMIN	VARCHAR(50), 
         			@BLN_PRIO					TINYINT, 
         			@BLN_ACTIF					TINYINT, 
         			@COM_TYPE_EVENEMENT_ADMIN	VARCHAR(255), 
         			@NUM_ORDRE					INT, 
         			@ID_UTILISATEUR				INT	
         AS 
         BEGIN
         	INSERT INTO TYPE_EVENEMENT_ADMIN
         			(
         				COD_TYPE_EVENEMENT_ADMIN, 
         				LIBC_TYPE_EVENEMENT_ADMIN, 
         				LIBL_TYPE_EVENEMENT_ADMIN, 
         				BLN_PRIO, 
         				BLN_ACTIF, 
         				DAT_MODIF, 
         				COM_TYPE_EVENEMENT_ADMIN, 
         				NUM_ORDRE, 
         				ID_UTILISATEUR, 
         				DAT_CREATION
         			)
         	VALUES
         			(
         				@COD_TYPE_EVENEMENT_ADMIN, 
         				@LIBC_TYPE_EVENEMENT_ADMIN, 
         				@LIBL_TYPE_EVENEMENT_ADMIN, 
         				@BLN_PRIO, 
         				@BLN_ACTIF, 
         				GETDATE(), 
         				@COM_TYPE_EVENEMENT_ADMIN, 
         				@NUM_ORDRE, 
         				@ID_UTILISATEUR, 
         				GETDATE()	
         			)

         	return @@IDENTITY
         END
GO
