         CREATE PROCEDURE [dbo].[LEC_DET_ACTION_PRISES_SESSION]
         	@ID_ACTION int
         AS
         BEGIN

         	DECLARE @IS_ENGAGE	INT
         	DECLARE @IS_PAS_ENTIEREMENT_ENGAGEE BIT
         	DECLARE @NB_PCR		INT
         	DECLARE @NB_PCE		INT

         	SELECT @IS_ENGAGE = COUNT(*)
         	FROM ENGAGEMENT
         	WHERE ID_ACTION_PEC = @ID_ACTION

         	SET @IS_PAS_ENTIEREMENT_ENGAGEE=0

               IF (dbo.SiActionPecPasEntierementEngagee(@ID_ACTION)>0)
         	BEGIN
         		SET @IS_PAS_ENTIEREMENT_ENGAGEE=1
         	END

         	select @NB_PCR = count(*) from POSTE_COUT_REGLE
         		INNER JOIN SESSION_PEC		on	SESSION_PEC.ID_SESSION_PEC	= POSTE_COUT_REGLE.ID_SESSION_PEC
         		INNER JOIN MODULE_PEC		on	MODULE_PEC.ID_MODULE_PEC	= SESSION_PEC.ID_MODULE_PEC
         	where id_action_pec = @ID_ACTION

         	SELECT  @NB_PCE = COUNT(*)
         	FROM	POSTE_COUT_ENGAGE
         			INNER JOIN ENGAGEMENT ON ENGAGEMENT.ID_ENGAGEMENT = POSTE_COUT_ENGAGE.ID_ENGAGEMENT
         			INNER JOIN MODULE_PEC ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_ENGAGE.ID_MODULE_PEC
         			INNER JOIN  ACTION_PEC ON ACTION_PEC.ID_ACTION_PEC = MODULE_PEC.ID_ACTION_PEC
         	WHERE	ACTION_PEC.ID_ACTION_PEC = @ID_ACTION

         	select 
         		ACTION_PEC.ID_ACTION_PEC,
         		ACTION_PEC.COD_ACTION_PEC AS NUM_ACTION, 
         		ACTION_PEC.LIBL_ACTION_PEC AS LIBL_ACTION, 
         		ACTION_PEC.ID_THEME,
         		ACTION_PEC.ID_NIVEAU,
         		ACTION_PEC.ID_SANCTION,
         		ACTION_PEC.DAT_DEB_ACTION_PEC AS DATE_DEBUT, 
         		ACTION_PEC.DAT_FIN_ACTION_PEC AS DATE_FIN,
         		ACTION_PEC.NUM_DUREE_JOUR, 
         		ACTION_PEC.NUM_DUREE_HEURE,
         		ACTION_PEC.ID_OPERATION_FINANCIERE as ID_OPERATION,	
         		ACTION_PEC.ID_AGENCE,
         		ACTION_PEC.CIBLE_ACTION AS CIBLE_ACTION, 
         		ACTION_PEC.DAT_CREATION, 
         		ACTION_PEC.DAT_MODIF, 
         		ACTION_PEC.ID_UTILISATEUR,
         		UTILISATEUR.COD_UTIL AS PAR,
         		UCREATEUR.COD_UTIL as CREATEUR,
         		ACTION_PEC.BLN_ACTIF AS ACTIF,
         		ROUND (ACTION_PEC.NUM_DUREE_JOUR - 
         			isnull((Select SUM(MODULE_PEC .NUM_DUREE_JOUR)
         				from MODULE_PEC
         				WHERE MODULE_PEC.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC
         					AND MODULE_PEC.BLN_ACTIF = 1
         				GROUP BY MODULE_PEC .ID_ACTION_PEC),0), 2)
         			as MAX_DUREE_JOUR,
         		ROUND (ACTION_PEC.NUM_DUREE_HEURE -
         			ISNULL((SELECT SUM(MODULE_PEC.NUM_DUREE_HEURE)
         					FROM MODULE_PEC
         					WHERE MODULE_PEC.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC
         						AND MODULE_PEC.BLN_ACTIF = 1
         					GROUP BY MODULE_PEC.ID_ACTION_PEC),0), 2)
         			AS MAX_DUREE_HEURE,
         		ACTION_PEC.BLN_CYCLE_COURT,
         		ISNULL((SELECT SUM(MODULE_PEC.NUM_DUREE_HEURE)
         					FROM MODULE_PEC
         					WHERE MODULE_PEC.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC
         						AND MODULE_PEC.BLN_ACTIF = 1
         					GROUP BY MODULE_PEC.ID_ACTION_PEC),0)
         		AS TOTAL_DUREE_UTILISE,
         		ACTION_PEC.COM_ACTION_PEC,
         		(SELECT TOP 1 NUM_DUREE_JOUR_ACTION_MAX
         			FROM PARAMETRES) AS NUM_DUREE_JOUR_ACTION_MAX,
         		(SELECT TOP 1 NUM_DUREE_HEURE_ACTION_MAX
         			FROM PARAMETRES) AS NUM_DUREE_HUERE_ACTION_MAX,
         		ACTION_PEC.ID_FORMACODE,
         		CASE 
         			WHEN @IS_ENGAGE > 0 THEN 1
         			ELSE 0 
         		END			AS ENGAGE,
         		ACTION_PEC.TIME_STAMP,
         		ACTION_PEC.DAT_CLOTURE,
                 @IS_PAS_ENTIEREMENT_ENGAGEE AS IS_PAS_ENTIEREMENT_ENGAGEE,
         		@NB_PCR AS NB_PCR,
         		@NB_PCE AS NB_PCE,
         		ACTION_PEC.ANNEE_ACTION_PEC,
         		ACTION_PEC.DAT_RECU,
         		ACTION_PEC.ID_DECISION_ACTION_PEC,
         		ACTION_PEC.AXE,
         		ACTION_PEC.DOMAINE,
         		dbo.GetActionPECCode(ACTION_PEC.COD_ACTION_PEC,ACTION_PEC.ANNEE_ACTION_PEC) AS CODE_ACTION,
         		ACTION_PEC.ID_CHARGEE_MISSION,
         		isnull(ACTION_PEC.BLN_REPRISE_ADHOC,0) AS BLN_REPRISE_ADHOC,
         		(SELECT  COUNT(*) + 1
         		FROM MODULE_PEC
         		WHERE ID_ACTION_PEC=@ID_ACTION) AS NEXT_MODULE_NUMBER,
         		ACTION_PEC.ID_AGENCE_CLOTURE,
         		ACTION_PEC.NUM_ARCHIVE,
         		ACTION_PEC.BLN_REPRISE_NESSIE 
         	from ACTION_PEC 
         			INNER JOIN UTILISATEUR ON UTILISATEUR.ID_UTILISATEUR = ACTION_PEC.ID_UTILISATEUR
         			INNER JOIN UTILISATEUR UCREATEUR ON UCREATEUR.ID_UTILISATEUR = ACTION_PEC.ID_UTILISATEUR_CREATEUR

         	WHERE ACTION_PEC.ID_ACTION_PEC = @ID_ACTION

         END

GO

         CREATE PROCEDURE [dbo].[LEC_GRP_SOUS_TYPE_COUT_MODULE_PEC]
            @ID_MODULE int,
            @BLN_CREATION int
         AS
         BEGIN
         	CREATE TABLE #TEMPLIST
         	(
         		ID_SOUS_TYPE_COUT INT,
         		MNT_ACCORDE DECIMAL(18,2)
         	)

         	SELECT 
         		SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT,
         		SUM (isnull(POSTE_COUT_REGLE.MNT_REGLE_HT,0)) AS MNT_ACCORDE
         	INTO #LISTPREMIER
         	FROM SOUS_TYPE_COUT
         		LEFT JOIN POSTE_COUT_REGLE ON POSTE_COUT_REGLE.ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT
         		AND POSTE_COUT_REGLE.ID_MODULE_PEC = @ID_MODULE
         		LEFT JOIN REGLEMENT ON REGLEMENT.ID_REGLEMENT = POSTE_COUT_REGLE.ID_REGLEMENT
         		WHERE REGLEMENT.DAT_VALID_REGLEMENT IS NOT NULL
         	GROUP BY SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT, DAT_VALID_REGLEMENT

          INSERT INTO #TEMPLIST (ID_SOUS_TYPE_COUT, MNT_ACCORDE)	
          SELECT ID_SOUS_TYPE_COUT, SUM(MNT_ACCORDE) FROM #LISTPREMIER GROUP BY ID_SOUS_TYPE_COUT

         	select 
         		isnull(sum(isnull(PLAN_FINANCEMENT_US.MNT_PLAN_FINANCEMENT_US,0)),0) AS MNT_CHIFFRE,
         		PLAN_FINANCEMENT_US.ID_POSTE_COUT_ENGAGE
         	into #TEMP_MNT_CHIFFRE
         	from PLAN_FINANCEMENT_US
         	left join POSTE_COUT_ENGAGE on POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE = PLAN_FINANCEMENT_US.ID_POSTE_COUT_ENGAGE
         	where POSTE_COUT_ENGAGE.ID_MODULE_PEC = @ID_MODULE
         	group by PLAN_FINANCEMENT_US.ID_POSTE_COUT_ENGAGE

         	Select
         		DISTINCT(SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT)	AS ID_SOUS_TYPE_COUT,
         		SOUS_TYPE_COUT.LIBL_SOUS_TYPE_COUT			AS SOUS_TYPE_COUT,
         		POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE		AS ID_POSTE_COUT_ENGAGE,
         		POSTE_COUT_ENGAGE.MNT_PREVISIONNEL_HT		AS MNT_PREVISIONNEL,
         		CASE 
         			WHEN POSTE_COUT_ENGAGE.ID_ENGAGEMENT IS NULL OR
         				@BLN_CREATION = 1 
         			THEN 1 
         			ELSE 0 
         		END AS MODIFIABLE_MNT,

         		CASE
         			WHEN (ACTION_PEC.BLN_CYCLE_COURT = 0) THEN
         				CASE
         					WHEN (DAT_DESENGAGEMENT	is NULL		AND (ID_TYPE_ENGAGEMENT	is null OR ID_TYPE_ENGAGEMENT	<> 2)	AND 
         							ENGAGEMENT.DAT_BAE	is NOT NULL) THEN POSTE_COUT_ENGAGE.MNT_ENGAGE_HT
         					ELSE 0
         				END
         			ELSE #TEMPLIST.MNT_ACCORDE
         		END											AS MNT_ENGAGE,

         		#TEMP_MNT_CHIFFRE.MNT_CHIFFRE			AS MNT_CHIFFRE,
         		#TEMPLIST.MNT_ACCORDE					AS MNT_ACCORDE,
         		@ID_MODULE								AS ID_MODULE,
         		POSTE_COUT_ENGAGE.ID_ENGAGEMENT,
         		@BLN_CREATION							AS MODE_CREATION,
         		SOUS_TYPE_COUT.BLN_ACTIF
         	FROM  SOUS_TYPE_COUT
         		LEFT JOIN POSTE_COUT_ENGAGE ON SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT = POSTE_COUT_ENGAGE.ID_SOUS_TYPE_COUT
         			AND POSTE_COUT_ENGAGE.ID_MODULE_PEC = @ID_MODULE
         			AND (
         				(@BLN_CREATION = 0) 

         				)
         		LEFT JOIN ENGAGEMENT ON ENGAGEMENT.ID_ENGAGEMENT = POSTE_COUT_ENGAGE.ID_ENGAGEMENT
         		LEFT JOIN MODULE_PEC ON POSTE_COUT_ENGAGE.ID_MODULE_PEC = MODULE_PEC.ID_MODULE_PEC
         		LEFT JOIN ACTION_PEC ON MODULE_PEC.ID_ACTION_PEC = ACTION_PEC.ID_ACTION_PEC
         		LEFT JOIN #TEMPLIST ON #TEMPLIST.ID_SOUS_TYPE_COUT = SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT
         		LEFT JOIN #TEMP_MNT_CHIFFRE ON #TEMP_MNT_CHIFFRE.ID_POSTE_COUT_ENGAGE = POSTE_COUT_ENGAGE.ID_POSTE_COUT_ENGAGE
         	WHERE

         		POSTE_COUT_ENGAGE.DAT_DESENGAGEMENT IS NULL	AND 
         		(POSTE_COUT_ENGAGE.MNT_ENGAGE_HT>=0 OR POSTE_COUT_ENGAGE.MNT_ENGAGE_HT IS NULL)
         		AND (ENGAGEMENT.ID_TYPE_ENGAGEMENT IS NULL OR ENGAGEMENT.ID_TYPE_ENGAGEMENT = 1 OR ENGAGEMENT.ID_TYPE_ENGAGEMENT = 3)
         	ORDER BY SOUS_TYPE_COUT.ID_SOUS_TYPE_COUT
         END   

GO

         CREATE PROCEDURE [dbo].[LEC_TACHE_AGENCE]

         @ID_UTIL int ,
         @MIN_AFF int
         AS   
         BEGIN
         	DECLARE 
         		@ID_AGENCE int,  
         		@NBR int	  

         	create table #TEMPO1  
         	 (APPLI VARCHAR (3),
         	  LIB CHAR(50) null,  
         	  NBR INTEGER null)  

         	select @ID_AGENCE=ID_AGENCE  
         	FROM UTILISATEUR  
         	WHERE ID_UTILISATEUR=@ID_UTIL  

         	SET @NBR =0
         	EXECUTE LEC_GRP_ETABLISSEMENT_PEC_ENGAGEMENT_ADH @ID_AGENCE, @NBR OUTPUT  

         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PEC',
         	 LIB = 'Lettre d''engagement Adh',  
         	 NBR = @NBR  
         	END  

         	SET @NBR =0
         	EXEC EDT_LISTE_BAP_SESSION 1, NULL, NULL, @ID_UTIL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,@NBR	

         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PEC',
         	 LIB = 'Liste BAP',  
         	 NBR = @NBR  
         	END  

         	SET @NBR =0
         	EXECUTE LEC_GRP_ETABLISSEMENT_RELANCE_ENGAGEMENT_ADH @ID_AGENCE, @NBR OUTPUT  

         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PEC',
         	 LIB = 'Lettre relance instruction',  
         	 NBR = @NBR  
         	END  

         	SET @NBR =0
         	EXECUTE LEC_GRP_ETAB_RELANCE_PIECE_REGL_ADH @ID_AGENCE, @NBR OUTPUT  

         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PEC',
         	 LIB = 'Piece regl adh',  
         	 NBR = @NBR  
         	END  

         	SET @NBR =0
         	EXECUTE LEC_GRP_ETAB_OF_RELANCE_PIECE_REGL_OF @ID_AGENCE, @NBR OUTPUT  

         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PEC',
         	 LIB = 'Piece regl OF',  
         	 NBR = @NBR  
         	END  

         	SET @NBR =0
         	EXECUTE LEC_GRP_ADHERENT_REMBOURSEMENT_SALAIRE '', NULL, @ID_AGENCE, @NBR OUTPUT  

         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PEC',
         	 LIB = 'Remboursement salaire',  
         	 NBR = @NBR  
         	END  

         	SET @NBR =0
         	EXECUTE LEC_GRP_ETAB_REJET_ADH @ID_AGENCE, @NBR OUTPUT  

         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PEC',
         	 LIB = 'Rejet Adh',  
         	 NBR = @NBR  
         	END  

         	SET @NBR =0
         	EXECUTE LEC_GRP_ACTION_ENGAGER @ID_AGENCE, @NBR OUTPUT  

         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PEC',
         	 LIB = 'Bons A Engager',  
         	 NBR = @NBR  
         	END  

         	SET @NBR =0
         	EXECUTE LEC_GRP_BON_A_PAYER @ID_AGENCE, @NBR OUTPUT  

         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PEC',
         	 LIB = 'Bons A Payer',  
         	 NBR = @NBR  
         	END  

         	SET @NBR =0
         	EXEC EDT_LISTE_BAP_SESSION_PRO 1, NULL, NULL, @ID_UTIL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,@NBR	

         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PRO',
         	 LIB = 'Liste BAP',  
         	 NBR = @NBR  
         	END  

         	SET @NBR =0
         	EXEC LEC_GRP_ETAB_ADH_ENGAGEMENT_CONTRAT_PRO @ID_AGENCE, @NBR OUTPUT  
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PRO',
         	 LIB = 'Lettre engagement pro Adh',  
         	 NBR = @NBR  
         	END  

         	SET @NBR =0
         	EXEC LEC_GRP_ETAB_OF_ENGAGEMENT_CONTRAT_PRO @ID_AGENCE, @NBR OUTPUT  
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PRO',
         	 LIB = 'Lettre engagement pro OF',  
         	 NBR = @NBR  
         	END  

         	SET @NBR =0
         	EXEC LEC_GRP_ETAB_ADH_RELANCE_ENGAGEMENT_CONTRAT_PRO @ID_AGENCE, @NBR OUTPUT  
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PRO',
         	 LIB = 'Relance engagement pro Adh',  
         	 NBR = @NBR  
         	END  

         	SET @NBR =0
         	EXEC LEC_GRP_ETAB_OF_RELANCE_ENGAGEMENT_CONTRAT_PRO @ID_AGENCE, @NBR OUTPUT  
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PRO',
         	 LIB = 'Relance engagement pro OF',  
         	 NBR = @NBR  
         	END  

         	SET @NBR =0
         	EXEC LEC_GRP_ETAB_ADH_RELANCE_REGLEMENT_CONTRAT_PRO @ID_AGENCE, @NBR OUTPUT  
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PRO',
         	 LIB = 'Relance rŠglement pro Adh',  
         	 NBR = @NBR  
         	END  

         	SET @NBR =0
         	EXEC LEC_GRP_ETAB_OF_RELANCE_REGLEMENT_CONTRAT_PRO @ID_AGENCE, @NBR OUTPUT  
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PRO',
         	 LIB = 'Relance rŠglement pro OF',  
         	 NBR = @NBR  
         	END  

         	SET @NBR =0
         	EXEC LEC_GRP_PRO_REMBOURSEMENT_SALAIRE_ADH null, null, @ID_AGENCE, @NBR OUTPUT  
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PRO',
         	 LIB = 'Lettre remboursement Adh',  
         	 NBR = @NBR  
         	END  

         	SET @NBR =0
         	EXEC LEC_GRP_PRO_REMBOURSEMENT_SALAIRE_ADH_TUTORAL null, null, @ID_AGENCE, @NBR OUTPUT  
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PRO',
         	 LIB = 'Lettre remboursement tut.',  
         	 NBR = @NBR  
         	END  

         	SET @NBR =0
         	EXEC LEC_GRP_PRO_REMBOURSEMENT_SALAIRE_OF null, null, @ID_AGENCE, @NBR OUTPUT  
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PRO',
         	 LIB = 'Lettre remboursement OF',  
         	 NBR = @NBR  
         	END  

         	SET @NBR =0
         	EXEC LEC_GRP_CONTRAT_PRO_A_ENGAGER @ID_AGENCE, @NBR OUTPUT  
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PRO',
         	 LIB = 'BAE',  
         	 NBR = @NBR  
         	END  

         	SET @NBR =0
         	EXEC LEC_GRP_BON_A_PAYER_PRO @ID_AGENCE, @NBR OUTPUT  
         	IF @NBR>=@MIN_AFF 
         	BEGIN  
         	 INSERT INTO #TEMPO1  
         	 SELECT   
         	 APPLI = 'PRO',
         	 LIB = 'BAP',  
         	 NBR = @NBR  
         	END  

         	select * from #TEMPO1  

         END
GO
 CREATE PROCEDURE [dbo].[UPD_PLAN_FINANCEMENT_US]

          @ID_UNITE_STAGIAIRE  INT,
          @ID_POSTE_COUT_ENGAGE INT,
          @ID_DISPOSITIF   INT,
          @ID_MODULE    INT,
          @BLN_PLUS10    BIT,
          @HOURS_ALL    DECIMAL(18,2),
          @HOURS_STAGIAIRE  DECIMAL(18,2),
          @MNT_POSTE_COUT_ENGAGE DECIMAL(18,2)
         AS
         BEGIN
          IF (@MNT_POSTE_COUT_ENGAGE <> 0)
          BEGIN
           DECLARE
            @MNT_PLAN_FINANCEMENT_US DECIMAL(18,2)

           SET @MNT_PLAN_FINANCEMENT_US = (@MNT_POSTE_COUT_ENGAGE * @HOURS_STAGIAIRE) / @HOURS_ALL

           UPDATE
            PLAN_FINANCEMENT_US
           SET
            MNT_PLAN_FINANCEMENT_US = @MNT_PLAN_FINANCEMENT_US
           WHERE 
            ID_UNITE_STAGIAIRE = @ID_UNITE_STAGIAIRE
            AND ID_POSTE_COUT_ENGAGE = @ID_POSTE_COUT_ENGAGE
          END
         END
GO

         CREATE PROCEDURE [dbo].[UPD_ADHERENT]
         	@ID_ADHERENT int,
         	@ID_AGENCE int,
         	@ID_ADRESSE_PRINCIPALE int,
         	@ID_MODE_PAIEMENT int,
         	@ID_BRANCHE int,
         	@ID_GROUPE int,
         	@ID_IDCC int,
         	@ID_MODE_VERSEMENT int,
         	@ID_NAF int,
         	@ID_ETABLISSEMENT_PRINCIPAL int,
         	@ID_SITUATION_FAF int,
         	@NUM_SIREN varchar(9),
         	@LIB_RAISON_SOCIALE varchar(50),
         	@LIB_SIGLE_ADHERENT varchar(15),
         	@BLN_ACTIF tinyint,
         	@BLN_ASSUJETTI_TA tinyint,
         	@BLN_GESTION_GROUPE tinyint,
         	@COM_ADHERENT varchar(255),
         	@BLN_HABILIT_ALTERNANCE tinyint,
         	@ID_UTILISATEUR int,
         	@LIB_MOT_PASSE varchar(30),
         	@EMAIL varchar(100),
         	@DAT_DEBUT_GROUPE datetime,
         	@LIB_ENSEIGNE varchar(35),
         	@BLN_MOINS_10 tinyint,
         	@ANNEE_MOINS_10 varchar(4),
         	@BLN_10_19 tinyint,
         	@ANNEE_10_19 varchar(4),
         	@BLN_20_PLUS tinyint,
         	@ANNEE_20_PLUS varchar(4),
         	@ID_TIERS_MANDATAIRE int,
         	@ID_ADHERENT_REPRENEUR int,
         	@ID_SITUATION_ECONOMIQUE int,
         	@ID_TYPE_TVA int,
         	@BLN_SERVICE_PERSONNE tinyint,
         	@TIME_STAMP timestamp,
         	@ID_CHARGEE_MISSION int,
         	@ID_CHARGEE_RELATION int,
         	@ID_TIERS_CABINET_COMPTABLE int,
         	@ID_SYNDICAT int,
         	@ID_FEDERATION int,
         	@SITE_WEB_ADHERENT varchar(100),
         	@ID_GROUPE_STATISTIQUE int,
         	@DAT_SITUATION_ECONOMIQUE datetime,
         	@LIB_TIERS_MANDATAIRE varchar(50)

         AS

         	if @LIB_SIGLE_ADHERENT is null
         	BEGIN
         		SET @LIB_SIGLE_ADHERENT  = SUBSTRING(@LIB_RAISON_SOCIALE, 1, 15)
         	END
             DECLARE @ID_PERIODE_ENCOURS INT

             select top 1 @ID_PERIODE_ENCOURS = ID_PERIODE
             from PERIODE
             where BLN_EN_COURS = 1 and BLN_ACTIF = 1 

         	DECLARE @ANNEE_10_19_OLD varchar(4)
         	DECLARE @ANNEE_20_PLUS_OLD varchar(4)

         	select 
         			@ANNEE_10_19_OLD = ANNEE_10_19,
         			@ANNEE_20_PLUS_OLD = ANNEE_20_PLUS
         	from ADHERENT
         	where
         			ID_ADHERENT = @ID_ADHERENT
         		and	TIME_STAMP = @TIME_STAMP

         	update ADHERENT set
         			ID_AGENCE = @ID_AGENCE,
         			ID_ADRESSE_PRINCIPALE = @ID_ADRESSE_PRINCIPALE,
         			ID_MODE_PAIEMENT = @ID_MODE_PAIEMENT,
         			ID_BRANCHE = @ID_BRANCHE,
         			ID_GROUPE = @ID_GROUPE,
         			ID_IDCC = @ID_IDCC,
         			ID_MODE_VERSEMENT = @ID_MODE_VERSEMENT,
         			ID_NAF = @ID_NAF,
         			ID_ETABLISSEMENT_PRINCIPAL = @ID_ETABLISSEMENT_PRINCIPAL,
         			ID_SITUATION_FAF = @ID_SITUATION_FAF,
         			NUM_SIREN = @NUM_SIREN,
         			LIB_RAISON_SOCIALE = @LIB_RAISON_SOCIALE,
         			LIB_SIGLE_ADHERENT = @LIB_SIGLE_ADHERENT,
         			BLN_ACTIF = @BLN_ACTIF,
         			BLN_ASSUJETTI_TA = @BLN_ASSUJETTI_TA,
         			BLN_GESTION_GROUPE = 1, 
         			COM_ADHERENT = @COM_ADHERENT,
         			BLN_HABILIT_ALTERNANCE = @BLN_HABILIT_ALTERNANCE,
         			ID_UTILISATEUR = @ID_UTILISATEUR,
         			LIB_MOT_PASSE = @LIB_MOT_PASSE,
         			EMAIL = @EMAIL,
         			DAT_DEBUT_GROUPE = @DAT_DEBUT_GROUPE,
         			LIB_ENSEIGNE = @LIB_ENSEIGNE,
         			BLN_MOINS_10 = @BLN_MOINS_10,
         			ANNEE_MOINS_10 = @ANNEE_MOINS_10,
         			BLN_10_19 = @BLN_10_19,
         			ANNEE_10_19 = @ANNEE_10_19,
         			BLN_20_PLUS = @BLN_20_PLUS,
         			ANNEE_20_PLUS = @ANNEE_20_PLUS,
         			ID_TIERS_MANDATAIRE = @ID_TIERS_MANDATAIRE,
         			ID_ADHERENT_REPRENEUR = @ID_ADHERENT_REPRENEUR,
         			ID_SITUATION_ECONOMIQUE = @ID_SITUATION_ECONOMIQUE,
         			DAT_MODIF = getDate(),
         			ID_TYPE_TVA = @ID_TYPE_TVA,
         			BLN_SERVICE_PERSONNE = @BLN_SERVICE_PERSONNE,
         			ID_CHARGEE_MISSION = @ID_CHARGEE_MISSION,
         			ID_CHARGEE_RELATION = @ID_CHARGEE_RELATION,
         			ID_TIERS_CABINET_COMPTABLE = @ID_TIERS_CABINET_COMPTABLE,
         			ID_SYNDICAT = @ID_SYNDICAT,
         			ID_FEDERATION = @ID_FEDERATION,
         			SITE_WEB_ADHERENT = @SITE_WEB_ADHERENT,
         			ID_GROUPE_STATISTIQUE = @ID_GROUPE_STATISTIQUE,
         			DAT_SITUATION_ECONOMIQUE = @DAT_SITUATION_ECONOMIQUE,
         			LIB_TIERS_MANDATAIRE = @LIB_TIERS_MANDATAIRE

         	where	ID_ADHERENT = @ID_ADHERENT
         		and	TIME_STAMP = @TIME_STAMP

         		IF @@ROWCOUNT = 0   
         		BEGIN  
         		   IF EXISTS(SELECT * FROM ADHERENT WHERE ID_ADHERENT  = @ID_ADHERENT)      
         		   BEGIN  

         		      RAISERROR(50001, 16, 1)  
         		   END  
         		   ELSE  
         		   BEGIN  

         		      RAISERROR(50002, 16, 1)  
         		   END  
         		END 
         		ELSE
         		BEGIN
         		IF(@ANNEE_10_19_OLD <> @ANNEE_10_19 or @ANNEE_20_PLUS_OLD <> @ANNEE_20_PLUS)
         		UPDATE VERSEMENT 
         		SET 
         		SYNC_BLN_SYNCHRO_SSIS = 1,
         		SYNC_DAT_SYNCHRO_SSIS = GETDATE()
         		FROM POSTE_VERSEMENT 
         		where POSTE_VERSEMENT.ID_VERSEMENT = VERSEMENT.ID_VERSEMENT and
         		POSTE_VERSEMENT.ID_ADHERENT_BENEFICIAIRE = @ID_ADHERENT and 
         		POSTE_VERSEMENT.ID_PERIODE = @ID_PERIODE_ENCOURS
         		END

GO
CREATE PROCEDURE [dbo].[UPD_SOUS_TYPE_COUT_MODULE_PEC]

          @ID_SOUS_TYPE_COUT  INT,
          @ID_MODULE_PEC   INT,
          @MNT_PREVISIONNEL  DECIMAL(18,2),  
          @MNT_CHIFFRE   DECIMAL(18,2),
          @ID_POSTE_COUT_ENGAGE INT OUTPUT
         AS
         BEGIN
          DECLARE
           @NUMREG int

          SELECT
           @NUMREG = COUNT(*)
          FROM
           POSTE_COUT_ENGAGE 
          WHERE
           ID_SOUS_TYPE_COUT = @ID_SOUS_TYPE_COUT
           AND ID_MODULE_PEC = @ID_MODULE_PEC
           AND DAT_DESENGAGEMENT IS NULL

          IF (@MNT_PREVISIONNEL IS NULL)
          BEGIN
           SET @MNT_PREVISIONNEL = 0
          END

          IF (@MNT_CHIFFRE IS NULL)
          BEGIN
           SET @MNT_CHIFFRE = 0
          END

          IF (@MNT_PREVISIONNEL <> 0) 
          BEGIN
           IF (@NUMREG = 0)  
           BEGIN
            INSERT INTO POSTE_COUT_ENGAGE
            (
             COD_POSTE_COUT_ENGAGE,
             ID_MODULE_PEC,
             ID_SOUS_TYPE_COUT,
             MNT_PREVISIONNEL_HT,
             MNT_ENGAGE_HT,
             BLN_OK_FINANCEMENT,
             DAT_CREATION
            )
            VALUES
            (
             0,
             @ID_MODULE_PEC,
             @ID_SOUS_TYPE_COUT,
             @MNT_PREVISIONNEL,
             @MNT_CHIFFRE,
             0,
             getdate()
            )

            UPDATE
             POSTE_COUT_ENGAGE
            SET
             COD_POSTE_COUT_ENGAGE = @@IDENTITY
            WHERE
             ID_POSTE_COUT_ENGAGE = @@IDENTITY

            SET @ID_POSTE_COUT_ENGAGE = @@IDENTITY
           END
           ELSE   
           BEGIN

            DECLARE
             @OLD_MNT_PREV DECIMAL (18,2),
             @ID_PCE_NONENGAGE INT

            SET @ID_PCE_NONENGAGE = NULL

            SELECT
             @ID_PCE_NONENGAGE = ID_POSTE_COUT_ENGAGE ,
             @OLD_MNT_PREV = MNT_PREVISIONNEL_HT
            FROM
             POSTE_COUT_ENGAGE 
            WHERE
             ID_SOUS_TYPE_COUT = @ID_SOUS_TYPE_COUT 
             AND ID_MODULE_PEC = @ID_MODULE_PEC
             AND DAT_DESENGAGEMENT IS NULL
             AND ID_ENGAGEMENT IS NULL 

            IF (@OLD_MNT_PREV = @MNT_PREVISIONNEL)
            BEGIN
             RETURN
            END

            IF (@ID_PCE_NONENGAGE IS NOT NULL)
            BEGIN
             UPDATE
              POSTE_COUT_ENGAGE
             SET 
              MNT_PREVISIONNEL_HT  = @MNT_PREVISIONNEL,
              MNT_ENGAGE_HT = @MNT_PREVISIONNEL,
              BLN_OK_FINANCEMENT = 0,
              DAT_MODIF = Getdate()
             WHERE 
              ID_POSTE_COUT_ENGAGE  = @ID_PCE_NONENGAGE
              AND ID_SOUS_TYPE_COUT = @ID_SOUS_TYPE_COUT
            END
            ELSE
            BEGIN

             UPDATE
              POSTE_COUT_ENGAGE
             SET 
              DAT_MODIF = DAT_MODIF
             WHERE 
              ID_SOUS_TYPE_COUT = @ID_SOUS_TYPE_COUT  
              AND ID_MODULE_PEC = @ID_MODULE_PEC
            END    
           END 

           IF @@ROWCOUNT = 0   
           BEGIN  
            IF EXISTS(
             SELECT * FROM POSTE_COUT_ENGAGE 
             WHERE ID_SOUS_TYPE_COUT  = @ID_SOUS_TYPE_COUT 
              AND ID_MODULE_PEC = @ID_MODULE_PEC
             )  
            BEGIN
             RAISERROR(50001, 16, 2)  
            END
            ELSE
            BEGIN
             RAISERROR(50002, 16, 2)  
            END
           END       
          END
          ELSE 
          BEGIN
           IF (@NUMREG <> 0) 
           BEGIN
            DECLARE
             @ID_PCE INT

            SET @ID_PCE = NULL

            SELECT
             @ID_PCE = ID_POSTE_COUT_ENGAGE 
            FROM
             POSTE_COUT_ENGAGE 
            WHERE
             ID_SOUS_TYPE_COUT = @ID_SOUS_TYPE_COUT  
             AND ID_MODULE_PEC = @ID_MODULE_PEC
             AND DAT_DESENGAGEMENT IS NULL
             AND ID_ENGAGEMENT IS NULL 

            IF (@ID_PCE IS NOT NULL)
            BEGIN
             UPDATE
              POSTE_COUT_ENGAGE
             SET 
              MNT_PREVISIONNEL_HT  = @MNT_PREVISIONNEL,
              MNT_ENGAGE_HT = @MNT_PREVISIONNEL,
              DAT_MODIF = Getdate()
             WHERE 
              ID_POSTE_COUT_ENGAGE  = @ID_PCE  

             UPDATE
              PLAN_FINANCEMENT_US
             SET 
              MNT_PLAN_FINANCEMENT_US = 0,
              MNT_PLAN_FINANCEMENT_US_TVA = 0
             FROM
              PLAN_FINANCEMENT_US PFUS
             WHERE
              PFUS.ID_POSTE_COUT_ENGAGE = @ID_PCE
              AND PFUS.ID_POSTE_COUT_REGLE IS NULL
            END
            ELSE 
            BEGIN
             UPDATE
              POSTE_COUT_ENGAGE 
             SET
              DAT_MODIF  = DAT_MODIF
             WHERE 
              ID_SOUS_TYPE_COUT  = @ID_SOUS_TYPE_COUT  
              AND ID_MODULE_PEC = @ID_MODULE_PEC       
            END 
           END
          END
         END
GO

         CREATE PROCEDURE [dbo].[INS_OR_UPD_PARAM_GLOBAL] 

         	@ID_PARAM_GLO int,
         	@ID_TYPE_ASSUJETISSEMENT int,
         	@ID_ACTIVITE int,
         	@COD_PARAM_GLO int,
         	@TAU_GLO_APPEL decimal(10,5),
         	@TAU_MIN tinyint,
         	@MNT_MIN int,
         	@BLN_ACTIF tinyint,
         	@COM_PARAM_GLO varchar(255),
         	@ID_PERIODE int,
         	@ID_REGIME int
         AS
         BEGIN
         	SET NOCOUNT ON;

         	if exists (select 1 from PARAMETRE_GLOBAL where ID_PARAM_GLO = @ID_PARAM_GLO)
         		UPDATE PARAMETRE_GLOBAL SET
         			ID_TYPE_ASSUJETISSEMENT = @ID_TYPE_ASSUJETISSEMENT,
         			ID_ACTIVITE =	@ID_ACTIVITE,
         			COD_PARAM_GLO = @COD_PARAM_GLO,
         			TAU_GLO_APPEL = @TAU_GLO_APPEL,
         			TAU_MIN =		@TAU_MIN,
         			MNT_MIN =		@MNT_MIN,
         			BLN_ACTIF =		@BLN_ACTIF,
         			COM_PARAM_GLO = @COM_PARAM_GLO ,
         			ID_PERIODE =	@ID_PERIODE,
         			ID_REGIME =		@ID_REGIME 
         		WHERE ID_PARAM_GLO = @ID_PARAM_GLO
         	else
         		INSERT INTO [PARAMETRE_GLOBAL] ([ID_PARAM_GLO],[ID_TYPE_ASSUJETISSEMENT],[ID_ACTIVITE],[COD_PARAM_GLO],[TAU_GLO_APPEL],[TAU_MIN],[MNT_MIN],[BLN_ACTIF],[COM_PARAM_GLO],[ID_PERIODE],[ID_REGIME])
         		VALUES(@ID_PARAM_GLO,@ID_TYPE_ASSUJETISSEMENT,@ID_ACTIVITE,@COD_PARAM_GLO,@TAU_GLO_APPEL,@TAU_MIN,@MNT_MIN,@BLN_ACTIF,@COM_PARAM_GLO,@ID_PERIODE,@ID_REGIME)
         END

GO

         CREATE PROCEDURE [dbo].[INS_EVENEMENT_ADMIN] 
         				@LIBL_EVENEMENT_ADMIN		VARCHAR(100), 
         				@ID_UTILISATEUR				INT, 
         				@ID_TYPE_EVENEMENT_ADMIN	INT, 
         				@ID_CONTRAT_PRO				INT, 
         				@BLN_ACTIF					TINYINT, 
         				@DAT_EVENEMENT_ADMIN		DATETIME				
         AS 
         BEGIN
         	INSERT INTO EVENEMENT_ADMIN
         			(
         				COD_EVENEMENT_ADMIN, 
         				LIBL_EVENEMENT_ADMIN, 
         				ID_UTILISATEUR, 
         				ID_TYPE_EVENEMENT_ADMIN, 
         				ID_CONTRAT_PRO, 
         				BLN_ACTIF, 
         				DAT_EVENEMENT_ADMIN
         			)
         	VALUES
         			(
         				'0', 
