         CREATE PROCEDURE [dbo].[UPD_MODULE_DATE_REJET_LETTRE_OF]
         	@IDS_MODULE_PEC varchar(500)	
         AS

         BEGIN

         	DECLARE @Item int;

         	CREATE TABLE #List(Item int)

         	DECLARE @Delimiter char
         	SET @Delimiter = ','
         	WHILE CHARINDEX(@Delimiter,@IDS_MODULE_PEC,0) <> 0
         	BEGIN
         		SELECT
         			@Item=RTRIM(LTRIM(SUBSTRING(@IDS_MODULE_PEC,1,CHARINDEX(@Delimiter,@IDS_MODULE_PEC,0)-1))),
         			@IDS_MODULE_PEC=RTRIM(LTRIM(SUBSTRING(@IDS_MODULE_PEC,CHARINDEX(@Delimiter,@IDS_MODULE_PEC,0)+1,LEN(@IDS_MODULE_PEC))))

         		IF LEN(@Item) > 0
         			INSERT INTO #List SELECT @Item
         	END

         	IF LEN(@IDS_MODULE_PEC) > 0
         		INSERT INTO #List SELECT @IDS_MODULE_PEC 

         	UPDATE MODULE_PEC
         	SET DAT_LETTRE_REJET_OF = GETDATE()
         	WHERE ID_MODULE_PEC IN (SELECT Item FROM #List)

         END

GO

         CREATE PROCEDURE UPD_GESTION_TRANSACTION_ETABLISSEMENT_OF
         				@ID_OF INT,
         				@ID_ETABLISSEMENT_OF INT,
         				@ID_ADRESSE INT,
         				@ID_UTILISATEUR INT,
         				@BLN_PRINCIPAL TINYINT,
         				@NUM_IBAN VARCHAR(34),
         				@BIC VARCHAR(11)
         AS

         	DECLARE @ID_TYPE_TRANSACTION INT
         	DECLARE @ID_SOUS_TYPE_TRANSACTION INT,
         			@ID_ETABLISSEMENT_OF_BENEF INT,
         			@ID_ADRESSE_BENEF INT,
         			@ID_CONTACT_BENEF INT,
         			@NUM_IBAN_BENEF VARCHAR(34)

         	SELECT @ID_SOUS_TYPE_TRANSACTION = SOUS_TYPE_TRANSACTION.ID_SOUS_TYPE_TRANSACTION
         	FROM   SOUS_TYPE_TRANSACTION
         	WHERE  SOUS_TYPE_TRANSACTION.COD_SOUS_TYPE_TRANSACTION = 'REGLEMT'

         	IF NOT EXISTS ( select * from  [TRANSACTION] 
         				where		 [TRANSACTION].ID_ETABLISSEMENT_OF_DEST = @ID_ETABLISSEMENT_OF 
         						AND  [TRANSACTION].ID_TYPE_TRANSACTION IS NULL
         						AND  [TRANSACTION].ID_SOUS_TYPE_TRANSACTION = @ID_SOUS_TYPE_TRANSACTION
         						AND  [TRANSACTION].ID_ACTIVITE IS NULL
         						AND [TRANSACTION].BLN_ACTIF = 1
         						AND [TRANSACTION].BLN_TRANSACTION_REGLEMENT_PRINCIPAL = 1) 
         	BEGIN

         		SELECT 
         			@ID_ETABLISSEMENT_OF_BENEF =ID_ETABLISSEMENT_OF,
         			@ID_ADRESSE_BENEF =ID_ADRESSE_PRINCIPALE, 
         			@ID_CONTACT_BENEF = NULL,
         			@NUM_IBAN_BENEF =NUM_IBAN
         		FROM ETABLISSEMENT_OF
         		WHERE ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF = @ID_ETABLISSEMENT_OF

         		IF LTRIM(@NUM_IBAN_BENEF) = '' SET @NUM_IBAN_BENEF = NULL
         		DECLARE @BLN_BENEFICIAIRE_IDENTIQUE_DESTINATAIRE TINYINT
         		SET @BLN_BENEFICIAIRE_IDENTIQUE_DESTINATAIRE = 0
         		IF(@ID_ETABLISSEMENT_OF=@ID_ETABLISSEMENT_OF_BENEF)
         		BEGIN
         			SET @BLN_BENEFICIAIRE_IDENTIQUE_DESTINATAIRE = 1
         		END

         			EXEC INS_TRANSACTION
         				@ID_ETABLISSEMENT_DEST = NULL, 
         				@ID_ETABLISSEMENT_OF_DEST = @ID_ETABLISSEMENT_OF, 
         				@ID_ETABLISSEMENT_BENEF = NULL, 
         				@ID_ETABLISSEMENT_OF_BENEF = @ID_ETABLISSEMENT_OF_BENEF, 
         				@ID_TIERS_BENEF = NULL, 
         				@ID_ADRESSE = @ID_ADRESSE_BENEF, 
         				@ID_CONTACT = @ID_CONTACT_BENEF, 
         				@ID_TYPE_TRANSACTION = null,
         				@ID_SOUS_TYPE_TRANSACTION = @ID_SOUS_TYPE_TRANSACTION, 
         				@ID_ACTIVITE = NULL, 
         				@BLN_ACTIF = 1, 
         				@ID_MODE_ENVOI_DOC = 1, 
         				@NUM_IBAN = @NUM_IBAN_BENEF, 
         				@ID_UTILISATEUR = @ID_UTILISATEUR, 
         				@BLN_TRANSACTION_REGLEMENT_PRINCIPAL = 1, 
         				@BLN_BENEFICIAIRE_IDENTIQUE_DESTINATAIRE = @BLN_BENEFICIAIRE_IDENTIQUE_DESTINATAIRE, 
         				@LIBL_TRANSACTION = 'Cr‚‚e avec l''OF',
         				@BIC = @BIC

         		UPDATE ETABLISSEMENT_OF 
         		SET NUM_IBAN = @NUM_IBAN_BENEF
         		WHERE ID_ETABLISSEMENT_OF = @ID_ETABLISSEMENT_OF

         	END

         SELECT * FROM TYPE_TRANSACTION
GO

CREATE PROCEDURE [dbo].[UPD_PIECES_REGLEMENT_NON_CONFORM]  
	@ID_MOTIF int,
	@ID_ARRIVEE_PIECE int,
	@BLN_ACTIF int
AS  

BEGIN
	DECLARE @EXIST int

         	SELECT @EXIST = COUNT (*)
         	FROM NR210
         	WHERE ID_MOTIF_NON_CONFORM_PIECE = @ID_MOTIF
         	AND ID_ARRIVEE_PIECE_PEC = @ID_ARRIVEE_PIECE

         	IF @EXIST <> 0
         	BEGIN
         		IF @BLN_ACTIF = 0
         		BEGIN
         			DELETE NR210
         			WHERE ID_MOTIF_NON_CONFORM_PIECE = @ID_MOTIF
         				AND ID_ARRIVEE_PIECE_PEC = @ID_ARRIVEE_PIECE
         		END
         	END
         	ELSE
         	BEGIN
         		IF @BLN_ACTIF = 1
         			INSERT INTO NR210
         				(ID_MOTIF_NON_CONFORM_PIECE, ID_ARRIVEE_PIECE_PEC)
         			VALUES
         				(@ID_MOTIF, @ID_ARRIVEE_PIECE)
         	END

         END
GO
 CREATE PROCEDURE [dbo].[LEC_GRP_IMPUTATION_PAR_ACTIVITE_EDITION]  
          @ID_ADHERENT    AS INT,  
          @ID_PERIODE     AS INT,  
          @ID_POSTE_VERSEMENT   AS INT,  
          @ID_TYPE_VERSEMENT   AS INT,  
          @ID_TYPE_ASSUJETISSEMENT AS INT,  
          @MASSE_SALARIALE   AS DECIMAL(18,2) = 0,  
          @MASSE_SALARIALE_CDD   AS DECIMAL(18,2) = 0, 
          @DATE      as datetime,  
          @ID_GROUPE_DE_ETABLISSEMENT as INT,  
          @ID_ETABLISSEMENT_VERSEUR AS INT    
         AS  

         BEGIN  

          SELECT @ID_TYPE_VERSEMENT = INI.ID_TYPE_VERSEMENT   
           FROM TYPE_VERSEMENT 
           inner join TYPE_VERSEMENT INI on 
          (INI.GRP_TYPE_VERSEMENT = TYPE_VERSEMENT.GRP_TYPE_VERSEMENT AND ini.BLN_VERSEMENT_INITIAL=1 )
           WHERE TYPE_VERSEMENT.ID_TYPE_VERSEMENT = @ID_TYPE_VERSEMENT 

          DECLARE @TAU_TVA  as decimal(10,5)  
          SELECT @TAU_TVA = R26.TAU_TVA   
          FROM R26   
           INNER JOIN ADHERENT ON (R26.ID_TYPE_TVA  = ADHERENT.ID_TYPE_TVA)  
           INNER JOIN PERIODE P2 ON datediff(day, isnull(@DATE, getdate()), P2.DAT_DEB_PERIODE) <= 0 AND   
                  datediff(day, isnull(@DATE, getdate()), P2.DAT_FIN_PERIODE) >= 0 AND   
                  P2.ID_TYPE_PERIODE = 2 AND   
                  R26.ID_PERIODE  = P2.ID_PERIODE  
          WHERE ADHERENT.ID_ADHERENT = @ID_ADHERENT  
          SET @TAU_TVA = isnull(@TAU_TVA, 0)   

          declare @ID_OPTION int  
          set @ID_OPTION = null  
          select @ID_OPTION = R20BIS.ID_OPTION  
          from R20BIS    
          where R20BIS.ID_GROUPE = @ID_GROUPE_DE_ETABLISSEMENT   
            AND R20BIS.ID_PERIODE = @ID_PERIODE 

         select   
           @ID_ADHERENT    as ID_ADHERENT,  
           @ID_PERIODE     as ID_PERIODE,  
           @ID_OPTION     as ID_OPTION,  
           imputation.COD_PERIODE,  
           imputation.NUM_ANNEE,  
           imputation.ID_ACTIVITE,  
           ACTIVITE.NUM_ORDRE,  
           ACTIVITE.LIBL_ACTIVITE,  
           imputation.MASSE_SALARIALE,  
           imputation.TAU_GLO_APPEL,  
           imputation.PRC_APPELE,  
           100 as PRC_OPTION,  
           imputation.PRC_FPSPP,  
           isnull(DEDUCTION.MNT_HT, 0)   as DEDUCTION_EN_COURS_MNT_HT,  
           (isnull(imputation.VERSE_HT, 0)-isnull(POSTE_IMPUTATION.MNT_HT, 0))   
                    as VERSE_HT,  
           POSTE_IMPUTATION.ID_POSTE_IMPUTATION,  
           POSTE_IMPUTATION.ID_POSTE_VERSEMENT,  
           POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE,  
           POSTE_IMPUTATION.DAT_MAJ_CPT_ADH,  
           isnull(POSTE_IMPUTATION.MNT_HT, 0) as IMPUTATION_MNT_HT,  
           isnull(POSTE_IMPUTATION.MNT_TVA, 0) as IMPUTATION_MNT_TVA,  
           isnull(POSTE_IMPUTATION.MNT_TTC, 0) as IMPUTATION_MNT_TTC,  
           imputation.ID_TYPE_TVA,  
           case when (ACTIVITE.COD_ACTIVITE not like 'DSP')  
           then @TAU_TVA   
           else 0 
           end as TAU_TVA,  
           POSTE_VERSEMENT.TIME_STAMP   as POSTE_VERSEMENT_TIME_STAMP,  
           POSTE_IMPUTATION.TIME_STAMP   as POSTE_IMPUTATION_TIME_STAMP,  
           DEDUCTION.TIME_STAMP    as DEDUCTION_TIME_STAMP,  
           ( CASE WHEN @ID_POSTE_VERSEMENT > 0  
              THEN ISNULL(imputation.DONT_DEJA_REGLE_FPSPP,0) - ISNULL(POSTE_IMPUTATION.DONT_REGLE_FPSPP,0) 
             ELSE        
              ISNULL(imputation.DONT_DEJA_REGLE_FPSPP,0)  
           END)        AS DONT_DEJA_REGLE_FPSPP,  
           ISNULL(POSTE_IMPUTATION.DONT_REGLE_FPSPP,0)     
                    AS DONT_REGLE_FPSPP,  
           imputation.PRC_FPSPP,  
           imputation.BLN_IMPUTABLE,
           TYPE_ACTIVITE.COD_TYPE_ACTIVITE ActivityType  

         from  dbo.GET_ACTIVITES_ADHERENT( @ID_ADHERENT,
                    @ID_PERIODE,
                    @ID_POSTE_VERSEMENT,
                    @ID_TYPE_VERSEMENT,  
                    @ID_TYPE_ASSUJETISSEMENT,  

                    @ID_ETABLISSEMENT_VERSEUR) imputation

           LEFT JOIN POSTE_IMPUTATION ON  POSTE_IMPUTATION.ID_ACTIVITE    = imputation.ID_ACTIVITE AND  
                   POSTE_IMPUTATION.ID_POSTE_VERSEMENT   = @ID_POSTE_VERSEMENT  
           LEFT JOIN POSTE_VERSEMENT ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT   = POSTE_VERSEMENT.ID_POSTE_VERSEMENT AND   
                   POSTE_VERSEMENT.ID_ADHERENT_BENEFICIAIRE = @ID_ADHERENT AND   
                   POSTE_VERSEMENT.ID_PERIODE     = @ID_PERIODE  AND   
                   POSTE_VERSEMENT.BLN_ACTIF     = 1   
           LEFT JOIN ADHERENT   ON  ADHERENT.ID_ADHERENT      = POSTE_VERSEMENT.ID_ADHERENT_BENEFICIAIRE  
           LEFT JOIN DEDUCTION   ON DEDUCTION.ID_ADHERENT      = @ID_ADHERENT AND   
                   DEDUCTION.ID_PERIODE      = @ID_PERIODE AND  
                   DEDUCTION.ID_ACTIVITE      = imputation.ID_ACTIVITE  
           INNER JOIN ACTIVITE   ON ACTIVITE.ID_ACTIVITE = imputation.ID_ACTIVITE  
           INNER JOIN TYPE_ACTIVITE ON TYPE_ACTIVITE.ID_TYPE_ACTIVITE = ACTIVITE.ID_TYPE_ACTIVITE   
          ORDER by ACTIVITE.NUM_ORDRE  

         END
GO

         CREATE PROCEDURE [dbo].[UPDATE_REGLEMENT_PRO_VALIDABLE]
         AS
         BEGIN

         	CREATE TABLE #TEMP (ID_SESSION_PRO int, ID_SESSION_BAP_PRO int)

         	INSERT INTO #TEMP
         	SELECT DISTINCT SESSION_PRO.ID_SESSION_PRO AS ID_SESSION_PRO,
         					SESSION_BAP_PRO.ID_SESSION_BAP_PRO
         	FROM			SESSION_PRO
         					LEFT JOIN  REGLEMENT_PRO AS REGLEMENT_PRO_ADH ON SESSION_PRO.ID_REGLEMENT_PRO_ADH = REGLEMENT_PRO_ADH.ID_REGLEMENT_PRO
         					LEFT JOIN  REGLEMENT_PRO AS REGLEMENT_PRO_OF ON SESSION_PRO.ID_REGLEMENT_PRO_OF = REGLEMENT_PRO_OF.ID_REGLEMENT_PRO
         					LEFT JOIN  SESSION_BAP_PRO ON 
         												(
         												SESSION_PRO.ID_SESSION_BAP_PRO_OF = SESSION_BAP_PRO.ID_SESSION_BAP_PRO
         												AND	REGLEMENT_PRO_OF.DAT_VALID_REGLEMENT IS NULL 
         												AND	REGLEMENT_PRO_OF.BLN_EN_COURS = 1 
         												AND	REGLEMENT_PRO_OF.BLN_ACTIF = 1 
         												AND	REGLEMENT_PRO_OF.DAT_EDITION IS NOT NULL
         												)
         	WHERE			SESSION_BAP_PRO.ID_SESSION_BAP_PRO IS NOT NULL

         	INSERT INTO #TEMP
         	SELECT DISTINCT SESSION_PRO.ID_SESSION_PRO AS ID_SESSION_PRO,
         					SESSION_BAP_PRO.ID_SESSION_BAP_PRO
         	FROM			SESSION_PRO 
         					LEFT JOIN  REGLEMENT_PRO AS REGLEMENT_PRO_ADH ON SESSION_PRO.ID_REGLEMENT_PRO_ADH = REGLEMENT_PRO_ADH.ID_REGLEMENT_PRO
         					LEFT JOIN  REGLEMENT_PRO AS REGLEMENT_PRO_OF ON SESSION_PRO.ID_REGLEMENT_PRO_OF = REGLEMENT_PRO_OF.ID_REGLEMENT_PRO
         					LEFT JOIN  SESSION_BAP_PRO ON
         												(
         												SESSION_PRO.ID_SESSION_BAP_PRO_ADH = SESSION_BAP_PRO.ID_SESSION_BAP_PRO
         											    AND REGLEMENT_PRO_ADH.DAT_VALID_REGLEMENT IS NULL 
         											    AND REGLEMENT_PRO_ADH.BLN_EN_COURS = 1 
         											    AND REGLEMENT_PRO_ADH.BLN_ACTIF = 1 
         											    AND REGLEMENT_PRO_ADH.DAT_EDITION IS NOT NULL
         												)
         	WHERE			SESSION_BAP_PRO.ID_SESSION_BAP_PRO IS NOT NULL
         	AND				NOT EXISTS (SELECT 1 FROM #TEMP WHERE #TEMP.ID_SESSION_PRO = SESSION_PRO.ID_SESSION_PRO AND #TEMP.ID_SESSION_BAP_PRO = SESSION_BAP_PRO.ID_SESSION_BAP_PRO)

         	UPDATE	REGLEMENT_PRO 
         	SET		REGLEMENT_PRO.DAT_VALID_REGLEMENT = GETDATE(),
         			REGLEMENT_PRO.BLN_EN_COURS = 0
         	WHERE		REGLEMENT_PRO.DAT_VALID_REGLEMENT IS NULL 
         						AND	REGLEMENT_PRO.BLN_EN_COURS = 1 
         						AND	REGLEMENT_PRO.BLN_ACTIF = 1 
         						AND	REGLEMENT_PRO.DAT_EDITION IS NOT NULL

         	UPDATE	SESSION_BAP_PRO
         	SET		SESSION_BAP_PRO.DAT_PAIEMENT  = GETDATE()
         	WHERE	SESSION_BAP_PRO.ID_SESSION_BAP_PRO  IN (SELECT DISTINCT ID_SESSION_BAP_PRO FROM #TEMP)

         	UPDATE REGLEMENT_PRO
         	SET	   REGLEMENT_PRO.BLN_EN_COURS = 0
         	WHERE  REGLEMENT_PRO.ID_REGLEMENT_PRO IN (
         				SELECT DISTINCT REGLEMENT_PRO.ID_REGLEMENT_PRO
         				FROM			REGLEMENT_PRO
         				WHERE		REGLEMENT_PRO.DAT_VALID_REGLEMENT IS NULL 
         						AND	REGLEMENT_PRO.BLN_EN_COURS = 1 
         						AND	REGLEMENT_PRO.BLN_ACTIF = 0
         						AND	REGLEMENT_PRO.DAT_EDITION IS NOT NULL 
         	)

         END

GO

