         CREATE  PROCEDURE [dbo].[LEC_GRP_PARCOURS_MBL]

         	@COD_PARCOURS VARCHAR(8),   
         	@BLN_ACTIF TINYINT,  
         	@ID_SALARIE INT ,
         	@ID_INDIVIDU INTEGER,
         	@ID_ETABLISSEMENT INT,
         	@ID_ADHERENT INT,
         	@LIBL_PARCOURS varchar(50),
         	@DAT_DEBUT datetime,
         	@DAT_FIN datetime

         AS
         DECLARE @SQLQuery AS NVARCHAR(1500)
         DECLARE @ParameterDefinition AS NVARCHAR(500) 

         BEGIN
         	SET @SQLQuery = ''

         	SET @SQLQuery += ' Select  '+ CHAR(13)
         	SET @SQLQuery += ' PARCOURS.ID_PARCOURS	, '+ CHAR(13)
         	SET @SQLQuery += ' PARCOURS.COD_PARCOURS, '+ CHAR(13)
         	SET @SQLQuery += ' SALARIE.ID_INDIVIDU, '+ CHAR(13)
         	SET @SQLQuery += ' SALARIE.ID_ETABLISSEMENT, '+ CHAR(13)
         	SET @SQLQuery += ' PARCOURS.ID_SALARIE, '+ CHAR(13)
         	SET @SQLQuery += ' PARCOURS.LIBL_PARCOURS, '+ CHAR(13)
         	SET @SQLQuery += ' PARCOURS.DAT_DEBUT, '+ CHAR(13)
         	SET @SQLQuery += ' PARCOURS.DAT_FIN, '+ CHAR(13)
         	SET @SQLQuery += ' PARCOURS.BLN_ACTIF, '+ CHAR(13)
         	SET @SQLQuery += ' INDIVIDU.NOM_INDIVIDU, '+ CHAR(13)
         	SET @SQLQuery += ' cast(coalesce(PT.somme_heures,0)  + coalesce(US.somme_stag,0)  '+ CHAR(13)
         	SET @SQLQuery += '  as decimal(18,2))	AS NUM_DUREE_TOTALE_HEURE '+ CHAR(13)

         	SET @SQLQuery += ' 	FROM  PARCOURS '+ CHAR(13)
         	SET @SQLQuery += ' 	INNER JOIN SALARIE on SALARIE.ID_SALARIE = PARCOURS.ID_SALARIE  '+ CHAR(13)
         	SET @SQLQuery += ' 	INNER JOIN ETABLISSEMENT on ETABLISSEMENT.ID_ETABLISSEMENT = SALARIE.ID_ETABLISSEMENT  '+ CHAR(13)
         	SET @SQLQuery += '  INNER JOIN INDIVIDU          ON SALARIE.ID_INDIVIDU	= INDIVIDU.ID_INDIVIDU '+ CHAR(13)

         	SET @SQLQuery += '  LEFT  JOIN (select	sum(COALESCE(PARCOURS_TEMP.NUM_DUREE_HEURE,0)) as somme_heures,  '+ CHAR(13)
         	SET @SQLQuery += '						ID_PARCOURS '+ CHAR(13)
         	SET @SQLQuery += '						from PARCOURS_TEMP '+ CHAR(13)
         	SET @SQLQuery += '						group by ID_PARCOURS ' + CHAR(13)
         	SET @SQLQuery += '				)  PT  '+ CHAR(13)
         	SET @SQLQuery += '				on PT.ID_PARCOURS = PARCOURS.ID_PARCOURS '+ CHAR(13)

         	SET @SQLQuery += '  LEFT  JOIN (select  sum(COALESCE(UNITE_STAGIAIRE.NB_HEURE_ENGAGE,0)) as somme_stag, ' + CHAR(13)
         	SET @SQLQuery += '						ID_PARCOURS ' + CHAR(13)
         	SET @SQLQuery += '						from UNITE_STAGIAIRE  '+ CHAR(13)
         	SET @SQLQuery += '						group by ID_PARCOURS  '+ CHAR(13) 
         	SET @SQLQuery += '				) US '+ CHAR(13) 
         	SET @SQLQuery += '				on US.ID_PARCOURS = PARCOURS.ID_PARCOURS 	 '+ CHAR(13)					
         	SET @SQLQuery += '  WHERE PARCOURS.BLN_ACTIF >= CASE @BLN_ACTIF WHEN 0 THEN 1 ELSE 0 END '  + CHAR(13)		

         	IF @COD_PARCOURS IS NOT NULL
         	BEGIN
         		SET @SQLQuery += '  AND PARCOURS.COD_PARCOURS	= '''+@COD_PARCOURS+''''  
         	END
         	IF @ID_SALARIE IS NOT NULL
         	BEGIN
         		SET @SQLQuery += '  AND PARCOURS.ID_SALARIE	 =  @ID_SALARIE ' + CHAR(13)		
         	END
         	IF @ID_INDIVIDU IS NOT NULL
         	BEGIN
         		SET @SQLQuery += '  AND SALARIE.ID_INDIVIDU = @ID_INDIVIDU '  + CHAR(13)		
         	END
         	IF @ID_ETABLISSEMENT IS NOT NULL
         	BEGIN
         		SET @SQLQuery += '  AND SALARIE.ID_ETABLISSEMENT = @ID_ETABLISSEMENT' + CHAR(13)		
         	END
         	IF @ID_ADHERENT IS NOT NULL
         	BEGIN
         		SET @SQLQuery += '  AND ETABLISSEMENT.ID_ADHERENT = @ID_ADHERENT' + CHAR(13)		
         	END
         	IF @DAT_DEBUT IS NOT NULL
         	BEGIN
         		SET @SQLQuery += '  AND (PARCOURS.DAT_DEBUT IS NULL OR PARCOURS.DAT_DEBUT >= @DAT_DEBUT)' + CHAR(13)		
         	END
         	IF @DAT_FIN IS NOT NULL
         	BEGIN
         		SET @SQLQuery += '  AND (PARCOURS.DAT_FIN IS NULL OR PARCOURS.DAT_FIN <=  @DAT_FIN)' + CHAR(13)		
         	END
         	IF @LIBL_PARCOURS IS NOT NULL
         	BEGIN
         		SET @SQLQuery += '  AND PARCOURS.LIBL_PARCOURS	LIKE '''+@LIBL_PARCOURS+'%'''   + CHAR(13)		
         	END
         	SET @SQLQuery += ' ORDER BY PARCOURS.ID_PARCOURS '

         	SET @ParameterDefinition = '@COD_PARCOURS VARCHAR(8), @BLN_ACTIF TINYINT, @ID_SALARIE INT ,@ID_INDIVIDU INTEGER,@ID_ETABLISSEMENT INT,@ID_ADHERENT INT,@LIBL_PARCOURS varchar(50),@DAT_DEBUT datetime,@DAT_FIN datetime'

         	EXECUTE sp_executesql @SQLQuery, @ParameterDefinition, @COD_PARCOURS, @BLN_ACTIF, @ID_SALARIE, @ID_INDIVIDU, @ID_ETABLISSEMENT, @ID_ADHERENT, @LIBL_PARCOURS, @DAT_DEBUT, @DAT_FIN

         END

GO
CREATE PROCEDURE [dbo].[GET_SOLDE_ENGAGEMENT_MODULE_POUR_ENVELOPPE]
          @ID_MODULE    INT,
          @ID_ENVELOPPE   INT,
          @ID_TYPE_FINANCEMENT INT,
          @ID_POSTE_COUT_REGLE INT
         WITH RECOMPILE
         AS

         BEGIN
          DECLARE
           @SOLDE_ENGAGEMENT_MODULE DECIMAL(18,2),
           @MONTANT_ENGAGE    DECIMAL(18,2),
           @MONTANT_CONSOMME   DECIMAL(18,2)

          SELECT
           @MONTANT_ENGAGE = sum(COALESCE(PLAN_FINANCEMENT_US.MNT_PLAN_FINANCEMENT_US,0))
          FROM
           STAGIAIRE_PEC
           INNER JOIN UNITE_STAGIAIRE
            ON UNITE_STAGIAIRE.ID_STAGIAIRE_PEC = STAGIAIRE_PEC.ID_STAGIAIRE_PEC
           INNER JOIN PLAN_FINANCEMENT_US
            ON UNITE_STAGIAIRE.ID_UNITE_STAGIAIRE = PLAN_FINANCEMENT_US.ID_UNITE_STAGIAIRE
          WHERE
           STAGIAIRE_PEC.ID_MODULE_PEC = @ID_MODULE
           AND STAGIAIRE_PEC.ID_SESSION_PEC IS NULL
           AND
           (
            PLAN_FINANCEMENT_US.ID_ENVELOPPE = @ID_ENVELOPPE
            OR
            (
             PLAN_FINANCEMENT_US.ID_ENVELOPPE IS NULL
             AND @ID_ENVELOPPE IS NULL
            )
           )
           AND
           (
            PLAN_FINANCEMENT_US.ID_TYPE_FINANCEMENT = @ID_TYPE_FINANCEMENT
            OR
            (
             PLAN_FINANCEMENT_US.ID_TYPE_FINANCEMENT IS NULL
             AND @ID_TYPE_FINANCEMENT IS NULL
            )
           )

          SELECT
           @MONTANT_CONSOMME = sum(COALESCE(PLAN_FINANCEMENT_US.MNT_PLAN_FINANCEMENT_US,0))
          FROM
           PLAN_FINANCEMENT_US
           INNER JOIN POSTE_COUT_REGLE
            ON POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE = PLAN_FINANCEMENT_US.ID_POSTE_COUT_REGLE
          WHERE
           POSTE_COUT_REGLE.ID_MODULE_PEC = @ID_MODULE
           AND POSTE_COUT_REGLE.BLN_ACTIF = 1
           AND
           (
            @ID_POSTE_COUT_REGLE IS NULL
            OR POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE <> @ID_POSTE_COUT_REGLE
           )
           AND
           (
            @ID_ENVELOPPE IS NULL
            OR
            (
             PLAN_FINANCEMENT_US.ID_ENVELOPPE = @ID_ENVELOPPE
            )
            OR
            (
             PLAN_FINANCEMENT_US.ID_ENVELOPPE IS NULL AND @ID_ENVELOPPE IS NULL
            )
           )
           AND
           (
            @ID_TYPE_FINANCEMENT IS NULL
            OR
            (
             PLAN_FINANCEMENT_US.ID_TYPE_FINANCEMENT = @ID_TYPE_FINANCEMENT
             OR
             (
              PLAN_FINANCEMENT_US.ID_TYPE_FINANCEMENT IS NULL
              AND @ID_TYPE_FINANCEMENT IS NULL
             )
            )
           )

          SET @SOLDE_ENGAGEMENT_MODULE = COALESCE(@MONTANT_ENGAGE,0) - COALESCE(@MONTANT_CONSOMME,0)

          SELECT
           @SOLDE_ENGAGEMENT_MODULE  AS SOLDE_ENGAGEMENT_MODULE
         END
GO

         CREATE PROCEDURE LEC_GRP_ORDRE_VIREMENT_REGULARISATION
         	@TYPE_ETAT INTEGER, 
         	@DATE_DEBUT datetime,
         	@DATE_FIN datetime
         with recompile
         AS
         	BEGIN
         		CREATE TABLE #TEMP
         		(
         			ID_VIREMENT_INTERNE_COLLECTE INTEGER,
         			ID_ACTIVITE INTEGER,
         			DAT_EDIT_VIREMENT_INTERNE_COLLECTE Datetime,
         			DAT_COMPTA_VIREMENT_INTERNE_COLLECTE Datetime,
         			MNT_VIREMENT_INTERNE_COLLECTE decimal(18,2)
         		)

         		IF (@TYPE_ETAT = 1)
         			BEGIN
         				INSERT INTO #TEMP
         				SELECT DISTINCT 
         					VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.ID_ACTIVITE,
         					VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.DAT_COMPTA_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE
         				FROM
         					VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_IMPUTATION ON VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE = POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_VERSEMENT ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT = POSTE_VERSEMENT.ID_POSTE_VERSEMENT

         					INNER JOIN TYPE_VERSEMENT ON	POSTE_VERSEMENT.ID_TYPE_VERSEMENT = TYPE_VERSEMENT.ID_TYPE_VERSEMENT
         				WHERE   

         					(TYPE_VERSEMENT.BLN_VERSEMENT = 1 and 
         					TYPE_VERSEMENT.BLN_VERSEMENT_INITIAL = 0) 

         					AND (VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE IS NULL)

         				UPDATE VIREMENT_INTERNE_COLLECTE
         				SET VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE = getDate()
         				where VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE in (select ID_VIREMENT_INTERNE_COLLECTE from #TEMP)
         			END
         		ELSE
         			BEGIN
         				INSERT INTO #TEMP
         				SELECT DISTINCT
         					VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.ID_ACTIVITE,
         					VIREMENT_INTERNE_COLLECTE.DAT_EDIT_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.DAT_COMPTA_VIREMENT_INTERNE_COLLECTE,
         					VIREMENT_INTERNE_COLLECTE.MNT_VIREMENT_INTERNE_COLLECTE
         				FROM
         					VIREMENT_INTERNE_COLLECTE
         					LEFT OUTER JOIN POSTE_IMPUTATION ON VIREMENT_INTERNE_COLLECTE.ID_VIREMENT_INTERNE_COLLECTE = POSTE_IMPUTATION.ID_VIREMENT_INTERNE_COLLECTE 
         					LEFT OUTER JOIN POSTE_VERSEMENT ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT = POSTE_VERSEMENT.ID_POSTE_VERSEMENT

         					INNER JOIN TYPE_VERSEMENT ON	POSTE_VERSEMENT.ID_TYPE_VERSEMENT = TYPE_VERSEMENT.ID_TYPE_VERSEMENT
         				WHERE       

         					(TYPE_VERSEMENT.BLN_VERSEMENT = 1 and 
         					TYPE_VERSEMENT.BLN_VERSEMENT_INITIAL = 0) 

         					AND ((@DATE_DEBUT IS NULL OR DATEDIFF(DAY,DAT_EDIT_VIREMENT_INTERNE_COLLECTE,@DATE_DEBUT) <= 0)) 
         					AND	((@DATE_FIN  IS NULL OR DATEDIFF(DAY,DAT_EDIT_VIREMENT_INTERNE_COLLECTE,@DATE_FIN ) >= 0))
         			END

         		SELECT
         			#TEMP.ID_VIREMENT_INTERNE_COLLECTE,
         			#TEMP.MNT_VIREMENT_INTERNE_COLLECTE,
         			TRANSIT.NUM_IBAN_TRANSIT,
         			TRANSIT.LIB_COMPTE_BANQUE,
         			ACTIVITE.LIB_COMPTE_BANQUE,
         			ACTIVITE.NUM_IBAN_ACTIVITE,
         			ACTIVITE.LIB_BANQUE,
         			PARAMETRES.NOM_PNM_SECRETAIRE_GENERAL,
         			PARAMETRES.NOM_PNM_DAF
         		FROM
         			#TEMP
         			INNER JOIN ACTIVITE ON  #TEMP.ID_ACTIVITE = ACTIVITE.ID_ACTIVITE
         			CROSS JOIN PARAMETRES
         			CROSS JOIN TRANSIT
         		WHERE
         			#TEMP.MNT_VIREMENT_INTERNE_COLLECTE > 0
         		order by
         			#TEMP.ID_VIREMENT_INTERNE_COLLECTE
         	END
GO

         CREATE  PROCEDURE [dbo].[LEC_GRP_PARCOURS]

         	@COD_PARCOURS VARCHAR(8),   
         	@BLN_ACTIF TINYINT,  
         	@ID_SALARIE INT ,
         	@ID_INDIVIDU INTEGER,
         	@ID_ETABLISSEMENT INT,
         	@ID_ADHERENT INT,
         	@LIBL_PARCOURS varchar(50),
         	@DAT_DEBUT datetime,
         	@DAT_FIN datetime

         AS
         DECLARE @SQLQuery AS NVARCHAR(1500)
         DECLARE @ParameterDefinition AS NVARCHAR(500) 

         BEGIN
         	SET @SQLQuery = ''

         	SET @SQLQuery += ' Select  '+ CHAR(13)
         	SET @SQLQuery += ' PARCOURS.ID_PARCOURS	, '+ CHAR(13)
         	SET @SQLQuery += ' PARCOURS.COD_PARCOURS, '+ CHAR(13)
         	SET @SQLQuery += ' SALARIE.ID_INDIVIDU, '+ CHAR(13)
         	SET @SQLQuery += ' SALARIE.ID_ETABLISSEMENT, '+ CHAR(13)
         	SET @SQLQuery += ' PARCOURS.ID_SALARIE, '+ CHAR(13)
         	SET @SQLQuery += ' PARCOURS.LIBL_PARCOURS, '+ CHAR(13)
         	SET @SQLQuery += ' PARCOURS.DAT_DEBUT, '+ CHAR(13)
         	SET @SQLQuery += ' PARCOURS.DAT_FIN, '+ CHAR(13)
         	SET @SQLQuery += ' PARCOURS.BLN_ACTIF, '+ CHAR(13)
         	SET @SQLQuery += ' INDIVIDU.NOM_INDIVIDU, '+ CHAR(13)
         	SET @SQLQuery += ' cast(coalesce(PT.somme_heures,0)  + coalesce(US.somme_stag,0)  '+ CHAR(13)
         	SET @SQLQuery += '  as decimal(18,2))	AS NUM_DUREE_TOTALE_HEURE '+ CHAR(13)

         	SET @SQLQuery += ' 	FROM  PARCOURS '+ CHAR(13)
         	SET @SQLQuery += ' 	INNER JOIN SALARIE on SALARIE.ID_SALARIE = PARCOURS.ID_SALARIE  '+ CHAR(13)
         	SET @SQLQuery += ' 	INNER JOIN ETABLISSEMENT on ETABLISSEMENT.ID_ETABLISSEMENT = SALARIE.ID_ETABLISSEMENT  '+ CHAR(13)
         	SET @SQLQuery += '  INNER JOIN INDIVIDU          ON SALARIE.ID_INDIVIDU	= INDIVIDU.ID_INDIVIDU '+ CHAR(13)

         	SET @SQLQuery += '  LEFT  JOIN (select	sum(COALESCE(PARCOURS_TEMP.NUM_DUREE_HEURE,0)) as somme_heures,  '+ CHAR(13)
         	SET @SQLQuery += '						ID_PARCOURS '+ CHAR(13)
         	SET @SQLQuery += '						from PARCOURS_TEMP '+ CHAR(13)
         	SET @SQLQuery += '						group by ID_PARCOURS ' + CHAR(13)
         	SET @SQLQuery += '				)  PT  '+ CHAR(13)
         	SET @SQLQuery += '				on PT.ID_PARCOURS = PARCOURS.ID_PARCOURS '+ CHAR(13)

         	SET @SQLQuery += '  LEFT  JOIN (select  sum(COALESCE(UNITE_STAGIAIRE.NB_HEURE_ENGAGE,0)) as somme_stag, ' + CHAR(13)
         	SET @SQLQuery += '						ID_PARCOURS ' + CHAR(13)
         	SET @SQLQuery += '						from UNITE_STAGIAIRE  '+ CHAR(13)
         	SET @SQLQuery += '						group by ID_PARCOURS  '+ CHAR(13) 
         	SET @SQLQuery += '				) US '+ CHAR(13) 
         	SET @SQLQuery += '				on US.ID_PARCOURS = PARCOURS.ID_PARCOURS 	 '+ CHAR(13)					
         	SET @SQLQuery += '  WHERE PARCOURS.BLN_ACTIF >= CASE @BLN_ACTIF WHEN 0 THEN 1 ELSE 0 END '  + CHAR(13)		

         	IF @COD_PARCOURS IS NOT NULL
         	BEGIN
         		SET @SQLQuery += '  AND PARCOURS.COD_PARCOURS	= '''+@COD_PARCOURS+''''  
         	END
         	IF @ID_SALARIE IS NOT NULL
         	BEGIN
         		SET @SQLQuery += '  AND PARCOURS.ID_SALARIE	 =  @ID_SALARIE ' + CHAR(13)		
         	END
         	IF @ID_INDIVIDU IS NOT NULL
         	BEGIN
         		SET @SQLQuery += '  AND SALARIE.ID_INDIVIDU = @ID_INDIVIDU '  + CHAR(13)		
         	END
         	IF @ID_ETABLISSEMENT IS NOT NULL
         	BEGIN
         		SET @SQLQuery += '  AND SALARIE.ID_ETABLISSEMENT = @ID_ETABLISSEMENT' + CHAR(13)		
         	END
         	IF @ID_ADHERENT IS NOT NULL
         	BEGIN
         		SET @SQLQuery += '  AND ETABLISSEMENT.ID_ADHERENT = @ID_ADHERENT' + CHAR(13)		
         	END
         	IF @DAT_DEBUT IS NOT NULL
         	BEGIN
         		SET @SQLQuery += '  AND (PARCOURS.DAT_DEBUT IS NULL OR PARCOURS.DAT_DEBUT >= @DAT_DEBUT)' + CHAR(13)		
         	END
         	IF @DAT_FIN IS NOT NULL
         	BEGIN
         		SET @SQLQuery += '  AND (PARCOURS.DAT_FIN IS NULL OR PARCOURS.DAT_FIN <=  @DAT_FIN)' + CHAR(13)		
         	END
         	IF @LIBL_PARCOURS IS NOT NULL
         	BEGIN
         		SET @SQLQuery += '  AND PARCOURS.LIBL_PARCOURS	LIKE '''+@LIBL_PARCOURS+'%'''   + CHAR(13)		
         	END
         	SET @SQLQuery += ' ORDER BY PARCOURS.ID_PARCOURS '

         	SET @ParameterDefinition = '@COD_PARCOURS VARCHAR(8), @BLN_ACTIF TINYINT, @ID_SALARIE INT ,@ID_INDIVIDU INTEGER,@ID_ETABLISSEMENT INT,@ID_ADHERENT INT,@LIBL_PARCOURS varchar(50),@DAT_DEBUT datetime,@DAT_FIN datetime'

         	EXECUTE sp_executesql @SQLQuery, @ParameterDefinition, @COD_PARCOURS, @BLN_ACTIF, @ID_SALARIE, @ID_INDIVIDU, @ID_ETABLISSEMENT, @ID_ADHERENT, @LIBL_PARCOURS, @DAT_DEBUT, @DAT_FIN

         END

GO
 CREATE PROCEDURE [dbo].[LEC_GRP_IMPUTATION_PAR_ACTIVITE]
          @ID_ADHERENT  INT,
          @ID_PERIODE   INT,
          @ID_VERSEMENT  INT = NULL,
          @ID_ETABLISSEMENT INT, 
          @ID_TYPE_VERSEMENT INT,
          @ID_ACTIVITE  INT
         AS

         BEGIN

          DECLARE
           @GRP_TYPE_VERSEMENT VARCHAR(1)

          SET
           @GRP_TYPE_VERSEMENT = NULL

          SELECT
           @GRP_TYPE_VERSEMENT = GRP_TYPE_VERSEMENT
          FROM
           TYPE_VERSEMENT 
          WHERE
           ID_TYPE_VERSEMENT = @ID_TYPE_VERSEMENT

          SELECT
           ADHERENT.ID_ADHERENT,
           PERIODE.ID_PERIODE,
           ACTIVITE.ID_ACTIVITE,
           CASE
            WHEN  (LEN(ETABLISSEMENT.NUM_SIRET) > 9)
             THEN SUBSTRING(ETABLISSEMENT.NUM_SIRET, 10, LEN(ETABLISSEMENT.NUM_SIRET))
            ELSE
             ''
           END AS NIC,
           ADHERENT.LIB_RAISON_SOCIALE,
           CASE WHEN ACTIVITE.ID_ACTIVITE IS NULL THEN 0 ELSE 1 END AS BLN_IMPUTABLE,
           ACTIVITE.LIBL_ACTIVITE,
           ACTIVITE.NUM_ORDRE,
           PERIODE.COD_PERIODE,
           PERIODE.NUM_ANNEE,
           dbo.GetMasseSalariale(ADHERENT.ID_ADHERENT,PERIODE.ID_PERIODE, ACTIVITE.ID_TYPE_MASSE_SALARIALE) AS MASSE_SALARIALE,
           CASE
            WHEN EXISTS (
               SELECT TOP 1
                ID_ADHERENT
               FROM
                R19
               WHERE
                R19.ID_ADHERENT = ADHERENT.ID_ADHERENT
                AND R19.ID_ACTIVITE = ACTIVITE.ID_ACTIVITE
                AND R19.ID_PERIODE = PERIODE.ID_PERIODE
               )
              THEN 1
             ELSE  0
           END AS COEFF_CALCUL,
           COALESCE(PARAMETRE_GLOBAL.TAU_GLO_APPEL, 0)      AS TAU_GLO_APPEL,
           100                AS PRC_OPTION,
           100     AS PRC_APPELE,
           COALESCE(DEDUCTION.MNT_HT,0)         AS DEDUCTION_MNT_HT,
           CAST(SUM(POSTE_IMPUTATION.MNT_HT * BLN_VERSEMENT)AS DECIMAL(18,2))    AS VERSE_HT,
           CAST(SUM(POSTE_IMPUTATION.MNT_HT * ABS(1 - BLN_VERSEMENT)) AS DECIMAL(18,2)) AS REVERSE_HT,
           CAST(SUM(POSTE_IMPUTATION.DONT_REGLE_FPSPP) AS DECIMAL(18,2))     AS VERSE_DONT_REGLE_FPSPP,
           CAST(SUM(POSTE_IMPUTATION.DONT_REGLE_FPSPP * ABS(1-BLN_VERSEMENT))AS DECIMAL(18,2)) AS REVERSE_DONT_REGLE_FPSPP,
           CASE 
            WHEN  (ACTIVITE.COD_ACTIVITE <> 'DSP')
             THEN COALESCE(DBO.GETCURRENTTVA(ADHERENT.ID_TYPE_TVA),0) 
            ELSE  0 
           END AS TAU_TVA,
           VIEW_VERSEMENT.ID_ETABLISSEMENT_BENEFICIAIRE,
           ADRESSE.LIB_ADR,
           ADRESSE.LIB_CP_CEDEX,
           ADRESSE.LIB_VIL_CEDEX,
           VIEW_VERSEMENT.GRP_TYPE_VERSEMENT,
           COD_TYPE_ACTIVITE ActivityType
          FROM
           VIEW_VERSEMENT
           INNER JOIN POSTE_IMPUTATION
            ON POSTE_IMPUTATION.ID_POSTE_VERSEMENT = VIEW_VERSEMENT.ID_POSTE_VERSEMENT
           INNER JOIN ETABLISSEMENT
            ON ETABLISSEMENT.ID_ETABLISSEMENT = VIEW_VERSEMENT.ID_ETABLISSEMENT_BENEFICIAIRE
           INNER JOIN ADHERENT
            ON ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT
           INNER JOIN ACTIVITE
            ON POSTE_IMPUTATION.ID_ACTIVITE = ACTIVITE.ID_ACTIVITE
           INNER JOIN PERIODE
            ON VIEW_VERSEMENT.ID_PERIODE = PERIODE.ID_PERIODE
           INNER JOIN R20
            ON R20.ID_ADHERENT = ADHERENT.ID_ADHERENT
             AND R20.ID_PERIODE = PERIODE.ID_PERIODE
           INNER JOIN BRANCHE
            ON BRANCHE.ID_BRANCHE = ADHERENT.ID_BRANCHE
           LEFT JOIN PARAMETRE_GLOBAL
            ON PARAMETRE_GLOBAL.ID_TYPE_ASSUJETISSEMENT = R20.ID_TYPE_ASSUJETISSEMENT
             AND PARAMETRE_GLOBAL.ID_PERIODE = PERIODE.ID_PERIODE
             AND PARAMETRE_GLOBAL.ID_ACTIVITE = ACTIVITE.ID_ACTIVITE
             AND PARAMETRE_GLOBAL.ID_REGIME = BRANCHE.ID_REGIME
           LEFT JOIN DEDUCTION
            ON DEDUCTION.ID_ADHERENT = ADHERENT.ID_ADHERENT
             AND DEDUCTION.ID_PERIODE = PERIODE.ID_PERIODE
             AND DEDUCTION.ID_ACTIVITE = ACTIVITE.ID_ACTIVITE
           LEFT JOIN ADRESSE
            ON ADRESSE.ID_ADRESSE = ETABLISSEMENT.ID_ADRESSE_PRINCIPALE
           INNER JOIN TYPE_ACTIVITE
            ON TYPE_ACTIVITE.ID_TYPE_ACTIVITE = ACTIVITE.ID_TYPE_ACTIVITE
          WHERE
           VIEW_VERSEMENT.ENBANQUE = 1
           AND VIEW_VERSEMENT.BLN_IMPAYE = 0
           AND VIEW_VERSEMENT.BLN_ACTIF = 1
           AND
           (
            @ID_ADHERENT IS NULL
            OR ADHERENT.ID_ADHERENT = @ID_ADHERENT
           )
           AND
           (
            @ID_PERIODE IS NULL
            OR PERIODE.ID_PERIODE = @ID_PERIODE
           )
           AND
           (
            @ID_VERSEMENT IS NULL
            OR VIEW_VERSEMENT.ID_VERSEMENT = @ID_VERSEMENT
           )
           AND
           (
            @ID_ETABLISSEMENT IS NULL
            OR VIEW_VERSEMENT.ID_ETABLISSEMENT_BENEFICIAIRE = @ID_ETABLISSEMENT
           )
           AND
           (
            @GRP_TYPE_VERSEMENT IS NULL
            OR VIEW_VERSEMENT.GRP_TYPE_VERSEMENT = @GRP_TYPE_VERSEMENT
           )
           AND
           (
            @ID_ACTIVITE IS NULL
            OR ACTIVITE.ID_ACTIVITE = @ID_ACTIVITE
           )
          GROUP BY
           ADHERENT.ID_ADHERENT,
           ADHERENT.ID_TYPE_TVA,
           ADHERENT.LIB_RAISON_SOCIALE,
           PERIODE.ID_PERIODE,
           PERIODE.COD_PERIODE,
           PERIODE.NUM_ANNEE,
           ACTIVITE.ID_ACTIVITE,
           ACTIVITE.COD_ACTIVITE,
           ACTIVITE.NUM_ORDRE,
           ACTIVITE.LIBL_ACTIVITE,
           ACTIVITE.ID_TYPE_MASSE_SALARIALE,
           VIEW_VERSEMENT.GRP_TYPE_VERSEMENT,
           VIEW_VERSEMENT.ID_ETABLISSEMENT_BENEFICIAIRE,
           ETABLISSEMENT.NUM_SIRET,
           PARAMETRE_GLOBAL.TAU_GLO_APPEL,
           PRC_OPTION,
           DEDUCTION.MNT_HT,
           ADRESSE.LIB_ADR,
           ADRESSE.LIB_CP_CEDEX,
           ADRESSE.LIB_VIL_CEDEX,
           COD_TYPE_ACTIVITE
          ORDER BY
           PERIODE.NUM_ANNEE DESC,
           ACTIVITE.NUM_ORDRE DESC,
           VIEW_VERSEMENT.GRP_TYPE_VERSEMENT,
           ACTIVITE.ID_ACTIVITE
         END
GO

         CREATE PROCEDURE [dbo].[GET_SESSION_ACTIF_AND_REGLEMENT_VALIDEES] 
         	@ID_MODULE_PRO		int
         AS 

         BEGIN

         	SELECT count(*) AS NUMBER_OF_SESSIONS
         	into #temp
         	FROM		SESSION_PRO
         	WHERE		SESSION_PRO.BLN_ACTIF = 1
         	AND	(SESSION_PRO.ID_REGLEMENT_PRO_ADH is  null and SESSION_PRO.ID_REGLEMENT_PRO_OF is null)
         	AND SESSION_PRO.ID_MODULE_PRO=@ID_MODULE_PRO

         	update #temp set NUMBER_OF_SESSIONS=NUMBER_OF_SESSIONS + (

         	SELECT count(*) AS NUMBER_OF_SESSIONS
         	FROM		SESSION_PRO
         	INNER JOIN	REGLEMENT_PRO ON	SESSION_PRO.ID_REGLEMENT_PRO_ADH  = REGLEMENT_PRO.ID_REGLEMENT_PRO 
         										OR	SESSION_PRO.ID_REGLEMENT_PRO_OF  = REGLEMENT_PRO.ID_REGLEMENT_PRO
         	WHERE		SESSION_PRO.BLN_ACTIF = 1
         	AND	(REGLEMENT_PRO.DAT_VALID_REGLEMENT IS  NULL)
         	AND SESSION_PRO.ID_MODULE_PRO=@ID_MODULE_PRO)

         	Select NUMBER_OF_SESSIONS from #temp

         	DROP TABLE #temp

         END
GO
CREATE PROCEDURE [dbo].[LEC_COMPTE]  
          @ID_GROUPE    INT,
          @ID_PERIODE_FISC  INT,
          @ID_TYPE_FINANCEMENT INT,
          @ID_ACTIVITE   INT,
          @COM_COMPTE    VARCHAR(255) = NULL  
         AS

         BEGIN
          DECLARE
           @ID_COMPTE  INT = -1,
           @LIBL_COMPTE VARCHAR(50),
           @BLN_ACTIF  INT = 1,
           @ID_TYPE_COMPTE INT = 1

          SELECT @ID_ACTIVITE = dbo.GetActiviteSourceFinancementIndividualisee(@ID_TYPE_FINANCEMENT, @ID_PERIODE_FISC, @ID_ACTIVITE)

          SELECT
           @ID_COMPTE = ID_COMPTE
          FROM
           COMPTE
          WHERE
           ID_GROUPE = @ID_GROUPE
           AND ID_PERIODE = @ID_PERIODE_FISC
           AND ID_TYPE_FINANCEMENT = @ID_TYPE_FINANCEMENT
           AND ID_ACTIVITE = @ID_ACTIVITE

          IF (@ID_COMPTE = -1 AND @ID_ACTIVITE IS NOT NULL)
          BEGIN
           SELECT
            @LIBL_COMPTE = GROUPE.LIB_GROUPE
           FROM
            GROUPE
           WHERE
            GROUPE.ID_GROUPE= @ID_GROUPE

           EXEC @ID_COMPTE = INS_COMPTE
             @LIBL_COMPTE,
             @BLN_ACTIF,
             @ID_GROUPE,
             @ID_PERIODE_FISC,
             @ID_TYPE_COMPTE,
             @ID_ACTIVITE,
             @ID_TYPE_FINANCEMENT

           IF (isnull(@ID_COMPTE,0) > 0 AND @COM_COMPTE IS NOT NULL)
           BEGIN
            UPDATE
             COMPTE
            SET
             COM_COMPTE = @COM_COMPTE
            WHERE
             ID_COMPTE = @ID_COMPTE
           END
          END

          RETURN @ID_COMPTE
         END
GO

         CREATE PROCEDURE [dbo].[UPD_DATE_LETTRE_RELANCE_REGLEMENT_OF]
         	@CODS_SESSION_PEC TEXT	
         AS

         BEGIN

         	DECLARE @Item varchar(17);

         	CREATE TABLE #List(Item VARCHAR(17) collate French_CI_AI)

         	DECLARE @Delimiter char
         	SET @Delimiter = ','
         	WHILE CHARINDEX(@Delimiter,@CODS_SESSION_PEC,0) <> 0
         	BEGIN
         		SELECT
         			@Item=RTRIM(LTRIM(SUBSTRING(@CODS_SESSION_PEC,1,CHARINDEX(@Delimiter,@CODS_SESSION_PEC,0)-1))),
         			@CODS_SESSION_PEC=RTRIM(LTRIM(SUBSTRING(@CODS_SESSION_PEC,CHARINDEX(@Delimiter,@CODS_SESSION_PEC,0)+1,DATALENGTH(@CODS_SESSION_PEC))))

         		IF LEN(@Item) > 0
         			INSERT INTO #List SELECT @Item
         	END

         	IF DATALENGTH(@CODS_SESSION_PEC) > 0
         		INSERT INTO #List SELECT @CODS_SESSION_PEC

         	SELECT  DISTINCT MODULE_PEC.ID_MODULE_PEC,
         					 SESSION_PEC.ID_SESSION_PEC,
         					 POSTE_COUT_REGLE.ID_POSTE_COUT_REGLE,
         					 POSTE_COUT_REGLE.BLN_FACTURE_DIRECTE,
         					 MODULE_PEC.ID_ETABLISSEMENT_OF,
         					 ETABLISSEMENT_OF.ID_OF

         	INTO	#TEMP_SESSIONS

         	FROM	MODULE_PEC
         			INNER JOIN SESSION_PEC ON MODULE_PEC.ID_MODULE_PEC = SESSION_PEC.ID_MODULE_PEC 
         			INNER JOIN POSTE_COUT_REGLE ON MODULE_PEC.ID_MODULE_PEC = POSTE_COUT_REGLE.ID_MODULE_PEC
         			INNER JOIN ETABLISSEMENT_OF ON MODULE_PEC.ID_ETABLISSEMENT_OF = ETABLISSEMENT_OF.ID_ETABLISSEMENT_OF 
         			INNER JOIN ORGANISME_FORMATION ON ETABLISSEMENT_OF.ID_OF = ORGANISME_FORMATION.ID_OF

         	WHERE		(MODULE_PEC.BLN_ACTIF = 1)
         			AND (SESSION_PEC.BLN_ACTIF = 1)
         			AND (POSTE_COUT_REGLE.BLN_ACTIF = 1)
         			AND ((MODULE_PEC.BLN_OK_PIECE = 0) OR (POSTE_COUT_REGLE.BLN_OK_PIECE = 0))
         			AND ( SESSION_PEC.COD_SESSION_PEC  in (SELECT Item FROM #List)  )

         	SELECT  DISTINCT ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC
         	INTO	#TEMP_RELANCE_1	
         	FROM    #TEMP_SESSIONS 
         			INNER JOIN ARRIVEE_PIECE_PEC ON #TEMP_SESSIONS.ID_POSTE_COUT_REGLE = ARRIVEE_PIECE_PEC.ID_POSTE_COUT_REGLE
         			INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         			INNER JOIN POSTE_COUT_REGLE ON POSTE_COUT_REGLE.ID_MODULE_PEC = #TEMP_SESSIONS.ID_MODULE_PEC										
         	WHERE		(PIECE_PEC.BLN_POSTE_COUT_REGLE = 1)
         			AND	(ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1 IS NULL) 
         			AND (ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2 IS NULL) 
         			AND (ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3 IS NULL)
         			AND (#TEMP_SESSIONS.BLN_FACTURE_DIRECTE = 1)
         			AND (PIECE_PEC.BLN_ACTIF = 1)
         			AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         			AND ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) AND ( EXISTS (select 1 from NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))
         	UNION

         	SELECT  DISTINCT ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC
         	FROM    #TEMP_SESSIONS 
         			INNER JOIN ARRIVEE_PIECE_PEC ON #TEMP_SESSIONS.ID_SESSION_PEC = ARRIVEE_PIECE_PEC.ID_SESSION_PEC
         			INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC

         	WHERE		(PIECE_PEC.BLN_SESSION = 1)
         			AND	(ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1 IS NULL) 
         			AND (ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2 IS NULL) 
         			AND (ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3 IS NULL)
         			AND (#TEMP_SESSIONS.BLN_FACTURE_DIRECTE = 1)
         			AND (PIECE_PEC.BLN_ACTIF = 1)
         			AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         			AND ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) AND ( EXISTS (select 1 from NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))
         	UNION

         	SELECT  DISTINCT ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC
         	FROM    #TEMP_SESSIONS
         			INNER JOIN ARRIVEE_PIECE_PEC ON #TEMP_SESSIONS.ID_MODULE_PEC = ARRIVEE_PIECE_PEC.ID_MODULE_PEC
         			INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC		
         	WHERE		(PIECE_PEC.BLN_MODULE = 1)
         			AND	(ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1 IS NULL) 
         			AND (ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2 IS NULL) 
         			AND (ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3 IS NULL)
         			AND (#TEMP_SESSIONS.BLN_FACTURE_DIRECTE = 1)
         			AND (PIECE_PEC.BLN_ACTIF = 1)
         			AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         			AND ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) AND ( EXISTS (select 1 from NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))
         	UNION
         	SELECT  DISTINCT ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC
         	FROM	#TEMP_SESSIONS
         			INNER JOIN STAGIAIRE_PEC ON #TEMP_SESSIONS.ID_MODULE_PEC = STAGIAIRE_PEC.ID_MODULE_PEC 
         			INNER JOIN ETABLISSEMENT ON STAGIAIRE_PEC.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT 
         			INNER JOIN ADHERENT ON ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT  
         			INNER JOIN ARRIVEE_PIECE_PEC ON ADHERENT.ID_ADHERENT = ARRIVEE_PIECE_PEC.ID_ADHERENT
         			INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         	WHERE		(PIECE_PEC.BLN_ADHERENT = 1)
         			AND	(ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1 IS NULL) 
         			AND (ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2 IS NULL) 
         			AND (ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3 IS NULL)
         			AND (PIECE_PEC.BLN_ACTIF = 1)
         			AND (#TEMP_SESSIONS.BLN_FACTURE_DIRECTE = 1)
         			AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         			AND ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) AND ( EXISTS (select 1 from NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))

         	UPDATE ARRIVEE_PIECE_PEC
         	SET	   ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1 = GETDATE()
         	WHERE  ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC IN (select #TEMP_RELANCE_1.ID_ARRIVEE_PIECE_PEC FROM #TEMP_RELANCE_1 )

         	SELECT  DISTINCT ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC
         	INTO	#TEMP_RELANCE_2	
         	FROM    #TEMP_SESSIONS 
         			INNER JOIN ARRIVEE_PIECE_PEC ON #TEMP_SESSIONS.ID_POSTE_COUT_REGLE = ARRIVEE_PIECE_PEC.ID_POSTE_COUT_REGLE
         			INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         			INNER JOIN POSTE_COUT_REGLE ON POSTE_COUT_REGLE.ID_MODULE_PEC = #TEMP_SESSIONS.ID_MODULE_PEC	
         			CROSS JOIN PARAMETRES

         	WHERE		(ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1 IS NOT NULL)
         			AND (GETDATE()-ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1 >= PARAMETRES.DELAI_RELANCE_PEC)
         			AND (ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2 IS NULL) 
         			AND (ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3 IS NULL)
         			AND (PIECE_PEC.BLN_POSTE_COUT_REGLE = 1)
         			AND (#TEMP_SESSIONS.BLN_FACTURE_DIRECTE = 1)
         			AND (PIECE_PEC.BLN_ACTIF = 1)
         			AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         			AND ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) AND ( EXISTS (select 1 from NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))
         	UNION

         	SELECT  DISTINCT ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC
         	FROM    #TEMP_SESSIONS 
         			INNER JOIN ARRIVEE_PIECE_PEC ON #TEMP_SESSIONS.ID_SESSION_PEC = ARRIVEE_PIECE_PEC.ID_SESSION_PEC
         			INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         			CROSS JOIN PARAMETRES									
         	WHERE		(PIECE_PEC.BLN_SESSION = 1)
         			AND	(ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1 IS NOT NULL)
         			AND (GETDATE()-ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1 >= PARAMETRES.DELAI_RELANCE_PEC)
         			AND (ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2 IS NULL) 
         			AND (ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3 IS NULL)
         			AND (#TEMP_SESSIONS.BLN_FACTURE_DIRECTE = 1)
         			AND (PIECE_PEC.BLN_ACTIF = 1)
         			AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         			AND ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) AND ( EXISTS (select 1 from NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))
         	UNION

         	SELECT  DISTINCT ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC
         	FROM    #TEMP_SESSIONS
         			INNER JOIN ARRIVEE_PIECE_PEC ON #TEMP_SESSIONS.ID_MODULE_PEC = ARRIVEE_PIECE_PEC.ID_MODULE_PEC
         			INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC	
         			CROSS JOIN PARAMETRES

         	WHERE		(ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1 IS NOT NULL)
         			AND (GETDATE()-ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1 >= PARAMETRES.DELAI_RELANCE_PEC)
         			AND (ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2 IS NULL) 
         			AND (ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3 IS NULL)
         			AND	(PIECE_PEC.BLN_MODULE = 1)
         			AND (#TEMP_SESSIONS.BLN_FACTURE_DIRECTE = 1)
         			AND (PIECE_PEC.BLN_ACTIF = 1)
         			AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         			AND ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) AND ( EXISTS (select 1 from NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))
         	UNION
         	SELECT  DISTINCT ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC
         	FROM	#TEMP_SESSIONS
         			INNER JOIN STAGIAIRE_PEC ON #TEMP_SESSIONS.ID_MODULE_PEC = STAGIAIRE_PEC.ID_MODULE_PEC 
         			INNER JOIN ETABLISSEMENT ON STAGIAIRE_PEC.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT 
         			INNER JOIN ADHERENT ON ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT  
         			INNER JOIN ARRIVEE_PIECE_PEC ON ADHERENT.ID_ADHERENT = ARRIVEE_PIECE_PEC.ID_ADHERENT
         			INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         			CROSS JOIN PARAMETRES

         	WHERE		(ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1 IS NOT NULL)
         			AND (GETDATE()-ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_1 >= PARAMETRES.DELAI_RELANCE_PEC)
         			AND (ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2 IS NULL) 
         			AND (ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3 IS NULL)
         			AND	(PIECE_PEC.BLN_ADHERENT = 1)
         			AND (PIECE_PEC.BLN_ACTIF = 1)
         			AND (#TEMP_SESSIONS.BLN_FACTURE_DIRECTE = 1)
         			AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         			AND ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) AND ( EXISTS (select 1 from NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))

         	UPDATE ARRIVEE_PIECE_PEC
         	SET	   ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2 = GETDATE()
         	WHERE  ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC IN (select #TEMP_RELANCE_2.ID_ARRIVEE_PIECE_PEC FROM #TEMP_RELANCE_2 )

         	SELECT  DISTINCT ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC
         	INTO	#TEMP_RELANCE_3	
         	FROM    #TEMP_SESSIONS 
         			INNER JOIN ARRIVEE_PIECE_PEC ON #TEMP_SESSIONS.ID_POSTE_COUT_REGLE = ARRIVEE_PIECE_PEC.ID_POSTE_COUT_REGLE
         			INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         			INNER JOIN POSTE_COUT_REGLE ON POSTE_COUT_REGLE.ID_MODULE_PEC = #TEMP_SESSIONS.ID_MODULE_PEC	
         			CROSS JOIN PARAMETRES

         	WHERE		(ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2 IS NOT NULL)
         			AND (GETDATE()-ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2 >= PARAMETRES.DELAI_RELANCE_PEC)  
         			AND (ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3 IS NULL)
         			AND (PIECE_PEC.BLN_POSTE_COUT_REGLE = 1)
         			AND (#TEMP_SESSIONS.BLN_FACTURE_DIRECTE = 1)
         			AND (PIECE_PEC.BLN_ACTIF = 1)
         			AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         			AND ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) AND ( EXISTS (select 1 from NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))
         	UNION

         	SELECT  DISTINCT ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC
         	FROM    #TEMP_SESSIONS 
         			INNER JOIN ARRIVEE_PIECE_PEC ON #TEMP_SESSIONS.ID_SESSION_PEC = ARRIVEE_PIECE_PEC.ID_SESSION_PEC
         			INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         			CROSS JOIN PARAMETRES									
         	WHERE		(PIECE_PEC.BLN_SESSION = 1)
         			AND	(ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2 IS NOT NULL)
         			AND (GETDATE()-ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2 >= PARAMETRES.DELAI_RELANCE_PEC)  
         			AND (ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3 IS NULL)
         			AND (#TEMP_SESSIONS.BLN_FACTURE_DIRECTE = 1)
         			AND (PIECE_PEC.BLN_ACTIF = 1)
         			AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         			AND ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) AND ( EXISTS (select 1 from NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))
         	UNION

         	SELECT  DISTINCT ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC
         	FROM    #TEMP_SESSIONS
         			INNER JOIN ARRIVEE_PIECE_PEC ON #TEMP_SESSIONS.ID_MODULE_PEC = ARRIVEE_PIECE_PEC.ID_MODULE_PEC
         			INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC	
         			CROSS JOIN PARAMETRES

         	WHERE		(ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2 IS NOT NULL)
         			AND (GETDATE()-ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2 >= PARAMETRES.DELAI_RELANCE_PEC)  
         			AND (ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3 IS NULL)
         			AND	(PIECE_PEC.BLN_MODULE = 1)
         			AND (#TEMP_SESSIONS.BLN_FACTURE_DIRECTE = 1)
         			AND (PIECE_PEC.BLN_ACTIF = 1)
         			AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         			AND ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) AND ( EXISTS (select 1 from NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))
         	UNION
         	SELECT  DISTINCT ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC
         	FROM	#TEMP_SESSIONS
         			INNER JOIN STAGIAIRE_PEC ON #TEMP_SESSIONS.ID_MODULE_PEC = STAGIAIRE_PEC.ID_MODULE_PEC 
         			INNER JOIN ETABLISSEMENT ON STAGIAIRE_PEC.ID_ETABLISSEMENT = ETABLISSEMENT.ID_ETABLISSEMENT 
         			INNER JOIN ADHERENT ON ETABLISSEMENT.ID_ADHERENT = ADHERENT.ID_ADHERENT  
         			INNER JOIN ARRIVEE_PIECE_PEC ON ADHERENT.ID_ADHERENT = ARRIVEE_PIECE_PEC.ID_ADHERENT
         			INNER JOIN PIECE_PEC ON ARRIVEE_PIECE_PEC.ID_PIECE_PEC = PIECE_PEC.ID_PIECE_PEC
         			CROSS JOIN PARAMETRES

         	WHERE		(ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2 IS NOT NULL)
         			AND (GETDATE()-ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_2 >= PARAMETRES.DELAI_RELANCE_PEC)  
         			AND (ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3 IS NULL)
         			AND	(PIECE_PEC.BLN_ADHERENT = 1)
         			AND (PIECE_PEC.BLN_ACTIF = 1)
         			AND (#TEMP_SESSIONS.BLN_FACTURE_DIRECTE = 1)
         			AND ((PIECE_PEC.BLN_BLOQUANT_ENGAGEMENT = 1) OR  (PIECE_PEC.BLN_BLOQUANT_REGLEMENT = 1))
         			AND ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 0) OR ((ARRIVEE_PIECE_PEC.BLN_ACTIF = 1) AND ( EXISTS (select 1 from NR210 WHERE NR210.ID_ARRIVEE_PIECE_PEC = ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC))))

         	UPDATE ARRIVEE_PIECE_PEC
         	SET	   ARRIVEE_PIECE_PEC.DAT_RELANCE_REGLE_3 = GETDATE()
         	WHERE  ARRIVEE_PIECE_PEC.ID_ARRIVEE_PIECE_PEC IN (select #TEMP_RELANCE_3.ID_ARRIVEE_PIECE_PEC FROM #TEMP_RELANCE_3 )

         END

GO
 CREATE PROCEDURE [dbo].[INS_VERSEMENT_EXTRANET]
          @ID_VERSEMENT INTEGER OUT,
          @ID_ADHERENT_EMETTEUR INTEGER,
          @ID_TIERS_EMETTEUR INTEGER,
          @ID_MODE_VERSEMENT INTEGER,
          @COD_VERSEMENT INTEGER,
          @LIB_BANQUE VARCHAR(50),
          @MNT_VERSEMENT decimal(18,2),  
          @BLN_PB_IMPUTATION TINYINT,
          @BLN_ACTIF TINYINT,
          @COM_VERSEMENT VARCHAR(255),
          @ID_UTILISATEUR INTEGER,
          @ID_BORDEREAU INTEGER,
          @NUM_CHEQUE VARCHAR(10),
          @DAT_ENCAISSEMENT DATETIME,
          @DAT_IMPUTATION DATETIME,
          @DAT_SAISIE DATETIME,
          @DAT_MAJ_COMPTES DATETIME,
          @DAT_COMPTA_COMPTES_ADH DATETIME,
          @DAT_ANNUL_COMPTES_ADH DATETIME,
          @DAT_PASSAGE_COMPTA DATETIME,
          @INDICATEUR_INSTANCE INTEGER,
          @ID_STATUT_VERSEMENT INTEGER,
          @BLN_IMPAYE TINYINT,
          @DAT_SAISIE_IMPAYE DATETIME,
          @BLN_ENCAISSEMENT_DIFFERE TINYINT,
          @DAT_VALID_VERSEMENT DATETIME = NULL,
          @ID_BANQUE INTEGER,
          @MODE_SAISIE_VERSEMENT VARCHAR(15),
          @REF_EXTRANET VARCHAR(20),
          @DAT_VALIDATION_EXTRANET DATETIME,
          @DAT_ECHEANCE DATETIME,
          @ID_MOTIF_REGLEMENT INTEGER,
          @ID_ETABLISSEMENT_EMETTEUR INT,
          @ID_TYPE_VERSEMENT INT,
          @LIBL_POSTE_VERSEMENT VARCHAR(50),
          @ID_PERIODE INT,
          @MNT_HT decimal(18,2),
          @MNT_TVA decimal(18,2),
          @SOLDE_FPSPP decimal(18,2) = 0,
          @SOLDE_PLAN decimal(18,2) = NULL,
          @CONTRIB_PROF decimal(18,2) = NULL,
          @REGULARISATION_FPSPP decimal(18,2) = NULL,
          @REGULARISATION_COMPENSATION decimal(18,2) = NULL,
          @TAUX_TVA decimal(18,2) = NULL,
          @MNT_DEDUCTION decimal(18,2) = NULL,
          @EMAIL_COLLECTE VARCHAR(50),
          @FROM_ADRESSE VARCHAR(50),
          @SOLDE_CONVENTIONNEL decimal(18,2) = NULL,
          @MNT_DSP decimal(18,2) = NULL
         AS

         BEGIN

          DECLARE
          @NB_BANQUE INT = 0

          SELECT  @NB_BANQUE = count(ID_BANQUE)
          FROM  BANQUE
          WHERE LIBL_BANQUE LIKE '%'+ @LIB_BANQUE+'%'

          IF @NB_BANQUE = 1
          BEGIN
           SELECT @ID_BANQUE = ID_BANQUE,
             @LIB_BANQUE = LIBL_BANQUE
           FROM BANQUE
           WHERE LIBL_BANQUE LIKE '%'+ @LIB_BANQUE+'%'
          END
          ELSE
          BEGIN
           SELECT @ID_BANQUE = ID_BANQUE,
             @LIB_BANQUE = LIBL_BANQUE
           FROM BANQUE
           WHERE COD_BANQUE = 'ND'
           AND  BLN_ACTIF = 1
          END

          SET @MNT_VERSEMENT = round(@MNT_VERSEMENT, 2)
          INSERT INTO VERSEMENT
          (
          ID_ADHERENT_EMETTEUR,
          ID_TIERS_EMETTEUR,
          ID_MODE_VERSEMENT,
          COD_VERSEMENT,
          DAT_CREATION,
          LIB_BANQUE ,
          MNT_VERSEMENT ,
          BLN_PB_IMPUTATION ,
          BLN_ACTIF ,
          ID_UTILISATEUR ,
          ID_BORDEREAU ,
          NUM_CHEQUE ,
          DAT_ENCAISSEMENT ,
          DAT_IMPUTATION ,
          DAT_SAISIE ,
          DAT_MAJ_COMPTES ,
          DAT_COMPTA_COMPTES_ADH ,
          DAT_ANNUL_COMPTES_ADH ,
          DAT_PASSAGE_COMPTA ,
          INDICATEUR_INSTANCE ,
          ID_STATUT_VERSEMENT ,
          BLN_IMPAYE ,
          DAT_SAISIE_IMPAYE ,
          BLN_ENCAISSEMENT_DIFFERE,
          DAT_VALID_VERSEMENT,
          ID_BANQUE,
          MODE_SAISIE_VERSEMENT,
          REF_EXTRANET,
          DAT_VALIDATION_EXTRANET,
          DAT_ECHEANCE,
          ID_MOTIF_REGLEMENT,
          ID_ETABLISSEMENT_EMETTEUR,
          BLN_ECHEANCIER
          )
          VALUES
          (
          @ID_ADHERENT_EMETTEUR,
          @ID_TIERS_EMETTEUR,
          @ID_MODE_VERSEMENT,
          @COD_VERSEMENT,
          getdate(),
          @LIB_BANQUE ,
          @MNT_VERSEMENT,
          @BLN_PB_IMPUTATION ,
          @BLN_ACTIF ,
          @ID_UTILISATEUR ,
          @ID_BORDEREAU ,
          @NUM_CHEQUE ,
          @DAT_ENCAISSEMENT ,
          @DAT_IMPUTATION ,
          @DAT_SAISIE ,
          @DAT_MAJ_COMPTES ,
          @DAT_COMPTA_COMPTES_ADH ,
          @DAT_ANNUL_COMPTES_ADH ,
          @DAT_PASSAGE_COMPTA ,
          @INDICATEUR_INSTANCE ,
          @ID_STATUT_VERSEMENT ,
          @BLN_IMPAYE ,
          @DAT_SAISIE_IMPAYE ,
          @BLN_ENCAISSEMENT_DIFFERE,
          @DAT_VALID_VERSEMENT,
          @ID_BANQUE,
          @MODE_SAISIE_VERSEMENT,
          @REF_EXTRANET,
          @DAT_VALIDATION_EXTRANET,
          @DAT_ECHEANCE,
          @ID_MOTIF_REGLEMENT,
          @ID_ETABLISSEMENT_EMETTEUR,
          0
          )

          SET @ID_VERSEMENT = @@IDENTITY

          UPDATE VERSEMENT
          SET  COD_VERSEMENT = @ID_VERSEMENT
          WHERE ID_VERSEMENT = @ID_VERSEMENT

          IF ((@COM_VERSEMENT IS NOT NULL) AND (@COM_VERSEMENT <> ''))
          BEGIN
           INSERT INTO COMMENTAIRES
           (
           TYPE_OBJET,
           ID_OBJET,
           [DATE],
           COMMENTAIRE,
           ID_UTILISATEUR
           )
           VALUES
           (
           3,
           @ID_VERSEMENT,
           getdate(),
           @COM_VERSEMENT ,
           82
           )
          END

          DECLARE
          @ID_POSTE_VERSEMENT INT

          EXEC
          @ID_POSTE_VERSEMENT = INS_POSTE_VERSEMENT
          @ID_VERSEMENT = @ID_VERSEMENT, 
          @ID_ADHERENT_BENEFICIAIRE = @ID_ADHERENT_EMETTEUR, 
          @ID_TYPE_VERSEMENT = @ID_TYPE_VERSEMENT, 
          @ID_PERIODE = @ID_PERIODE, 
          @LIBL_POSTE_VERSEMENT = @LIBL_POSTE_VERSEMENT, 
          @MNT_POSTE_VERSEMENT = @MNT_VERSEMENT, 
          @BLN_PB_IMPUTATION = @BLN_PB_IMPUTATION, 
          @BLN_ACTIF = 1, 
          @ID_ETABLISSEMENT_BENEFICIAIRE = @ID_ETABLISSEMENT_EMETTEUR 

          DECLARE @ID_TYPE_TVA INT

          SELECT @ID_TYPE_TVA = ID_TYPE_TVA from TYPE_TVA where COD_TYPE_TVA = '13' 

          SET @TAUX_TVA = ISNULL([dbo].GetCurrentTVA(@ID_TYPE_TVA), 0)

          declare @ID_TYPE_ASSUJETTISSEMENT int

          select @ID_TYPE_ASSUJETTISSEMENT = R20.ID_TYPE_ASSUJETISSEMENT
          from R20 
          where ID_ADHERENT = @ID_ADHERENT_EMETTEUR 
          and  ID_PERIODE = @ID_PERIODE 

          DECLARE @ID_ACTIVITE_DSP INT = NULL

          SELECT TOP 1
             @ID_ACTIVITE_DSP = R19.ID_ACTIVITE
          FROM R19
          inner join ACTIVITE   on R19.ID_ACTIVITE = ACTIVITE.ID_ACTIVITE  
          inner join TYPE_ACTIVITE on TYPE_ACTIVITE.ID_TYPE_ACTIVITE = ACTIVITE.ID_TYPE_ACTIVITE  
          WHERE r19.ID_PERIODE  = @ID_PERIODE 
          and  R19.ID_ADHERENT  = @ID_ADHERENT_EMETTEUR 
          and  COD_TYPE_ACTIVITE = 'DSP'

          declare @IMPUTATION TABLE  
          (
          ID_ACTIVITE int,  
          NUM_ORDRE int,  
          MASSE_SALARIALE DECIMAL(18,2),  
          TAU_GLO_APPEL float,  
          PRC_APPELE tinyint,  
          PRC_FPSPP decimal(5,3),  
          VERSE_HT decimal(18,2),  
          DONT_DEJA_REGLE_FPSPP decimal(18,2),
          DEDUCTION_MNT_HT decimal(18,2),
          DU_HT decimal(18,2)  
          )

          INSERT INTO @IMPUTATION
          (ID_ACTIVITE ,  
          NUM_ORDRE ,  
          MASSE_SALARIALE ,  
          TAU_GLO_APPEL ,  
          PRC_APPELE ,  
          PRC_FPSPP ,  
          VERSE_HT ,  
          DONT_DEJA_REGLE_FPSPP ,
          DEDUCTION_MNT_HT
          )
          SELECT 
          imputation.ID_ACTIVITE ,  
          NUM_ORDRE ,  
          MASSE_SALARIALE ,  
          TAU_GLO_APPEL ,  
          PRC_APPELE ,  
          PRC_FPSPP ,  
          VERSE_HT ,  
          DONT_DEJA_REGLE_FPSPP ,
          isnull(DEDUCTION.MNT_HT, 0)   as DEDUCTION_MNT_HT
          from  dbo.GET_ACTIVITES_ADHERENT ( @ID_ADHERENT_EMETTEUR,
                    @ID_PERIODE,
                    0, 
                    @ID_TYPE_VERSEMENT,  
                    @ID_TYPE_ASSUJETTISSEMENT,  
                    @ID_ETABLISSEMENT_EMETTEUR
                   ) imputation
          LEFT JOIN DEDUCTION  ON DEDUCTION.ID_ADHERENT = @ID_ADHERENT_EMETTEUR 
                AND DEDUCTION.ID_PERIODE = @ID_PERIODE 
                AND DEDUCTION.ID_ACTIVITE = imputation.ID_ACTIVITE   
          WHERE imputation.bln_imputable = 1         
          and  imputation.ID_ACTIVITE <> coalesce(@ID_ACTIVITE_DSP, 0)

          IF @ID_TYPE_VERSEMENT = 4 
          BEGIN
           update @IMPUTATION  
           set DU_HT = (MASSE_SALARIALE * (TAU_GLO_APPEL / 100.00) * (PRC_APPELE / 100.00)) - DEDUCTION_MNT_HT - VERSE_HT     
          END
          ELSE IF @ID_TYPE_VERSEMENT = 3  
          BEGIN
           update @IMPUTATION  
           set DU_HT = @MNT_VERSEMENT   / (1 + @TAUX_TVA)
          END
          ELSE
          BEGIN
           update @IMPUTATION  
           set DU_HT = -1

           RAISERROR('Type de versement inconnu', 16, 1)
          END

          declare @DU_HT decimal(18,2), 
            @ID_ACTIVITE int
          declare @ID_POSTE_IMPUTATION int
          declare @montant_ttc decimal(18,2), 
            @montant_ht decimal(18,2), 
            @montant_tva decimal(18,2)

          declare @solde_total decimal(18,2) = @MNT_VERSEMENT

          DECLARE curs_imp CURSOR FOR
          SELECT ID_ACTIVITE, 
            DU_HT
          from @IMPUTATION
          where DU_HT > 0

          OPEN curs_imp

          FETCH NEXT FROM curs_imp
          INTO @ID_ACTIVITE, @DU_HT

          WHILE @@FETCH_STATUS = 0
          BEGIN
           set @montant_ttc = @DU_HT * (1.00 + @TAUX_TVA);

           if (@montant_ttc > @solde_total)
            set @montant_ttc = @solde_total

           set @solde_total= @solde_total - @montant_ttc
           set @montant_ht = @montant_ttc / (1.00 + @TAUX_TVA);
           set @montant_tva = @montant_ttc - @montant_ht

           if (@montant_ttc > 0)
           EXEC
            @ID_POSTE_IMPUTATION = INS_POSTE_IMPUTATION @ID_ACTIVITE = @ID_ACTIVITE, 
                       @ID_POSTE_VERSEMENT = @ID_POSTE_VERSEMENT, 
                       @ID_VIREMENT_INTERNE_COLLECTE = NULL, 
                       @MNT_HT = @montant_ht, 
                       @MNT_TVA = @montant_tva, 
                       @MNT_TTC = @montant_ttc, 
                       @DAT_MAJ_CPT_ADH = NULL, 
                       @ID_VIREMENT_INTERNE_COLLECTE_IMPAYE = NULL, 
                       @DONT_REGLE_FPSPP = 0

           FETCH NEXT FROM curs_imp INTO @ID_ACTIVITE, @DU_HT
          END
          CLOSE curs_imp
          DEALLOCATE curs_imp

          SET @MNT_DSP    = coalesce(round(@MNT_DSP, 2), 0)

          IF ((@MNT_DSP > 0)AND (@ID_ACTIVITE_DSP IS NOT NULL))
          BEGIN

           EXEC INS_POSTE_IMPUTATION @ID_ACTIVITE = @ID_ACTIVITE_DSP,   
                   @ID_POSTE_VERSEMENT = @ID_POSTE_VERSEMENT, 
                   @ID_VIREMENT_INTERNE_COLLECTE = NULL,  
                   @MNT_HT = @MNT_DSP  ,      
                   @MNT_TVA = 0,        
                   @MNT_TTC = @MNT_DSP,      
                   @DAT_MAJ_CPT_ADH = NULL,     
                   @ID_VIREMENT_INTERNE_COLLECTE_IMPAYE = NULL,
                   @DONT_REGLE_FPSPP = 0
          END

          declare @ECART_TTC decimal(18,2)

          SELECT @ECART_TTC = @MNT_VERSEMENT - ISNULL(SUM (MNT_TTC) , 0)
          FROM POSTE_IMPUTATION 
          WHERE ID_POSTE_VERSEMENT = @ID_POSTE_VERSEMENT

          IF (@ECART_TTC <> 0) AND ABS(@ECART_TTC ) <= 0.05 
          BEGIN
           UPDATE  POSTE_IMPUTATION
           SET   MNT_TTC = MNT_TTC + @ECART_TTC
           FROM  POSTE_IMPUTATION 
           INNER JOIN ACTIVITE on POSTE_IMPUTATION.ID_ACTIVITE = ACTIVITE.ID_ACTIVITE  
           WHERE  ID_POSTE_VERSEMENT = @ID_POSTE_VERSEMENT
           AND   (
               (COD_ACTIVITE = 'PRO' AND @ID_TYPE_VERSEMENT = 4) 
               OR 
               (COD_ACTIVITE = 'VOL' AND @ID_TYPE_VERSEMENT = 3) 
              )     
          END

          declare @TTC decimal(18,2), @HT decimal(18,2), @TVA decimal(15,2)
          SELECT @TTC = ISNULL(SUM (MNT_TTC) , 0), 
            @HT  = ISNULL(SUM (MNT_HT) , 0), 
            @TVA = ISNULL(SUM (MNT_TVA) , 0) 
          FROM POSTE_IMPUTATION 
          WHERE ID_POSTE_VERSEMENT = @ID_POSTE_VERSEMENT

          SET @ECART_TTC = @TTC - @HT - @TVA
          if (@ECART_TTC <> 0) AND ABS(@ECART_TTC ) <= 0.05 
           BEGIN
           UPDATE  POSTE_IMPUTATION
           SET MNT_TVA = MNT_TVA + @ECART_TTC
           FROM  POSTE_IMPUTATION 
           INNER JOIN ACTIVITE on POSTE_IMPUTATION.ID_ACTIVITE = ACTIVITE.ID_ACTIVITE  
           WHERE  ID_POSTE_VERSEMENT = @ID_POSTE_VERSEMENT
           AND   (
               (COD_ACTIVITE = 'PRO' AND @ID_TYPE_VERSEMENT = 4) 
               OR 
               (COD_ACTIVITE = 'VOL' AND @ID_TYPE_VERSEMENT = 3) 
              )     
           END

          INSERT INTO POSTE_VERSSEMENT_ETABLISSEMENT_CONCERNEE
          (
          ID_POSTE_VERSEMENT,
          ID_ETABLISSEMENT_CONCERNEE
          )
          SELECT
          @ID_POSTE_VERSEMENT,
          ETAB.ID_ETABLISSEMENT
          FROM
          ADHERENT ADH
          INNER JOIN ETABLISSEMENT ETAB
          ON ADH.ID_ADHERENT=ETAB.ID_ADHERENT
          WHERE
          ADH.ID_ADHERENT = @ID_ADHERENT_EMETTEUR

          IF @ID_TYPE_VERSEMENT = 4 
          BEGIN
           DECLARE
           @SUBJECT VARCHAR(255),
           @BODY VARCHAR(MAX),
           @ERROR_MESSAGE NVARCHAR(4000)

           IF @SOLDE_FPSPP < 0
           BEGIN
            SET @SUBJECT = 'Extranet : le versement donne lieu …ÿ un trop vers‚ FPSPP'
            SET @BODY =
            '<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.01 Transitional//EN"><html><head><meta http-equiv = "content-type" content = "text/html; charset = utf-8">'+
            '<title>email</title></head><body>'+
            '<p> Le versement '+cast(@ID_VERSEMENT AS VARCHAR(8))+' donne lieu … un trop vers‚ FPSPP';

            EXEC DBO.ENVOIE_MAIL
              @RECIPIENTS = @EMAIL_COLLECTE,
              @COPY_RECIPIENTS = NULL,
              @BLIND_COPY_RECIPIENTS = NULL,
              @SUBJECT = @SUBJECT,
              @BODY_FORMAT = 'html',
              @BODY = @BODY,
              @FROM_ADRESS = @FROM_ADRESSE,
              @ATTACHMENT_PATH = NULL,
              @ERROR_MESSAGE = @ERROR_MESSAGE
           END
          END

          IF ((@ID_ACTIVITE_DSP IS NULL) AND (@MNT_DSP > 0))
          BEGIN
           SET @SUBJECT = 'Extranet : montant DSP saisi pour l''adh‚rent qui n''a pas d''activit‚ DSP'
           SET @BODY =
           '<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.01 Transitional//EN"><html><head><meta http-equiv = "content-type" content = "text/html; charset = utf-8">'+
           '<title>email</title></head><body>'+
           '<p> Le versement '+cast(@ID_VERSEMENT AS VARCHAR(8))+' a un mnt DSP, or l''adherent '+
           cast(@ID_ADHERENT_EMETTEUR AS VARCHAR(6)) +'n''a pas activit‚ DSP d‚finie' ;

           EXEC dbo.ENVOIE_MAIL
             @RECIPIENTS = @EMAIL_COLLECTE,
             @COPY_RECIPIENTS = NULL,
             @BLIND_COPY_RECIPIENTS = NULL,
             @SUBJECT = @SUBJECT,
             @BODY_FORMAT = 'html',
             @BODY = @BODY,
             @FROM_ADRESS = @FROM_ADRESSE,
             @ATTACHMENT_PATH = NULL,
             @ERROR_MESSAGE = @ERROR_MESSAGE
          END

         END
GO   
